insert into fcps_mcq_stage (id, subject_name, chapter_name, question, options, correct_answer, explanation) values
('73e9a5d0-f6da-59fe-b5eb-3423ba3db1a9'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The cranium (neurocranium) is composed of:', '["14 bones","12 bones","10 bones","8 bones","6 bones"]'::jsonb, '8 bones', 'The neurocranium (the skull) encloses and protects the brain. The viscerocranium (facial skeleton) has 14 bones.'),
('bf4173c5-e296-5d6b-a7af-bbcded63b100'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The calvaria (skull cap) consists of:', '["The frontal bone, two parietal bones, and the occipital bone","Only the parietal bones and its associated anatomical structures","The ethmoid and sphenoid bones and its associated anatomical structures","The maxilla and mandible and its associated anatomical structures","The temporal and sphenoid bones and its associated anatomical structures"]'::jsonb, 'The frontal bone, two parietal bones, and the occipital bone', 'The calvaria (the upper part of the skull) is composed of the frontal, parietal, and occipital bones (the cranial vault).'),
('a606eb0c-6c57-58c1-a47a-a49b2c7aab80'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The outer and inner tables of the skull are separated by:', '["The diploe","The dura mater","The arachnoid mater","The pia mater","The periosteum"]'::jsonb, 'The diploe', 'The diploe (cancellous bone) contains the diploic veins that connect the intracranial and extracranial venous systems.'),
('087d6852-04b2-5642-b78c-e6c6a57c9877'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The coronal suture separates:', '["The parietal bones from the occipital bone","The frontal bone from the ethmoid","The frontal bone from the two parietal bones","The temporal bones from the parietal bones","The parietal bones from each other"]'::jsonb, 'The frontal bone from the two parietal bones', 'The coronal suture (a fibrous joint) runs from the pterion to the bregma. It fuses around age 30.'),
('da48285d-4b27-598b-97e0-86b57c6ab077'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The sagittal suture separates:', '["The temporal and parietal bones","The frontal bone from the nasal bones","The two parietal bones","The frontal and parietal bones","The parietal and occipital bones"]'::jsonb, 'The two parietal bones', 'The sagittal suture runs from the bregma to the lambda. The vertex of the skull is at the midpoint of the sagittal suture.'),
('2b369972-eceb-5890-89fe-f5d62c2c21a6'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The lambdoid suture separates:', '["The parietal bones from each other","The temporal and parietal bones","The parietal bones from the occipital bone","The frontal and parietal bones","The sphenoid and ethmoid bones"]'::jsonb, 'The parietal bones from the occipital bone', 'The lambdoid suture (lambda-shaped) is posterior. Craniosynostosis of the lambdoid suture causes posterior plagiocephaly.'),
('e26b77e9-62f9-5d03-9420-2aec296e0705'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The squamous suture separates:', '["The frontal and parietal bones","The ethmoid and frontal bones","The parietal and occipital bones","The sphenoid and temporal bones","The temporal bone (squamous part) from the parietal bone"]'::jsonb, 'The temporal bone (squamous part) from the parietal bone', 'The squamous suture (parietotemporal suture) is on the lateral aspect of the skull.'),
('b5b23373-7542-5a29-82cc-a782b874aea9'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The bregma is:', '["The lambda","The pterion","The asterion","The junction of the coronal and sagittal sutures","The junction of the sagittal and lambdoid sutures"]'::jsonb, 'The junction of the coronal and sagittal sutures', 'The bregma (midline point) is the landmark for the anterior fontanelle (closes by 18-24 months).'),
('91c9d2d3-5d68-5eec-9ca8-b6a8ff11dd01'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The lambda is:', '["The junction of the coronal and sagittal sutures","The junction of the sagittal and lambdoid sutures","The pterion","The bregma","The asterion"]'::jsonb, 'The junction of the sagittal and lambdoid sutures', 'The lambda (midline point) is the landmark for the posterior fontanelle (closes by 3-4 months).'),
('52a4a1fd-2640-5c2b-93c5-a567311af6dd'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'In a surgical context, The pterion is:', '["The junction of the sagittal and lambdoid sutures and its associated anatomical structures","The H-shaped junction of the frontal, parietal, temporal, and sphenoid bones (the thinnest part o","The asterion and its associated anatomical structures","The lambda and its associated anatomical structures","The bregma and its associated anatomical structures"]'::jsonb, 'The H-shaped junction of the frontal, parietal, temporal, and sphenoid bones (the thinnest part o', 'The pterion (in the temporal region) overlies the middle meningeal artery (a fracture here causes extradural hemorrhage).'),
('db9daaf3-b165-5433-afe5-feb79f8013ff'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The asterion is:', '["The junction of the lambdoid, occipitomastoid, and parietomastoid sutures","The glabella and its associated anatomical structures","The lambda and its associated anatomical structures","The pterion and its associated anatomical structures","The bregma and its associated anatomical structures"]'::jsonb, 'The junction of the lambdoid, occipitomastoid, and parietomastoid sutures', 'The asterion (posteroinferior to the external auditory meatus) is a landmark for the transverse-sigmoid sinus junction.'),
('1977bcdf-dfd0-5e34-83a1-a12bc90a163d'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The nasion is:', '["The midline depression at the junction of the frontal and two nasal bones","The glabella and its associated anatomical structures","The inion and its associated anatomical structures","The lambda and its associated anatomical structures","The bregma and its associated anatomical structures"]'::jsonb, 'The midline depression at the junction of the frontal and two nasal bones', 'The nasion (nasofrontal suture) is a key cephalometric landmark for the skull base.'),
('741f94c7-0c52-5b19-8b4d-8a00ef0393b6'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The glabella is:', '["The inion and its associated anatomical structures","The smooth prominence of the frontal bone above the nasion","The nasion and its associated anatomical structures","The bregma and its associated anatomical structures","The lambda and its associated anatomical structures"]'::jsonb, 'The smooth prominence of the frontal bone above the nasion', 'The glabella (a landmark for frontal sinus) is the most anterior projection of the frontal bone.'),
('64b7e1e4-bc4b-56cd-a469-0c3da3855ce3'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The inion is:', '["The bregma and its associated anatomical structures","The glabella and its associated anatomical structures","The lambda and its associated anatomical structures","The most prominent point of the external occipital protuberance","The nasion and its associated anatomical structures"]'::jsonb, 'The most prominent point of the external occipital protuberance', 'The inion (posterior midline of the skull) is the attachment of the ligamentum nuchae and the trapezius muscle.'),
('1e77301d-b7bf-5f7a-99db-6e1eadb1be1c'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The vertex is:', '["The lambda","The nasion","The highest point of the skull","The inion","The bregma"]'::jsonb, 'The highest point of the skull', 'The vertex (the top of the skull) is an important landmark for neurosurgical approaches.'),
('1a628d52-21bf-5e64-8178-d6ce4d1ba89f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The opisthion is:', '["The glabella","The basion","The inion","The anterior border of the foramen magnum","The midpoint of the posterior border of the foramen magnum"]'::jsonb, 'The midpoint of the posterior border of the foramen magnum', 'The opisthion (posterior margin of the foramen magnum) is the landmark for the craniocervical junction.'),
('07dbe862-ca7e-5c77-962d-5a5382cdaf69'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The basion is:', '["The nasion","The posterior border of the foramen magnum","The inion","The opisthion","The midpoint of the anterior border of the foramen magnum"]'::jsonb, 'The midpoint of the anterior border of the foramen magnum', 'The basion (anterior margin of the foramen magnum) is the landmark for the dens on the lateral skull X-ray (Wackenheim clivus line).'),
('03a756ee-354e-51b7-96f1-5f7581ae1e1b'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The external occipital protuberance:', '["A midline prominence on the occipital bone","The nuchal lines","The inferior nuchal line","The superior nuchal line","The inion"]'::jsonb, 'A midline prominence on the occipital bone', 'The external occipital protuberance (EOP) is a palpable landmark at the nape of the neck (the inion may be more prominent).'),
('ae493b14-25ea-5993-9b4c-633381d600b4'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The superior nuchal line:', '["The nuchal crest and its associated anatomical structures","The highest nuchal line and its associated anatomical structures","The external occipital crest and its associated anatomical structures","A curved ridge on the occipital bone (the attachment of the trapezius, SCM","The inferior nuchal line and its associated anatomical structures"]'::jsonb, 'A curved ridge on the occipital bone (the attachment of the trapezius, SCM', 'The superior nuchal line (from the EOP to the mastoid process) is the upper limit of the posterior neck dissection.'),
('22ed7ec0-6290-5b69-a061-a09575fe0ec4'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The inferior nuchal line:', '["The highest nuchal line and its associated anatomical structures","A curved ridge below the superior nuchal line (the attachment of the rectus capitis posterior maj","The nuchal crest and its associated anatomical structures","The superior nuchal line and its associated anatomical structures","The external occipital crest and its associated anatomical structures"]'::jsonb, 'A curved ridge below the superior nuchal line (the attachment of the rectus capitis posterior maj', 'The inferior nuchal line (below the superior nuchal line) is the attachment of the suboccipital muscles.'),
('fca7e770-d0c7-5dd3-83b7-76621157358b'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The foramen magnum is located:', '["In the occipital bone (the largest foramen at the base of the skull — transmits the medulla oblon","In the parietal bone and its associated anatomical structures","In the temporal bone and its associated anatomical structures","In the sphenoid bone and its associated anatomical structures","In the frontal bone and its associated anatomical structures"]'::jsonb, 'In the occipital bone (the largest foramen at the base of the skull — transmits the medulla oblon', 'The foramen magnum (25 x 30 mm) is the opening between the cranial cavity and the vertebral canal.'),
('a0ec1fb6-8c46-5719-9ac7-448771575723'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The occipital condyles:', '["The elliptical bony processes on each side of the foramen magnum","The styloid processes and its associated anatomical structures","The mastoid processes and its associated anatomical structures","The mandibular condyles and its associated anatomical structures","The zygomatic arches and its associated anatomical structures"]'::jsonb, 'The elliptical bony processes on each side of the foramen magnum', 'The occipital condyles (convex, face inferolaterally) form the atlanto-occipital joint (flexion/extension — yes nodding).'),
('107cab67-e697-5613-b8a9-a513a3894663'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The condylar canal:', '["Transmits the internal carotid artery and its associated anatomical structures","Transmits the hypoglossal nerve and its associated anatomical structures","A small canal posterior to the occipital condyle (transmits the condylar emissary vein from the s","Transmits the vertebral artery and its associated anatomical structures","Transmits the spinal accessory nerve and its associated anatomical structures"]'::jsonb, 'A small canal posterior to the occipital condyle (transmits the condylar emissary vein from the s', 'The condylar canal (emissary vein) connects the intracranial and extracranial venous systems (a route for infection spread).'),
('f541ec0a-e842-5d47-8843-902c6e1111bb'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The hypoglossal canal is located:', '["In the sphenoid bone and its associated anatomical structures","Above and anterior to the foramen magnum, in the occipital bone","In the parietal bone and its associated anatomical structures","In the temporal bone and its associated anatomical structures","In the ethmoid bone and its associated anatomical structures"]'::jsonb, 'Above and anterior to the foramen magnum, in the occipital bone', 'The hypoglossal canal (anterior condylar canal) pierces the occipital bone at the base of the occipital condyle.'),
('0e57bae6-209d-5d0a-b3cc-97082ebc450a'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The petrous temporal bone:', '["The styloid process","A dense, pyramidal part of the temporal bone","The squamous part of the temporal bone","The mastoid part","The tympanic part"]'::jsonb, 'A dense, pyramidal part of the temporal bone', 'The petrous temporal bone (the hardest bone in the body) separates the middle and posterior cranial fossae.'),
('d41e62e9-b103-5976-86ab-7d5e5554f900'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The squamous part of the temporal bone:', '["The tympanic part and its associated anatomical structures","A thin, fan-shaped part (forms the lateral wall of the middle cranial fossa — contains the groove","The petrous part and its associated anatomical structures","The mastoid part and its associated anatomical structures","The styloid process and its associated anatomical structures"]'::jsonb, 'A thin, fan-shaped part (forms the lateral wall of the middle cranial fossa — contains the groove', 'The squamous temporal bone (pterion area) is the thinnest part of the skull (fractured in lateral head trauma).'),
('b87045be-78dd-5f9e-aec4-35f5ff8de81b'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The tympanic part of the temporal bone:', '["The mastoid air cells and its associated anatomical structures","The styloid process and its associated anatomical structures","The squama and its associated anatomical structures","The middle ear and its associated anatomical structures","A curved plate that forms the anterior wall, floor, and posterior wall of the external auditory m"]'::jsonb, 'A curved plate that forms the anterior wall, floor, and posterior wall of the external auditory m', 'The tympanic part (ring-like in the newborn) forms the non-mobile part of the external auditory canal.'),
('f9bc34b1-0a90-5381-96bc-51ab80128fe8'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The mastoid part of the temporal bone:', '["The styloid process and its associated anatomical structures","The petrous ridge and its associated anatomical structures","The squamous part and its associated anatomical structures","The tympanic ring and its associated anatomical structures","The posterior part (contains the mastoid air cells and the mastoid process — the attachment of th"]'::jsonb, 'The posterior part (contains the mastoid air cells and the mastoid process — the attachment of th', 'Mastoiditis (infection of the mastoid air cells) is a complication of otitis media (Hennebert sign and the Trautmann triangle).'),
('541f9a04-eb2f-5106-bda8-f708a0972d8b'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The mastoid process is:', '["The styloid process","The condylar process","The coronoid process","A conical bony projection","Tthe zygomatic process"]'::jsonb, 'A conical bony projection', 'The mastoid process (palpable behind the ear) is absent at birth and develops during the second year of life.'),
('ae428c15-4c22-5148-a259-598035c0089f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The styloid process is:', '["The zygomatic process and its associated anatomical structures","A long, slender bony projection from the temporal bone (the attachment of the stylohyoid","The pterygoid process and its associated anatomical structures","The mastoid process and its associated anatomical structures","The condylar process and its associated anatomical structures"]'::jsonb, 'A long, slender bony projection from the temporal bone (the attachment of the stylohyoid', 'The styloid process (a remnant of the second branchial arch) is variable in length (Eagle syndrome when elongated >3 cm).'),
('38fe2cd7-669a-5ce8-9694-8f5f3ee63881'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The stylomastoid foramen:', '["The hypoglossal canal and its associated anatomical structures","Between the styloid and mastoid processes","The foramen rotundum and its associated anatomical structures","The jugular foramen and its associated anatomical structures","The foramen ovale and its associated anatomical structures"]'::jsonb, 'Between the styloid and mastoid processes', 'The stylomastoid foramen is a landmark for the facial nerve (the nerve is vulnerable to injury in mastoid surgery).'),
('00174673-d805-5904-8514-333db3478da9'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The mastoid antrum:', '["An air-filled cavity in the petrous temporal bone (communicates with the middle ear and the masto","The eustachian tube and its associated anatomical structures","The inner ear and its associated anatomical structures","The external auditory meatus and its associated anatomical structures","The middle ear cavity and its associated anatomical structures"]'::jsonb, 'An air-filled cavity in the petrous temporal bone (communicates with the middle ear and the masto', 'The mastoid antrum (the key to mastoid surgery) is located 1.5 cm deep to the suprameatal triangle (Macewen triangle).'),
('69b665e8-69e3-56d4-bb85-db4b0d2631b4'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The tegmen tympani:', '["The posterior wall of the middle ear and its associated anatomical structures","A thin plate of bone (the roof of the middle ear and the mastoid antrum — separates the middle ea","The medial wall of the middle ear and its associated anatomical structures","The floor of the middle ear and its associated anatomical structures","The lateral wall of the middle ear and its associated anatomical structures"]'::jsonb, 'A thin plate of bone (the roof of the middle ear and the mastoid antrum — separates the middle ea', 'The tegmen tympani (a thin bone) can be eroded by cholesteatoma, causing intracranial complications (meningitis, brain abscess).'),
('9bec1973-3d60-54a2-b416-26d0202247ed'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The sigmoid sinus groove:', '["The groove for the middle meningeal artery and its associated anatomical structures","The groove for the superior sagittal sinus and its associated anatomical structures","The groove for the inferior petrosal sinus and its associated anatomical structures","The groove for the cavernous sinus and its associated anatomical structures","A groove on the inner surface of the mastoid (the course of the sigmoid sinus — the direct contin"]'::jsonb, 'A groove on the inner surface of the mastoid (the course of the sigmoid sinus — the direct contin', 'The sigmoid sinus (located posterior to the mastoid antrum) is at risk during mastoid surgery (sigmoid sinus thrombosis).'),
('340993ed-2ac9-510b-9f8c-81152dde173a'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The middle meningeal artery grooves:', '["The frontal bone and its associated anatomical structures","The inner surface of the squamous temporal and parietal bones (the artery runs in the epidural sp","The occipital bone and its associated anatomical structures","The sphenoid bone and its associated anatomical structures","The ethmoid bone and its associated anatomical structures"]'::jsonb, 'The inner surface of the squamous temporal and parietal bones (the artery runs in the epidural sp', 'The middle meningeal artery (the epidural artery) enters the skull through the foramen spinosum and divides into anterior and posterior branches.'),
('cc80aec0-ec72-56a9-b488-bdb41b30b7af'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The sphenoid bone is:', '["A triangular bone and its associated anatomical structures","A butterfly-shaped bone at the base of the skull (the keystone of the cranial floor","A curved bone and its associated anatomical structures","A flat bone and its associated anatomical structures","A C-shaped bone and its associated anatomical structures"]'::jsonb, 'A butterfly-shaped bone at the base of the skull (the keystone of the cranial floor', 'The sphenoid bone (the central bone of the skull base) has a body, two lesser wings, two greater wings, and two pterygoid processes.'),
('4e7e63de-a7af-521e-8ab0-1f318f414e50'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The sella turcica (pituitary fossa):', '["The optic groove and its associated anatomical structures","The tuberculum sellae and its associated anatomical structures","A saddle-shaped depression in the body of the sphenoid bone","The dorsum sellae and its associated anatomical structures","The sphenoid sinus and its associated anatomical structures"]'::jsonb, 'A saddle-shaped depression in the body of the sphenoid bone', 'The sella turcica (Turk saddle) houses the pituitary gland. The roof is the diaphragma sellae (a dural fold).'),
('f91f0c76-1042-5f1a-8cca-f3c44fb43677'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The tuberculum sellae is:', '["The sphenoid crest","The posterior boundary of the sella","The dorsum sellae","The clivus","A bony ridge anterior to the sella turcica"]'::jsonb, 'A bony ridge anterior to the sella turcica', 'The tuberculum sellae (anterior to the sella) is a landmark for the suprasellar cistern (tuberculum sellae meningiomas).'),
('f43e0c68-8d75-5fa9-8852-3bea65f8f5a0'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The dorsum sellae is:', '["The sphenoid rostrum and its associated anatomical structures","The clivus and its associated anatomical structures","A square plate of bone posterior to the sella turcica (the posterior boundary of the pituitary fo","The tuberculum sellae and its associated anatomical structures","The anterior boundary and its associated anatomical structures"]'::jsonb, 'A square plate of bone posterior to the sella turcica (the posterior boundary of the pituitary fo', 'The dorsum sellae (posterior clinoid processes) is the attachment of the petrosphenoid ligament (Dorello canal transmits CN VI).'),
('6839bb3c-4607-5083-babe-620e3ecd626f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The anterior clinoid processes:', '["The posterior clinoid processes and its associated anatomical structures","The pterygoid processes and its associated anatomical structures","The temporal processes and its associated anatomical structures","The zygomatic processes and its associated anatomical structures","Projections of the lesser wings of the sphenoid (the attachment of the falciform ligament and the"]'::jsonb, 'Projections of the lesser wings of the sphenoid (the attachment of the falciform ligament and the', 'The anterior clinoid processes (the roof of the cavernous sinus) are removed surgically to access the ophthalmic artery aneurysms.'),
('d3fbf11c-9d18-5f20-b36d-9860130b2c06'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The posterior clinoid processes:', '["The pterygoid processes and its associated anatomical structures","The zygomatic processes and its associated anatomical structures","Projections of the dorsum sellae (the attachment of the tentorium cerebelli and the petrosphenoid","The anterior clinoid processes and its associated anatomical structures","The mastoid processes and its associated anatomical structures"]'::jsonb, 'Projections of the dorsum sellae (the attachment of the tentorium cerebelli and the petrosphenoid', 'The posterior clinoid processes (part of the dorsum sellae) are the posterior boundary of the sella turcica.'),
('eea9825a-1660-5aaf-bd06-14d097cfd764'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The optic groove (sulcus chiasmaticus):', '["A transverse groove on the body of the sphenoid (between the optic canals — contains the optic ch","The sphenoid sinus and its associated anatomical structures","The clivus and its associated anatomical structures","The tuberculum sellae and its associated anatomical structures","The sella turcica and its associated anatomical structures"]'::jsonb, 'A transverse groove on the body of the sphenoid (between the optic canals — contains the optic ch', 'The optic groove (prechiasmatic sulcus) is bounded by the tuberculum sellae posteriorly and the optic canals laterally.'),
('a224754e-1d04-5db3-8f50-1652fa792fb1'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The clivus is:', '["The sella turcica and its associated anatomical structures","The sphenoid sinus and its associated anatomical structures","The floor of the middle cranial fossa and its associated anatomical structures","The sloping bone surface from the dorsum sellae to the foramen magnum (the anterior boundary of t","The temporal bone and its associated anatomical structures"]'::jsonb, 'The sloping bone surface from the dorsum sellae to the foramen magnum (the anterior boundary of t', 'The clivus (the basiocciput) supports the pons and the medulla oblongata (clival chordomas are rare tumors of the skull base).'),
('55b1706c-8ae0-5daf-a816-05f2c267b189'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The optic canal is:', '["The foramen rotundum and its associated anatomical structures","The foramen spinosum and its associated anatomical structures","A short canal in the lesser wing of the sphenoid (transmits the optic nerve and the ophthalmic ar","The superior orbital fissure and its associated anatomical structures","The foramen ovale and its associated anatomical structures"]'::jsonb, 'A short canal in the lesser wing of the sphenoid (transmits the optic nerve and the ophthalmic ar', 'The optic canal (optic strut) connects the middle cranial fossa to the orbit (optic nerve compression here causes visual loss).'),
('bd4de804-ea1d-5ddd-97a9-a6b22b1b8a66'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The superior orbital fissure:', '["A slit between the lesser and greater wings of the sphenoid (transmits CN III, IV, V1, VI","The foramen rotundum and its associated anatomical structures","The optic canal and its associated anatomical structures","The foramen ovale and its associated anatomical structures","The inferior orbital fissure and its associated anatomical structures"]'::jsonb, 'A slit between the lesser and greater wings of the sphenoid (transmits CN III, IV, V1, VI', 'The superior orbital fissure (SOF) syndrome (trauma or tumors) causes ophthalmoplegia and ptosis.'),
('55bb841c-a053-5687-9e8b-17467a8bcb5a'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The foramen rotundum opens into:', '["The infratemporal fossa","The orbit","The middle ear","The pterygopalatine fossa","The nasal cavity"]'::jsonb, 'The pterygopalatine fossa', 'The foramen rotundum (in the greater wing of the sphenoid) is a landmark for the pterygopalatine fossa.'),
('077da120-0ef7-5006-81b8-38b3a8456942'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The foramen ovale opens into:', '["The infratemporal fossa (transmits the mandibular nerve CN V3, the accessory meningeal artery","The nasal cavity and its associated anatomical structures","The pterygopalatine fossa and its associated anatomical structures","The orbit and its associated anatomical structures","The middle cranial fossa and its associated anatomical structures"]'::jsonb, 'The infratemporal fossa (transmits the mandibular nerve CN V3, the accessory meningeal artery', 'The foramen ovale (posterolateral to the foramen rotundum) is a target for percutaneous trigeminal rhizotomy.'),
('7197ef2e-93aa-57cd-a036-c6e67134efc3'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The foramen spinosum:', '["The foramen rotundum and its associated anatomical structures","A small foramen posterolateral to the foramen ovale","The jugular foramen and its associated anatomical structures","The foramen ovale and its associated anatomical structures","The carotid canal and its associated anatomical structures"]'::jsonb, 'A small foramen posterolateral to the foramen ovale', 'The foramen spinosum (sphenoid bone) is a landmark for the middle meningeal artery in middle cranial fossa surgery.'),
('d4a03ea2-d42c-5b67-8984-354196cbad1b'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The emissary sphenoidal foramen (foramen of Vesalius):', '["The foramen rotundum and its associated anatomical structures","An inconstant foramen medial to the foramen ovale (transmits an emissary vein from the cavernous","The foramen ovale and its associated anatomical structures","The foramen lacerum and its associated anatomical structures","The foramen spinosum and its associated anatomical structures"]'::jsonb, 'An inconstant foramen medial to the foramen ovale (transmits an emissary vein from the cavernous', 'The foramen of Vesalius (sphenoidal emissary foramen) is present in 40% of skulls and is a route for infection spread.'),
('3bb1525c-1cba-5313-816e-8704e257f3a2'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'On diagnostic evaluation, The foramen lacerum:', '["Transmits the hypoglossal nerve and its associated anatomical structures","A closed foramen (filled by fibrocartilage in life) at the junction of the sphenoid, temporal","Transmits the internal carotid artery and its associated anatomical structures","An open canal and its associated anatomical structures","Transmits the jugular vein and its associated anatomical structures"]'::jsonb, 'A closed foramen (filled by fibrocartilage in life) at the junction of the sphenoid, temporal', 'The foramen lacerum (the ICA passes over the foramen lacerum, not through it — the ICA enters the skull through the carotid canal).'),
('eab56691-c1af-5bf9-9ef0-c2970a955330'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The carotid canal:', '["A canal in the petrous temporal bone (transmits the internal carotid artery and the sympathetic p","The jugular foramen and its associated anatomical structures","The hypoglossal canal and its associated anatomical structures","The foramen lacerum and its associated anatomical structures","The foramen magnum and its associated anatomical structures"]'::jsonb, 'A canal in the petrous temporal bone (transmits the internal carotid artery and the sympathetic p', 'The carotid canal (in the petrous temporal bone) has a vertical and a horizontal segment (the ICA turns forward in the horizontal segment).'),
('ee563627-a367-569c-8b6f-93aa540c0ca3'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The jugular foramen is divided by:', '["The mastoid process and its associated anatomical structures","The dural folds and its associated anatomical structures","The carotid sheath and its associated anatomical structures","A bony spur (the intrajugular process) into an anteromedial (nervous) part and a posterolateral (","The styloid process and its associated anatomical structures"]'::jsonb, 'A bony spur (the intrajugular process) into an anteromedial (nervous) part and a posterolateral (', 'The jugular foramen (the largest foramen in the skull base) transmits CN IX, X, XI and the IJV. The venous part is the larger (the jugular bulb).'),
('b4d0f5df-63c5-54de-ae76-c231e4e1a302'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The jugular bulb:', '["The torcular herophili and its associated anatomical structures","The dilated upper end of the internal jugular vein in the jugular foramen","The confluence of sinuses and its associated anatomical structures","The sigmoid sinus and its associated anatomical structures","The cavernous sinus and its associated anatomical structures"]'::jsonb, 'The dilated upper end of the internal jugular vein in the jugular foramen', 'A high-riding jugular bulb (a normal variant) can cause conductive hearing loss or pulsatile tinnitus.'),
('b4ef2e2b-2545-5359-a97b-c80e95f6e56f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The internal acoustic meatus:', '["The jugular foramen","The hypoglossal canal","The foramen magnum","The external acoustic meatus","A canal in the petrous temporal bone"]'::jsonb, 'A canal in the petrous temporal bone', 'The internal acoustic meatus (IAM) on the posteromedial surface of the petrous temporal bone opens into the posterior cranial fossa.'),
('a03a6028-2f88-5e30-b395-382fc52c32b9'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The subarcuate fossa:', '["The vestibular aqueduct and its associated anatomical structures","The internal acoustic meatus and its associated anatomical structures","A small depression above the internal acoustic meatus (contains a small dural process and a branc","The jugular foramen and its associated anatomical structures","The cochlear aqueduct and its associated anatomical structures"]'::jsonb, 'A small depression above the internal acoustic meatus (contains a small dural process and a branc', 'The subarcuate fossa (in the petrous temporal bone) is a remnant of the subarcuate tract in the developing temporal bone.'),
('8cff6ba5-64bf-5c2e-a55f-cf091f944afc'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The vestibular aqueduct:', '["The cochlear aqueduct and its associated anatomical structures","A small canal in the petrous temporal bone (transmits the endolymphatic duct from the vestibule t","The internal acoustic meatus and its associated anatomical structures","The carotid canal and its associated anatomical structures","The facial canal and its associated anatomical structures"]'::jsonb, 'A small canal in the petrous temporal bone (transmits the endolymphatic duct from the vestibule t', 'Enlarged vestibular aqueduct (LVA/EVA) is the most common cause of congenital sensorineural hearing loss (Mondini dysplasia).'),
('505886a8-528f-5460-b482-82b9369b995e'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The cochlear aqueduct:', '["The petrosal canal and its associated anatomical structures","The endolymphatic duct and its associated anatomical structures","The vestibular aqueduct and its associated anatomical structures","The internal acoustic meatus and its associated anatomical structures","A small canal that connects the perilymphatic space (scala tympani) to the subarachnoid space (a"]'::jsonb, 'A small canal that connects the perilymphatic space (scala tympani) to the subarachnoid space (a', 'The cochlear aqueduct (perilymphatic duct) transmits a small vein and perilymph (may communicate with CSF in some species).'),
('567098f5-ff49-5369-8460-60f54c8eef43'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The facial canal (Fallopian canal):', '["The carotid canal and its associated anatomical structures","The superior canal and its associated anatomical structures","A Z-shaped canal in the petrous temporal bone (the course of the facial nerve from the IAM to the","The lateral canal and its associated anatomical structures","The internal acoustic meatus and its associated anatomical structures"]'::jsonb, 'A Z-shaped canal in the petrous temporal bone (the course of the facial nerve from the IAM to the', 'The facial canal (30 mm) has three segments: labyrinthine (shortest, narrowest), tympanic (horizontal), and mastoid (vertical).'),
('1e4d83dd-887a-5714-a112-1e03e0447a83'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The geniculate ganglion:', '["The otic ganglion and its associated anatomical structures","The trigeminal ganglion and its associated anatomical structures","A sensory ganglion of the facial nerve at the first bend of the facial canal (contains the cell b","The vestibular ganglion and its associated anatomical structures","The spiral ganglion and its associated anatomical structures"]'::jsonb, 'A sensory ganglion of the facial nerve at the first bend of the facial canal (contains the cell b', 'The geniculate ganglion (geniculate = knee) is a key landmark in the facial nerve. Geniculate neuralgia is a rare cause of facial pain.'),
('f2666f2d-2fcc-597b-a89d-4ec44f7dfa9b'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The greater petrosal nerve:', '["A branch of the facial nerve (from the geniculate ganglion) — carries parasympathetic fibers to t","The nerve of the pterygoid canal and its associated anatomical structures","The lesser petrosal nerve and its associated anatomical structures","The deep petrosal nerve and its associated anatomical structures","The chorda tympani and its associated anatomical structures"]'::jsonb, 'A branch of the facial nerve (from the geniculate ganglion) — carries parasympathetic fibers to t', 'The greater petrosal nerve (CN VII) runs in a groove on the petrous temporal bone (petrosal nerve resection for crocodile tears).'),
('533e2a83-a53c-561a-9a86-4d1e65ccd0e6'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The lesser petrosal nerve:', '["A branch of the glossopharyngeal nerve (CN IX) — carries parasympathetic fibers to the otic gangl","The nerve of the pterygoid canal and its associated anatomical structures","The deep petrosal nerve and its associated anatomical structures","The chorda tympani and its associated anatomical structures","The greater petrosal nerve and its associated anatomical structures"]'::jsonb, 'A branch of the glossopharyngeal nerve (CN IX) — carries parasympathetic fibers to the otic gangl', 'The lesser petrosal nerve (from the tympanic plexus of CN IX) passes through the foramen ovale to the otic ganglion.'),
('0a1c5dea-98d0-5c94-9a7d-46878f8e1a4f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The chorda tympani nerve:', '["The lesser petrosal nerve and its associated anatomical structures","The greater petrosal nerve and its associated anatomical structures","The tympanic nerve and its associated anatomical structures","A branch of CN VII that enters the middle ear (carries taste from the anterior 2/3 of the tongue","The deep petrosal nerve and its associated anatomical structures"]'::jsonb, 'A branch of CN VII that enters the middle ear (carries taste from the anterior 2/3 of the tongue', 'The chorda tympani passes between the incus and the malleus (crosses the tympanic membrane — may be injured in middle ear surgery).'),
('4d100b63-7990-5cb9-a910-23062b085547'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The tympanic membrane (eardrum):', '["The oval window and its associated anatomical structures","The round window and its associated anatomical structures","The Eustachian tube and its associated anatomical structures","The tympanic cavity and its associated anatomical structures","A thin, translucent membrane (8-10 mm) that separates the external ear from the middle ear (vibra"]'::jsonb, 'A thin, translucent membrane (8-10 mm) that separates the external ear from the middle ear (vibra', 'The tympanic membrane (three layers: skin, fibrous, mucous) has a pars tensa (the main part) and a pars flaccida (the attic/Shrapnell membrane).'),
('789f16e8-c1cc-5c11-a541-283b04ea2154'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The umbo of the tympanic membrane:', '["The malleolar fold","The pars flaccida","The annulus","The central depression","The cone of light"]'::jsonb, 'The central depression', 'The umbo (the most retracted point of the tympanic membrane) is the landmark for the cone of light reflex (otoscopy).'),
('8df91398-8a0a-5036-8843-3f483c79e44d'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The cone of light:', '["The pars flaccida and its associated anatomical structures","The umbo and its associated anatomical structures","The annulus and its associated anatomical structures","A triangular reflection of light on the tympanic membrane (anteroinferior quadrant — a normal oto","The malleolar stripe and its associated anatomical structures"]'::jsonb, 'A triangular reflection of light on the tympanic membrane (anteroinferior quadrant — a normal oto', 'The cone of light (the light reflex) is absent in middle ear effusion (the drum is dull and retracted).'),
('3e91b98f-6e18-59d1-9616-caa11c1113f6'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The middle ear (tympanic cavity):', '["An air-filled cavity in the petrous temporal bone (contains the ossicles — malleus, incus","The eustachian tube and its associated anatomical structures","The external ear and its associated anatomical structures","The inner ear and its associated anatomical structures","The mastoid and its associated anatomical structures"]'::jsonb, 'An air-filled cavity in the petrous temporal bone (contains the ossicles — malleus, incus', 'The middle ear (2 cm long, 1 cm high, 5-6 mm deep) communicates with the nasopharynx via the eustachian tube.'),
('20f0e6e4-2130-5b2d-bc44-b0c0f664b91b'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The ossicles of the middle ear:', '["The cochlea and its associated anatomical structures","Malleus (hammer), incus (anvil), and stapes (stirrup) — transmit vibrations from the tympanic mem","The auditory nerve and its associated anatomical structures","The semicircular canals and its associated anatomical structures","The tympanic membrane and its associated anatomical structures"]'::jsonb, 'Malleus (hammer), incus (anvil), and stapes (stirrup) — transmit vibrations from the tympanic mem', 'The ossicles (the three smallest bones in the body) amplify the sound pressure by a factor of 1.3 (lever ratio) and 17 (area ratio).'),
('a258488e-e946-53ff-8492-b80858764610'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The oval window (fenestra vestibuli):', '["The vestibule and its associated anatomical structures","The semicircular canal and its associated anatomical structures","The round window and its associated anatomical structures","The opening in the medial wall of the middle ear (covered by the footplate of the stapes — transm","The cochlea and its associated anatomical structures"]'::jsonb, 'The opening in the medial wall of the middle ear (covered by the footplate of the stapes — transm', 'The oval window (2.5 x 1.5 mm) is the interface between the middle ear and the inner ear (stapedectomy for otosclerosis).'),
('83388597-9613-5095-892e-4b1e06e9be14'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The round window (fenestra cochleae):', '["A membrane-covered opening in the middle ear (allows the perilymph to move in response to stapes","The oval window and its associated anatomical structures","The cochlea and its associated anatomical structures","The semicircular canal and its associated anatomical structures","The vestibule and its associated anatomical structures"]'::jsonb, 'A membrane-covered opening in the middle ear (allows the perilymph to move in response to stapes', 'The round window (the secondary tympanic membrane) is important for cochlear mechanics (the round window reflex is used in cochlear implant assessment).'),
('797400e5-6785-562d-856b-408218b8ff57'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The Eustachian (pharyngotympanic) tube:', '["Connects the middle ear to the external ear","Connects the inner ear to the pharynx","Connects the middle ear to the nasopharynx","Connects the middle ear to the mastoid","Connects the nose to the throat"]'::jsonb, 'Connects the middle ear to the nasopharynx', 'The eustachian tube (4 cm in adults, shorter and more horizontal in children) is opened by the tensor veli palatini.'),
('c948aa9f-0edc-5b7f-8482-a039beef19e9'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The inner ear (labyrinth) consists of:', '["The bony labyrinth (cochlea, vestibule, semicircular canals) and the membranous labyrinth","Only the cochlea and its associated anatomical structures","The external ear and the tympanic membrane and its associated anatomical structures","The middle ear and the ossicles and its associated anatomical structures","Only the semicircular canals and its associated anatomical structures"]'::jsonb, 'The bony labyrinth (cochlea, vestibule, semicircular canals) and the membranous labyrinth', 'The inner ear (the organ of hearing and balance) is embedded in the petrous temporal bone (the hardest bone in the body).'),
('1cd0285b-1dd4-5195-bedc-6906b5614cc9'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The cochlea is:', '["A spiral, snail-shaped structure","The saccule","The vestibule","The semicircular canal","The utricle"]'::jsonb, 'A spiral, snail-shaped structure', 'The cochlea (2.5 turns in humans) converts sound waves into neural signals (the hair cells of the organ of Corti).'),
('8c921d05-b72d-5d62-bd8f-1dfd8e0ebabb'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The organ of Corti:', '["The otolithic membrane and its associated anatomical structures","The sensory epithelium of the cochlea (contains inner and outer hair cells — the receptors for he","The crista ampullaris and its associated anatomical structures","The macula and its associated anatomical structures","The vestibular apparatus and its associated anatomical structures"]'::jsonb, 'The sensory epithelium of the cochlea (contains inner and outer hair cells — the receptors for he', 'The organ of Corti (on the basilar membrane) has one row of inner hair cells (afferent, 95% of CN VIII fibers) and three rows of outer hair cells (efferent, cochlear amplifier).'),
('23d3f5de-d7c2-55f4-be4e-be594fb7757c'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The vestibule:', '["The semicircular canals and its associated anatomical structures","The modiolus and its associated anatomical structures","The central part of the inner ear (contains the saccule and utricle — the otolithic organs for li","The organ of Corti and its associated anatomical structures","The cochlea and its associated anatomical structures"]'::jsonb, 'The central part of the inner ear (contains the saccule and utricle — the otolithic organs for li', 'The vestibule (the cavity between the cochlea and the semicircular canals) contains the sensory maculae for gravity and linear acceleration.'),
('0688bd87-5c3d-53f4-94eb-01eb306329f9'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The saccule and utricle:', '["The cochlea and its associated anatomical structures","The cristae and its associated anatomical structures","Otolithic organs in the vestibule (detect linear acceleration and gravity — contain maculae with","The semicircular canals and its associated anatomical structures","The organ of Corti and its associated anatomical structures"]'::jsonb, 'Otolithic organs in the vestibule (detect linear acceleration and gravity — contain maculae with', 'The saccule (vertical, detects vertical acceleration) and the utricle (horizontal, detects horizontal acceleration) are oriented at right angles to each other.'),
('58be6197-972e-5688-aa62-d9219544e080'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The semicircular canals:', '["The vestibule and its associated anatomical structures and its associated structures","The utricle and its associated anatomical structures and its associated structures","The cochlea and its associated anatomical structures and its associated structures","The saccule and its associated anatomical structures and its associated structures","Three mutually perpendicular canals (superior, lateral, posterior) that detect rotational (angular"]'::jsonb, 'Three mutually perpendicular canals (superior, lateral, posterior) that detect rotational (angular', 'The semicircular canals (bony, 6.5 mm in diameter) contain the membranous semicircular ducts with the crista ampullaris at one end.'),
('edd9a3ad-1dda-568c-9d6d-28fa9a9abd5e'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The ampulla of the semicircular canal:', '["The macula and its associated anatomical structures","The organ of Corti and its associated anatomical structures","The saccule and its associated anatomical structures","The dilated end of each semicircular canal (contains the crista ampullaris — the sensory organ fo","The utricle and its associated anatomical structures"]'::jsonb, 'The dilated end of each semicircular canal (contains the crista ampullaris — the sensory organ fo', 'The crista ampullaris (hair cells embedded in the cupula) detects endolymph movement during head rotation (BPPV involves canalithiasis).'),
('809cfee5-432b-5e26-ba46-08f995c2c99d'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The endolymphatic duct and sac:', '["The semicircular duct and its associated anatomical structures","The perilymphatic duct and its associated anatomical structures","The vestibular aqueduct and its associated anatomical structures","A membranous duct that drains endolymph from the membranous labyrinth to the endolymphatic sac (i","The cochlear aqueduct and its associated anatomical structures"]'::jsonb, 'A membranous duct that drains endolymph from the membranous labyrinth to the endolymphatic sac (i', 'The endolymphatic sac (in the subarcuate fossa) absorbs endolymph (Meniere disease is associated with endolymphatic hydrops).'),
('4a219fc2-1404-5a93-9d29-78f5668b2167'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The perilymph:', '["Cerebrospinal fluid and its associated anatomical structures","Blood plasma and its associated anatomical structures","The fluid in the bony labyrinth (surrounds the membranous labyrinth — similar to extracellular fl","The fluid in the membranous labyrinth and its associated anatomical structures","Lymph and its associated anatomical structures"]'::jsonb, 'The fluid in the bony labyrinth (surrounds the membranous labyrinth — similar to extracellular fl', 'Perilymph (high Na, low K) is located in the scala vestibuli and scala tympani (the scala media contains endolymph).'),
('129b5d78-f172-56bd-af76-31a692b8f7bd'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The endolymph:', '["Cerebrospinal fluid","The fluid in the membranous labyrinth","Blood plasma","The fluid in the bony labyrinth","Lymph"]'::jsonb, 'The fluid in the membranous labyrinth', 'Endolymph (high K, low Na) is produced by the stria vascularis in the cochlea (endocochlear potential +80 mV).'),
('978439e0-6fe6-552e-bba1-7133dd286dcb'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The facial nerve (CN VII) in the cranium:', '["Exits the brainstem at the pontomedullary junction, passes through the internal acoustic meatus a","Exits at the foramen rotundum and its associated anatomical structures","Exits at the optic canal and its associated anatomical structures","Exits at the foramen ovale and its associated anatomical structures","Exits at the jugular foramen and its associated anatomical structures"]'::jsonb, 'Exits the brainstem at the pontomedullary junction, passes through the internal acoustic meatus a', 'The facial nerve (motor, sensory, and parasympathetic) has an extra-axial course of about 3 cm from the brainstem to the IAM.'),
('01516208-2039-5b32-8b95-3cf3acfdf9e6'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The vestibulocochlear nerve (CN VIII):', '["Exits the brainstem at the pontomedullary junction, passes through the internal acoustic meatus","Exits at the foramen rotundum and its associated anatomical structures","Exits at the jugular foramen and its associated anatomical structures","Exits at the foramen ovale and its associated anatomical structures","Exits at the hypoglossal canal and its associated anatomical structures"]'::jsonb, 'Exits the brainstem at the pontomedullary junction, passes through the internal acoustic meatus', 'The vestibulocochlear nerve (CN VIII) is the nerve of hearing and balance (acoustic neuroma is a schwannoma of CN VIII).'),
('3761648f-480f-52ec-9476-53c47db037eb'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The glossopharyngeal nerve (CN IX) exits the skull through:', '["The hypoglossal canal","The stylomastoid foramen","The jugular foramen","The foramen ovale","The foramen rotundum"]'::jsonb, 'The jugular foramen', 'CN IX (mixed nerve) exits the posterolateral sulcus of the medulla and passes through the jugular foramen.'),
('0857e936-137c-5bae-9864-5aa97672ed42'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The vagus nerve (CN X) exits the skull through:', '["The foramen ovale","The stylomastoid foramen","The carotid canal","The foramen magnum","The jugular foramen"]'::jsonb, 'The jugular foramen', 'CN X (the longest cranial nerve) emerges from the medulla between the olive and the pyramid and passes through the jugular foramen.'),
('d7aa7487-560f-5dd7-92fd-1e41009eb03f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The spinal accessory nerve (CN XI) exits the skull through:', '["The foramen ovale","The foramen magnum","The stylomastoid foramen","The jugular foramen","The hypoglossal canal"]'::jsonb, 'The jugular foramen', 'CN XI (accessory nerve) has two roots: the cranial root (from the medulla, joins the vagus) and the spinal root (from C1-C5, supplies SCM and trapezius).'),
('25ff8e8e-6046-564a-a60b-ed05c9f65d0e'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The hypoglossal nerve (CN XII) exits the skull through:', '["The hypoglossal canal","The jugular foramen","The stylomastoid foramen","The foramen ovale","The foramen magnum"]'::jsonb, 'The hypoglossal canal', 'CN XII (motor to the tongue) emerges from the preolivary sulcus of the medulla and passes through the hypoglossal canal.'),
('8243521a-6758-5774-a330-ed08ba0ad5e0'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The trigeminal nerve (CN V) exits the brainstem:', '["At the spinal cord","At the midbrain","At the midlateral pons","At the cerebellum","At the medulla"]'::jsonb, 'At the midlateral pons', 'CN V (the trigeminal nerve) has the largest sensory root of all cranial nerves (the motor root is the nerve of the first branchial arch).'),
('a543dbb0-6c45-5cd4-8ac7-992b6c5a986e'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The abducens nerve (CN VI) exits the brainstem:', '["At the spinal cord","At the medulla","At the midbrain","At the pontomedullary junction","At the lateral pons"]'::jsonb, 'At the pontomedullary junction', 'CN VI (the abducens, motor to the lateral rectus) has the longest intracranial course (vulnerable to increased ICP, causing CN VI palsy).'),
('3d575ddd-2283-507b-8d9a-edbbb4652c76'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The facial nerve (CN VII) exits the brainstem:', '["At the medulla","At the pontomedullary junction","At the pons","At the spinal cord","At the midbrain"]'::jsonb, 'At the pontomedullary junction', 'CN VII (facial nerve) emerges at the cerebellopontine angle (CPA) between the pons and the medulla.'),
('8311c8ad-2c9a-56a0-b465-f8c671bd7ca8'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The vestibulocochlear nerve (CN VIII) exits the brainstem:', '["At the midbrain","At the spinal cord","At the pons","At the pontomedullary junction","At the medulla"]'::jsonb, 'At the pontomedullary junction', 'CN VIII (vestibulocochlear nerve) is located in the cerebellopontine angle (acoustic neuroma compresses the CPA structures).'),
('9f53fa21-942d-5d06-9a9d-3818e796b3de'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The glossopharyngeal nerve (CN IX) exits the brainstem:', '["At the posterolateral sulcus of the medulla","At the midline","At the anterolateral sulcus","At the pons","At the midbrain"]'::jsonb, 'At the posterolateral sulcus of the medulla', 'CN IX (glossopharyngeal) emerges from the medulla in the retro-olivary groove (posterolateral sulcus).'),
('3c8f0f99-3f66-5cf5-be5b-c850aff84ca2'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The vagus nerve (CN X) exits the brainstem:', '["At the anterolateral sulcus","At the posterolateral sulcus of the medulla","At the pons","At the midbrain","At the midline"]'::jsonb, 'At the posterolateral sulcus of the medulla', 'CN X (vagus) emerges from the medulla just below CN IX (the three nerves CN IX, X, XI are in a row in the retro-olivary groove).'),
('4a7e5c39-ee63-595c-9b3b-e61e718233cf'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The spinal accessory nerve (CN XI) exits the brainstem:', '["The cranial root exits the posterolateral sulcus (the spinal root ascends from the spinal cord th","At the midline and its associated anatomical structures","At the midbrain and its associated anatomical structures","At the pons and its associated anatomical structures","At the anterolateral sulcus and its associated anatomical structures"]'::jsonb, 'The cranial root exits the posterolateral sulcus (the spinal root ascends from the spinal cord th', 'The spinal accessory nerve (CN XI) is unique in having a spinal origin (the spinal root ascends and joins the cranial root briefly).'),
('db64d8a3-75f2-56e4-a2b7-7f30b7986f79'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The hypoglossal nerve (CN XII) exits the brainstem:', '["At the anterolateral sulcus (preolivary sulcus) of the medulla","At the midbrain and its associated anatomical structures","At the posterolateral sulcus and its associated anatomical structures","At the midline and its associated anatomical structures","At the pons and its associated anatomical structures"]'::jsonb, 'At the anterolateral sulcus (preolivary sulcus) of the medulla', 'CN XII (hypoglossal) emerges as a series of rootlets in the preolivary sulcus of the medulla (motor to the tongue).'),
('dc73f319-6059-5aee-888f-310f081e6081'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The cerebellum is located:', '["In the middle cranial fossa","Above the tentorium","In the anterior cranial fossa","In the posterior cranial fossa","In the supratentorial compartment"]'::jsonb, 'In the posterior cranial fossa', 'The cerebellum (the little brain) is the largest part of the hindbrain (coordinates movement, balance, and posture).'),
('6632e83f-b0e6-5944-aa61-408391bcdec4'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The cerebellar hemispheres and the vermis:', '["Three lobes","Two hemispheres (the lateral masses) and the vermis","Four lobes","Two lobes separated by the vermis","A single lobe"]'::jsonb, 'Two hemispheres (the lateral masses) and the vermis', 'The cerebellum is divided into the anterior lobe, the posterior lobe (the largest), and the flocculonodular lobe.'),
('605e5913-4262-5440-862f-eead282fd668'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The cerebellar tonsils:', '["Two rounded lobules on the inferior surface of the cerebellum (herniate through the foramen magnu","The vermis and its associated anatomical structures","The cerebellar hemispheres and its associated anatomical structures","The nodulus and its associated anatomical structures","The flocculus and its associated anatomical structures"]'::jsonb, 'Two rounded lobules on the inferior surface of the cerebellum (herniate through the foramen magnu', 'Tonsillar herniation (coning) compresses the medulla and is life-threatening (requires urgent decompression).'),
('cbf8866a-9e3a-5aa5-86b9-0e7203d2081f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The tentorium cerebelli:', '["The tentorial notch and its associated anatomical structures","The falx cerebri and its associated anatomical structures","The falx cerebelli and its associated anatomical structures","The diaphragma sellae and its associated anatomical structures","A dural fold that separates the cerebellum (infratentorial) from the occipital lobes (supratentor"]'::jsonb, 'A dural fold that separates the cerebellum (infratentorial) from the occipital lobes (supratentor', 'The tentorium cerebelli (tent-shaped) has a free edge (the tentorial notch/incisura) where the midbrain passes through.'),
('a903e0ff-4628-5480-854e-3a35ff710403'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The falx cerebri:', '["The diaphragma sellae and its associated anatomical structures","The falx cerebelli and its associated anatomical structures","The tentorial notch and its associated anatomical structures","A dural fold in the sagittal plane (separates the two cerebral hemispheres","The tentorium cerebelli and its associated anatomical structures"]'::jsonb, 'A dural fold in the sagittal plane (separates the two cerebral hemispheres', 'The falx cerebri (sickle-shaped) attaches to the crista galli anteriorly and the tentorium cerebelli posteriorly.'),
('87d37823-d00e-5fa1-9f2e-04b08c8472d2'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The falx cerebelli:', '["The falx cerebri and its associated anatomical structures","The petroclinoid fold and its associated anatomical structures","A small dural fold in the posterior cranial fossa (separates the cerebellar hemispheres","The diaphragma sellae and its associated anatomical structures","The tentorium cerebelli and its associated anatomical structures"]'::jsonb, 'A small dural fold in the posterior cranial fossa (separates the cerebellar hemispheres', 'The falx cerebelli (a small sickle) attaches from the internal occipital crest to the foramen magnum.'),
('a00be926-f578-55db-883c-e9233ad0c3da'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The diaphragma sellae:', '["The tentorium cerebelli and its associated anatomical structures","The cavernous sinus roof and its associated anatomical structures","A dural roof over the pituitary fossa (covers the pituitary gland, with a small opening for the p","The falx cerebri and its associated anatomical structures","The falx cerebelli and its associated anatomical structures"]'::jsonb, 'A dural roof over the pituitary fossa (covers the pituitary gland, with a small opening for the p', 'The diaphragma sellae (a horizontal dural fold) separates the pituitary from the suprasellar cistern.'),
('986117f7-f124-5ef7-9997-a649e6522e3b'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The cavernous sinus:', '["The sigmoid sinus and its associated anatomical structures","A paired dural venous sinus lateral to the sella turcica (contains CN III, IV, V1, V2, VI","The straight sinus and its associated anatomical structures","The transverse sinus and its associated anatomical structures","The superior sagittal sinus and its associated anatomical structures"]'::jsonb, 'A paired dural venous sinus lateral to the sella turcica (contains CN III, IV, V1, V2, VI', 'The cavernous sinus (the most clinically important venous sinus) communicates with the facial veins (the danger triangle of the face).'),
('05acf222-94ab-5964-b733-5cd6f317580d'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'Cavernous sinus thrombosis:', '["A superior sagittal sinus thrombosis and its associated anatomical structures","A straight sinus thrombosis and its associated anatomical structures","A cerebral venous thrombosis and its associated anatomical structures","A sigmoid sinus thrombosis and its associated anatomical structures","A life-threatening infection of the cavernous sinus (causes periorbital edema, proptosis"]'::jsonb, 'A life-threatening infection of the cavernous sinus (causes periorbital edema, proptosis', 'Cavernous sinus thrombosis (from facial/sinus infections) has a high mortality rate (requires IV antibiotics and anticoagulation).'),
('3a5d10a4-c56e-5c86-9ccc-f7a571034e78'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The intercavernous sinuses:', '["The superior petrosal sinus and its associated anatomical structures","Venous connections between the right and left cavernous sinuses","The sphenoparietal sinus and its associated anatomical structures","The basilar plexus and its associated anatomical structures","The inferior petrosal sinus and its associated anatomical structures"]'::jsonb, 'Venous connections between the right and left cavernous sinuses', 'The intercavernous sinuses (anterior and posterior) form the circular sinus around the pituitary stalk (a surgical landmark).'),
('c52509c6-8294-5d29-8089-1238e606c332'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The superior sagittal sinus:', '["The transverse sinus and its associated anatomical structures","The inferior sagittal sinus and its associated anatomical structures","A large dural venous sinus in the upper border of the falx cerebri (drains from the crista galli","The straight sinus and its associated anatomical structures","The sigmoid sinus and its associated anatomical structures"]'::jsonb, 'A large dural venous sinus in the upper border of the falx cerebri (drains from the crista galli', 'The superior sagittal sinus (SSS) receives the cerebral veins (lacunae laterales with arachnoid granulations). SSS thrombosis causes hemorrhagic infarction.'),
('012630d0-c971-5fae-bec5-d6c31051f78a'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The inferior sagittal sinus:', '["The straight sinus and its associated anatomical structures","The superior sagittal sinus and its associated anatomical structures","A small dural sinus in the lower free edge of the falx cerebri","The sigmoid sinus and its associated anatomical structures","The transverse sinus and its associated anatomical structures"]'::jsonb, 'A small dural sinus in the lower free edge of the falx cerebri', 'The inferior sagittal sinus runs in the posterior 2/3 of the falx cerebri and joins the great cerebral vein to form the straight sinus.'),
('d65c24ca-6258-5155-a582-c6021f8f14f0'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The straight sinus:', '["The superior sagittal sinus and its associated anatomical structures","The transverse sinus and its associated anatomical structures","The sigmoid sinus and its associated anatomical structures","A dural venous sinus at the junction of the falx cerebri and the tentorium cerebelli (drains into","The inferior sagittal sinus and its associated anatomical structures"]'::jsonb, 'A dural venous sinus at the junction of the falx cerebri and the tentorium cerebelli (drains into', 'The straight sinus (formed by the union of the inferior sagittal sinus and the great cerebral vein) runs posteriorly and downward.'),
('cbc3d21a-6e7c-5239-9d13-bbb0c670576a'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The transverse sinus:', '["The sigmoid sinus and its associated anatomical structures","A paired sinus that runs laterally from the torcular herophili (in the groove on the occipital bone","The superior sagittal sinus and its associated anatomical structures","The occipital sinus and its associated anatomical structures","The straight sinus and its associated anatomical structures"]'::jsonb, 'A paired sinus that runs laterally from the torcular herophili (in the groove on the occipital bone', 'The transverse sinus (the horizontal limb) becomes the sigmoid sinus at the level of the mastoid (the sigmoid sinus descends to the jugular bulb).'),
('4175d74e-8112-55e8-a60c-7fc3c3514055'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The sigmoid sinus:', '["The straight sinus and its associated anatomical structures","The superior sagittal sinus and its associated anatomical structures","The occipital sinus and its associated anatomical structures","An S-shaped sinus that is the continuation of the transverse sinus (drains into the internal jugu","The transverse sinus and its associated anatomical structures"]'::jsonb, 'An S-shaped sinus that is the continuation of the transverse sinus (drains into the internal jugu', 'The sigmoid sinus (a curved channel on the mastoid part of the temporal bone) is prone to injury in mastoid surgery.'),
('6612db9c-8ff8-59cb-8308-543354bda8be'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The occipital sinus:', '["The transverse sinus","The straight sinus","The sigmoid sinus","The superior sagittal sinus","A small sinus in the falx cerebelli"]'::jsonb, 'A small sinus in the falx cerebelli', 'The occipital sinus (the smallest of the dural sinuses) connects the marginal sinuses around the foramen magnum to the torcular herophili.'),
('27524ac2-f5ee-5396-b0fc-6899a10bf1af'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The torcular herophili (confluence of sinuses):', '["The cavernous sinus","The sagittal sinus","The junction of the inferior sagittal and straight sinuses","The confluence of the superior sagittal sinus, straight sinus, and transverse sinuses (at the int","The junction of the sigmoid and transverse sinuses"]'::jsonb, 'The confluence of the superior sagittal sinus, straight sinus, and transverse sinuses (at the int', 'The torcular herophili (the confluence of sinuses) is a landmark for the inion (the transverse sinuses run laterally from the torcular).'),
('2c57137c-10e0-5f5c-be3d-809977519109'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The superior petrosal sinus:', '["The inferior petrosal sinus","The sphenoparietal sinus","The cavernous sinus","The sigmoid sinus","A small sinus that runs along the petrous ridge"]'::jsonb, 'A small sinus that runs along the petrous ridge', 'The superior petrosal sinus (in the tentorium) connects the cavernous sinus and the transverse sinus.'),
('83b716b1-912b-55d8-9084-5e98f0ef67d9'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The inferior petrosal sinus:', '["The sigmoid sinus and its associated anatomical structures","The superior petrosal sinus and its associated anatomical structures","The basilar plexus and its associated anatomical structures","A sinus that runs in the groove between the petrous temporal bone and the occipital bone (drains","The cavernous sinus and its associated anatomical structures"]'::jsonb, 'A sinus that runs in the groove between the petrous temporal bone and the occipital bone (drains', 'The inferior petrosal sinus (IPS) passes through the jugular foramen to join the IJV (IPS sampling for Cushing syndrome localization).'),
('64919250-2c3b-56b8-9ed4-ef3ce09d447f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The sphenoparietal sinus:', '["The cavernous sinus","The inferior petrosal sinus","The intercavernous sinus","A sinus along the lesser wing of the sphenoid","The superior petrosal sinus"]'::jsonb, 'A sinus along the lesser wing of the sphenoid', 'The sphenoparietal sinus (of Breschet) drains the middle meningeal veins and the Sylvian veins into the cavernous sinus.'),
('b18a21e6-ef9c-5827-bbe7-1aa2d93964eb'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The basilar plexus (clival plexus):', '["The occipital sinus and its associated anatomical structures","A venous network on the clivus (connects the cavernous sinuses and the inferior petrosal sinuses","The superior petrosal sinus and its associated anatomical structures","The intercavernous sinus and its associated anatomical structures","The cavernous sinus and its associated anatomical structures"]'::jsonb, 'A venous network on the clivus (connects the cavernous sinuses and the inferior petrosal sinuses', 'The basilar plexus (Batson plexus) is a connection between the intracranial dural sinuses and the epidural vertebral venous plexus.'),
('f8939986-125a-553d-9ecf-074d87fbb392'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The arachnoid granulations (Pacchionian granulations):', '["The choroid plexus and its associated anatomical structures","Projections of the arachnoid mater into the dural venous sinuses","The Ependyma and its associated anatomical structures","The dura mater and its associated anatomical structures","The pia mater and its associated anatomical structures"]'::jsonb, 'Projections of the arachnoid mater into the dural venous sinuses', 'Arachnoid granulations (the site of CSF reabsorption) are most numerous along the superior sagittal sinus (the lacunae laterales).'),
('1b1d17c8-ae80-5de5-bce5-2a19f6c4a066'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The CSF is produced by:', '["The blood vessels","The meninges","The brain parenchyma","The arachnoid granulations","The choroid plexus"]'::jsonb, 'The choroid plexus', 'The choroid plexus (a tuft of capillaries covered by ependymal cells) produces CSF by active secretion (Na-K-ATPase).'),
('1e1ac94a-b03b-5558-8126-130c726d4106'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The lateral ventricles (right and left):', '["The subarachnoid space and its associated anatomical structures","The 3rd ventricle and its associated anatomical structures","The cerebral aqueduct and its associated anatomical structures","The largest CSF spaces in the brain (each has a frontal horn, body, atrium, occipital horn","The 4th ventricle and its associated anatomical structures"]'::jsonb, 'The largest CSF spaces in the brain (each has a frontal horn, body, atrium, occipital horn', 'The lateral ventricles (C-shaped) communicate with the 3rd ventricle through the interventricular foramina (of Monro).'),
('6dc50075-efe0-52da-9503-6430b1c609ed'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The foramen of Monro (interventricular foramen):', '["The opening between the 3rd and 4th ventricles","The foramen of Magendie","The cerebral aqueduct","The opening between the 4th ventricle and the subarachnoid space","The opening between the lateral ventricle and the 3rd ventricle (transmits choroid plexus and the"]'::jsonb, 'The opening between the lateral ventricle and the 3rd ventricle (transmits choroid plexus and the', 'The foramen of Monro (paired) is the narrowest part of the ventricular system (can be obstructed by colloid cyst).'),
('9ab64d2b-f462-5751-8b9b-e8ec292bbaa6'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The 3rd ventricle:', '["The largest ventricle and its associated anatomical structures","The 4th ventricle and its associated anatomical structures","A narrow slit-like midline cavity (between the two thalami — communicates with the lateral ventri","The lateral ventricle and its associated anatomical structures","The cerebral aqueduct and its associated anatomical structures"]'::jsonb, 'A narrow slit-like midline cavity (between the two thalami — communicates with the lateral ventri', 'The 3rd ventricle (5 mm wide) is surrounded by the hypothalamus and the thalamus (the habenular commissure and posterior commissure are posterior).'),
('d9ffab93-d509-5eeb-9bb2-1c613c344b16'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The cerebral aqueduct (of Sylvius):', '["A narrow channel through the midbrain","Connects the 4th ventricle to the subarachnoid space","The spinal canal","The foramen of Luschka","Connects the lateral ventricles to the 3rd ventricle"]'::jsonb, 'A narrow channel through the midbrain', 'The cerebral aqueduct (1-2 mm in diameter) is the most common site of congenital hydrocephalus (aqueductal stenosis).'),
('2b7c8ab3-b59b-5c4d-892a-ed22f1641aea'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The 4th ventricle:', '["The 3rd ventricle and its associated anatomical structures","The cerebral aqueduct and its associated anatomical structures","The midline ventricle and its associated anatomical structures","The lateral ventricle and its associated anatomical structures","A diamond-shaped cavity (between the pons/medulla and the cerebellum — connects to the subarachno"]'::jsonb, 'A diamond-shaped cavity (between the pons/medulla and the cerebellum — connects to the subarachno', 'The 4th ventricle (the rhomboid fossa) is the floor of the 4th ventricle (contains the facial colliculus and the hypoglossal and vagal trigones).'),
('4d54c3de-048a-537b-9b85-f180b4d28a46'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The foramen of Magendie (median aperture):', '["The foramen of Luschka and its associated anatomical structures","The cerebral aqueduct and its associated anatomical structures","A midline opening in the inferior roof of the 4th ventricle","The foramen of Monro and its associated anatomical structures","The interventricular foramen and its associated anatomical structures"]'::jsonb, 'A midline opening in the inferior roof of the 4th ventricle', 'The foramen of Magendie (the median aperture) is the primary CSF outflow from the 4th ventricle at the level of the obex.'),
('59b393d3-f0c8-59e2-9f38-cd1e754bc21b'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The foramina of Luschka (lateral apertures):', '["The cerebral aqueduct and its associated anatomical structures","The interventricular foramen and its associated anatomical structures","The foramen of Monro and its associated anatomical structures","The foramen of Magendie and its associated anatomical structures","Paired lateral openings in the roof of the 4th ventricle (drain CSF into the cerebellopontine ang"]'::jsonb, 'Paired lateral openings in the roof of the 4th ventricle (drain CSF into the cerebellopontine ang', 'The foramina of Luschka (the lateral apertures) open into the subarachnoid space at the level of the pontomedullary junction.'),
('3b210174-fc8c-5af6-b308-a1985ff05678'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The CSF flow pathway:', '["Through the choroid plexus and its associated anatomical structures","Lateral ventricles → foramen of Monro → 3rd ventricle → cerebral aqueduct → 4th ventricle → foram","Through the brain parenchyma and its associated anatomical structures","To the spinal canal and back and its associated anatomical structures","Directly to the blood and its associated anatomical structures"]'::jsonb, 'Lateral ventricles → foramen of Monro → 3rd ventricle → cerebral aqueduct → 4th ventricle → foram', 'The CSF circulation (bulk flow) maintains the intracranial pressure (lumbar puncture accesses the spinal subarachnoid space).'),
('87db4d84-bdb2-5adb-b14f-9cb3279232a8'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'Hydrocephalus:', '["A normal variant and its associated anatomical structures","A combination of the above and its associated anatomical structures","A brain tumor and its associated anatomical structures","An abnormal accumulation of CSF in the ventricular system (may be communicating","A decrease in CSF volume and its associated anatomical structures"]'::jsonb, 'An abnormal accumulation of CSF in the ventricular system (may be communicating', 'Hydrocephalus (increased intracranial pressure in children causes a rapidly increasing head circumference, sunset eyes, and a high-pitched cry).'),
('4cd393aa-bed6-5ccd-a6c1-0058bcae55ef'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The choroid plexus in the lateral ventricle is located:', '["In the frontal horn","In the 3rd ventricle only","In the occipital horn","In the body and the temporal horn","Along the entire ventricle"]'::jsonb, 'In the body and the temporal horn', 'The choroid plexus (the tela choroidea) is a highly vascularized structure that produces CSF by active secretion.'),
('6971985e-8fe5-553a-abef-4abe7dc74919'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The craniopharyngeal canal:', '["The pterygoid canal and its associated anatomical structures","A persistent embryologic canal in the sphenoid bone (the remnant of the Rathke pouch — a rare cau","The vidian canal and its associated anatomical structures","The optic canal and its associated anatomical structures","The hypoglossal canal and its associated anatomical structures"]'::jsonb, 'A persistent embryologic canal in the sphenoid bone (the remnant of the Rathke pouch — a rare cau', 'The craniopharyngeal canal (at the junction of the sphenoid body and the basiocciput) is the path of the Rathke pouch (craniopharyngioma).'),
('362184dd-af79-5b8a-a3aa-11618c151713'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The pterygoid canal (vidian canal):', '["The vomerovaginal canal and its associated anatomical structures","The nasopalatine canal and its associated anatomical structures","The pterygopalatine canal and its associated anatomical structures","A canal in the sphenoid bone at the base of the pterygoid process (transmits the nerve of the pte","The palatovaginal canal and its associated anatomical structures"]'::jsonb, 'A canal in the sphenoid bone at the base of the pterygoid process (transmits the nerve of the pte', 'The pterygoid canal (Vidian canal) in the sphenoid bone transmits the nerve of the pterygoid canal (from the greater and deep petrosal nerves).'),
('0e2a32e1-cbd7-5c84-aaad-08a6a6fbe968'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The palatovaginal (pharyngeal) canal:', '["The vomerovaginal canal and its associated anatomical structures","The incisive canal and its associated anatomical structures","A small canal at the junction of the sphenoid and palatine bones (transmits the pharyngeal branch","The pterygopalatine canal and its associated anatomical structures","The pterygoid canal and its associated anatomical structures"]'::jsonb, 'A small canal at the junction of the sphenoid and palatine bones (transmits the pharyngeal branch', 'The palatovaginal canal (pharyngeal canal) is located between the sphenoid process of the palatine bone and the vaginal process of the sphenoid.'),
('70507106-3f80-5a5a-bd8a-6f2c5da9af12'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The vomerovaginal canal:', '["The pterygoid canal and its associated anatomical structures","The nasopalatine canal and its associated anatomical structures","A small canal between the vomer and the vaginal process of the sphenoid","The palatovaginal canal and its associated anatomical structures","The incisive canal and its associated anatomical structures"]'::jsonb, 'A small canal between the vomer and the vaginal process of the sphenoid', 'The vomerovaginal canal (a midline structure) is a small vascular channel.'),
('72aa28d4-65c2-5883-8147-0f129ebbaf35'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The stylohyoid chain:', '["The styloid process, the stylohyoid ligament, and the lesser horn of the hyoid bone (the embryolo","The mandible and its associated anatomical structures","The temporal bone and its associated anatomical structures","The sphenoid bone and its associated anatomical structures","The hyoid bone and its associated anatomical structures"]'::jsonb, 'The styloid process, the stylohyoid ligament, and the lesser horn of the hyoid bone (the embryolo', 'The stylohyoid chain (Reichert cartilage of the second arch) may calcify (Eagle syndrome causes oropharyngeal pain).'),
('0b53f9df-55d7-5cd1-a444-11d763c0924f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The Caldwell-Luc procedure (radical antrostomy):', '["A ethmoid procedure and its associated anatomical structures","A cranial procedure and its associated anatomical structures","An opening into the maxillary sinus through the canine fossa","A mastoid procedure and its associated anatomical structures","An orbital procedure and its associated anatomical structures"]'::jsonb, 'An opening into the maxillary sinus through the canine fossa', 'The Caldwell-Luc approach (intraoral, through the thin bone of the canine fossa) is used for maxillary sinus surgery.'),
('833e8928-b5a1-5f4e-9d5a-8fff98c7f242'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The transsphenoidal approach:', '["A surgical approach to the pituitary gland through the sphenoid sinus (via the nasal cavity and t","A transfacial approach and its associated anatomical structures","A transcranial approach and its associated anatomical structures","A transorbital approach and its associated anatomical structures","An intraoral approach and its associated anatomical structures"]'::jsonb, 'A surgical approach to the pituitary gland through the sphenoid sinus (via the nasal cavity and t', 'The transsphenoidal approach (endoscopic or microscopic) is the preferred approach for most pituitary tumors (avoids craniotomy).'),
('84b8e883-69e7-515a-acc8-117bad298b10'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The retrosigmoid approach (suboccipital):', '["A transsphenoidal approach and its associated anatomical structures","An intraventricular approach and its associated anatomical structures","A temporal approach and its associated anatomical structures","A surgical approach to the cerebellopontine angle (through the occipital bone","A frontal approach and its associated anatomical structures"]'::jsonb, 'A surgical approach to the cerebellopontine angle (through the occipital bone', 'The retrosigmoid approach is used for vestibular schwannoma (acoustic neuroma), trigeminal neuralgia (MVD), and CPA tumors.'),
('181f599b-b535-53a3-bc9c-7a7ac01ae657'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The frontotemporal (pterional) approach:', '["A standard neurosurgical approach (a frontotemporal craniotomy through the pterion","An intraventricular approach and its associated anatomical structures","A transsphenoidal approach and its associated anatomical structures","An endoscopic approach and its associated anatomical structures","A suboccipital approach and its associated anatomical structures"]'::jsonb, 'A standard neurosurgical approach (a frontotemporal craniotomy through the pterion', 'The pterional approach (Yasargil) is used for anterior circulation aneurysms, tumors of the frontal and temporal lobes, and the sellar region.'),
('04d697b1-54d2-58fe-95cf-ccb4d1a9c941'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The burr hole:', '["A cranioplasty and its associated anatomical structures","A craniotomy and its associated anatomical structures","A small hole in the skull (made with a perforator and a burr for drainage of CSF","A trephination and its associated anatomical structures","A craniectomy and its associated anatomical structures"]'::jsonb, 'A small hole in the skull (made with a perforator and a burr for drainage of CSF', 'Burr holes are placed at specific landmarks (Kocher point for frontal horn, Frazier point for posterior fossa, Dandy point for occipital horn).'),
('b4e6f9fa-a3d9-5732-9449-0b99439525bc'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'Kocher point:', '["The occipital point and its associated anatomical structures","The suboccipital point and its associated anatomical structures","A point for frontal ventriculostomy (2-3 cm from the midline and 1 cm anterior to the coronal sut","The temporal point and its associated anatomical structures","The frontotemporal point and its associated anatomical structures"]'::jsonb, 'A point for frontal ventriculostomy (2-3 cm from the midline and 1 cm anterior to the coronal sut', 'Kocher point (midpupillary line, 1 cm anterior to the coronal suture) accesses the frontal horn of the lateral ventricle.'),
('b4082a74-6d76-5eec-9b03-52da4c60b1da'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'Frazier point:', '["A point for posterior fossa CSF drainage","The supraorbital point and its associated structures","Keen point and its associated structures","Kocher point and its associated structures","Dandy point and its associated structures"]'::jsonb, 'A point for posterior fossa CSF drainage', 'Frazier point (suboccipital) is used for posterior fossa ventricular drainage (the lateral atria).'),
('6cfa5d19-c727-5437-b0e5-fa45e7cd91ae'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The Dandy point:', '["Kocher point and its associated structures","Keen point and its associated structures","Frazier point and its associated structures","The pterion and its associated structures","A point for occipital ventriculostomy"]'::jsonb, 'A point for occipital ventriculostomy', 'Dandy point (occipital) is used to access the occipital horn of the lateral ventricle.'),
('99bd9d2f-f670-5688-9d7a-1f61ae3d4685'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The foramen of the skull base that transmits the internal jugular vein:', '["The jugular foramen","The carotid canal","The foramen spinosum","The foramen magnum","The foramen ovale"]'::jsonb, 'The jugular foramen', 'The jugular foramen (pars venosa) is the largest foramen of the skull base (the IJV is the direct continuation of the sigmoid sinus).'),
('e30c1a0d-cefa-59f6-8254-9d5d8d01a738'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The foramen of the skull base that transmits the internal carotid artery:', '["The foramen lacerum","The carotid canal","The optic canal","The foramen magnum","The jugular foramen"]'::jsonb, 'The carotid canal', 'The ICA enters the base of the skull through the carotid canal at the base of the petrous temporal bone.'),
('4df3fdc7-3d9e-52a4-ab88-7dd4a8931c36'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The foramen of the skull base that transmits the maxillary nerve:', '["The inferior orbital fissure","The foramen ovale","The infraorbital foramen","The foramen rotundum","The superior orbital fissure"]'::jsonb, 'The foramen rotundum', 'The foramen rotundum (a short canal, 4 mm) is located in the greater wing of the sphenoid bone.'),
('73e6092b-b068-58a8-8a4f-5b72a31b5a6f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The foramen of the skull base that transmits the mandibular nerve:', '["The jugular foramen","The foramen spinosum","The foramen lacerum","The foramen rotundum","The foramen ovale"]'::jsonb, 'The foramen ovale', 'The foramen ovale (oval-shaped, 7 x 4 mm) is posterior and lateral to the foramen rotundum.'),
('78e36bb1-56e7-5869-854d-188b9d35933d'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The foramen of the skull base that transmits the middle meningeal artery:', '["The foramen ovale","The foramen spinosum","The jugular foramen","The carotid canal","The foramen rotundum"]'::jsonb, 'The foramen spinosum', 'The foramen spinosum (a small, round foramen) is the landmark for the middle meningeal artery (distal to the pterion).'),
('41f8cfbc-5cfa-557c-9691-0bdbc2d26727'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The foramen of the skull base that transmits the optic nerve:', '["The foramen magnum","The optic canal","The hypoglossal canal","The foramen rotundum","The superior orbital fissure"]'::jsonb, 'The optic canal', 'The optic canal (the optic strut) is 5-10 mm long and is a narrow passage for CN II and the ophthalmic artery.'),
('5ac19471-84c7-5678-af7d-d1fc958a45c4'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The foramen of the skull base that transmits the oculomotor, trochlear, ophthalmic, and abducens nerves:', '["The foramen rotundum","The cavernous sinus","The superior orbital fissure","The optic canal","The foramen ovale"]'::jsonb, 'The superior orbital fissure', 'The superior orbital fissure (22 mm long) transmits CN III, IV, V1, VI, the ophthalmic veins, and sympathetic fibers from the cavernous plexus.'),
('915ecc80-fda2-5d2a-ad63-22e7e18b8386'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The pterygopalatine fossa communicates with:', '["The middle cranial fossa (through the foramen rotundum), the orbit (through the inferior orbital","Only the orbit and its associated anatomical structures","Only the nasal cavity and its associated anatomical structures","Only the cranial cavity and its associated anatomical structures","Only the infratemporal fossa and its associated anatomical structures"]'::jsonb, 'The middle cranial fossa (through the foramen rotundum), the orbit (through the inferior orbital', 'The pterygopalatine fossa is a narrow, inverted pyramidal space (the crossroads of the face) containing the pterygopalatine ganglion and the maxillary nerve.'),
('e6f8ed58-7317-5a0b-9590-aacb956f7bc3'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The infratemporal fossa communicates with:', '["Only the cranial cavity and its associated anatomical structures","Only the pterygopalatine fossa and its associated anatomical structures","The pterygopalatine fossa (through the pterygomaxillary fissure), the middle cranial fossa (throu","Only the nasal cavity and its associated anatomical structures","Only the orbit and its associated anatomical structures"]'::jsonb, 'The pterygopalatine fossa (through the pterygomaxillary fissure), the middle cranial fossa (throu', 'The infratemporal fossa (the region deep to the ramus of the mandible) contains the pterygoid muscles, the mandibular nerve, and the maxillary artery.'),
('b0e50ba3-dfaf-5da6-95fc-19153906b42b'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The temporal fossa:', '["A shallow depression on the side of the skull (bounded superiorly by the superior temporal line a","The pterygomaxillary fissure and its associated anatomical structures","The infratemporal fossa and its associated anatomical structures","The temporal region and its associated anatomical structures","The pterygopalatine fossa and its associated anatomical structures"]'::jsonb, 'A shallow depression on the side of the skull (bounded superiorly by the superior temporal line a', 'The temporal fossa (the temple) is covered by the temporal fascia (the temporalis muscle fills the fossa and passes under the zygomatic arch).'),
('64238486-484b-5adb-bc1f-9c6273f73e97'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The middle cranial fossa contains:', '["The frontal lobes and its associated anatomical structures","The brainstem and its associated anatomical structures","The cerebellum and its associated anatomical structures","The temporal lobes, the pituitary gland, the cavernous sinuses, CN II-VI","The occipital lobes and its associated anatomical structures"]'::jsonb, 'The temporal lobes, the pituitary gland, the cavernous sinuses, CN II-VI', 'The middle cranial fossa (the largest fossa) is bounded anteriorly by the lesser wing of the sphenoid and posteriorly by the petrous ridge.'),
('a5db4dda-bfb8-535a-9991-f983c0877c83'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The anterior cranial fossa contains:', '["The frontal lobes (the orbital and olfactory areas), the olfactory bulbs and tracts","The occipital lobes and its associated anatomical structures","The temporal lobes and its associated anatomical structures","The pituitary gland and its associated anatomical structures","The cerebellum and its associated anatomical structures"]'::jsonb, 'The frontal lobes (the orbital and olfactory areas), the olfactory bulbs and tracts', 'The anterior cranial fossa (the floor of the frontal fossa) is bounded by the frontal crest anteriorly and the sphenoid ridge posteriorly.'),
('92348c48-5c56-5ff1-a2ea-e1271d8e97b7'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The posterior cranial fossa contains:', '["The frontal lobes and its associated anatomical structures","The temporal lobes and its associated anatomical structures","The occipital lobes and its associated anatomical structures","The brainstem (midbrain, pons, medulla), the cerebellum, the 4th ventricle, and CN V-XII","The basal ganglia and its associated anatomical structures"]'::jsonb, 'The brainstem (midbrain, pons, medulla), the cerebellum, the 4th ventricle, and CN V-XII', 'The posterior cranial fossa (the smallest and deepest fossa) is bounded by the petrous ridges and the clivus anteriorly and the occipital bone posteriorly.'),
('3dafa691-6a7d-5d3b-8d15-2f4b16397cfd'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The foramen magnum is the largest opening in the:', '["Skull base","Posterior cranial fossa","Calvaria","Anterior cranial fossa","Middle cranial fossa"]'::jsonb, 'Posterior cranial fossa', 'The foramen magnum (the opening in the occipital bone) connects the posterior cranial fossa to the vertebral canal (the safest site for a lumbar puncture is at L4-L5).'),
('19d33003-745d-5ad4-83c5-ee2e2576efd7'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The clivus is formed by:', '["The temporal bone and its associated anatomical structures","The occipital bone and its associated anatomical structures","The basiocciput and the basisphenoid (a sloping surface from the dorsum sellae to the foramen mag","The sphenoid bone and its associated anatomical structures","The petrous temporal bone and its associated anatomical structures"]'::jsonb, 'The basiocciput and the basisphenoid (a sloping surface from the dorsum sellae to the foramen mag', 'The clivus (the anterior boundary of the posterior fossa) has the pons and medulla resting on it (clival chordoma and meningioma).'),
('8c0e5085-956b-5636-bc71-b303412b2228'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The jugular tubercle:', '["A small bony prominence on the occipital bone (above the hypoglossal canal","The pterygoid process and its associated anatomical structures","The mastoid process and its associated anatomical structures","The occipital condyle and its associated anatomical structures","The styloid process and its associated anatomical structures"]'::jsonb, 'A small bony prominence on the occipital bone (above the hypoglossal canal', 'The jugular tubercle (above the hypoglossal canal and medial to the jugular foramen) is an important landmark in the far-lateral approach.'),
('e79a5d10-d85b-5561-bec1-8970f5e2e0d3'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The prevertebral (retropharyngeal) space:', '["The space between the pleura and the ribs","The space between the buccopharyngeal fascia and the prevertebral fascia (a potential space for r","The space between the pericardium and the heart","The space between the dura and the skull","The space between the peritoneum and the abdominal wall"]'::jsonb, 'The space between the buccopharyngeal fascia and the prevertebral fascia (a potential space for r', 'Retropharyngeal abscess (most common in children under 5) can cause airway obstruction, stridor, and dysphagia (requires urgent drainage).'),
('3d770a92-79f0-56f6-acb1-6744b980fd54'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The danger space (the third space of the deep neck):', '["The prevertebral space and its associated anatomical structures","The submandibular space and its associated anatomical structures","The space between the alar fascia and the prevertebral fascia (from the skull base to the posteri","The parotid space and its associated anatomical structures","The retropharyngeal space and its associated anatomical structures"]'::jsonb, 'The space between the alar fascia and the prevertebral fascia (from the skull base to the posteri', 'The danger space (the alar fascia separates it from the retropharyngeal space) communicates directly with the posterior mediastinum.'),
('f610106f-655c-53be-b8ee-8da46eab4efa'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The prevertebral space:', '["The retropharyngeal space and its associated anatomical structures","The pretracheal space and its associated anatomical structures","The submandibular space and its associated anatomical structures","The space between the prevertebral fascia and the vertebral bodies (a true anatomical space that","The parapharyngeal space and its associated anatomical structures"]'::jsonb, 'The space between the prevertebral fascia and the vertebral bodies (a true anatomical space that', 'The prevertebral space (the most posterior of the deep neck spaces) contains the prevertebral muscles and the sympathetic trunk.'),
('5118e32b-8e7c-5473-9064-3cdeaff99a64'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The parapharyngeal (pharyngomaxillary) space:', '["The masticator space and its associated anatomical structures","The submandibular space and its associated anatomical structures","A potential space shaped like an inverted pyramid (on each side of the pharynx — from the skull b","The parotid space and its associated anatomical structures","The retropharyngeal space and its associated anatomical structures"]'::jsonb, 'A potential space shaped like an inverted pyramid (on each side of the pharynx — from the skull b', 'The parapharyngeal space (the lateral pharyngeal space) communicates with the submandibular space and the parotid space.'),
('5cb1792b-fb25-588d-8e9a-fe61bb150217'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The masticator space:', '["The parotid space and its associated anatomical structures","The canine space and its associated anatomical structures","A fascial space (encloses the ramus of the mandible and the muscles of mastication — infection ca","The submandibular space and its associated anatomical structures","The parapharyngeal space and its associated anatomical structures"]'::jsonb, 'A fascial space (encloses the ramus of the mandible and the muscles of mastication — infection ca', 'The masticator space (formed by the splitting of the deep cervical fascia around the masseter and the temporalis muscles) is assessed in dental infections.'),
('a4060064-f205-5a9e-be73-78abd357655f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The submandibular space (floor of the mouth):', '["The parapharyngeal space and its associated anatomical structures","The masticator space and its associated anatomical structures","A potential space between the mucosa of the floor of the mouth and the mylohyoid muscle (Ludwig a","The submental space and its associated anatomical structures","The sublingual space and its associated anatomical structures"]'::jsonb, 'A potential space between the mucosa of the floor of the mouth and the mylohyoid muscle (Ludwig a', 'Ludwig angina (a rapidly spreading submandibular space infection) causes dysphagia, stridor, and airway compromise (requires urgent airway management).'),
('0efbb9b9-097a-5485-b328-c91f2b2442ab'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The canine space:', '["The submandibular space and its associated anatomical structures","A fascial space between the quadratus labii superioris and the bone of the maxilla (anterior to t","The sublingual space and its associated anatomical structures","The parapharyngeal space and its associated anatomical structures","The buccal space and its associated anatomical structures"]'::jsonb, 'A fascial space between the quadratus labii superioris and the bone of the maxilla (anterior to t', 'The canine space (infraorbital space) is a common site for dental abscess drainage (the canine fossa approach in Caldwell-Luc procedure).'),
('1a84df30-de79-5596-b386-c9f3302a43cc'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The buccal space:', '["The sublingual space and its associated anatomical structures","A fascial space between the buccinator muscle and the skin of the cheek (contains the buccal fat","The submandibular space and its associated anatomical structures","The masticator space and its associated anatomical structures","The parapharyngeal space and its associated anatomical structures"]'::jsonb, 'A fascial space between the buccinator muscle and the skin of the cheek (contains the buccal fat', 'The buccal space (the buccal fat pad is a signet of buccal space infection or trauma).'),
('fe0d2779-ec70-5056-8241-96d373c5f08e'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The zygomatic arch is formed by:', '["The frontal bone and the zygomatic bone and its associated anatomical structures","The maxilla and the zygomatic bone and its associated anatomical structures","The zygomatic bone and the maxilla and its associated anatomical structures","The temporal bone and the sphenoid bone and its associated anatomical structures","The temporal process of the zygomatic bone and the zygomatic process of the temporal bone"]'::jsonb, 'The temporal process of the zygomatic bone and the zygomatic process of the temporal bone', 'The zygomatic arch (the cheekbone) is the origin of the masseter muscle and is a key landmark for facial trauma.'),
('c9ff3650-be70-5a36-9fd5-8c45fbda29c6'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The temporozygomatic suture:', '["The suture between the temporal process of the zygomatic bone and the zygomatic process of the te","The zygomaticomaxillary suture and its associated anatomical structures","The temporomandibular joint and its associated anatomical structures","The sphenozygomatic suture and its associated anatomical structures","The frontozygomatic suture and its associated anatomical structures"]'::jsonb, 'The suture between the temporal process of the zygomatic bone and the zygomatic process of the te', 'The temporozygomatic suture (part of the zygomatic arch) is the site of zygomatic arch fracture.'),
('47a00d1b-4826-58c2-ae37-19edfa518d71'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The nasofrontal suture:', '["The frontonasal suture and its associated anatomical structures","The suture between the frontal bone and the two nasal bones","The nasomaxillary suture and its associated anatomical structures","The frontoethmoidal suture and its associated anatomical structures","The frontomaxillary suture and its associated anatomical structures"]'::jsonb, 'The suture between the frontal bone and the two nasal bones', 'The nasofrontal suture (the nasion) is a cephalometric landmark for the skull base (used in craniofacial surgery).'),
('3e5d1d75-13fb-501f-87fb-95ac8aa8cfd7'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The frontoethmoidal suture:', '["The sphenoethmoidal suture and its associated anatomical structures","The suture between the frontal bone and the ethmoid bone (contains the cribriform plate and the a","The nasofrontal suture and its associated anatomical structures","The frontozygomatic suture and its associated anatomical structures","The sphenofrontal suture and its associated anatomical structures"]'::jsonb, 'The suture between the frontal bone and the ethmoid bone (contains the cribriform plate and the a', 'The frontoethmoidal suture is the level of the cribriform plate (a landmark for the anterior skull base and the olfactory fossa).'),
('244ea686-fd6d-536c-add9-9a186ed4e6b2'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The sphenoethmoidal suture:', '["The sphenofrontal suture and its associated anatomical structures","The sphenotemporal suture and its associated anatomical structures","The suture between the sphenoid bone and the ethmoid bone (the anterior boundary of the sphenoid","The sphenoparietal suture and its associated anatomical structures","The frontoethmoidal suture and its associated anatomical structures"]'::jsonb, 'The suture between the sphenoid bone and the ethmoid bone (the anterior boundary of the sphenoid', 'The sphenoethmoidal suture (the junction of the sphenoid and ethmoid bones) is a landmark for the anterior cranial fossa.'),
('112747ce-ec4e-5f67-9805-4c03a161b9ca'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The mastoid foramen:', '["The stylomastoid foramen","A small foramen in the mastoid process","The carotid canal","The hypoglossal canal","The jugular foramen"]'::jsonb, 'A small foramen in the mastoid process', 'The mastoid foramen (posterior to the stylomastoid foramen) is a surgical landmark for the sigmoid sinus.'),
('83bd8992-97b3-5e44-b955-85200a27217e'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The parietal foramen:', '["The foramen magnum and its associated anatomical structures","The foramen ovale and its associated anatomical structures","A small foramen near the sagittal suture (transmits the parietal emissary vein to the superior sa","The foramen spinosum and its associated anatomical structures","The mastoid foramen and its associated anatomical structures"]'::jsonb, 'A small foramen near the sagittal suture (transmits the parietal emissary vein to the superior sa', 'The parietal foramen (near the lambda, at the posterior part of the sagittal suture) is a landmark for the superior sagittal sinus.'),
('837f5fcf-cf15-58ae-857a-72b5732100e0'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The sphenoidal emissary foramen (foramen of Vesalius):', '["The foramen lacerum and its associated anatomical structures","The foramen rotundum and its associated anatomical structures","A small foramen medial to the foramen ovale (transmits an emissary vein from the cavernous sinus","The foramen spinosum and its associated anatomical structures","The foramen ovale and its associated anatomical structures"]'::jsonb, 'A small foramen medial to the foramen ovale (transmits an emissary vein from the cavernous sinus', 'The foramen of Vesalius (sphenoidal emissary foramen) is a route for the spread of infection from the face to the cavernous sinus.'),
('e4aea3ab-2707-5b1f-be01-d89276439f16'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The infraorbital groove and canal:', '["The nasolacrimal canal and its associated anatomical structures","A groove on the posterior surface of the maxilla (continues as the infraorbital canal — transmits","The incisive canal and its associated anatomical structures","The greater palatine canal and its associated anatomical structures","The pterygopalatine canal and its associated anatomical structures"]'::jsonb, 'A groove on the posterior surface of the maxilla (continues as the infraorbital canal — transmits', 'The infraorbital nerve (V2) travels in the infraorbital groove and canal to exit at the infraorbital foramen (supplies the midface).'),
('a96314ac-3299-508a-b1bc-5ff5e0428c2e'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The greater palatine canal:', '["The lesser palatine canal and its associated anatomical structures","A canal in the maxilla and the palatine bone (transmits the greater palatine nerve and vessels to","The nasopalatine canal and its associated anatomical structures","The pterygopalatine canal and its associated anatomical structures","The incisive canal and its associated anatomical structures"]'::jsonb, 'A canal in the maxilla and the palatine bone (transmits the greater palatine nerve and vessels to', 'The greater palatine canal (pterygopalatine canal) descends from the pterygopalatine fossa to the greater palatine foramen.'),
('a1c1fa1b-66ce-5a19-8781-0416fe098719'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The lesser palatine canals:', '["Small canals posterior to the greater palatine canal (transmit the lesser palatine nerves to the","The incisive canal and its associated anatomical structures","The nasopalatine canal and its associated anatomical structures","The greater palatine canal and its associated anatomical structures","The pterygopalatine canal and its associated anatomical structures"]'::jsonb, 'Small canals posterior to the greater palatine canal (transmit the lesser palatine nerves to the', 'The lesser palatine canals (from the pterygopalatine fossa) descend in the pyramidal process of the palatine bone.'),
('18a75caa-30bd-543d-8ad4-8d039b73a87f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The incisive canal:', '["The lesser palatine canal and its associated anatomical structures","The greater palatine canal and its associated anatomical structures","The canal between the nasal cavity and the incisive foramen (transmits the nasopalatine nerve and","The nasolacrimal canal and its associated anatomical structures","The pterygopalatine canal and its associated anatomical structures"]'::jsonb, 'The canal between the nasal cavity and the incisive foramen (transmits the nasopalatine nerve and', 'The incisive canal (Stenson foramen) is the passage of the nasopalatine nerve (CN V2) to the anterior hard palate.'),
('86d91500-8f82-5950-8968-f749b4fff304'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The nasolacrimal canal:', '["The pterygopalatine canal and its associated anatomical structures","The infraorbital canal and its associated anatomical structures","A bony canal that drains the lacrimal sac into the inferior meatus of the nose (formed by the max","The incisive canal and its associated anatomical structures","The greater palatine canal and its associated anatomical structures"]'::jsonb, 'A bony canal that drains the lacrimal sac into the inferior meatus of the nose (formed by the max', 'The nasolacrimal canal (1.5 cm) runs from the lacrimal fossa (at the medial canthus) to the inferior meatus (the valve of Hasner prevents air reflux).'),
('4991df08-9829-57d5-9510-d185d6ca31c1'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The lacrimal fossa:', '["The medial orbital wall","The nasal cavity","The inferomedial orbit","A depression in the orbital roof","The ethmoid sinus"]'::jsonb, 'A depression in the orbital roof', 'The lacrimal fossa (the lacrimal gland is in the superolateral part of the orbit) is a landmark for the frontozygomatic suture.'),
('287853a9-250c-5c64-b025-505a44e56ea0'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The optic strut:', '["The middle clinoid process and its associated anatomical structures","The optic canal and its associated anatomical structures","The anterior clinoid process and its associated anatomical structures","The bony bridge between the root of the lesser wing of the sphenoid and the anterior clinoid proc","The superior orbital fissure and its associated anatomical structures"]'::jsonb, 'The bony bridge between the root of the lesser wing of the sphenoid and the anterior clinoid proc', 'The optic strut (the posterior root of the lesser wing of the sphenoid) separates the optic canal from the superior orbital fissure.'),
('91baf852-e388-5221-a9f3-4005df8e162e'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The anterior clinoid process:', '["The middle clinoid process and its associated anatomical structures","The zygomatic process and its associated anatomical structures","The pterygoid process and its associated anatomical structures","The posterior clinoid process and its associated anatomical structures","A projection of the lesser wing of the sphenoid (the attachment of the falciform ligament and the"]'::jsonb, 'A projection of the lesser wing of the sphenoid (the attachment of the falciform ligament and the', 'The anterior clinoid process (the clinoid = bedpost) is a bony spur that overlies the ICA and the optic nerve (anterior clinoidectomy is an advanced skull base technique).'),
('088bbe93-795b-5d9e-a2f8-4e86bd4991a9'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The middle clinoid process:', '["A small bony projection at the lateral side of the sella turcica (may be connected to the anterio","The anterior clinoid process and its associated anatomical structures","The posterior clinoid process and its associated anatomical structures","The pterygoid process and its associated anatomical structures","The sphenoid crest and its associated anatomical structures"]'::jsonb, 'A small bony projection at the lateral side of the sella turcica (may be connected to the anterio', 'The middle clinoid process (variable) can form a bony ring (carotico-clinoid foramen) around the ICA.'),
('be06cc2c-45ae-5516-9643-336688d4a30f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The posterior clinoid process:', '["The pterygoid process and its associated anatomical structures","The anterior clinoid process and its associated anatomical structures","The middle clinoid process and its associated anatomical structures","The sphenoid crest and its associated anatomical structures","A projection of the dorsum sellae (the posterior boundary of the sella turcica and the attachment"]'::jsonb, 'A projection of the dorsum sellae (the posterior boundary of the sella turcica and the attachment', 'The posterior clinoid process is the posterior attachment of the petrosphenoid ligament (Gruber ligament) under which CN VI passes (Dorello canal).'),
('cacff083-6b29-56d6-b23f-718c5760e962'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The Dorello canal:', '["The jugular foramen and its associated anatomical structures","The superior orbital fissure and its associated anatomical structures","The cavernous sinus and its associated anatomical structures","The space between the petrosphenoid ligament (Gruber ligament) and the petrous temporal bone (tra","The hypoglossal canal and its associated anatomical structures"]'::jsonb, 'The space between the petrosphenoid ligament (Gruber ligament) and the petrous temporal bone (tra', 'Dorello canal (a fibro-osseous tunnel) is the site of CN VI compression in Gradenigo syndrome (apical petrositis causes CN VI palsy and retro-orbital pain).'),
('27116493-d3ff-5be7-a77e-352d2578c428'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The petrosphenoid ligament (Gruber ligament):', '["The petroclinoid fold and its associated anatomical structures","The falciform ligament and its associated anatomical structures","The sphenopetrosal suture and its associated anatomical structures","A fibrous band from the petrous apex to the posterior clinoid process","The tentorium and its associated anatomical structures"]'::jsonb, 'A fibrous band from the petrous apex to the posterior clinoid process', 'The petrosphenoid ligament (Gruber ligament) forms the roof of Dorello canal.'),
('b196408d-f3a3-5ccf-b9bd-e654cae40d06'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The lateral sellar compartment (the cavernous sinus):', '["A venous space lateral to the sella (contains the ICA, CN III, IV, V1, V2","Meckel cave and its associated anatomical structures","The sella turcica and its associated anatomical structures","Sphenoid sinus and its associated anatomical structures","The pituitary fossa and its associated anatomical structures"]'::jsonb, 'A venous space lateral to the sella (contains the ICA, CN III, IV, V1, V2', 'The cavernous sinus (the lateral wall contains CN III, IV, V1, V2; the medial wall contains the ICA and CN VI).'),
('ceff6338-dd47-5418-8fa2-adc0cd33b10a'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'Meckel cave (trigeminal cave):', '["The cavernous sinus and its associated anatomical structures","The internal acoustic meatus and its associated anatomical structures","A dural pouch in the petrous temporal bone (contains the trigeminal ganglion — the entrance of th","The sella turcica and its associated anatomical structures","The jugular foramen and its associated anatomical structures"]'::jsonb, 'A dural pouch in the petrous temporal bone (contains the trigeminal ganglion — the entrance of th', 'Meckel cave (the trigeminal cistern) is a recess of the posterior fossa that contains the trigeminal ganglion and its rootlets.'),
('be03728b-2d31-57fd-9a58-dca6302ebd73'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The trigeminal ganglion (Gasserian ganglion):', '["The geniculate ganglion","A large sensory ganglion in Meckel cave","The spiral ganglion","The otic ganglion","The vestibular ganglion"]'::jsonb, 'A large sensory ganglion in Meckel cave', 'The trigeminal ganglion (the semilunar or Gasserian ganglion) is the site of radiofrequency ablation for trigeminal neuralgia.'),
('c60392e8-1e9f-569d-b783-6221ba76c9b0'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The foramen of the trigeminal nerve (porus trigeminus):', '["The superior orbital fissure and its associated anatomical structures","The foramen rotundum and its associated anatomical structures","The tentorial notch and its associated anatomical structures","The opening from the posterior fossa into Meckel cave (the entrance of the trigeminal nerve root","The foramen ovale and its associated anatomical structures"]'::jsonb, 'The opening from the posterior fossa into Meckel cave (the entrance of the trigeminal nerve root', 'The porus trigeminus (the trigeminal pore) is a dural opening in the roof of the posterior fossa for the trigeminal nerve.'),
('5bb77a7e-2e7f-5d85-a51f-6aac2594bfb0'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The tentorial notch (incisura):', '["The optic canal and its associated anatomical structures","The U-shaped opening in the tentorium cerebelli (the passage of the midbrain from the supratentor","The petrous apex and its associated anatomical structures","The superior orbital fissure and its associated anatomical structures","The foramen magnum and its associated anatomical structures"]'::jsonb, 'The U-shaped opening in the tentorium cerebelli (the passage of the midbrain from the supratentor', 'The tentorial notch (tentorial hiatus) is the site of herniation syndromes (uncal herniation compresses CN III and the midbrain).'),
('957640be-4e72-5223-8567-3a09d415d1b2'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'Uncal herniation (transtentorial herniation):', '["The cerebellar tonsils herniate through the foramen magnum","The pituitary gland herniates into the sphenoid sinus","The medial temporal lobe (uncus) herniates through the tentorial notch (compresses CN III, the PCA","The cingulate gyrus herniates under the falx","The brain herniates through a craniotomy defect"]'::jsonb, 'The medial temporal lobe (uncus) herniates through the tentorial notch (compresses CN III, the PCA', 'Uncal herniation (ipsilateral fixed and dilated pupil, hemiparesis, and decreased consciousness) is a life-threatening emergency.'),
('e1a6260e-bd79-5cd0-a94d-1529d244dde2'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'Central (transtentorial) herniation:', '["Uncal herniation and its associated anatomical structures","The diencephalon and the midbrain descend through the tentorial notch (caused by bilateral or mid","Tonsillar herniation and its associated anatomical structures","Transcalvarial herniation and its associated anatomical structures","Cingulate herniation and its associated anatomical structures"]'::jsonb, 'The diencephalon and the midbrain descend through the tentorial notch (caused by bilateral or mid', 'Central herniation causes progressive loss of consciousness, abnormal posturing, and respiratory pattern changes.'),
('523ac2dc-86b9-55e3-bdbe-6f1e2108e25a'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'Tonsillar herniation (coning):', '["The cerebellar tonsils herniate through the foramen magnum (compresses the medulla — causes cardi","Cingulate herniation and its associated anatomical structures","Uncal herniation and its associated anatomical structures","Central herniation and its associated anatomical structures","Transcalvarial herniation and its associated anatomical structures"]'::jsonb, 'The cerebellar tonsils herniate through the foramen magnum (compresses the medulla — causes cardi', 'Tonsillar herniation (coning) is the most dangerous herniation syndrome (compression of the respiratory and cardiac centers in the medulla).'),
('8a5b64c7-ec77-55f8-a141-3c271a7d3760'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'Subfalcine (cingulate) herniation:', '["Tonsillar herniation and its associated anatomical structures","Uncal herniation and its associated anatomical structures","The cingulate gyrus herniates under the falx cerebri (causes ACA compression — contralateral leg","Transcalvarial herniation and its associated anatomical structures","Central herniation and its associated anatomical structures"]'::jsonb, 'The cingulate gyrus herniates under the falx cerebri (causes ACA compression — contralateral leg', 'Subfalcine herniation (the most common herniation pattern) is caused by a mass in the frontal or parietal lobe.'),
('907c879e-cb6e-5944-b8d1-3214120aadc6'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The external occipital protuberance is at the level of:', '["The confluence of sinuses","The superior nuchal line","The inion","The C1 vertebra","The foramen magnum"]'::jsonb, 'The confluence of sinuses', 'The external occipital protuberance (inion) is the landmark for the transverse sinus (the sinus runs laterally from the torcular).'),
('1ddbaedb-264b-5231-887c-88dedb5eac40'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The superior nuchal line is at the level of:', '["The occipital pole and its associated anatomical structures","The confluence of sinuses and its associated anatomical structures","The sigmoid sinus and its associated anatomical structures","The foramen magnum and its associated anatomical structures","The transverse sinus (the sinus runs along the external occipital protuberance and the superior n"]'::jsonb, 'The transverse sinus (the sinus runs along the external occipital protuberance and the superior n', 'The superior nuchal line (the attachment of the occipital muscles) corresponds to the level of the torcular herophili.'),
('3c897c22-ce0a-5d2c-beb2-167517692b61'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The Frankfurt horizontal plane:', '["The orbitomeatal line and its associated anatomical structures","The canthomeatal line and its associated anatomical structures","The Reid baseline and its associated anatomical structures","The infraorbitomeatal line and its associated anatomical structures","A standard anthropological reference plane (from the inferior orbital margin to the upper margin"]'::jsonb, 'A standard anthropological reference plane (from the inferior orbital margin to the upper margin', 'The Frankfurt plane (the orbitomeatal plane) is the zero reference for CT and MRI head imaging.'),
('9cfd5c26-dba5-5fe0-a486-89dbf3c94861'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The Reid baseline (Reid base line):', '["The canthomeatal line and its associated anatomical structures","The orbitomeatal line and its associated anatomical structures","A line from the inferior orbital margin to the upper margin of the external auditory meatus (the","The intercommissural line and its associated anatomical structures","The bicarotid line and its associated anatomical structures"]'::jsonb, 'A line from the inferior orbital margin to the upper margin of the external auditory meatus (the', 'The Reid baseline (orbitomeatal line) is the reference for CT scanning (parallel to the skull base).'),
('524800ad-e139-5e2a-bd84-5f51d9da6c59'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The canthomeatal line:', '["The Reid baseline and its associated anatomical structures","The orbitomeatal line and its associated anatomical structures","The Frankfurt plane and its associated anatomical structures","The intercommissural line and its associated anatomical structures","A line from the lateral canthus of the eye to the external auditory meatus (used for CT and MRI o"]'::jsonb, 'A line from the lateral canthus of the eye to the external auditory meatus (used for CT and MRI o', 'The canthomeatal line (orbito-meatal line) is the most commonly used reference for axial CT of the brain.'),
('11577c63-8c0f-5a10-948c-271423b047c3'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The anatomical landmarks for a lumbar puncture:', '["The iliac crests (the intercristal line at L4-L5) — the needle is inserted at L3-L4 or L4-L5","The coccyx and its associated anatomical structures","The sacral hiatus and its associated anatomical structures","The xiphisternum and its associated anatomical structures","The spinous process of C7 and its associated anatomical structures"]'::jsonb, 'The iliac crests (the intercristal line at L4-L5) — the needle is inserted at L3-L4 or L4-L5', 'The intercristal line (Tuffier line) at the top of the iliac crests crosses the L4 spine or the L4-L5 interspace.'),
('8dbbaf77-ea25-5298-8b1b-ec19e4c2c46d'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The conus medullaris in adults is located at:', '["L1-L2","L4-L5","L2-L3","T12-L1","L3-L4"]'::jsonb, 'L1-L2', 'The conus medullaris (the terminal end of the spinal cord) is at L1-L2 in adults and at L3 in newborns.'),
('1efe545b-0b80-58e7-8580-9f46c5b5692f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The filum terminale:', '["The denticulate ligament and its associated anatomical structures","The conus medullaris and its associated anatomical structures","The cauda equina and its associated anatomical structures","The spinal pia mater and its associated anatomical structures","A pial extension from the conus medullaris to the coccyx (anchors the spinal cord to the vertebra"]'::jsonb, 'A pial extension from the conus medullaris to the coccyx (anchors the spinal cord to the vertebra', 'The filum terminale (terminal filum) consists of the filum terminale internum (pia, within the dural sac) and the filum terminale externum (dura and pia).'),
('fc9f41a0-2503-5b33-ab53-6e64dcc57d94'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The denticulate ligaments:', '["The arachnoid trabeculae and its associated anatomical structures","The spinal ligaments and its associated anatomical structures","The spinal pia and its associated anatomical structures","The filum terminale and its associated anatomical structures","Pial folds on each side of the spinal cord (between the dorsal and ventral roots — anchor the cor"]'::jsonb, 'Pial folds on each side of the spinal cord (between the dorsal and ventral roots — anchor the cor', 'The denticulate ligaments (21 pairs) are landmarks for the lateral corticospinal tract (the spinothalamic tract is anterior to them).'),
('3a93133d-b4ae-56c6-93b0-20285fe7dc99'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The spinal meninges:', '["The filum terminale and the denticulate ligaments and its associated anatomical structures","Only the pia and its associated anatomical structures","Only the dura and its associated anatomical structures","Dura mater (tough outer layer), arachnoid mater (middle layer), and pia mater (inner layer — adhe","Only the arachnoid and its associated anatomical structures"]'::jsonb, 'Dura mater (tough outer layer), arachnoid mater (middle layer), and pia mater (inner layer — adhe', 'The spinal meninges (the covering layers of the spinal cord) are continuous with the cranial meninges through the foramen magnum.'),
('e18a6e54-8657-5cb0-b807-986f0eb9002e'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The epidural space (spinal):', '["The subdural space and its associated anatomical structures","The subarachnoid space and its associated anatomical structures","The space between the dura mater and the vertebral canal (contains fat, loose connective tissue","The extradural space and its associated anatomical structures","The intradural space and its associated anatomical structures"]'::jsonb, 'The space between the dura mater and the vertebral canal (contains fat, loose connective tissue', 'The epidural space (extradural space) is the site for epidural anesthesia (the ligamentum flavum is the landmark for loss of resistance).'),
('62014a50-4f97-5b74-aba4-b5baae065a84'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The subdural space (spinal):', '["The pial space and its associated anatomical structures","The intradural space and its associated anatomical structures","The epidural space and its associated anatomical structures","A potential space between the dura mater and the arachnoid mater","The subarachnoid space and its associated anatomical structures"]'::jsonb, 'A potential space between the dura mater and the arachnoid mater', 'The subdural space (a true or potential space) is the plane for subdural hematomas (bridging veins cross this space).'),
('365b13e9-8e63-5bb1-ade8-6e434f9cdf7a'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The subarachnoid space (spinal):', '["The intradural space and its associated anatomical structures","The space between the arachnoid and the pia (contains CSF, the spinal cord, nerve roots","The pial space and its associated anatomical structures","The subdural space and its associated anatomical structures","The epidural space and its associated anatomical structures"]'::jsonb, 'The space between the arachnoid and the pia (contains CSF, the spinal cord, nerve roots', 'The subarachnoid space (the lumbar cistern between L2 and S2) is the site for lumbar puncture (the needle must reach the subarachnoid space).'),
('716c523d-b11f-5211-956a-9c20340df8eb'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The lumbar cistern (thecal sac):', '["The filum terminale and its associated anatomical structures","The spinal cord and its associated anatomical structures","The conus medullaris and its associated anatomical structures","The cauda equina and its associated anatomical structures","The subarachnoid space below the conus medullaris"]'::jsonb, 'The subarachnoid space below the conus medullaris', 'The lumbar cistern (the dural sac ends at S2) is the safest site for CSF sampling (below the level of the spinal cord).'),
('facb33e3-0962-5801-ad45-53902f3144b0'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The cauda equina consists of:', '["The conus medullaris and its associated anatomical structures","The dorsal and ventral roots of the lumbar, sacral, and coccygeal nerves (below the conus medulla","The denticulate ligaments and its associated anatomical structures","The filum terminale and its associated anatomical structures","The spinal cord and its associated anatomical structures"]'::jsonb, 'The dorsal and ventral roots of the lumbar, sacral, and coccygeal nerves (below the conus medulla', 'The cauda equina (horse tail) is the bundle of nerve roots within the lumbar cistern (cauda equina syndrome is a surgical emergency).'),
('218d564d-81ea-57f0-b7fb-776ed01919d1'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The myodural bridge:', '["The filum terminale and its associated anatomical structures","The subarachnoid space and its associated anatomical structures","The epidural space and its associated anatomical structures","A connective tissue band from the rectus capitis posterior minor to the dura (may be involved in","The denticulate ligament and its associated anatomical structures"]'::jsonb, 'A connective tissue band from the rectus capitis posterior minor to the dura (may be involved in', 'The myodural bridge (the suboccipital muscle connection to the dura) is a recently described anatomical structure.'),
('36d82cba-8b9c-5674-a293-b7ad9f8107ea'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The internal vertebral venous plexus (Batson plexus):', '["The hemiazygos vein and its associated anatomical structures","A valveless venous plexus within the epidural space (connects the pelvic, abdominal","The vertebral veins and its associated anatomical structures","The azygos vein and its associated anatomical structures","The exterior vertebral venous plexus and its associated anatomical structures"]'::jsonb, 'A valveless venous plexus within the epidural space (connects the pelvic, abdominal', 'Batson plexus (the vertebral venous plexus) provides a route for the spread of prostate, breast, and lung cancer metastases to the spine.'),
('d15374f3-8f76-5d68-b720-c9051143191a'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The craniovertebral junction (CVJ):', '["The cervicothoracic junction and its associated anatomical structures","The sacrococcygeal junction and its associated anatomical structures","The region of the occipital bone, the atlas (C1), and the axis (C2) — the most mobile part of the","The lumbosacral junction and its associated anatomical structures","The thoracolumbar junction and its associated anatomical structures"]'::jsonb, 'The region of the occipital bone, the atlas (C1), and the axis (C2) — the most mobile part of the', 'The CVJ (the transition between the skull and the spine) is a complex anatomical region prone to congenital anomalies and traumatic injuries.'),
('3ac09ed4-3253-518a-b56e-bfb96bf6c945'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The atlanto-occipital joint:', '["A synovial joint (between the occipital condyles and the superior articular facets of the atlas —","The sacroiliac joint and its associated anatomical structures","The shoulder joint and its associated anatomical structures","The temporomandibular joint and its associated anatomical structures","The atlantoaxial joint and its associated anatomical structures"]'::jsonb, 'A synovial joint (between the occipital condyles and the superior articular facets of the atlas —', 'The atlanto-occipital joint (a condylar joint) allows about 15 degrees of flexion-extension (the movement of nodding).'),
('a5939a41-094f-5106-8dbc-5b23c2c2539d'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The atlantoaxial joint:', '["The atlanto-occipital joint and its associated anatomical structures","The facet joint and its associated anatomical structures","Three synovial joints (one median: dens-anterior arch of atlas; two lateral","The atlantoaxial joint and its associated anatomical structures","The intervertebral disc and its associated anatomical structures"]'::jsonb, 'Three synovial joints (one median: dens-anterior arch of atlas; two lateral', 'The atlantoaxial joint (the dens is the pivot) provides 50% of the rotation of the neck (head rotation).'),
('5a17c372-7238-55d1-b2f1-dd82fc1cdbf5'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The transverse ligament of the atlas:', '["The cruciform ligament and its associated anatomical structures","The tectorial membrane and its associated anatomical structures","The apical ligament and its associated anatomical structures","A strong ligament that holds the dens against the anterior arch of the atlas (prevents C1-C2 subl","The alar ligament and its associated anatomical structures"]'::jsonb, 'A strong ligament that holds the dens against the anterior arch of the atlas (prevents C1-C2 subl', 'The transverse ligament (the strongest ligament of the atlantoaxial complex) ruptures in Jefferson fracture or in Down syndrome (atlantoaxial instability).'),
('4ff7704f-bd53-5723-a8bd-1ca234e3dafc'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The alar ligaments:', '["The cruciform ligament and its associated anatomical structures","The tectorial membrane and its associated anatomical structures","The apical ligament and its associated anatomical structures","Two strong ligaments from the dens to the occipital condyles (check rotation and side-bending of","The transverse ligament and its associated anatomical structures"]'::jsonb, 'Two strong ligaments from the dens to the occipital condyles (check rotation and side-bending of', 'The alar ligaments (paired) limit rotation of the head to about 20 degrees (ruptured in severe flexion-rotation injuries).'),
('ee68c014-8a32-5cf4-8acd-1b2a999f5ffe'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The apical ligament of the dens:', '["A small midline ligament from the apex of the dens to the anterior margin of the foramen magnum (","The transverse ligament and its associated anatomical structures","The alar ligament and its associated anatomical structures","The cruciform ligament and its associated anatomical structures","The tectorial membrane and its associated anatomical structures"]'::jsonb, 'A small midline ligament from the apex of the dens to the anterior margin of the foramen magnum (', 'The apical ligament (a vestigial structure) is of little clinical significance (does not provide significant mechanical stability).'),
('61823ab4-a984-5b62-bf4c-9c23452e4bc1'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The cruciform ligament:', '["A cross-shaped ligament (the transverse ligament + longitudinal bands) that stabilizes the dens a","The transverse ligament and its associated anatomical structures","The apical ligament and its associated anatomical structures","The alar ligament and its associated anatomical structures","The tectorial membrane and its associated anatomical structures"]'::jsonb, 'A cross-shaped ligament (the transverse ligament + longitudinal bands) that stabilizes the dens a', 'The cruciform ligament (the cross of the atlas) consists of the strong transverse ligament and two vertical bands (ascending and descending).'),
('82b00c4d-6f8a-5c48-90d2-ded65f416268'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'With respect to management, The tectorial membrane:', '["The supraspinous ligament and its associated anatomical structures","The posterior longitudinal ligament and its associated anatomical structures","The anterior longitudinal ligament and its associated anatomical structures","The upward continuation of the posterior longitudinal ligament (from the axis to the clivus — beh","The ligamentum flavum and its associated anatomical structures"]'::jsonb, 'The upward continuation of the posterior longitudinal ligament (from the axis to the clivus — beh', 'The tectorial membrane (the ''covering membrane'') is a broad ligament that covers the dens and its ligaments (extends from the axis to the clivus).'),
('5e84010f-b37b-5e43-aeef-d9294f0dfd2c'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The anterior atlanto-occipital membrane:', '["The tectorial membrane and its associated anatomical structures","A broad fibrous band between the anterior arch of the atlas and the foramen magnum (the continuat","The posterior atlanto-occipital membrane and its associated anatomical structures","The cruciform ligament and its associated anatomical structures","The ligamentum flavum and its associated anatomical structures"]'::jsonb, 'A broad fibrous band between the anterior arch of the atlas and the foramen magnum (the continuat', 'The anterior atlanto-occipital membrane (the supra-atlantal extension of the ALL) covers the atlanto-occipital joint anteriorly.'),
('aa25b362-8685-5fa9-bf27-03fab57ee7d1'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The posterior atlanto-occipital membrane:', '["The anterior atlanto-occipital membrane and its associated anatomical structures","The tectorial membrane and its associated anatomical structures","A broad band between the posterior arch of the atlas and the foramen magnum (the continuation of","The nuchal ligament and its associated anatomical structures","The ligamentum flavum and its associated anatomical structures"]'::jsonb, 'A broad band between the posterior arch of the atlas and the foramen magnum (the continuation of', 'The posterior atlanto-occipital membrane (the posterior atlanto-occipital membrane) is pierced by the vertebral artery, the first cervical nerve, and the posterior spinal artery.'),
('5af56c80-17e7-54ef-a251-4657755ff704'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The nuchal ligament (ligamentum nuchae):', '["The anterior longitudinal ligament and its associated anatomical structures","A thick midline ligament from the external occipital protuberance to the C7 spinous process (the","The supraspinous ligament and its associated anatomical structures","The interspinous ligament and its associated anatomical structures","The ligamentum flavum and its associated anatomical structures"]'::jsonb, 'A thick midline ligament from the external occipital protuberance to the C7 spinous process (the', 'The nuchal ligament (the posterior cervical ligament) is the continuation of the supraspinous ligament in the neck.'),
('b01bfc14-6787-5f1c-b025-11917b746055'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The anterior longitudinal ligament (ALL):', '["The supraspinous ligament and its associated anatomical structures","The posterior longitudinal ligament and its associated anatomical structures","The ligamentum flavum and its associated anatomical structures","A strong band on the anterior surface of the vertebral bodies (from the occiput to the sacrum — p","The interspinous ligament and its associated anatomical structures"]'::jsonb, 'A strong band on the anterior surface of the vertebral bodies (from the occiput to the sacrum — p', 'The ALL (the only ligament that lies on the anterior surface of the spine) is thicker in the thoracic region (prevents anterior disc herniation and hyperextension).'),
('fb35af10-dfde-5abe-a561-d63d20eb77b2'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The posterior longitudinal ligament (PLL):', '["The anterior longitudinal ligament and its associated anatomical structures","The supraspinous ligament and its associated anatomical structures","A band on the posterior surface of the vertebral bodies (within the vertebral canal — prevents hy","The ligamentum flavum and its associated anatomical structures","The interspinous ligament and its associated anatomical structures"]'::jsonb, 'A band on the posterior surface of the vertebral bodies (within the vertebral canal — prevents hy', 'The PLL is narrower and weaker than the ALL (the posterolateral disc herniations are common because the PLL is thin).'),
('81a8e755-8477-53df-be9e-60a00f35cd28'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The ligamentum flavum:', '["A yellow elastic ligament between the laminae of adjacent vertebrae (the last ligament pierced du","The anterior longitudinal ligament and its associated anatomical structures","The supraspinous ligament and its associated anatomical structures","The interspinous ligament and its associated anatomical structures","The posterior longitudinal ligament and its associated anatomical structures"]'::jsonb, 'A yellow elastic ligament between the laminae of adjacent vertebrae (the last ligament pierced du', 'The ligamentum flavum (the yellow ligament) is thickest in the lumbar region (epidural anesthesia depends on the loss of resistance as the needle pierces it).'),
('e765910d-779a-561b-bf41-41d050d730a1'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The supraspinous ligament:', '["A fibrous band connecting the tips of the spinous processes (from C7 to the sacrum — the nuchal l","The interspinous ligament and its associated anatomical structures","The posterior longitudinal ligament and its associated anatomical structures","The anterior longitudinal ligament and its associated anatomical structures","The ligamentum flavum and its associated anatomical structures"]'::jsonb, 'A fibrous band connecting the tips of the spinous processes (from C7 to the sacrum — the nuchal l', 'The supraspinous ligament (palpable as a ridge in the midline of the back) is punctured during a midline lumbar puncture.'),
('d3a74d04-2d47-57e0-ae07-9fa7808e18da'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The interspinous ligament:', '["The anterior longitudinal ligament and its associated anatomical structures","The posterior longitudinal ligament and its associated anatomical structures","The ligamentum flavum and its associated anatomical structures","The supraspinous ligament and its associated anatomical structures","A thin fibrous band between adjacent spinous processes (lies between the supraspinous ligament an"]'::jsonb, 'A thin fibrous band between adjacent spinous processes (lies between the supraspinous ligament an', 'The interspinous ligament (the weakest ligament in the spine) is the first ligament pierced during a paramedian lumbar puncture.'),
('e9cb4c79-23c2-5669-8911-1e24f3607b6d'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The intertransverse ligament:', '["A thin membrane between the transverse processes (less developed in the cervical and lumbar spines","The supraspinous ligament and its associated anatomical structures","The ligamentum flavum and its associated anatomical structures","The interspinous ligament and its associated anatomical structures","The anterior longitudinal ligament and its associated anatomical structures"]'::jsonb, 'A thin membrane between the transverse processes (less developed in the cervical and lumbar spines', 'The intertransverse ligament (ligament between the transverse processes) is important for segmental stability.'),
('76882891-3022-5132-ac34-42ee5a639421'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The craniectomy:', '["A burr hole and its associated anatomical structures","The cranioplasty and its associated anatomical structures","The craniotomy and its associated anatomical structures","The surgical removal of a part of the skull (without replacement — for decompression in increased","A trephination and its associated anatomical structures"]'::jsonb, 'The surgical removal of a part of the skull (without replacement — for decompression in increased', 'A decompressive craniectomy (the removal of a large skull segment) is a life-saving procedure for refractory intracranial hypertension.'),
('a0398c7b-3962-548d-9a23-0008ae02ca02'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The external auditory meatus is formed by:', '["The zygomatic process","The tympanic part of the temporal bone","The petrous temporal bone","The mastoid process","The squamous temporal bone"]'::jsonb, 'The tympanic part of the temporal bone', 'The external auditory meatus (the ear canal, 2.5 cm) has an outer cartilaginous 1/3 and an inner bony 2/3.'),
('ab2bd9dc-15b6-5a45-a38e-e4d1ec4ee32c'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The tympanic membrane is innervated by:', '["CN V1 and its associated anatomical structures","CN V2 and its associated anatomical structures","CN IX and its associated anatomical structures","CN V3 (mandibular nerve — auriculotemporal branch) and CN VII (facial nerve) and CN X","CN VIII and its associated anatomical structures"]'::jsonb, 'CN V3 (mandibular nerve — auriculotemporal branch) and CN VII (facial nerve) and CN X', 'The tympanic membrane (the sensory innervation is from CN V3, CN VII, and CN X) — irritation of the posterior wall (CN X) can cause cough.'),
('1d601b10-35e4-554b-874a-606758467502'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The pharyngotympanic tube (eustachian tube):', '["Connects the external ear to the middle ear and its associated anatomical structures","Connects the nose to the throat and its associated anatomical structures","Connects the nasopharynx (above the soft palate) to the middle ear (the bony part is 1/3","Connects the middle ear to the inner ear and its associated anatomical structures","Connects the middle ear to the mastoid and its associated anatomical structures"]'::jsonb, 'Connects the nasopharynx (above the soft palate) to the middle ear (the bony part is 1/3', 'The eustachian tube (the opening is in the nasopharynx, behind the inferior turbinate) is opened by the tensor veli palatini.'),
('7fbc7391-3c0c-537e-8cce-b9c64cd77249'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The fissula ante fenestram:', '["A small cleft of connective tissue in the otic capsule (anterior to the oval window — a site of p","The cochlear aqueduct and its associated anatomical structures","The round window and its associated anatomical structures","The vestibular aqueduct and its associated anatomical structures","The oval window and its associated anatomical structures"]'::jsonb, 'A small cleft of connective tissue in the otic capsule (anterior to the oval window — a site of p', 'Otosclerosis (abnormal bone remodeling in the fissula ante fenestram) causes stapes fixation and conductive hearing loss.'),
('19e09b3c-97c9-50a8-8121-6d53c8c2ae0f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The modiolus of the cochlea:', '["The basilar membrane and its associated anatomical structures","The central bony core of the cochlea (contains the spiral canal for the cochlear nerve and the sp","The organ of Corti and its associated anatomical structures","The Reissner membrane and its associated anatomical structures","The spiral ligament and its associated anatomical structures"]'::jsonb, 'The central bony core of the cochlea (contains the spiral canal for the cochlear nerve and the sp', 'The modiolus (the axial pillar of the cochlea) is perforated by the cochlear nerve fibers and blood vessels.'),
('f08ba912-dd74-53c1-9a71-5575dc3f93a3'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The spiral ganglion:', '["The sensory ganglion of the cochlear nerve (located in the modiolus, contains the cell bodies of","The spiral organ and its associated anatomical structures","The vestibular ganglion and its associated anatomical structures","The trigeminal ganglion and its associated anatomical structures","The geniculate ganglion and its associated anatomical structures"]'::jsonb, 'The sensory ganglion of the cochlear nerve (located in the modiolus, contains the cell bodies of', 'The spiral ganglion (the first-order neurons for hearing) receives input from the inner hair cells of the organ of Corti.'),
('62dc9604-f82a-50ba-98b7-bc9a12b9fcda'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The vestibular (Scarpa) ganglion:', '["The ciliary ganglion and its associated anatomical structures","The spiral ganglion and its associated anatomical structures","The geniculate ganglion and its associated anatomical structures","The trigeminal ganglion and its associated anatomical structures","The sensory ganglion of the vestibular nerve (in the internal acoustic meatus — contains the cell"]'::jsonb, 'The sensory ganglion of the vestibular nerve (in the internal acoustic meatus — contains the cell', 'The vestibular ganglion (Scarpa ganglion) is located in the fundus of the IAM (the superior part for the utricle and the superior semicircular canal; the inferior part for the saccule and the posterior semicircular canal).'),
('d1f007df-8843-58c1-8882-6803e6981afe'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The bony labyrinth (the otic capsule):', '["The cavity in the petrous temporal bone (contains the membranous labyrinth — the cochlea, vestibule","The external ear and its associated anatomical structures","The facial canal and its associated anatomical structures","The internal acoustic meatus and its associated anatomical structures","The middle ear and its associated anatomical structures"]'::jsonb, 'The cavity in the petrous temporal bone (contains the membranous labyrinth — the cochlea, vestibule', 'The bony labyrinth (otic capsule) is the hardest bone in the body (otosclerosis involves abnormal bone remodeling within the otic capsule).'),
('ec68e293-547b-5153-82ab-576139fecef3'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The endolymphatic hydrops:', '["A decrease in perilymph and its associated anatomical structures","A normal variant and its associated anatomical structures","An increase in the volume of endolymph (causes Meniere disease — episodic vertigo, tinnitus","A decrease in endolymph and its associated anatomical structures","An increase in perilymph and its associated anatomical structures"]'::jsonb, 'An increase in the volume of endolymph (causes Meniere disease — episodic vertigo, tinnitus', 'Meniere disease (endolymphatic hydrops) is characterized by intermittent vertigo (lasting 20 minutes to 12 hours) with aural fullness.'),
('82d241c6-c3c2-5a8c-87c6-4ad712cedee5'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The perilymph fistula:', '["A labyrinthine fistula and its associated anatomical structures","An endolymphatic fistula and its associated anatomical structures","An abnormal communication between the middle ear and the perilymphatic space (causes hearing loss","A CSF fistula and its associated anatomical structures","A middle ear effusion and its associated anatomical structures"]'::jsonb, 'An abnormal communication between the middle ear and the perilymphatic space (causes hearing loss', 'A perilymph fistula (the oval window or the round window rupture) causes sudden hearing loss and vertigo (the fistula test is positive for nystagmus).'),
('9f59e6ee-3715-5c5f-92fd-ed0f7b07cfab'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The stapedius muscle:', '["The malleus and its associated anatomical structures","A tiny muscle in the middle ear (stabilizes the stapes and protects the inner ear from loud sound","The stapes and its associated anatomical structures","The tensor tympani and its associated anatomical structures","The incus and its associated anatomical structures"]'::jsonb, 'A tiny muscle in the middle ear (stabilizes the stapes and protects the inner ear from loud sound', 'The stapedius muscle (the smallest striated muscle in the body) contracts in response to loud sounds (the acoustic reflex).'),
('4cdeebfb-ce28-5b0b-a937-7e41038b8f3f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The tensor tympani muscle:', '["Tenses the tympanic membrane","Opens the eustachian tube","Stabilizes the stapes","Moves the incus","Closes the eustachian tube"]'::jsonb, 'Tenses the tympanic membrane', 'The tensor tympani (CN V3) is the second middle ear muscle (both tensor tympani and stapedius contract in the acoustic reflex).'),
('c5766101-a6bc-5501-9ef8-3d8dc40edecb'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The acoustic reflex (stapedial reflex):', '["The cochlear reflex and its associated anatomical structures","The acoustic blink reflex and its associated anatomical structures","The startle reflex and its associated anatomical structures","Bilateral contraction of the stapedius muscles in response to loud sound (>70 dB","The tensor tympani reflex and its associated anatomical structures"]'::jsonb, 'Bilateral contraction of the stapedius muscles in response to loud sound (>70 dB', 'The acoustic reflex (the stapedial reflex) protects the cochlea from loud sounds and is used clinically to assess hearing (acoustic reflex testing).'),
('8e23fb62-8208-5c72-9fb4-3e8f82f06e43'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The cochlear microphonic potential:', '["The summating potential and its associated anatomical structures","The auditory brainstem response and its associated anatomical structures","The endocochlear potential and its associated anatomical structures","An electrical potential generated by the outer hair cells of the cochlea (the cochlear amplifier","The action potential of CN VIII and its associated anatomical structures"]'::jsonb, 'An electrical potential generated by the outer hair cells of the cochlea (the cochlear amplifier', 'The cochlear microphonic (CM) is used in electrophysiologic testing of hearing (the CM is present in auditory neuropathy spectrum disorder).'),
('a2cb46ee-690e-54c2-a84e-b324063cbdab'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The otoacoustic emissions (OAEs):', '["Sounds from the middle ear and its associated anatomical structures","Sounds from the brainstem and its associated anatomical structures","Sounds from the auditory nerve and its associated anatomical structures","Sounds from the inner ear and its associated anatomical structures","Low-intensity sounds produced by the outer hair cells of the cochlea (in response to acoustic sti"]'::jsonb, 'Low-intensity sounds produced by the outer hair cells of the cochlea (in response to acoustic sti', 'OAEs (distortion product or transient evoked) assess the integrity of the cochlear outer hair cells (absent in sensorineural hearing loss > 40 dB).'),
('81ee1475-9649-58ce-99ee-de59f99f0540'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The auditory brainstem response (ABR):', '["The middle latency response and its associated anatomical structures","Electrophysiologic waveforms recorded from the scalp in response to clicks (waves I-VII from the","The otoacoustic emissions and its associated anatomical structures","The electrocochleography and its associated anatomical structures","The cochlear microphonic and its associated anatomical structures"]'::jsonb, 'Electrophysiologic waveforms recorded from the scalp in response to clicks (waves I-VII from the', 'ABR (auditory brainstem response) is used for hearing threshold estimation, acoustic neuroma screening, and intraoperative monitoring of CN VIII.'),
('d59d42b4-641d-5141-956f-08baa839f363'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The caloric reflex test:', '["The Dix-Hallpike test and its associated anatomical structures","The optokinetic nystagmus and its associated anatomical structures","The head impulse test and its associated anatomical structures","Irrigation of the external auditory canal with warm or cold water (induces nystagmus — tests the","The rotary chair test and its associated anatomical structures"]'::jsonb, 'Irrigation of the external auditory canal with warm or cold water (induces nystagmus — tests the', 'The caloric test (cold water induces nystagmus away from the irrigated ear; warm water induces nystagmus toward the ear — COWS: Cold Opposite Warm Same).'),
('69140231-a4c2-5d56-af3c-b79cd6dfd5d1'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The vestibulo-ocular reflex (VOR):', '["The saccadic eye movement and its associated anatomical structures","The smooth pursuit and its associated anatomical structures","A reflex that stabilizes the eyes during head movement (afferent: vestibular nerve","The optokinetic reflex and its associated anatomical structures","The cervico-ocular reflex and its associated anatomical structures"]'::jsonb, 'A reflex that stabilizes the eyes during head movement (afferent: vestibular nerve', 'The VOR (the gain of the eye movement is equal to the head movement — the head impulse test is used to assess the VOR in peripheral vertigo).'),
('99f1f212-89f7-52cb-8674-7995d9e00bc7'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The anterior semicircular canal:', '["The saccule","The utricle","Detects head rotation in the sagittal plane","The lateral semicircular canal","The posterior semicircular canal"]'::jsonb, 'Detects head rotation in the sagittal plane', 'The anterior (superior) semicircular canal (at a right angle to the lateral and posterior canals) is the most common canal involved in BPPV.'),
('55208580-46b2-5b1d-b8a0-dd5af6d394c2'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The lateral (horizontal) semicircular canal:', '["The utricle and its associated anatomical structures","The saccule and its associated anatomical structures","Detects head rotation in the horizontal plane (the yaw plane — the canal that is most sensitive t","The posterior semicircular canal and its associated anatomical structures","The anterior semicircular canal and its associated anatomical structures"]'::jsonb, 'Detects head rotation in the horizontal plane (the yaw plane — the canal that is most sensitive t', 'The lateral semicircular canal (30 degrees from the horizontal) is tested in the caloric reflex test (the canal that is most accessible).'),
('5a89500c-ff4c-524c-ace7-0993e24d6e66'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The posterior semicircular canal:', '["The lateral semicircular canal","The anterior semicircular canal","The utricle","The saccule","Detects head rotation in the coronal plane"]'::jsonb, 'Detects head rotation in the coronal plane', 'The posterior semicircular canal (the longest canal) is the second most common canal involved in BPPV (the Dix-Hallpike test triggers nystagmus).'),
('27d7d040-b1cb-57ba-926c-b2335a78eb5a'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'Benign paroxysmal positional vertigo (BPPV):', '["Episodic vertigo from otoconia dislodged into the semicircular canal (usually the posterior canal","The vestibular neuronitis and its associated anatomical structures","The perilymph fistula and its associated anatomical structures","The central vertigo and its associated anatomical structures","Meniere disease and its associated anatomical structures"]'::jsonb, 'Episodic vertigo from otoconia dislodged into the semicircular canal (usually the posterior canal', 'BPPV (canalithiasis — free-floating particles in the semicircular canal) is treated by canalith repositioning (Epley or Semont maneuver).'),
('71dd94e1-319a-580b-80fa-bf0dc3bc61a0'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'Vestibular neuronitis (vestibular neuritis):', '["BPPV and its associated anatomical structures","Acute unilateral vestibular dysfunction (severe vertigo without hearing loss — likely viral","The central vertigo and its associated anatomical structures","The labyrinthitis and its associated anatomical structures","Meniere disease and its associated anatomical structures"]'::jsonb, 'Acute unilateral vestibular dysfunction (severe vertigo without hearing loss — likely viral', 'Vestibular neuronitis (the vestibular nerve inflammation) causes constant vertigo for days (the head impulse test is positive).'),
('4f55d3d7-c9d2-58fc-b712-24a11fb715f3'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'Labyrinthitis:', '["Vestibular neuronitis and its associated anatomical structures","BPPV and its associated anatomical structures","Inflammation of the inner ear (vertigo with hearing loss — may be viral or bacterial","Meniere disease and its associated anatomical structures","The otosclerosis and its associated anatomical structures"]'::jsonb, 'Inflammation of the inner ear (vertigo with hearing loss — may be viral or bacterial', 'Labyrinthitis (the inflammation of the labyrinth) may be serous (viral, self-limited) or suppurative (bacterial, destructive).'),
('9ef24c8f-8d44-5991-bf71-84606bdacbc4'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The endolymphatic shunt:', '["A cochlear implant and its associated anatomical structures","A stapedectomy and its associated anatomical structures","A mastoidectomy and its associated anatomical structures","A surgical treatment for Meniere disease (drains the endolymph from the endolymphatic sac to the","A tympanoplasty and its associated anatomical structures"]'::jsonb, 'A surgical treatment for Meniere disease (drains the endolymph from the endolymphatic sac to the', 'The endolymphatic shunt (the endolymphatic sac decompression) is an invasive procedure for intractable Meniere disease.'),
('3ef85c33-21d5-5e46-9d23-dbb16c7511ba'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The cochlear implant:', '["A bone-anchored hearing aid and its associated anatomical structures","A neural prosthesis that electrically stimulates the spiral ganglion cells (for severe-to-profoun","A hearing aid and its associated anatomical structures","A brainstem implant and its associated anatomical structures","A middle ear implant and its associated anatomical structures"]'::jsonb, 'A neural prosthesis that electrically stimulates the spiral ganglion cells (for severe-to-profoun', 'A cochlear implant (the internal electrode array is inserted into the scala tympani) bypasses the outer hair cells and directly stimulates the auditory nerve.'),
('20226b46-041b-5706-a2b8-b9a4e485613d'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The round window is the site for:', '["Stapedectomy and its associated anatomical structures","Cochlear implant electrode insertion (the electrode array passes through the round window into th","Mastoidectomy and its associated anatomical structures","Tympanostomy tube insertion and its associated anatomical structures","Myringotomy and its associated anatomical structures"]'::jsonb, 'Cochlear implant electrode insertion (the electrode array passes through the round window into th', 'The round window (fenestra cochleae) is the standard surgical access to the cochlea for cochlear implantation.'),
('14b69e71-a999-51b2-91e6-2fd1f3d9b203'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The superior canal dehiscence syndrome (SCDS):', '["The perilymph fistula and its associated anatomical structures","BPPV and its associated anatomical structures","Meniere disease and its associated anatomical structures","A thinning or absence of the bone over the superior semicircular canal (causes sound- or pressure","The otosclerosis and its associated anatomical structures"]'::jsonb, 'A thinning or absence of the bone over the superior semicircular canal (causes sound- or pressure', 'SCDS (Minor syndrome) causes vertigo and nystagmus in response to loud sounds (Tullio phenomenon) or pressure (the Valsalva maneuver).'),
('a629c868-2789-57d1-8537-1daa2646f7a1'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The Tullio phenomenon:', '["The caloric nystagmus and its associated anatomical structures","The optokinetic nystagmus and its associated anatomical structures","The spontaneous nystagmus and its associated anatomical structures","The positional nystagmus and its associated anatomical structures","Vertigo and nystagmus induced by loud sounds (associated with superior canal dehiscence or perily"]'::jsonb, 'Vertigo and nystagmus induced by loud sounds (associated with superior canal dehiscence or perily', 'The Tullio phenomenon (sound-induced vertigo) is a characteristic symptom of superior canal dehiscence syndrome.'),
('ddb39483-6d35-5c47-8f49-c12ff75ad728'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The Hennebert sign:', '["Vertigo and nystagmus induced by pressure on the tragus or the outer ear (in perilymph fistula or","The Tullio phenomenon and its associated anatomical structures","The Romberg test and its associated anatomical structures","The head impulse test and its associated anatomical structures","The Dix-Hallpike test and its associated anatomical structures"]'::jsonb, 'Vertigo and nystagmus induced by pressure on the tragus or the outer ear (in perilymph fistula or', 'The Hennebert sign (the positive fistula test) indicates an abnormal communication between the middle ear and the inner ear.'),
('b0313730-de3c-5769-aeed-e2694ce78622'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The Dix-Hallpike test:', '["The head impulse test and its associated anatomical structures","The caloric reflex test and its associated anatomical structures","The optokinetic test and its associated anatomical structures","The provocative test for BPPV (the patient is moved from sitting to supine with the head turned t","The rotary chair test and its associated anatomical structures"]'::jsonb, 'The provocative test for BPPV (the patient is moved from sitting to supine with the head turned t', 'The Dix-Hallpike test (the Hallpike maneuver) is the gold standard for the diagnosis of posterior canal BPPV.'),
('1da1cbb6-6ea2-5175-b7c9-98521b79c545'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The Epley maneuver:', '["The Semont maneuver and its associated anatomical structures","The Gufoni maneuver and its associated anatomical structures","The liberatory maneuver and its associated anatomical structures","The canalith repositioning maneuver for posterior canal BPPV (a series of head and body rotations","The Brandt-Daroff exercises and its associated anatomical structures"]'::jsonb, 'The canalith repositioning maneuver for posterior canal BPPV (a series of head and body rotations', 'The Epley maneuver (the particle repositioning maneuver) has a success rate of > 80% for treating posterior canal BPPV.'),
('fb073bda-ad0f-530d-8639-f2e9fb42d446'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The Semont maneuver:', '["The liberatory maneuver for posterior canal BPPV (a rapid 180-degree rotation from the side-lying","The Epley maneuver and its associated anatomical structures","The canalith repositioning maneuver and its associated anatomical structures","The Gufoni maneuver and its associated anatomical structures","The Brandt-Daroff exercises and its associated anatomical structures"]'::jsonb, 'The liberatory maneuver for posterior canal BPPV (a rapid 180-degree rotation from the side-lying', 'The Semont maneuver (a less commonly used maneuver) is effective for posterior canal BPPV but requires the patient to move quickly.'),
('0b7b45ff-363d-50f7-94e9-642159cad2aa'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The Brandt-Daroff exercises:', '["The Semont maneuver and its associated anatomical structures","Habituation exercises for BPPV (repeated lateral head and body tilts — performed at home by the p","The Gufoni maneuver and its associated anatomical structures","The liberatory maneuver and its associated anatomical structures","The Epley maneuver and its associated anatomical structures"]'::jsonb, 'Habituation exercises for BPPV (repeated lateral head and body tilts — performed at home by the p', 'The Brandt-Daroff exercises (the home exercise program for BPPV) are less effective than the Epley maneuver but are used for residual symptoms.'),
('abc138c5-970c-55a3-a26f-ff2cfc959bdc'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The mastoid tip is a landmark for:', '["The glossopharyngeal nerve and its associated anatomical structures","The hypoglossal nerve and its associated anatomical structures","The facial nerve and its associated anatomical structures","The accessory nerve (CN XI) as it enters the SCM","The vagus nerve and its associated anatomical structures"]'::jsonb, 'The accessory nerve (CN XI) as it enters the SCM', 'The mastoid tip (the insertion of the SCM) is a landmark for the spinal accessory nerve (CN XI) in the posterior triangle of the neck.'),
('dc4609fd-0fd2-5145-9645-30983dbfbcc9'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The sternocleidomastoid (SCM) muscle arises from:', '["The clavicle and the spine and its associated anatomical structures","The mastoid and the occipital bone and its associated anatomical structures","The manubrium (sternal head) and the medial clavicle (clavicular head) — inserts on the mastoid p","The trapezius and the omohyoid and its associated anatomical structures","The mandible and the hyoid and its associated anatomical structures"]'::jsonb, 'The manubrium (sternal head) and the medial clavicle (clavicular head) — inserts on the mastoid p', 'The SCM (innervated by CN XI and C2-C3) rotates the head to the opposite side and flexes the neck.'),
('69e43c95-5d27-520e-92d8-5e1e03a5745d'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The trapezius muscle arises from:', '["The external occipital protuberance, the nuchal ligament, and the spinous processes of C7-T12 — i","The mastoid process and the clavicle and its associated anatomical structures","The occipital bone and the mastoid and its associated anatomical structures","The spine and the sacrum and its associated anatomical structures","The sternum and the clavicle and its associated anatomical structures"]'::jsonb, 'The external occipital protuberance, the nuchal ligament, and the spinous processes of C7-T12 — i', 'The trapezius (innervated by CN XI and C3-C4) elevates, retracts, and rotates the scapula (shoulder shrug).'),
('9cb5710f-bd80-5966-b682-44ce4cf1386f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The spinal accessory nerve (CN XI) is at risk during:', '["The posterior triangle lymph node biopsy (the nerve runs in the posterior triangle","The carotid endarterectomy and its associated anatomical structures","The submandibular gland excision and its associated anatomical structures","The parotidectomy and its associated anatomical structures","The thyroidectomy and its associated anatomical structures"]'::jsonb, 'The posterior triangle lymph node biopsy (the nerve runs in the posterior triangle', 'CN XI injury (during posterior triangle lymph node biopsy or neck dissection) causes shoulder droop, scapular winging, and difficulty shrugging.'),
('0e72fbeb-7a34-528b-b63e-fb470e19148c'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The phrenic nerve (C3-C5) is at risk during:', '["The thyroid surgery and its associated anatomical structures","The cardiovascular surgery (especially during the internal thoracic artery harvesting and the cen","The submandibular surgery and its associated anatomical structures","The parotid surgery and its associated anatomical structures","The lymph node biopsy and its associated anatomical structures"]'::jsonb, 'The cardiovascular surgery (especially during the internal thoracic artery harvesting and the cen', 'The phrenic nerve (descending on the anterior scalene muscle) can be injured in the root of the neck (phrenic nerve palsy causes an elevated hemidiaphragm).'),
('cd85a279-1370-5046-a055-491121b2ca53'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The brachial plexus (C5-T1) is at risk during:', '["The first rib fracture or the clavicle fracture (the roots of the brachial plexus over the first","The radius fracture and its associated anatomical structures","The scapula fracture and its associated anatomical structures","The ulna fracture and its associated anatomical structures","The humerus fracture and its associated anatomical structures"]'::jsonb, 'The first rib fracture or the clavicle fracture (the roots of the brachial plexus over the first', 'The brachial plexus (the roots between the anterior and middle scalenes) can be injured in the birth trauma (Erb-Duchenne palsy C5-C6 and Klumpke palsy C8-T1).'),
('d12edaec-a034-5895-ac2b-8e14c17c6035'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The hypoglossal nerve (CN XII) is at risk during:', '["The lymph node biopsy and its associated anatomical structures","The parotid surgery and its associated anatomical structures","The submandibular surgery and its associated anatomical structures","The thyroid surgery and its associated anatomical structures","The carotid endarterectomy (the nerve is looped over the carotid bifurcation — The ansa cervicali"]'::jsonb, 'The carotid endarterectomy (the nerve is looped over the carotid bifurcation — The ansa cervicali', 'CN XII (the motor nerve to the tongue) loops around the carotid bifurcation and is vulnerable during carotid endarterectomy (deviation of the tongue to the side of injury).'),
('56e8fd77-8557-514e-a1b6-9403379db863'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The marginal mandibular nerve (CN VII) is at risk during:', '["The thyroid surgery and its associated anatomical structures","The submandibular gland excision and the parotid surgery (the nerve runs along the angle of the m","The lymph node biopsy and its associated anatomical structures","The sternocleidomastoid release and its associated anatomical structures","The carotid endarterectomy and its associated anatomical structures"]'::jsonb, 'The submandibular gland excision and the parotid surgery (the nerve runs along the angle of the m', 'The marginal mandibular nerve (CN VII) supplies the depressor anguli oris (injury causes an asymmetric smile).'),
('2b0fdd10-73d7-5856-b026-bf6910ab0cab'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The recurrent laryngeal nerve (CN X) is at risk during:', '["The thyroid surgery","The carotid endarterectomy","The parotid surgery","The submandibular surgery","The lymph node biopsy"]'::jsonb, 'The thyroid surgery', 'The RLN (a branch of CN X) is located in the tracheoesophageal groove (the left RLN loops around the aortic arch; the right RLN loops around the right subclavian artery).'),
('bc1095db-3a5c-52e6-87c9-c9ec1ff338a5'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The external laryngeal nerve (CN X) is at risk during:', '["The submandibular surgery and its associated anatomical structures","The ligation of the superior thyroid artery (in thyroid surgery — injury causes the cricothyroid","The lymph node biopsy and its associated anatomical structures","The carotid endarterectomy and its associated anatomical structures","The parotid surgery and its associated anatomical structures"]'::jsonb, 'The ligation of the superior thyroid artery (in thyroid surgery — injury causes the cricothyroid', 'The external laryngeal nerve (a branch of the superior laryngeal nerve) is located superior to the thyroid gland and innervates the cricothyroid muscle.'),
('af702cea-879e-5e5a-88ab-862a8987bdd7'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The thoracic duct is at risk during:', '["The left-sided neck dissection (especially in the left supraclavicular region — injury causes chy","The parotid surgery and its associated anatomical structures","The submandibular surgery and its associated anatomical structures","The thyroid surgery and its associated anatomical structures","The right-sided neck dissection and its associated anatomical structures"]'::jsonb, 'The left-sided neck dissection (especially in the left supraclavicular region — injury causes chy', 'The thoracic duct (ascending from the thorax) arches into the neck at the level of the C7 vertebra and drains at the left venous angle.'),
('f97796e3-94bf-569e-a205-fe78eff00906'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The spinal cord tracts (ascending and descending) are:', '["The only descending tracts","The only sensory tracts","The only motor tracts","The posterior columns","The only ascending tracts"]'::jsonb, 'The posterior columns', 'The spinal cord (the long tracts) has an orderly somatotopic and laminated arrangement (the corticospinal tract is in the posterior part of the internal capsule).'),
('45440607-a706-590a-9585-9d6c0726c9b0'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The corticospinal tract (the pyramidal tract):', '["The spinocerebellar tract and its associated anatomical structures","The dorsal columns and its associated anatomical structures","The rubrospinal tract and its associated anatomical structures","The descending motor tract from the cerebral cortex to the spinal motor neurons (the crossed trac","The spinothalamic tract and its associated anatomical structures"]'::jsonb, 'The descending motor tract from the cerebral cortex to the spinal motor neurons (the crossed trac', 'The corticospinal tract (the longest and the largest descending tract) controls voluntary fine motor movements (the upper motor neuron).'),
('120ebd6d-0262-5222-90d9-239eba201061'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The spinothalamic tract:', '["The corticospinal tract and its associated anatomical structures","The ascending sensory tract that carries pain and temperature (the lateral spinothalamic","The dorsal columns and its associated anatomical structures","The spinocerebellar tract and its associated anatomical structures","The medial lemniscus and its associated anatomical structures"]'::jsonb, 'The ascending sensory tract that carries pain and temperature (the lateral spinothalamic', 'The spinothalamic tract (the paleospinothalamic and the neospinothalamic pathways) crosses at the level of the spinal cord entry (the anterolateral system).'),
('9f66c0ba-7577-5c07-a383-b30a2f03785b'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The dorsal columns (the posterior columns):', '["The ascending sensory tracts that carry fine touch, two-point discrimination, vibration","The spinocerebellar tract and its associated anatomical structures","The anterolateral system and its associated anatomical structures","The spinothalamic tract and its associated anatomical structures","The corticospinal tract and its associated anatomical structures"]'::jsonb, 'The ascending sensory tracts that carry fine touch, two-point discrimination, vibration', 'The dorsal columns (the medial lemniscal pathway) cross at the medulla (the dorsal column nuclei). The fasciculus gracilis (medial) carries the lower body and the fasciculus cuneatus (lateral) carries the upper body.'),
('0efc4727-cd5c-528b-927a-bcb92a146e66'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The spinocerebellar tracts:', '["The ascending tracts that carry unconscious proprioception from the muscle and joint receptors to","The corticospinal tract and its associated anatomical structures","The dorsal columns and its associated anatomical structures","The spinothalamic tract and its associated anatomical structures","The tectospinal tract and its associated anatomical structures"]'::jsonb, 'The ascending tracts that carry unconscious proprioception from the muscle and joint receptors to', 'The spinocerebellar tracts (the dorsal spinocerebellar tract is uncrossed; the ventral spinocerebellar tract is crossed) are essential for the coordination of movement.'),
('d92065a8-9eee-58d3-a966-eebc857de7f9'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The trigeminal sensory pathways:', '["The dorsal columns and its associated anatomical structures","The glossopharyngeal nerve and its associated anatomical structures","The pain and temperature (the spinal trigeminal tract), the light touch (the principal sensory nu","The facial nerve and its associated anatomical structures","The spinothalamic tract and its associated anatomical structures"]'::jsonb, 'The pain and temperature (the spinal trigeminal tract), the light touch (the principal sensory nu', 'The trigeminal sensory nuclei (the three levels of the brainstem) extend from the midbrain (the mesencephalic) to the upper cervical cord (the spinal nucleus).'),
('6375d357-0385-5e5f-a9d8-63aa81b6eec9'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The lateral lemniscus:', '["The medial lemniscus and its associated anatomical structures","The corticospinal tract and its associated anatomical structures","The trigeminal lemniscus and its associated anatomical structures","The auditory pathway from the cochlear nucleus to the inferior colliculus (the brainstem auditory","The spinal lemniscus and its associated anatomical structures"]'::jsonb, 'The auditory pathway from the cochlear nucleus to the inferior colliculus (the brainstem auditory', 'The lateral lemniscus (the auditory tract) is located at the lateral part of the brainstem (the auditory fibers cross at the trapezoid body).'),
('8f3a5b49-c042-548a-aeb7-a915558efe06'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The medial lemniscus:', '["The corticospinal tract and its associated anatomical structures","The continuation of the dorsal columns (the fine touch and proprioception pathway","The trigeminal lemniscus and its associated anatomical structures","The spinothalamic tract and its associated anatomical structures","The lateral lemniscus and its associated anatomical structures"]'::jsonb, 'The continuation of the dorsal columns (the fine touch and proprioception pathway', 'The medial lemniscus (the medial lemniscal pathway) is the sensory pathway for the discriminative touch, the vibration, and the proprioception.'),
('655abbbe-e262-5bac-9232-22de69b49b4f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The cranial nerve nuclei are located in:', '["The spinal cord and its associated anatomical structures","The brainstem (the midbrain, the pons, and the medulla) — the motor nuclei are medial","The thalamus and its associated anatomical structures","The cerebral cortex and its associated anatomical structures","The cerebellum and its associated anatomical structures"]'::jsonb, 'The brainstem (the midbrain, the pons, and the medulla) — the motor nuclei are medial', 'The cranial nerve nuclei (the GSE, GVE, SVE, GVA, SVA, and SSE columns) are organized in a longitudinal columnar pattern in the brainstem.'),
('98db6c10-429b-51d2-acbe-012f3c889916'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The structures in the cavernous sinus:', '["The ICA (the sympathetic plexus), the CN III, CN IV, CN V1, CN V2, and CN VI","The carotid sinus and its associated anatomical structures","The jugular bulb and its associated anatomical structures","The trigeminal ganglion and its associated anatomical structures","The optic nerve and its associated anatomical structures"]'::jsonb, 'The ICA (the sympathetic plexus), the CN III, CN IV, CN V1, CN V2, and CN VI', 'The cavernous sinus (the lateral wall contains CN III, CN IV, CN V1, and CN V2; the medial wall contains the ICA and CN VI).'),
('1970ad04-ab4c-59cb-a272-1d071812c822'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The petrous apex:', '["The middle ear and its associated anatomical structures","The mastoid antrum and its associated anatomical structures","The inner ear and its associated anatomical structures","The part of the petrous temporal bone that points medially and forward (contains the internal aco","The styloid process and its associated anatomical structures"]'::jsonb, 'The part of the petrous temporal bone that points medially and forward (contains the internal aco', 'The petrous apex (the tip of the petrous temporal bone) is adjacent to the clivus and the sphenoid bone (petrous apicitis/Gradenigo syndrome).'),
('994b7257-1aae-517a-b8b6-8573006a4d78'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'Gradenigo syndrome (apical petrositis):', '["The otosclerosis and its associated anatomical structures","A classic triad: the CN VI palsy (the abducens nerve), the retro-orbital pain (the trigeminal nerve","The labyrinthitis and its associated anatomical structures","BPPV and its associated anatomical structures","Meniere disease and its associated anatomical structures"]'::jsonb, 'A classic triad: the CN VI palsy (the abducens nerve), the retro-orbital pain (the trigeminal nerve', 'Gradenigo syndrome (the inflammation of the petrous apex) is a complication of the acute otitis media (requires antibiotics and/or mastoidectomy).'),
('27a89de4-3c18-5ecf-8c99-7aed8db26459'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The cochlear nerve:', '["The facial nerve and its associated anatomical structures","The glossopharyngeal nerve and its associated anatomical structures","The vestibular nerve and its associated anatomical structures","The part of CN VIII (the auditory nerve) that carries the hearing information from the organ of C","The trigeminal nerve and its associated anatomical structures"]'::jsonb, 'The part of CN VIII (the auditory nerve) that carries the hearing information from the organ of C', 'The cochlear nerve (the spiral nerve) has about 30,000 afferent fibers (the inner hair cells contact the type I spiral ganglion cells; the outer hair cells contact the type II cells).'),
('969ae6da-9d8f-560b-9ecd-8f3899b75fdf'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The vestibular nerve:', '["The oculomotor nerve and its associated anatomical structures","The cochlear nerve and its associated anatomical structures","The trigeminal nerve and its associated anatomical structures","The part of CN VIII (the balance nerve) that carries the balance information from the semicircula","The facial nerve and its associated anatomical structures"]'::jsonb, 'The part of CN VIII (the balance nerve) that carries the balance information from the semicircula', 'The vestibular nerve (the superior and the inferior vestibular nerves) supplies the hair cells of the crista ampullaris and the maculae.'),
('a389b96c-fc69-5244-b4a7-2e6796a5284d'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The nervus intermedius (the nerve of Wrisberg):', '["The chorda tympani and its associated anatomical structures","The greater petrosal nerve and its associated anatomical structures","The sensory and the parasympathetic root of the facial nerve (CN VII) — carries taste from the an","The motor root of CN VII and its associated anatomical structures","The facial nerve proper and its associated anatomical structures"]'::jsonb, 'The sensory and the parasympathetic root of the facial nerve (CN VII) — carries taste from the an', 'The nervus intermedius (the intermediate nerve) runs between the motor root of CN VII and the vestibulocochlear nerve (CN VIII) in the cerebellopontine angle.'),
('c5bd928b-8bf0-502b-b42c-c8b3de96e2e3'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The Wrisberg reflex (the geniculate neuralgia):', '["The glossopharyngeal neuralgia and its associated anatomical structures","The occipital neuralgia and its associated anatomical structures","A rare condition of the nervus intermedius (causes deep ear pain, the paroxysmal pain in the ear","The postherpetic neuralgia and its associated anatomical structures","The trigeminal neuralgia and its associated anatomical structures"]'::jsonb, 'A rare condition of the nervus intermedius (causes deep ear pain, the paroxysmal pain in the ear', 'The nervus intermedius neuralgia (the geniculate neuralgia) is a rare cause of otalgia and is treated with the microvascular decompression or the nerve sectioning.'),
('4d00822b-c6c3-594e-b533-f920c00c674d'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The cranial dura mater has two layers:', '["The falx and the tentorium and its associated anatomical structures","The cavernous and the sagittal sinuses and its associated anatomical structures","The subdural and the epidural spaces and its associated anatomical structures","The periosteal layer (the outer, adherent to the bone) and the meningeal layer (the inner","The arachnoid and the pia and its associated anatomical structures"]'::jsonb, 'The periosteal layer (the outer, adherent to the bone) and the meningeal layer (the inner', 'The cranial dura mater (the pachymeninges) is the tough outermost layer of the meninges (the dural venous sinuses lie between the two layers).'),
('875802f6-840f-5a13-bd70-73cc178d2949'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The dural venous sinuses are:', '["The veins of the brain and its associated anatomical structures","The cerebral veins and its associated anatomical structures","The endothelial-lined channels between the two layers of the cranial dura (the superior sagittal","The arteries of the brain and its associated anatomical structures","The emissary veins and its associated anatomical structures"]'::jsonb, 'The endothelial-lined channels between the two layers of the cranial dura (the superior sagittal', 'The dural venous sinuses (collect the blood from the brain and the CSF from the arachnoid granulations) drain into the internal jugular vein.'),
('c33771cf-f295-5232-af0b-998edea391bb'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The meningeal arteries:', '["The arteries of the face and its associated anatomical structures","The arteries of the skull and its associated anatomical structures","The arteries of the scalp and its associated anatomical structures","The arteries of the brain and its associated anatomical structures","The arteries that supply the dura mater (the middle meningeal artery is the largest — the epidura"]'::jsonb, 'The arteries that supply the dura mater (the middle meningeal artery is the largest — the epidura', 'The middle meningeal artery (from the maxillary artery) enters the skull through the foramen spinosum and runs in the epidural space (the pterion is the thinnest part of the skull).'),
('fbfe68f3-7eca-5c39-bde9-9aad10c9a0c6'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The dural venous sinus thrombosis:', '["The superior sagittal sinus thrombosis and its associated anatomical structures","The cavernous sinus thrombosis and its associated anatomical structures","The transverse sinus thrombosis and its associated anatomical structures","The arterial thrombosis and its associated anatomical structures","The thrombosis of the dural venous sinuses (causes the headache, the papilledema, the seizures"]'::jsonb, 'The thrombosis of the dural venous sinuses (causes the headache, the papilledema, the seizures', 'The dural venous sinus thrombosis (the hypercoagulable state, the infection, or the dehydration) is treated with the anticoagulation.'),
('00dbcf57-7647-5514-8122-022d8c7d34d0'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The Arnold-Chiari malformation (Chiari malformation):', '["The aqueductal stenosis and its associated anatomical structures","The herniation of the cerebellar tonsils through the foramen magnum into the cervical spinal cana","The Dandy-Walker malformation and its associated anatomical structures","The neural tube defect and its associated anatomical structures","The encephalocele and its associated anatomical structures"]'::jsonb, 'The herniation of the cerebellar tonsils through the foramen magnum into the cervical spinal cana', 'Chiari malformation (the most common congenital anomaly of the craniovertebral junction) causes the headache, the neck pain, the ataxia, and the syringomyelia.'),
('881d352a-6d1b-55a4-884c-82977c78d73f'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The Dandy-Walker malformation:', '["The aqueductal stenosis and its associated anatomical structures","The corpus callosum agenesis and its associated anatomical structures","Chiari malformation and its associated anatomical structures","The cystic dilation of the 4th ventricle, the hypoplasia of the cerebellar vermis","The holoprosencephaly and its associated anatomical structures"]'::jsonb, 'The cystic dilation of the 4th ventricle, the hypoplasia of the cerebellar vermis', 'The Dandy-Walker malformation (the Dandy-Walker complex) presents in infancy with the hydrocephalus, the developmental delay, and the ataxia.'),
('9482e848-91ed-5865-ac52-c5627c8eba9a'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The syringomyelia:', '["The intramedullary tumor and its associated anatomical structures","The multiple sclerosis and its associated anatomical structures","A fluid-filled cavity (the syrinx) within the spinal cord (often associated with Chiari malformat","The spinal cord infarction and its associated anatomical structures","The hydromyelia and its associated anatomical structures"]'::jsonb, 'A fluid-filled cavity (the syrinx) within the spinal cord (often associated with Chiari malformat', 'Syringomyelia (the expansion of the central canal by the CSF) causes the dissociated sensory loss (the loss of pain and temperature with the preservation of the fine touch — the anterior commissure of the spinothalamic fibers).'),
('477e98c1-8bce-5762-b4d3-03120182f0fa'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The basilar invagination (the basilar impression):', '["The platybasia and its associated anatomical structures","The atlantoaxial subluxation and its associated anatomical structures","The os odontoideum and its associated anatomical structures","The Klippel-Feil syndrome and its associated anatomical structures","The upward displacement of the dens into the foramen magnum (causes the brainstem compression and"]'::jsonb, 'The upward displacement of the dens into the foramen magnum (causes the brainstem compression and', 'Basilar invagination (the dens projects above the Chamberlain line) is a common cause of the craniomedullary compression.'),
('9728ec20-f25c-5176-9658-e7307d31d15a'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The Chamberlain line:', '["A lateral radiograph line from the hard palate to the opisthion (the tip of the dens should be be","The Wackenheim clivus line and its associated anatomical structures","The McRae line and its associated anatomical structures","The McGregor line and its associated anatomical structures","The Welcher basal angle and its associated anatomical structures"]'::jsonb, 'A lateral radiograph line from the hard palate to the opisthion (the tip of the dens should be be', 'The Chamberlain line (the palato-occipital line) is used to assess the basilar invagination (the dens is normally 1-2 mm below the line).'),
('efa67989-299d-546f-9ebf-22e61c042bc2'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The McRae line:', '["The Wackenheim clivus line and its associated anatomical structures","The Chamberlain line and its associated anatomical structures","The Welcher basal angle and its associated anatomical structures","A line from the basion to the opisthion (the foramen magnum line — the dens should not project ab","The McGregor line and its associated anatomical structures"]'::jsonb, 'A line from the basion to the opisthion (the foramen magnum line — the dens should not project ab', 'The McRae line (the foramen magnum line) is the most reliable line for assessing the basilar invagination (the dens tip should be at or below the line).'),
('077ef7d2-4f62-5756-b349-a9df86af0ae2'::uuid, 'Anatomy (Paper 2)', 'Cranium', 'The foramen magnum syndrome:', '["The conus medullaris syndrome and its associated anatomical structures","The central cord syndrome and its associated anatomical structures","The cauda equina syndrome and its associated anatomical structures","The Brown-Sequard syndrome and its associated anatomical structures","The compression of the medulla oblongata and the upper cervical cord at the foramen magnum (cause"]'::jsonb, 'The compression of the medulla oblongata and the upper cervical cord at the foramen magnum (cause', 'The foramen magnum (the largest opening of the skull) is the site of the tonsillar herniation (the coning) and the craniovertebral junction tumors.'),
('d5d5696a-02be-5c8c-aec6-d452812a4557'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The brain weighs approximately:', '["1000 g","500 g","1400 g","2000 g","2500 g"]'::jsonb, '1400 g', 'The brain (2% of body weight) receives 15% of cardiac output and uses 20% of O2.'),
('f9b6b783-9ad4-568c-ac5c-ad18cd576f16'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The cerebrum is divided into:', '["The brainstem and cerebellum","Two hemispheres by the longitudinal fissure","Four lobes by the central sulcus","Three parts by the Sylvian fissure","Two hemispheres by the transverse fissure"]'::jsonb, 'Two hemispheres by the longitudinal fissure', 'Each hemisphere controls the contralateral side of the body.'),
('4ce7cba8-fbb3-5abb-8032-1aef18227189'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The layers of the scalp (SCALP):', '["Skin, Connective tissue, Aponeurosis, Loose areolar tissue, Pericranium","Skin, Cranium, Aorta, Lymph, Periosteum","Skin, Cranium, Aponeurosis, Loose tissue, Periosteum","Skin, Connective tissue, Arteries, Lymph, Pericranium","Skin, Cartilage, Aponeurosis, Ligament, Periosteum"]'::jsonb, 'Skin, Connective tissue, Aponeurosis, Loose areolar tissue, Pericranium', 'The dangerous layer (loose areolar tissue) allows spread of infection into the cranial cavity.'),
('928c55fa-1dc4-5486-aea6-9d3edc9d6597'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The meninges (outer to inner):', '["Pia, Arachnoid, Dura and its associated structures","Dura mater, Arachnoid mater, Pia mater","Arachnoid, Dura, Pia and its associated structures","Pia, Dura, Arachnoid and its associated structures","Dura, Pia, Arachnoid and its associated structures"]'::jsonb, 'Dura mater, Arachnoid mater, Pia mater', 'Dura (thick, tough), Arachnoid (delicate, CSF in subarachnoid space), Pia (adherent to brain surface).'),
('9e0b768e-9407-5ccf-b5bd-49c1d03d09e0'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The falx cerebri is:', '["A fold of dura between the two cerebral hemispheres","A fold of dura between cerebrum and cerebellum","A fold of dura in the spinal canal","A fold of dura at the brainstem","A fold of dura covering the pituitary"]'::jsonb, 'A fold of dura between the two cerebral hemispheres', 'Falx cerebri (sickle-shaped) attaches to the crista galli and the internal occipital protuberance.'),
('ad2d424b-ffd8-54ee-8ad0-07ae914f139a'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The tentorium cerebelli separates:', '["The cerebellum from the medulla","The two cerebral hemispheres","The brainstem from the cerebrum","The occipital lobes from the cerebellum","The frontal from the temporal lobe"]'::jsonb, 'The occipital lobes from the cerebellum', 'Tentorium cerebelli (tent-shaped) is attached to the petrous ridges and the clinoid processes.'),
('e318bf89-a263-55fc-9bea-d9b59a3bf4fb'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The dural venous sinuses are located between:', '["Between the skull and the dura","The dura and the arachnoid","Within the brain tissue","The arachnoid and the pia","The two layers of the dura mater"]'::jsonb, 'The two layers of the dura mater', 'Dural sinuses (e.g., superior sagittal, transverse, sigmoid, cavernous) drain venous blood from the brain.'),
('222862df-cf21-5432-93c6-908d811dce94'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The superior sagittal sinus runs:', '["In the cavernous sinus","Along the tentorium","Along the attached edge of the falx cerebri","Along the free edge of the falx cerebri","Along the floor of the skull"]'::jsonb, 'Along the attached edge of the falx cerebri', 'Arachnoid granulations (Pacchionian) project into the superior sagittal sinus for CSF absorption.'),
('18a6c264-be88-5633-bee8-ac93b6b29ba4'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The straight sinus is located at:', '["The sella turcica and its associated anatomical structures","The base of the skull and its associated anatomical structures","The junction of the falx cerebri and the tentorium cerebelli","The cavernous sinus and its associated anatomical structures","The foramen magnum and its associated anatomical structures"]'::jsonb, 'The junction of the falx cerebri and the tentorium cerebelli', 'The straight sinus (formed by the confluence of the inferior sagittal sinus and the great cerebral vein) drains into the confluence of sinuses.'),
('69249041-e281-523b-aed8-cd6515111320'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The confluence of sinuses (torcular Herophili) is located at:', '["The petrous ridge and its associated structures","The crista galli and its associated structures","The internal occipital protuberance","The sella turcica and its associated structures","The foramen magnum and its associated structures"]'::jsonb, 'The internal occipital protuberance', 'The confluence receives blood from the superior sagittal, straight, and occipital sinuses, draining into the transverse sinuses.'),
('67565a64-3264-59e6-a07c-9b4bed749759'::uuid, 'Anatomy (Paper 2)', 'Brain', 'For a patient presenting with symptoms, The cavernous sinus contains:', '["ICA, CN III, CN IV, CN V1, CN V2, CN VI, and sympathetic fibers","Only CN III and CN VI and its associated anatomical structures","Only CN V1 and V2 and its associated anatomical structures","The optic nerve and its associated anatomical structures","Only the ICA and its associated anatomical structures"]'::jsonb, 'ICA, CN III, CN IV, CN V1, CN V2, CN VI, and sympathetic fibers', 'Cavernous sinus (on either side of the sella turcica) is a major venous channel. It drains into the superior and inferior petrosal sinuses.'),
('7af4da4b-dcf6-5103-9bff-ec1c8ba00b45'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The internal carotid artery (ICA) supplies:', '["The spinal cord","The posterior 1/3 of the cerebrum","The anterior 2/3 of the cerebrum","The brainstem","The cerebellum"]'::jsonb, 'The anterior 2/3 of the cerebrum', 'The ICA (from the carotid canal) gives off the ophthalmic, posterior communicating, anterior choroidal, anterior cerebral, and middle cerebral arteries.'),
('f5131774-eb30-51d9-b0d6-21cf6a3c5254'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The vertebral arteries supply:', '["Only the spinal cord and its associated anatomical structures","The posterior 1/3 of the cerebrum, the brainstem, and the cerebellum","Only the cerebellum and its associated anatomical structures","The anterior 2/3 of the cerebrum and its associated anatomical structures","Only the medulla and its associated anatomical structures"]'::jsonb, 'The posterior 1/3 of the cerebrum, the brainstem, and the cerebellum', 'Vertebral arteries (from subclavian) pass through transverse foramina of C1-C6 and join to form the basilar artery.'),
('a66f9976-b162-54cc-af73-308fde7b528d'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The circle of Willis is formed by:', '["The vertebral and basilar arteries","Only the PCom and PCA","ACA, ACom, ICA, PCom, PCA, and basilar artery","Only the ACA and MCA","Only the ICA and basilar"]'::jsonb, 'ACA, ACom, ICA, PCom, PCA, and basilar artery', 'The circle of Willis (at the base of the brain, surrounding the optic chiasm and pituitary stalk) provides collateral circulation.'),
('c7bb3d46-02ef-53c8-aeac-419e7589c6f5'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The anterior cerebral artery (ACA) supplies:', '["The temporal lobe","The medial aspect of the frontal and parietal lobes","The occipital lobe","The cerebellum","The lateral aspect of the hemisphere"]'::jsonb, 'The medial aspect of the frontal and parietal lobes', 'ACA occlusion causes contralateral weakness and sensory loss in the lower limb (leg > arm).'),
('ca492f08-f830-5266-8753-b5c369d92e1a'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The middle cerebral artery (MCA) supplies:', '["The lateral aspect of the frontal, parietal, and temporal lobes (motor and sensory cortex for the","The medial aspect of the hemisphere and its associated anatomical structures","The cerebellum and its associated anatomical structures","The brainstem and its associated anatomical structures","The occipital lobe and its associated anatomical structures"]'::jsonb, 'The lateral aspect of the frontal, parietal, and temporal lobes (motor and sensory cortex for the', 'MCA (the largest branch of ICA) is the most common site of stroke. Occlusion causes contralateral weakness (face and arm > leg).'),
('46ac94c8-7637-5676-b001-69d077327da0'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The posterior cerebral artery (PCA) supplies:', '["The occipital lobe (primary visual cortex) and the inferomedial temporal lobe","The sensory cortex and its associated anatomical structures","The motor cortex and its associated anatomical structures","The frontal lobe and its associated anatomical structures","The parietal lobe and its associated anatomical structures"]'::jsonb, 'The occipital lobe (primary visual cortex) and the inferomedial temporal lobe', 'PCA occlusion causes contralateral homonymous hemianopia (visual field loss with macular sparing).'),
('8e254933-9094-5e15-ae0b-2f745943ea08'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The lenticulostriate arteries (from MCA):', '["Supply the brainstem and its associated anatomical structures","Supply the cerebral cortex and its associated anatomical structures","Deep penetrating arteries supplying the basal ganglia and the internal capsule (common site of hy","Supply the choroid plexus and its associated anatomical structures","Supply the cerebellum and its associated anatomical structures"]'::jsonb, 'Deep penetrating arteries supplying the basal ganglia and the internal capsule (common site of hy', 'Lenticulostriate arteries (small, fragile) are prone to rupture in hypertension (putaminal hemorrhage).'),
('3591cb6c-be63-5217-b668-5963ecef9251'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The anterior choroidal artery (from ICA):', '["Supplies the choroid plexus, optic tract, internal capsule (posterior limb), and the globus pallidus","Supplies the occipital lobe and its associated anatomical structures","Supplies the brainstem and its associated anatomical structures","Supplies the frontal lobe and its associated anatomical structures","Supplies the cerebellum and its associated anatomical structures"]'::jsonb, 'Supplies the choroid plexus, optic tract, internal capsule (posterior limb), and the globus pallidus', 'Anterior choroidal artery occlusion can cause contralateral hemiparesis, hemianopia, and sensory loss.'),
('6252c50f-f0f7-500d-82fa-461a4692694e'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Regarding clinical scenarios, The basilar artery is formed by:', '["The union of the two vertebral arteries at the pontomedullary junction","The posterior cerebral arteries and its associated anatomical structures","The union of the two ICAs and its associated anatomical structures","The union of the vertebral and ICA and its associated anatomical structures","The anterior cerebral arteries and its associated anatomical structures"]'::jsonb, 'The union of the two vertebral arteries at the pontomedullary junction', 'Basilar artery (the main artery of the pons) runs in the basilar groove of the pons and bifurcates into the PCAs.'),
('8d62c904-ce0b-5dcc-b7d1-394763036ae8'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The superior cerebellar artery (SCA) supplies:', '["The pons","The occipital lobe","The inferior surface of the cerebellum","The superior surface of the cerebellum and the midbrain","The medulla"]'::jsonb, 'The superior surface of the cerebellum and the midbrain', 'SCA (from the basilar artery) supplies the superior half of the cerebellum and the superior cerebellar peduncle.'),
('b1f9158e-adfe-5a74-8e97-d800b1c688dd'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The anterior inferior cerebellar artery (AICA) supplies:', '["The superior cerebellum and its associated anatomical structures","The anterior inferior surface of the cerebellum, the lateral pons, and the inner ear (labyrinthin","The midbrain and its associated anatomical structures","The posterior inferior cerebellum and its associated anatomical structures","The medulla and its associated anatomical structures"]'::jsonb, 'The anterior inferior surface of the cerebellum, the lateral pons, and the inner ear (labyrinthin', 'AICA (from the basilar artery) gives off the labyrinthine artery. Occlusion causes lateral pontine syndrome.'),
('13a61e5c-0a0c-5d22-81a8-59ae223cf388'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The posterior inferior cerebellar artery (PICA) supplies:', '["The superior cerebellum and its associated anatomical structures","The occipital lobe and its associated anatomical structures","The posterior inferior surface of the cerebellum, the lateral medulla (and the choroid plexus of","The pons and its associated anatomical structures","The midbrain and its associated anatomical structures"]'::jsonb, 'The posterior inferior surface of the cerebellum, the lateral medulla (and the choroid plexus of', 'PICA (from the vertebral artery) occlusion causes lateral medullary syndrome (Wallenberg syndrome).'),
('17c0d912-274f-5df4-ae03-de0ba84481a6'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The cerebral cortex (gray matter) consists of:', '["Cell bodies of neurons (6 layers of the neocortex: molecular, external granular, external pyramidal","Glial cells and its associated anatomical structures","Blood vessels and its associated anatomical structures","Myelinated axons and its associated anatomical structures","White matter and its associated anatomical structures"]'::jsonb, 'Cell bodies of neurons (6 layers of the neocortex: molecular, external granular, external pyramidal', 'The neocortex (isocortex) has 6 layers. The allocortex (hippocampus, olfactory) has 3 layers.'),
('54537a57-6c92-5759-8983-f197720fb19c'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The primary motor cortex (Brodmann area 4) is located in:', '["The insula","The temporal lobe","The postcentral gyrus","The occipital lobe","The precentral gyrus"]'::jsonb, 'The precentral gyrus', 'The motor homunculus (Penfield) is organized somatotopically on the precentral gyrus.'),
('aef6484f-eaef-5147-b34b-347838629fac'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The primary somatosensory cortex (Brodmann areas 3, 1, 2) is located in:', '["The insula","The temporal lobe","The postcentral gyrus","The precentral gyrus","The occipital lobe"]'::jsonb, 'The postcentral gyrus', 'Sensory homunculus (somatotopic organization) represents the body parts on the postcentral gyrus.'),
('7d8ca214-5b78-5847-bc72-8a4e2989a879'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The primary visual cortex (Brodmann area 17) is located in:', '["The superior temporal gyrus","The insula","The postcentral gyrus","The calcarine sulcus","The precentral gyrus"]'::jsonb, 'The calcarine sulcus', 'Area 17 (striate cortex) receives visual input from the lateral geniculate body of the thalamus.'),
('817f261f-9c45-5323-bead-3016fd02d855'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The primary auditory cortex (Brodmann areas 41, 42) is located in:', '["The transverse temporal gyrus of Heschl","The insula and its associated structures","The postcentral gyrus and its associated structures","The precentral gyrus and its associated structures","The occipital lobe and its associated structures"]'::jsonb, 'The transverse temporal gyrus of Heschl', 'Auditory cortex receives input from the medial geniculate body (MGB) of the thalamus.'),
('da2100b2-3091-5e72-89ae-854f94d0a824'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Broca area (motor speech, Brodmann areas 44, 45) is located in:', '["The angular gyrus","The superior temporal gyrus","The inferior frontal gyrus","The supramarginal gyrus","The precentral gyrus"]'::jsonb, 'The inferior frontal gyrus', 'Broca aphasia: non-fluent aphasia with preserved comprehension (damage to Broca area).'),
('853949bb-7650-55d5-a338-b048dee86b98'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Wernicke area (sensory speech, Brodmann area 22) is located in:', '["The superior temporal gyrus","The angular gyrus","The insula","The inferior frontal gyrus","The occipital lobe"]'::jsonb, 'The superior temporal gyrus', 'Wernicke aphasia: fluent aphasia with impaired comprehension (damage to Wernicke area).'),
('b213b3f3-8187-5b2d-b8cc-43180b4a7877'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The arcuate fasciculus connects:', '["The parietal and temporal lobes","The frontal and occipital lobes","The two hemispheres","The thalamus and the cortex","Broca area and Wernicke area"]'::jsonb, 'Broca area and Wernicke area', 'Conduction aphasia (damage to arcuate fasciculus): inability to repeat, with fluent speech and good comprehension.'),
('3fa7d242-bf0f-5e78-8ae4-a2dd053573eb'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The corpus callosum is:', '["The largest commissural tract","A part of the limbic system","A tract connecting the frontal and occipital lobes","A cranial nerve","A basal ganglion"]'::jsonb, 'The largest commissural tract', 'Corpus callosum (200 million axons) is divided into the genu, body, splenium, and rostrum.'),
('78c717ac-f191-5851-a662-9e8e298b8cd4'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The internal capsule is:', '["A basal ganglion and its associated anatomical structures","A cranial nerve and its associated anatomical structures","A meningeal layer and its associated anatomical structures","A ventricle and its associated anatomical structures","A white matter tract between the caudate/putamen and the thalamus (carrying motor and sensory fib"]'::jsonb, 'A white matter tract between the caudate/putamen and the thalamus (carrying motor and sensory fib', 'Internal capsule (anterior limb, genu, posterior limb) contains the corticospinal tract (posterior limb).'),
('8f953db8-4122-5559-b7bc-34dff0521446'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The corticospinal (pyramidal) tract runs through:', '["The anterior limb of the internal capsule","The cerebral peduncle","The posterior limb of the internal capsule","The corona radiata","The genu of the internal capsule"]'::jsonb, 'The posterior limb of the internal capsule', 'Corticospinal tract (80% cross in the medullary pyramids) innervates contralateral motor neurons.'),
('5695163c-4b46-57e9-8004-2bbf71e1ec54'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The basal ganglia include:', '["Only caudate and putamen","Caudate, putamen, globus pallidus, subthalamic nucleus, and substantia nigra","Only substantia nigra","Only globus pallidus and subthalamic nucleus","The thalamus and hypothalamus"]'::jsonb, 'Caudate, putamen, globus pallidus, subthalamic nucleus, and substantia nigra', 'Basal ganglia (extrapyramidal system) are involved in motor control (smooth, purposeful movement).'),
('a7056ab2-5036-533d-9ff1-e85f4dda35be'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The striatum (neostriatum) consists of:', '["The caudate and the globus pallidus","The substantia nigra and the subthalamic nucleus","The globus pallidus and the putamen","The caudate nucleus and the putamen","The amygdala and the hippocampus"]'::jsonb, 'The caudate nucleus and the putamen', 'The striatum receives input from the cerebral cortex (the main input nucleus of the basal ganglia).'),
('9db1e3f2-d8ee-534d-b278-a60c2133e354'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The globus pallidus (pallidum) is divided into:', '["Internal and external segments","Medial and lateral segments","Anterior and posterior segments","Dorsal and ventral segments","Superior and inferior segments"]'::jsonb, 'Internal and external segments', 'Globus pallidus internus (GPi) projects to the thalamus (motor loop). Globus pallidus externus (GPe) is part of the indirect pathway.'),
('3bbabfd1-2761-510b-b406-10bb5922efcd'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The substantia nigra is divided into:', '["Pars reticulata and pars medialis and its associated anatomical structures","Pars compacta (GABAergic) and pars reticulata and its associated anatomical structures","Substantia nigra is uniform and its associated anatomical structures","Pars compacta and pars lateralis and its associated anatomical structures","Pars compacta (dopaminergic, degenerates in Parkinson disease) and pars reticulata"]'::jsonb, 'Pars compacta (dopaminergic, degenerates in Parkinson disease) and pars reticulata', 'Parkinson disease: loss of dopaminergic neurons in the substantia nigra pars compacta (causes tremor, rigidity, bradykinesia).'),
('7d0905f2-33b5-5eb2-9086-bf5fa89cf234'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The subthalamic nucleus is:', '["Part of the thalamus","A small nucleus lateral to the thalamus","Part of the putamen","Part of the caudate","Part of the hypothalamus"]'::jsonb, 'A small nucleus lateral to the thalamus', 'Lesion of the subthalamic nucleus (STN) causes contralateral hemiballismus (flinging movements).'),
('d47eefb6-1c31-5a06-a8ed-7c91db149e1c'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The direct pathway of the basal ganglia:', '["Regulates sensory input","Facilitates movement","Regulates autonomic function","Has no effect on movement","Inhibits movement"]'::jsonb, 'Facilitates movement', 'The direct pathway (D1 receptors) disinhibits the thalamus, promoting movement.'),
('ffee2730-3e50-5a9f-a863-4fc8de9e9fc9'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The indirect pathway of the basal ganglia:', '["Regulates autonomic function","Inhibits movement","Facilitates movement","Has no effect on movement","Regulates sensory input"]'::jsonb, 'Inhibits movement', 'The indirect pathway (D2 receptors) increases inhibition of the thalamus, suppressing movement.'),
('5ac6d1f0-7b90-57ed-9e49-4a43c0022b7d'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The thalamus acts as:', '["The center of emotion","A relay station for sensory and motor signals","The center of motor coordination","The center of autonomic regulation","The center of memory"]'::jsonb, 'A relay station for sensory and motor signals', 'The thalamus (paired, egg-shaped) has many nuclei (VPL, VPM, LGN, MGN, etc.) projecting to the cortex.'),
('fa77a093-4a64-5af2-895f-dcbde26af6ab'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The lateral geniculate nucleus (LGN) of the thalamus relays:', '["Motor information","Olfactory information","Somatosensory information","Visual information","Auditory information"]'::jsonb, 'Visual information', 'LGN (lateral geniculate body) receives input from the optic tract and projects to the calcarine cortex via the optic radiation.'),
('a4a36ff7-6948-5f01-8ac7-ef7ec9cc76a2'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The medial geniculate nucleus (MGN) of the thalamus relays:', '["Somatosensory information","Auditory information","Visual information","Olfactory information","Motor information"]'::jsonb, 'Auditory information', 'MGN (medial geniculate body) is the thalamic relay for audition.'),
('bfe562e1-21e7-57ef-a917-9220b88ef04c'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The ventral posterolateral nucleus (VPL) relays:', '["Auditory information and its associated anatomical structures","Somatosensory information from the face and its associated anatomical structures","Visual information and its associated anatomical structures","Somatosensory information from the body (spinothalamic and dorsal column-medial lemniscus pathway","Motor information and its associated anatomical structures"]'::jsonb, 'Somatosensory information from the body (spinothalamic and dorsal column-medial lemniscus pathway', 'VPL (ventral posterolateral) receives input from the spinothalamic tract and the medial lemniscus.'),
('c04e097e-adda-5f6c-b3f0-8bbc70699a69'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The ventral posteromedial nucleus (VPM) relays:', '["Visual information","Somatosensory information from the body","Motor information","Auditory information","Somatosensory information from the face"]'::jsonb, 'Somatosensory information from the face', 'VPM receives input from the trigeminal lemniscus (pain, temperature, and touch from the face).'),
('d7ba4d5f-2b16-591a-8ff7-318e8bb95f56'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The hypothalamus controls:', '["Autonomic function, temperature, hunger, thirst, sleep-wake cycle, and the endocrine system (pitu","Sensory processing and its associated anatomical structures","Motor coordination and its associated anatomical structures","Language and its associated anatomical structures","Vision and its associated anatomical structures"]'::jsonb, 'Autonomic function, temperature, hunger, thirst, sleep-wake cycle, and the endocrine system (pitu', 'Hypothalamus (the ''master regulator'') is connected to the pituitary (hypothalamic-pituitary axis).'),
('5a5e2aac-f7a0-5f13-9349-6d3961adbf3a'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The hippocampus is essential for:', '["Motor control and its associated anatomical structures","Vision and its associated anatomical structures","Language and its associated anatomical structures","Emotion and its associated anatomical structures","Memory formation (declarative memory) and spatial navigation"]'::jsonb, 'Memory formation (declarative memory) and spatial navigation', 'Hippocampus (in the medial temporal lobe) is crucial for long-term memory. Bilateral damage causes anterograde amnesia.'),
('0740dfe4-1170-5857-ad38-132f3385ab12'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The amygdala is responsible for:', '["Memory formation","Language","Motor control","Emotion","Vision"]'::jsonb, 'Emotion', 'Amygdala (almond-shaped, in the anterior temporal lobe) is part of the limbic system.'),
('8aee6211-df2f-549d-a396-a88acdb9d992'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The limbic system includes:', '["Only the cingulate gyrus and its associated anatomical structures","Only the hippocampus and its associated anatomical structures","Only the amygdala and its associated anatomical structures","Hippocampus, amygdala, cingulate gyrus, fornix, mammillary bodies, and the septal nuclei","The basal ganglia and its associated anatomical structures"]'::jsonb, 'Hippocampus, amygdala, cingulate gyrus, fornix, mammillary bodies, and the septal nuclei', 'The limbic system (the ''emotional brain'') also has connections to the hypothalamus and the prefrontal cortex.'),
('34b1279d-ed02-55d4-ba45-d9e1ce93fd54'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The fornix is:', '["A cranial nerve and its associated anatomical structures","A basal ganglion and its associated anatomical structures","A white matter tract connecting the hippocampus to the mammillary bodies","A ventricle and its associated anatomical structures","A dural sinus and its associated anatomical structures"]'::jsonb, 'A white matter tract connecting the hippocampus to the mammillary bodies', 'Fornix (arch-shaped) carries output from the hippocampus to the mammillary bodies and the septal nuclei.'),
('fce44d9a-2cc1-5eb6-b7c8-b84ada42e0ca'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The mammillary bodies are:', '["Part of the cerebellum","Part of the hypothalamus","Part of the thalamus","Part of the pituitary","Part of the basal ganglia"]'::jsonb, 'Part of the hypothalamus', 'Mammillary bodies (rounded, paired) are involved in the Papez circuit of memory. Damage causes Korsakoff syndrome (alcoholism).'),
('73e5cd41-71a9-5728-b2d5-b2501984bebf'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The cingulate gyrus is:', '["A part of the occipital lobe","A part of the frontal lobe","A part of the parietal lobe","A part of the limbic system","A part of the temporal lobe"]'::jsonb, 'A part of the limbic system', 'The cingulate gyrus (limbic lobe) is involved in emotion, motivation, and attention.'),
('508233b6-290f-5b24-b757-719f59be3a6f'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The ventricular system of the brain consists of:', '["Only the third and fourth ventricles and its associated anatomical structures","Only the lateral ventricles and its associated anatomical structures","Two lateral ventricles, the third ventricle, the cerebral aqueduct, and the fourth ventricle","The lateral, third, and fourth ventricles only and its associated anatomical structures","Only the central canal and its associated anatomical structures"]'::jsonb, 'Two lateral ventricles, the third ventricle, the cerebral aqueduct, and the fourth ventricle', 'The ventricles (CSF-filled spaces) are lined by ependymal cells. CSF is produced by the choroid plexus.'),
('f13ca0c2-9986-5b13-9ca4-4d2e6363a71f'::uuid, 'Anatomy (Paper 2)', 'Brain', 'CSF is produced by:', '["The brain parenchyma","The arachnoid granulations","The choroid plexus","The pia mater","The ependymal cells"]'::jsonb, 'The choroid plexus', 'CSF (150 mL total, 500 mL produced/day) flows from the lateral ventricles -> foramen of Monro -> 3rd ventricle -> aqueduct -> 4th ventricle -> subarachnoid space.'),
('23ee870f-bcc7-5c30-a764-31b86d004257'::uuid, 'Anatomy (Paper 2)', 'Brain', 'CSF drains into the venous system through:', '["The foramen of Magendie and its associated anatomical structures","The choroid plexus and its associated anatomical structures","The foramen of Luschka and its associated anatomical structures","The cerebral aqueduct and its associated anatomical structures","The arachnoid granulations (Pacchionian bodies) projecting into the superior sagittal sinus"]'::jsonb, 'The arachnoid granulations (Pacchionian bodies) projecting into the superior sagittal sinus', 'Arachnoid granulations (villi) reabsorb CSF into the dural venous sinuses (pressure-dependent).'),
('902328a0-1abf-5ed4-99e5-d1bcc62803c8'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The foramen of Monro connects:', '["The fourth ventricle to the subarachnoid space","The lateral ventricle to the third ventricle","The third ventricle to the aqueduct","The third ventricle to the fourth ventricle","The lateral ventricle to the subarachnoid space"]'::jsonb, 'The lateral ventricle to the third ventricle', 'The interventricular foramen (of Monro) transmits the choroid plexus and the thalamostriate vein.'),
('7078cd24-0127-5843-8952-0cdb326eb78f'::uuid, 'Anatomy (Paper 2)', 'Brain', 'In a surgical context, The cerebral aqueduct (of Sylvius):', '["Connects the third ventricle to the fourth ventricle","Connects the lateral ventricle to the third ventricle","Connects the fourth ventricle to the subarachnoid space","Connects the fourth ventricle to the central canal","Is in the medulla"]'::jsonb, 'Connects the third ventricle to the fourth ventricle', 'The aqueduct (the narrowest part of the ventricular system) can be blocked (aqueductal stenosis -> hydrocephalus).'),
('6afc5c6b-b09d-5b7c-a83c-3802c4f14289'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The foramen of Magendie (median aperture) and the foramina of Luschka (lateral apertures):', '["Connect the ventricle to the spinal canal and its associated anatomical structures","Allow CSF to flow from the fourth ventricle into the subarachnoid space (cisterna magna and later","Allow CSF to drain into the venous sinuses and its associated anatomical structures","Connect the third ventricle to the fourth ventricle and its associated anatomical structures","Connect the lateral ventricle to the third ventricle and its associated anatomical structures"]'::jsonb, 'Allow CSF to flow from the fourth ventricle into the subarachnoid space (cisterna magna and later', 'The three openings (1 median + 2 lateral) are the only exits for CSF from the ventricular system.'),
('67eadecf-219d-5f84-a68b-3761cba3cf13'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The subarachnoid space lies between:', '["The pia and the brain","The dura and the skull","The arachnoid mater and the pia mater","The pia and the arachnoid only in the spinal canal","The dura and the arachnoid"]'::jsonb, 'The arachnoid mater and the pia mater', 'Subarachnoid space (widened areas = cisterns, e.g., cisterna magna, prepontine cistern).'),
('d42e1a9b-452e-5968-b3ec-84cfdcd139ac'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The cisterna magna (cerebellomedullary cistern) is located:', '["At the optic chiasm","Around the midbrain","At the sylvian fissure","Between the cerebellum and the medulla","At the base of the brain"]'::jsonb, 'Between the cerebellum and the medulla', 'Cisterna magna (largest cistern) can be accessed for CSF collection (cisternal puncture).'),
('2e808256-c1cc-5b36-b5ca-eff7315ff7af'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The lumbar cistern (subarachnoid space in the spinal canal):', '["From C1 to T12","From L1 to L5","From L2 to S2","From S2 to S5","From T12 to L2"]'::jsonb, 'From L2 to S2', 'Lumbar puncture (at L3-L4 or L4-L5) accesses the lumbar cistern to collect CSF.'),
('ff4de97d-6194-570f-8daa-8538a8465f75'::uuid, 'Anatomy (Paper 2)', 'Brain', 'On diagnostic evaluation, The blood-brain barrier (BBB) is formed by:', '["The choroid plexus and its associated anatomical structures","Tight junctions between the endothelial cells of the cerebral capillaries (with astrocyte foot pr","The ependymal cells and its associated anatomical structures","The pia mater and its associated anatomical structures","The arachnoid mater and its associated anatomical structures"]'::jsonb, 'Tight junctions between the endothelial cells of the cerebral capillaries (with astrocyte foot pr', 'BBB (a structural and functional barrier) protects the brain from toxins and pathogens.'),
('f3f7e007-67cf-5916-becb-67825e3c48a7'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The blood-CSF barrier is formed by:', '["The pia mater","The dura mater","The choroid plexus epithelium","The arachnoid granulations","The cerebral capillary endothelium"]'::jsonb, 'The choroid plexus epithelium', 'The choroid plexus (a ''modified ependyma'') secretes CSF and forms the blood-CSF barrier.'),
('f7820298-142b-5161-9e50-42212d09a0c1'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The circumventricular organs (CVOs) are:', '["Parts of the cerebellum","Lobes of the brain","Areas of the brain without a BBB","Areas with the tightest BBB","Cerebral ventricles"]'::jsonb, 'Areas of the brain without a BBB', 'CVOs (lacking BBB) allow the brain to sample blood (chemoreception, emesis, osmoregulation).'),
('667e57dd-0965-50fa-9fda-f34bdc44806d'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The area postrema (in the medulla) is:', '["The cardiac center and its associated anatomical structures","The swallowing center and its associated anatomical structures","The vasomotor center and its associated anatomical structures","The respiratory center and its associated anatomical structures","The chemoreceptor trigger zone (CTZ) for vomiting (lacks a BBB, responds to emetic stimuli in the"]'::jsonb, 'The chemoreceptor trigger zone (CTZ) for vomiting (lacks a BBB, responds to emetic stimuli in the', 'The area postrema (the ''vomiting center of the medulla'') is located at the floor of the fourth ventricle.'),
('19d9c345-fa21-58cf-8e8b-28d299dbcd1d'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The cerebellum consists of:', '["The vermis only and its associated anatomical structures","The flocculonodular lobe only and its associated anatomical structures","Two hemispheres only and its associated anatomical structures","The vermis (midline) and two cerebellar hemispheres (divided into anterior, posterior","The tonsils only and its associated anatomical structures"]'::jsonb, 'The vermis (midline) and two cerebellar hemispheres (divided into anterior, posterior', 'The cerebellum (''little brain'') is involved in coordination, balance, and motor learning.'),
('c844e149-297c-521e-bcd2-484fe16aa0bf'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The cerebellar hemispheres are connected by:', '["The pons","The anterior commissure","The corpus callosum","The vermis","The posterior commissure"]'::jsonb, 'The vermis', 'The vermis (narrow midline strip) is phylogenetically older than the hemispheres.'),
('3e089568-d53a-5d22-8de9-a556b18fcc63'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The cerebellar cortex has three layers:', '["Purkinje, Granular, and Molecular","Molecular, Granular, and External granular","Molecular (outer), Purkinje cell (middle), and Granular","Granular, Molecular, and Purkinje","External granular, Purkinje, and Internal granular"]'::jsonb, 'Molecular (outer), Purkinje cell (middle), and Granular', 'Purkinje cells (large, flask-shaped) are the only output neurons of the cerebellar cortex (inhibit deep nuclei).'),
('54e9a1c3-008b-5eb1-a7a0-86651a44ae56'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The cerebellar deep nuclei (medial to lateral):', '["Dentate only and its associated anatomical structures","Fastigial only and its associated anatomical structures","Embolliform only and its associated anatomical structures","Fastigial, globose, emboliform, and dentate","Globose only and its associated anatomical structures"]'::jsonb, 'Fastigial, globose, emboliform, and dentate', 'Deep cerebellar nuclei project to the thalamus, the brainstem, and the spinal cord.'),
('a78714db-920d-5fa8-b395-e63f2b06c415'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The flocculonodular lobe (archicerebellum):', '["Involved in limb coordination","Involved in speech","Involved in motor planning","The oldest part of the cerebellum","Involved in fine motor control"]'::jsonb, 'The oldest part of the cerebellum', 'Flocculonodular lobe (vestibulocerebellum) receives input from the vestibular nuclei. Damage causes truncal ataxia.'),
('7e42cdf2-b334-5f63-a52d-d1df4bf877ab'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The anterior lobe (paleocerebellum):', '["Involved in cognition","Cerebrocerebellum","Vestibulocerebellum","Involved in speech","Spinocerebellum"]'::jsonb, 'Spinocerebellum', 'Spinocerebellum (vermis + intermediate zone) receives input from the spinal cord. Damage causes ataxia of the trunk and limbs.'),
('41061dbf-fed6-5237-9fe9-528f77e578be'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The posterior lobe (neocerebellum):', '["Spinocerebellum and its associated anatomical structures","Eye movement and its associated anatomical structures","Cerebrocerebellum (involved in planning, initiation, and timing of voluntary movement - the large","Balance control and its associated anatomical structures","Vestibulocerebellum and its associated anatomical structures"]'::jsonb, 'Cerebrocerebellum (involved in planning, initiation, and timing of voluntary movement - the large', 'Cerebrocerebellum (lateral hemispheres) receives input from the cerebral cortex (via the pontine nuclei). Damage causes limb ataxia.'),
('450ae570-a836-5203-991b-9153767fb5cc'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Cerebellar ataxia presents with:', '["Hyperreflexia and its associated anatomical structures","Bradykinesia and its associated anatomical structures","Resting tremor and its associated anatomical structures","Rigidity and its associated anatomical structures","Intention tremor, dysmetria, dysdiadochokinesia, nystagmus, and wide-based gait"]'::jsonb, 'Intention tremor, dysmetria, dysdiadochokinesia, nystagmus, and wide-based gait', 'Cerebellar lesions cause ipsilateral deficits (the cerebellum controls the ipsilateral side of the body).'),
('70eda51a-f5d4-567a-84f9-a4d815e6a859'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The brainstem consists of:', '["Pons and medulla only","Midbrain and medulla only","Midbrain and pons only","Midbrain, pons, and medulla oblongata","Cerebellum and pons"]'::jsonb, 'Midbrain, pons, and medulla oblongata', 'The brainstem (the ''stem'' of the brain) contains the reticular formation, cranial nerve nuclei, and long tracts.'),
('1f39f9b3-8282-5913-93f2-c4be23ec8912'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The midbrain (mesencephalon) contains:', '["The inferior colliculi and its associated anatomical structures","The olives and its associated anatomical structures","The pyramids and its associated anatomical structures","The trapezoid body and its associated anatomical structures","The cerebral peduncles (crus cerebri), substantia nigra, and the periaqueductal gray (with the aq"]'::jsonb, 'The cerebral peduncles (crus cerebri), substantia nigra, and the periaqueductal gray (with the aq', 'Midbrain (the smallest part of the brainstem) is the level of CN III and IV.'),
('3b441390-55c0-5e86-9dc7-2d65eb19ea01'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The cerebral peduncles (crus cerebri) contain:', '["The cerebellar peduncles and its associated anatomical structures","The cranial nerve nuclei and its associated anatomical structures","Sensory tracts and its associated anatomical structures","The reticular formation and its associated anatomical structures","The corticospinal, corticobulbar, and corticopontine fibers"]'::jsonb, 'The corticospinal, corticobulbar, and corticopontine fibers', 'The crus cerebri (the anterior part of the cerebral peduncle) is the ''motor highway'' of the midbrain.'),
('ef1288e4-09fe-57a3-8de2-f68f8bf93c99'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The superior colliculus is involved in:', '["Pain modulation","Auditory reflexes","Motor coordination","Balance","Visual reflexes"]'::jsonb, 'Visual reflexes', 'Superior colliculus (the ''visual reflex center'') receives input from the retina and the visual cortex.'),
('0dce3c1f-9900-50c0-82c7-08a71a524754'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The inferior colliculus is involved in:', '["Balance","Pain modulation","Motor coordination","Auditory reflexes","Visual reflexes"]'::jsonb, 'Auditory reflexes', 'Inferior colliculus (the ''auditory reflex center'') receives input from the cochlear nuclei and the lateral lemniscus.'),
('ef01b849-f8f6-5cc7-b191-06627baea6af'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The pons (metencephalon) contains:', '["The substantia nigra and its associated anatomical structures","The olives and its associated anatomical structures","The pyramids and its associated anatomical structures","The pontine nuclei (corticopontocerebellar relay), the middle cerebellar peduncle, and CN V, VI","The inferior colliculi and its associated anatomical structures"]'::jsonb, 'The pontine nuclei (corticopontocerebellar relay), the middle cerebellar peduncle, and CN V, VI', 'The pons (bridge) connects the cerebellum to the brainstem via the middle cerebellar peduncle.'),
('fc4e5ba1-599b-5bd0-9065-900f5b501b41'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The pontine nuclei receive input from:', '["The cerebellum and its associated anatomical structures","The brainstem and its associated anatomical structures","The thalamus and its associated anatomical structures","The spinal cord and its associated anatomical structures","The cerebral cortex (corticopontine fibers) and project to the contralateral cerebellar cortex (p"]'::jsonb, 'The cerebral cortex (corticopontine fibers) and project to the contralateral cerebellar cortex (p', 'Pontine nuclei (in the ventral pons) are the major relay in the corticopontocerebellar pathway.'),
('d0390526-79f8-592c-b7dd-280af52ca0bc'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The medulla oblongata (myelencephalon) contains:', '["The cerebral peduncles and its associated anatomical structures","The substantia nigra and its associated anatomical structures","The superior colliculi and its associated anatomical structures","The pyramids (corticospinal tract), the olives (inferior olivary nuclei), and CN IX, X, XI","The pontine nuclei and its associated anatomical structures"]'::jsonb, 'The pyramids (corticospinal tract), the olives (inferior olivary nuclei), and CN IX, X, XI', 'Medulla (the lowest part of the brainstem) is continuous with the spinal cord at the foramen magnum.'),
('8cab943c-dec2-59f4-8934-fe482859ec86'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The pyramid of the medulla contains:', '["The trigeminal lemniscus","The dorsal columns","The corticospinal tract","The medial lemniscus","The spinothalamic tract"]'::jsonb, 'The corticospinal tract', 'The pyramidal decussation (at the junction of the medulla and the spinal cord) causes contralateral motor control.'),
('0136252e-67cb-5723-b8fa-ae0dcf4af9b6'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The olive (inferior olivary nucleus) is involved in:', '["Cerebellar motor learning","Pain modulation","Visual processing","Auditory processing","Balance"]'::jsonb, 'Cerebellar motor learning', 'Inferior olivary nucleus (the ''olive'') sends climbing fibers to the cerebellar cortex (essential for motor learning).'),
('652ea4bb-62d3-5e34-9f80-6aaed54b719e'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The reticular formation is:', '["A ventricle and its associated anatomical structures","A single nucleus and its associated anatomical structures","A network of interconnected neurons throughout the brainstem (involved in arousal, sleep","A white matter tract and its associated anatomical structures","A cranial nerve and its associated anatomical structures"]'::jsonb, 'A network of interconnected neurons throughout the brainstem (involved in arousal, sleep', 'The reticular formation (the ''reticular activating system'', RAS) regulates the sleep-wake cycle and levels of consciousness.'),
('20203011-a4ae-54c8-9d35-f2b55b368e42'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The reticular activating system (RAS) projects to:', '["The basal ganglia","The thalamus and the cortex","The spinal cord","The hippocampus","The cerebellum"]'::jsonb, 'The thalamus and the cortex', 'The RAS (in the brainstem reticular formation) is damaged in coma and persistent vegetative state.'),
('9105026e-f4fe-5daf-8416-2d2f61d365be'::uuid, 'Anatomy (Paper 2)', 'Brain', 'With respect to management, The cranial nerve nuclei are located in:', '["The thalamus","The spinal cord","The brainstem","The cerebellum","The cerebral cortex"]'::jsonb, 'The brainstem', 'CN III-XII have nuclei in the brainstem. CN I (olfactory) is in the olfactory bulb. CN II (optic) is in the retina.'),
('8756c44f-044c-54fc-ba03-cbc2b5287136'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The oculomotor nerve (CN III) nucleus is located in:', '["The medulla","The pons","The hypothalamus","The thalamus","The midbrain"]'::jsonb, 'The midbrain', 'CN III (oculomotor) innervates all extraocular muscles except LR (CN VI) and SO (CN IV).'),
('890d3fcd-fda9-5e8a-a73c-416954bc112f'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The trochlear nerve (CN IV) nucleus is located in:', '["The midbrain (at the level of the inferior colliculus, the only CN that exits from the dorsal bra","The hypothalamus and its associated anatomical structures","The pons and its associated anatomical structures","The medulla and its associated anatomical structures","The thalamus and its associated anatomical structures"]'::jsonb, 'The midbrain (at the level of the inferior colliculus, the only CN that exits from the dorsal bra', 'CN IV (trochlear) innervates the superior oblique muscle (depresses the eye in adduction).'),
('788e183c-e456-5545-995e-7979a6a2f186'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The trigeminal nerve (CN V) nuclei are located in:', '["The pons only and its associated anatomical structures","The medulla only and its associated anatomical structures","The midbrain only and its associated anatomical structures","The thalamus and its associated anatomical structures","The midbrain (mesencephalic), pons (principal sensory and motor), and medulla"]'::jsonb, 'The midbrain (mesencephalic), pons (principal sensory and motor), and medulla', 'CN V (trigeminal) has 3 sensory nuclei and 1 motor nucleus. It provides sensation to the face and motor to the muscles of mastication.'),
('7d69a7fd-3382-5086-a08a-2ab8640714bf'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The abducens nerve (CN VI) nucleus is located in:', '["The midbrain","The hypothalamus","The medulla","The pons","The thalamus"]'::jsonb, 'The pons', 'CN VI (abducens) innervates the lateral rectus muscle (abducts the eye).'),
('faea12f0-8083-53d0-9972-afb29437f7e1'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The facial nerve (CN VII) nucleus is located in:', '["The hypothalamus","The midbrain","The medulla","The pons","The thalamus"]'::jsonb, 'The pons', 'CN VII (facial) innervates the muscles of facial expression (motor) and taste (anterior 2/3 of the tongue).'),
('1b3af936-ac69-51d8-930a-ca922a83445d'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The vestibulocochlear nerve (CN VIII) nuclei are located in:', '["The medulla only","The pons only","The pons and the medulla","The midbrain only","The cerebellum"]'::jsonb, 'The pons and the medulla', 'CN VIII (vestibulocochlear) has the cochlear nuclei (hearing) and the vestibular nuclei (balance).'),
('ad56e692-153e-5217-9eec-57a7bfee7e22'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The glossopharyngeal nerve (CN IX) nuclei are located in:', '["The pons","The thalamus","The hypothalamus","The midbrain","The medulla"]'::jsonb, 'The medulla', 'CN IX (glossopharyngeal) innervates the parotid gland, taste (posterior 1/3 of the tongue), and the carotid body/sinus.'),
('cbe8d8d9-e5be-5e0b-b546-494d06b3833d'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The vagus nerve (CN X) nuclei are located in:', '["The midbrain","The pons","The hypothalamus","The medulla","The thalamus"]'::jsonb, 'The medulla', 'CN X (vagus) is the longest and most widely distributed cranial nerve (parasympathetic to the thorax and abdomen).'),
('74ff9191-4828-54bc-8a12-6eb24a3ed525'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The accessory nerve (CN XI) nucleus is located in:', '["The medulla (cranial root) and the cervical spinal cord","The midbrain and its associated anatomical structures","The pons and its associated anatomical structures","The hypothalamus and its associated anatomical structures","The thalamus and its associated anatomical structures"]'::jsonb, 'The medulla (cranial root) and the cervical spinal cord', 'CN XI (spinal accessory) innervates the sternocleidomastoid and the trapezius muscles.'),
('c71731f2-fce9-5a47-9dce-d8be26230343'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The hypoglossal nerve (CN XII) nucleus is located in:', '["The thalamus","The midbrain","The hypothalamus","The medulla","The pons"]'::jsonb, 'The medulla', 'CN XII (hypoglossal) innervates all intrinsic and most extrinsic muscles of the tongue (except palatoglossus, CN X).'),
('4ef98e17-8c8e-564c-ae7b-7a6c5e893145'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The medial lemniscus carries:', '["Vision and its associated anatomical structures","Pain and temperature and its associated anatomical structures","Proprioception, vibration, and fine touch","Motor fibers and its associated anatomical structures","Facial sensation and its associated anatomical structures"]'::jsonb, 'Proprioception, vibration, and fine touch', 'The medial lemniscus (ML) is the second-order neuron pathway for dorsal column modalities. It decussates in the medulla.'),
('f023c65c-1977-57c3-b0fb-9adc4512bf8e'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The spinothalamic tract carries:', '["Proprioception","Pain and temperature","Fine touch","Vibration","Motor fibers"]'::jsonb, 'Pain and temperature', 'Spinothalamic tract (STT, anterolateral system): first-order neurons enter and synapse in the substantia gelatinosa (Rexed II). Decussation in the anterior commissure.'),
('9aba3a4e-c6e7-5a7d-b969-15464c07ed3c'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The corticospinal tract (pyramidal tract) crosses at:', '["The spinal cord","The decussation of the pyramids","The midbrain","The internal capsule","The pons"]'::jsonb, 'The decussation of the pyramids', 'The corticospinal tract (CST) originates from the motor cortex, passes through the internal capsule, the cerebral peduncle, and the pyramids.'),
('6227368b-9e57-5a4b-bcad-03b3d82a151a'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Wallenberg syndrome (lateral medullary syndrome) results from:', '["PCA occlusion and its associated anatomical structures","PICA occlusion (causes ipsilateral Horner, ataxia, dysphagia, hoarseness","MCA occlusion and its associated anatomical structures","Basilar artery occlusion and its associated anatomical structures","ACA occlusion and its associated anatomical structures"]'::jsonb, 'PICA occlusion (causes ipsilateral Horner, ataxia, dysphagia, hoarseness', 'Wallenberg: ipsilateral Horner (sympathetic), ipsilateral ataxia (restiform body), ipsilateral dysphagia/hoarseness (nucleus ambiguus), contralateral pain/temp (spinothalamic).'),
('d28ce800-ba6c-5d57-b2f0-c10d454366f4'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Weber syndrome (superior alternating hemiplegia) results from:', '["Basilar artery occlusion and its associated anatomical structures","Posterior cerebral artery or penetrating branch occlusion (ipsilateral CN III palsy + contralater","ACA occlusion and its associated anatomical structures","PICA occlusion and its associated anatomical structures","MCA occlusion and its associated anatomical structures"]'::jsonb, 'Posterior cerebral artery or penetrating branch occlusion (ipsilateral CN III palsy + contralater', 'Weber syndrome (midbrain): CN III fascicle (ipsilateral) and cerebral peduncle (contralateral hemiparesis).'),
('4ff0e281-e24f-506c-ba27-551837063417'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Millard-Gubler syndrome (inferior alternating hemiplegia) results from:', '["Midbrain lesion","Thalamic lesion","Medullary lesion","Cerebellar lesion","Pontine lesion"]'::jsonb, 'Pontine lesion', 'Millard-Gubler (ventral pons): CN VI (lateral rectus) and CN VII (face) ipsilateral + CST (contralateral).'),
('2d0787dc-c55a-5329-b043-a520905fe317'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The subdural space is located:', '["Between the arachnoid and the pia","Between the dura and the arachnoid","Between the pia and the brain","Within the brain","Between the skull and the dura"]'::jsonb, 'Between the dura and the arachnoid', 'Subdural hematoma (bridging vein rupture) is common in elderly and alcoholics (crescent-shaped, crosses sutures).'),
('67351fa2-6bc4-5da4-90f1-fb0a7c59efb3'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The epidural (extradural) space is located:', '["Between the skull and the dura","Between the dura and the arachnoid","Between the pia and the brain","Within the brain","Between the arachnoid and the pia"]'::jsonb, 'Between the skull and the dura', 'Epidural hematoma (middle meningeal artery tear) is biconvex/lens-shaped, does not cross sutures. Neurosurgical emergency.'),
('3c0cf3eb-ef75-5716-9d5e-cfdf82843ce3'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The subarachnoid space contains:', '["Pus and its associated structures","Venous blood and its associated structures","CSF and the major cerebral arteries","Edema fluid and its associated structures","Tumor cells and its associated structures"]'::jsonb, 'CSF and the major cerebral arteries', 'Subarachnoid hemorrhage (SAH): bleeding into the subarachnoid space (most commonly from a berry aneurysm rupture).'),
('33a9eba3-9baf-5266-9329-f20cefbe99b9'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Berry aneurysms most commonly occur at:', '["The MCA bifurcation","The bifurcation of the circle of Willis","The PCA bifurcation","The ICA bifurcation","The basilar artery tip"]'::jsonb, 'The bifurcation of the circle of Willis', 'Berry aneurysms (saccular, congenital) are commonly at the ACom, PCom, or MCA bifurcation. Rupture causes SAH.'),
('2b57b1ed-d53d-5229-b9bb-97ca30a2d024'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The most common site for a cerebral aneurysm is:', '["The internal carotid artery","The posterior communicating artery","The middle cerebral artery","The anterior communicating artery","The basilar artery"]'::jsonb, 'The anterior communicating artery', 'ACom aneurysms (30%): may present with bitemporal hemianopia (compression of the optic chiasm).'),
('f02a3dfb-7fc8-541b-8223-0c231e59f04c'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The most common site for primary intracerebral hemorrhage (hypertensive hemorrhage) is:', '["The temporal lobe","The occipital lobe","The medulla","The frontal lobe","The putamen"]'::jsonb, 'The putamen', 'Hypertensive hemorrhage: lenticulostriate arteries (from MCA) rupture -> putamen (most common), followed by thalamus, cerebellum, and pons.'),
('498a4198-2cb8-553c-89ff-32b88ec47877'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Hydrocephalus is:', '["A collection of pus in the brain","A tumor of the brain","A collection of blood in the brain","An abnormal accumulation of CSF in the ventricles","A swelling of the brain"]'::jsonb, 'An abnormal accumulation of CSF in the ventricles', 'Non-communicating (obstructive) hydrocephalus: block within the ventricular system. Communicating: impaired CSF absorption (e.g., after SAH).'),
('8696ffb7-05d9-5c4a-bffc-c08a9eea589b'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The thalamostriate vein is a landmark for:', '["The midbrain","The internal capsule","The foramen of Monro","The basal ganglia","The thalamus"]'::jsonb, 'The foramen of Monro', 'The thalamostriate vein (draining the basal ganglia and the thalamus) runs toward the foramen of Monro.'),
('2fa38a91-b039-5723-b994-a164f6a4ad50'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The internal cerebral veins (paired):', '["Drain the spinal cord and its associated anatomical structures","Drain the cerebral cortex and its associated anatomical structures","Drain the deep structures of the hemisphere (basal ganglia, thalamus, choroid plexus","Drain the cerebellum and its associated anatomical structures","Drain the brainstem and its associated anatomical structures"]'::jsonb, 'Drain the deep structures of the hemisphere (basal ganglia, thalamus, choroid plexus', 'The internal cerebral veins (deep cerebral veins) run in the velum interpositum (the roof of the 3rd ventricle).'),
('abfff75a-86ad-5703-89cf-83e109e3cb8e'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The great cerebral vein (of Galen):', '["Collects blood from the internal cerebral veins and the basal veins","Drains the cerebellum and its associated anatomical structures","Drains the spinal cord and its associated anatomical structures","Drains the cerebral cortex and its associated anatomical structures","Drains the brainstem and its associated anatomical structures"]'::jsonb, 'Collects blood from the internal cerebral veins and the basal veins', 'The great cerebral vein (of Galen) is a short, midline vein running in the quadrigeminal cistern.'),
('85f55884-0b1c-5e3b-92d4-eb5ba2da2ed5'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The superficial middle cerebral vein drains into:', '["The straight sinus","The superior sagittal sinus","The cavernous sinus","The transverse sinus","The sigmoid sinus"]'::jsonb, 'The cavernous sinus', 'The superficial middle cerebral vein (sylvian vein) runs in the lateral sulcus and drains into the cavernous sinus.'),
('65289f71-a463-513b-92d6-9763a13d70cc'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The vein of Labb (inferior anastomotic vein) connects:', '["The superior sagittal sinus to the sigmoid sinus","The superficial middle cerebral vein to the transverse sinus","The superior sagittal sinus to the straight sinus","The cavernous sinus to the straight sinus","The deep and superficial venous systems"]'::jsonb, 'The superficial middle cerebral vein to the transverse sinus', 'The vein of Labb is the main drainage from the temporal lobe to the transverse sinus.'),
('e804d1d5-d499-5383-8dfa-214f9e826755'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The vein of Trolard (superior anastomotic vein) connects:', '["The superficial middle cerebral vein to the superior sagittal sinus","The superior sagittal sinus to the straight sinus","The cavernous sinus to the transverse sinus","The cavernous sinus to the straight sinus","The superficial and deep venous systems"]'::jsonb, 'The superficial middle cerebral vein to the superior sagittal sinus', 'The vein of Trolard (great anastomotic vein) drains the frontal and parietal lobes to the superior sagittal sinus.'),
('8f1c3c47-b5e7-5acf-9093-c15829d94151'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The cavernous sinus connects to the pterygoid plexus via:', '["The straight sinus and its associated anatomical structures","The internal jugular vein and its associated anatomical structures","The superior sagittal sinus and its associated anatomical structures","The facial vein and its associated anatomical structures","The emissary veins (through the foramen ovale, the foramen lacerum, and the superior orbital fiss"]'::jsonb, 'The emissary veins (through the foramen ovale, the foramen lacerum, and the superior orbital fiss', 'The cavernous sinus-pterygoid plexus connection (valveless) allows the spread of infection from the face to the cavernous sinus.'),
('73e8faaa-6535-5afd-b5d7-57c546dcc01e'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The dural venous sinuses ultimately drain into:', '["The vertebral vein","The subclavian vein","The external jugular vein","The facial vein","The internal jugular vein"]'::jsonb, 'The internal jugular vein', 'The sigmoid sinus (the continuation of the transverse sinus) becomes the internal jugular vein at the jugular foramen.'),
('f24dacc6-004a-576e-9402-62ca021aa3f3'::uuid, 'Anatomy (Paper 2)', 'Brain', 'For a patient presenting with symptoms, The olfactory nerve (CN I) fibers pass through:', '["The foramen rotundum","The optic canal","The cribriform plate of the ethmoid bone","The superior orbital fissure","The foramen ovale"]'::jsonb, 'The cribriform plate of the ethmoid bone', 'CN I (olfactory): special visceral afferent for smell. The olfactory bulb (anterior cranial fossa) projects to the olfactory cortex.'),
('87957c2a-36dc-5d39-b11a-efd1bc0e2c0c'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Regarding clinical scenarios, The optic nerve (CN II) passes through:', '["The inferior orbital fissure","The superior orbital fissure","The foramen ovale","The optic canal","The foramen rotundum"]'::jsonb, 'The optic canal', 'CN II (optic): special somatic afferent for vision. The optic chiasm (above the pituitary) where the nasal fibers cross.'),
('4d75e334-4a17-58b7-b2e2-e9cdca73844b'::uuid, 'Anatomy (Paper 2)', 'Brain', 'In a surgical context, The oculomotor nerve (CN III) passes through:', '["The superior orbital fissure","The foramen rotundum","The foramen ovale","The inferior orbital fissure","The optic canal"]'::jsonb, 'The superior orbital fissure', 'CN III (oculomotor) carries parasympathetic fibers (pupil constriction and accommodation) via the ciliary ganglion.'),
('b4e6136d-1652-54e0-ad01-77a44804c2fd'::uuid, 'Anatomy (Paper 2)', 'Brain', 'On diagnostic evaluation, The trochlear nerve (CN IV) passes through:', '["The optic canal","The foramen ovale","The inferior orbital fissure","The superior orbital fissure","The foramen rotundum"]'::jsonb, 'The superior orbital fissure', 'CN IV (trochlear): the only CN that exits from the DORSAL midbrain. Innervates the superior oblique.'),
('06638bc9-5f3b-57d8-a91d-d412d2b2e5a6'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The trigeminal nerve (CN V) divisions exit through:', '["V1: foramen rotundum, V2: foramen ovale, V3: superior orbital fissure","All through the foramen rotundum","V1: superior orbital fissure, V2: foramen rotundum, V3: foramen ovale","All through the foramen ovale","All through the superior orbital fissure"]'::jsonb, 'V1: superior orbital fissure, V2: foramen rotundum, V3: foramen ovale', 'CN V (trigeminal) has 3 divisions: ophthalmic (V1), maxillary (V2), and mandibular (V3).'),
('70719693-07e3-5863-bbba-cba9411cc259'::uuid, 'Anatomy (Paper 2)', 'Brain', 'With respect to management, The abducens nerve (CN VI) passes through:', '["The foramen ovale","The foramen rotundum","The inferior orbital fissure","The optic canal","The superior orbital fissure"]'::jsonb, 'The superior orbital fissure', 'CN VI (abducens) has the longest intracranial course (susceptible to raised ICP causing false localizing sign).'),
('341b964e-f945-5c75-905b-580b9a7736ea'::uuid, 'Anatomy (Paper 2)', 'Brain', 'For a patient presenting with symptoms, The facial nerve (CN VII) passes through:', '["The foramen spinosum and its associated anatomical structures","The internal acoustic meatus -> the facial canal (with the geniculate ganglion","The foramen ovale and its associated anatomical structures","The jugular foramen and its associated anatomical structures","The foramen magnum and its associated anatomical structures"]'::jsonb, 'The internal acoustic meatus -> the facial canal (with the geniculate ganglion', 'CN VII (facial) has 4 segments: intracranial, meatal, labyrinthine, and tympanic/mastoid. The chorda tympani (taste) branches in the facial canal.'),
('1004abfa-a815-526c-bf9f-899b23994533'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The vestibulocochlear nerve (CN VIII) passes through:', '["The jugular foramen","The internal acoustic meatus","The foramen magnum","The superior orbital fissure","The stylomastoid foramen"]'::jsonb, 'The internal acoustic meatus', 'CN VIII: the cochlear division (hearing) and the vestibular division (balance). The labyrinthine artery (from AICA) is the blood supply.'),
('dfd4f961-51dc-5c4e-8ea5-12444edc61ef'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The glossopharyngeal nerve (CN IX) passes through:', '["The foramen spinosum","The jugular foramen","The internal acoustic meatus","The foramen ovale","The stylomastoid foramen"]'::jsonb, 'The jugular foramen', 'CN IX (glossopharyngeal) provides sensory innervation to the carotid body and sinus (baro- and chemoreceptors).'),
('1becfc42-7f7d-5e30-a22c-2ab36c8bd848'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The vagus nerve (CN X) passes through:', '["The internal acoustic meatus","The stylomastoid foramen","The foramen spinosum","The foramen ovale","The jugular foramen"]'::jsonb, 'The jugular foramen', 'CN X (vagus) descends in the carotid sheath, gives off the recurrent laryngeal nerve, and enters the abdomen through the esophageal hiatus.'),
('99cabf24-eaf7-5658-9238-8eb10751404c'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The accessory nerve (CN XI, spinal root) passes through:', '["The foramen ovale","The internal acoustic meatus","The jugular foramen","The foramen spinosum","The foramen magnum"]'::jsonb, 'The jugular foramen', 'CN XI (spinal accessory) ascends through the foramen magnum and exits through the jugular foramen.'),
('f8db8537-0a99-5c1b-a6d1-50efc263c535'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The hypoglossal nerve (CN XII) passes through:', '["The foramen spinosum","The foramen magnum","The jugular foramen","The foramen ovale","The hypoglossal canal"]'::jsonb, 'The hypoglossal canal', 'CN XII (hypoglossal) runs in the carotid sheath (between the ICA and IJV) to reach the tongue muscles.'),
('3da4692d-e1f5-5bf5-9cf8-ff44ce548756'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Regarding clinical scenarios, The pineal gland is located:', '["In the epithalamus","In the pituitary fossa","In the hypothalamus","In the thalamus","In the midbrain"]'::jsonb, 'In the epithalamus', 'The pineal gland (pineal body) secretes melatonin (regulates circadian rhythm). Calcification is a radiological landmark (in the midline).'),
('408af3b1-348d-5839-9448-b6257f96b2b3'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The pituitary gland (hypophysis) is located:', '["In the sella turcica","In the posterior cranial fossa","In the third ventricle","In the hypothalamus","In the anterior cranial fossa"]'::jsonb, 'In the sella turcica', 'The pituitary (the ''master gland'') is connected to the hypothalamus by the infundibulum (pituitary stalk).'),
('3b91591a-b07f-5139-bc3d-a6531aeffdf3'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The pituitary is divided into:', '["The pars distalis and the pars intermedia only and its associated anatomical structures","Superior and inferior parts and its associated anatomical structures","Right and left lobes and its associated anatomical structures","The infundibulum and the pars tuberalis and its associated anatomical structures","Adenohypophysis (anterior, from the oral ectoderm, Rathke pouch) and neurohypophysis (posterior"]'::jsonb, 'Adenohypophysis (anterior, from the oral ectoderm, Rathke pouch) and neurohypophysis (posterior', 'Adenohypophysis (75%) secretes GH, TSH, ACTH, FSH, LH, prolactin. Neurohypophysis stores ADH and oxytocin (produced in the hypothalamus).'),
('d845ca82-af39-5cc5-9acf-8d2513d5ec86'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The diencephalon consists of:', '["Hypothalamus only and its associated anatomical structures","Epithalamus and subthalamus only and its associated anatomical structures","Thalamus and hypothalamus only and its associated anatomical structures","Thalamus, hypothalamus, epithalamus (including the pineal gland), and the subthalamus","Thalamus only and its associated anatomical structures"]'::jsonb, 'Thalamus, hypothalamus, epithalamus (including the pineal gland), and the subthalamus', 'The diencephalon (the ''between brain'') surrounds the 3rd ventricle.'),
('eaf8d5db-f757-5d04-9c30-baadb3e9982e'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The hypothalamus is connected to the pituitary via:', '["Both the portal system and the neural connection","The hypothalamic-hypophyseal portal system (for releasing/inhibiting hormones to the anterior pit","The anterior commissure","The optic chiasm","The infundibulum"]'::jsonb, 'Both the portal system and the neural connection', 'The portal system (hypothalamus -> anterior pituitary) and the hypothalamohypophyseal tract (hypothalamus -> posterior pituitary).'),
('40bc8c19-1819-5755-b195-45ccfb1aeeed'::uuid, 'Anatomy (Paper 2)', 'Brain', 'In a surgical context, The optic chiasm is located:', '["In the temporal lobe","In the frontal lobe","Above the pituitary fossa","In the brainstem","In the occipital lobe"]'::jsonb, 'Above the pituitary fossa', 'The optic chiasm (where nasal fibers cross) is above the pituitary. Pituitary tumors compress the chiasm -> bitemporal hemianopia.'),
('c694c3d0-a9e1-5396-a18c-d22e60aabcad'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The lateral ventricles consist of:', '["Only the body and the posterior horn and its associated anatomical structures","The lateral and third ventricles and its associated anatomical structures","Anterior (frontal) horn, body, atrium, posterior (occipital) horn, and inferior (temporal) horn","Only the anterior horn and the body and its associated anatomical structures","Only the atrium and the temporal horn and its associated anatomical structures"]'::jsonb, 'Anterior (frontal) horn, body, atrium, posterior (occipital) horn, and inferior (temporal) horn', 'Each lateral ventricle is C-shaped, surrounding the caudate nucleus and the thalamus.'),
('63a27c52-fb6f-5846-a5d7-862a1ec98cf8'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The choroid plexus of the lateral ventricle extends into:', '["The occipital horn and its associated anatomical structures","The third ventricle and its associated anatomical structures","The entire ventricle and its associated anatomical structures","The frontal horn and its associated anatomical structures","The body, the atrium, and the temporal horn"]'::jsonb, 'The body, the atrium, and the temporal horn', 'The choroid plexus (site of CSF production) is absent from the frontal and occipital horns.'),
('66a8291f-d1bd-5233-b6ce-681dc05aab29'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The septum pellucidum:', '["Part of the corpus callosum and its associated anatomical structures","Part of the caudate and its associated anatomical structures","Part of the fornix and its associated anatomical structures","A thin membrane between the two lateral ventricles","Part of the thalamus and its associated anatomical structures"]'::jsonb, 'A thin membrane between the two lateral ventricles', 'The septum pellucidum (two laminae) separates the anterior horns of the lateral ventricles.'),
('d4f5f8a9-09a7-5efc-ae40-9d888e5f99be'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The pineal gland calcifies with age and is a landmark for:', '["The thalamus","The corpus callosum","The midline","The hypothalamus","The pituitary"]'::jsonb, 'The midline', 'Pineal calcification (visible on CT/X-ray) should be in the midline. Shift indicates a mass lesion.'),
('8a978c5b-074c-533e-8c00-52c159fbe0a5'::uuid, 'Anatomy (Paper 2)', 'Brain', 'On diagnostic evaluation, The foramen magnum transmits:', '["The pons and its associated anatomical structures","The cerebellum and its associated anatomical structures","The internal carotid arteries and its associated anatomical structures","The medulla oblongata (the spinal cord), the vertebral arteries, the spinal roots of CN XI","The midbrain and its associated anatomical structures"]'::jsonb, 'The medulla oblongata (the spinal cord), the vertebral arteries, the spinal roots of CN XI', 'The foramen magnum (the largest foramen of the skull) is located in the posterior cranial fossa.'),
('d101dcc5-217d-5990-b29a-b02c35fdf9a6'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The tentorial notch (incisura) contains:', '["The medulla","The midbrain","The cerebellum","The pons","The occipital lobe"]'::jsonb, 'The midbrain', 'The tentorial notch (the opening of the tentorium cerebelli) is the site of transtentorial herniation.'),
('01529106-9408-5a76-8a5d-56b6c9350545'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Transtentorial (uncal) herniation causes:', '["Compression of CN VII and its associated anatomical structures","Compression of CN VI and its associated anatomical structures","Compression of CN III (ipsilateral dilated pupil), the cerebral peduncle (contralateral hemiparesis","Compression of CN IX and its associated anatomical structures","Compression of CN X and its associated anatomical structures"]'::jsonb, 'Compression of CN III (ipsilateral dilated pupil), the cerebral peduncle (contralateral hemiparesis', 'Uncal herniation (the medial temporal lobe is pushed over the tentorial edge) is a neurosurgical emergency.'),
('898bc0d2-5753-55bb-97cb-956b7f634ebf'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Tonsillar herniation (coning) causes:', '["Compression of the pons and its associated anatomical structures","Compression of CN III and its associated anatomical structures","Compression of the cerebellum and its associated anatomical structures","Compression of the medulla (respiratory arrest, bradycardia, hypertension - Cushing response","Compression of the midbrain and its associated anatomical structures"]'::jsonb, 'Compression of the medulla (respiratory arrest, bradycardia, hypertension - Cushing response', 'Tonsillar herniation (the cerebellar tonsils are pushed through the foramen magnum) is rapidly fatal.'),
('fef345b3-5591-578c-81dc-d00bb3e97e6e'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The CSF pressure in the lumbar cistern (normal recumbent) is:', '["25-35 cm H2O","35-45 cm H2O","15-25 cm H2O","5-15 cm H2O","0-5 cm H2O"]'::jsonb, '5-15 cm H2O', 'Normal CSF pressure (measured by lumbar puncture) is 5-15 cm H2O. Opening pressure >20 cm H2O suggests raised intracranial pressure.'),
('0024139a-9d95-52f9-962e-c795fe4cce40'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The Queckenstedt test (jugular vein compression):', '["Measures the glucose level and its associated anatomical structures","Measures the bacterial culture and its associated anatomical structures","Measures the CSF protein and its associated anatomical structures","Measures the patency of the spinal subarachnoid space (CSF pressure rises with IJ compression if","Measures the cell count and its associated anatomical structures"]'::jsonb, 'Measures the patency of the spinal subarachnoid space (CSF pressure rises with IJ compression if', 'The Queckenstedt test: compression of the IJ vein increases ICP, which is transmitted to the lumbar CSF if the spinal subarachnoid space is patent.'),
('b6f13d48-c45a-5c42-bf73-6e372c45363c'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The blood supply of the caudate nucleus and the internal capsule is mainly from:', '["The posterior cerebral artery and its associated anatomical structures","The superior cerebellar artery and its associated anatomical structures","The anterior choroidal artery and its associated anatomical structures","The basilar artery and its associated anatomical structures","The lenticulostriate arteries (from the MCA) and the recurrent artery of Heubner"]'::jsonb, 'The lenticulostriate arteries (from the MCA) and the recurrent artery of Heubner', 'The recurrent artery of Heubner (the largest branch of the A2 segment of the ACA) supplies the anterior limb of the internal capsule.'),
('beeee226-c11b-55a9-9320-c867fdd05629'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The recurrent artery of Heubner arises from:', '["The middle cerebral artery","The anterior choroidal artery","The anterior cerebral artery","The posterior cerebral artery","The internal carotid artery"]'::jsonb, 'The anterior cerebral artery', 'The recurrent artery of Heubner (a medial lenticulostriate artery) supplies the caudate nucleus (head) and the internal capsule (anterior limb).'),
('fe866838-27a7-5fb2-99e7-06a5c7ef97a6'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The basal vein (of Rosenthal) drains:', '["The brainstem and its associated anatomical structures","The cerebral cortex and its associated anatomical structures","The choroid plexus and its associated anatomical structures","The cerebellum and its associated anatomical structures","The basal forebrain, the insula, and the deep structures"]'::jsonb, 'The basal forebrain, the insula, and the deep structures', 'The basal vein (of Rosenthal) runs laterally around the midbrain to join the great cerebral vein.'),
('8b5823ff-1969-5dab-a1a3-c0d2a0fe583b'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The insula (Island of Reil) is:', '["A separate lobe and its associated anatomical structures","A basal ganglion and its associated anatomical structures","A portion of the cerebral cortex hidden within the lateral sulcus (sylvian fissure","A cranial nerve and its associated anatomical structures","A white matter tract and its associated anatomical structures"]'::jsonb, 'A portion of the cerebral cortex hidden within the lateral sulcus (sylvian fissure', 'The insula (the 5th lobe) is covered by the frontal, parietal, and temporal opercula. It is involved in taste, pain, and autonomic function.'),
('36f3c760-fb93-5733-b4be-1bad5bf58356'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The claustrum is:', '["A thin sheet of gray matter between the putamen and the insula","A part of the limbic system and its associated anatomical structures","A part of the basal ganglia and its associated anatomical structures","A white matter tract and its associated anatomical structures","A part of the thalamus and its associated anatomical structures"]'::jsonb, 'A thin sheet of gray matter between the putamen and the insula', 'The claustrum (thin, irregular layer) may be involved in consciousness and salience detection.'),
('cf4737a1-2abf-5f88-9862-57e677792b15'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The extreme capsule is:', '["A cranial nerve","A white matter tract between the insula and the claustrum","A white matter tract between the claustrum and the putamen","A part of the internal capsule","A part of the corona radiata"]'::jsonb, 'A white matter tract between the insula and the claustrum', 'The extreme capsule (the most lateral of the capsules) separates the insula from the claustrum.'),
('e48767c7-ae78-5975-8ca9-6b672403a978'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The external capsule is:', '["A part of the corona radiata","A white matter tract between the insula and the claustrum","A part of the internal capsule","A cranial nerve","A white matter tract between the putamen and the claustrum"]'::jsonb, 'A white matter tract between the putamen and the claustrum', 'The external capsule (a thin sheet of white matter) lies between the putamen (medial) and the claustrum (lateral).'),
('e76da406-8d6d-5f32-9102-5d739e0f35d6'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The uncinate fasciculus connects:', '["The temporal lobe to the occipital lobe","The thalamus to the cortex","The frontal lobe to the anterior temporal lobe","The two hemispheres","The frontal lobe to the parietal lobe"]'::jsonb, 'The frontal lobe to the anterior temporal lobe', 'The uncinate fasciculus (a ''hook-shaped'' tract) is involved in language, emotion, and executive function.'),
('6c0ed47a-8e97-50d6-b89f-5077b60b8442'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The cingulum is:', '["A dural sinus and its associated anatomical structures","A cranial nerve and its associated anatomical structures","A basal ganglion and its associated anatomical structures","A white matter tract within the cingulate gyrus (connects parts of the limbic system","A ventricle and its associated anatomical structures"]'::jsonb, 'A white matter tract within the cingulate gyrus (connects parts of the limbic system', 'The cingulum (the ''girdle'' of the limbic system) is part of the Papez circuit of emotion and memory.'),
('d487d1de-8fec-554c-82e9-c6377f1e6f1f'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The superior longitudinal fasciculus (SLF) connects:', '["The frontal, parietal, occipital, and temporal lobes","Only the frontal and temporal lobes","Only the frontal and parietal lobes","The two hemispheres","The thalamus to the cortex"]'::jsonb, 'The frontal, parietal, occipital, and temporal lobes', 'The SLF (the arcuate fasciculus is part of it) is involved in language (connecting Broca and Wernicke areas).'),
('67597826-82f1-522a-af9a-32d56e1c7965'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The inferior longitudinal fasciculus (ILF) connects:', '["The frontal and temporal lobes","The two hemispheres","The frontal and parietal lobes","The thalamus to the cortex","The occipital lobe and the temporal lobe"]'::jsonb, 'The occipital lobe and the temporal lobe', 'The ILF carries visual information from the occipital lobe to the temporal lobe (object recognition).'),
('72476e66-497b-559d-8d22-d4ba3079c41b'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The inferior fronto-occipital fasciculus (IFOF) connects:', '["The frontal and temporal lobes","The frontal and parietal lobes","The two hemispheres","The frontal lobe and the occipital lobe","The thalamus to the cortex"]'::jsonb, 'The frontal lobe and the occipital lobe', 'The IFOF (a major ventral stream tract) is involved in semantic processing and reading.'),
('515060c6-5e32-546d-bdb9-3f41aee26af4'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The optic radiation (geniculocalcarine tract) projects from:', '["The optic chiasm to the LGN","The LGN to the primary visual cortex","The retina to the LGN","The superior colliculus to the occipital cortex","The LGN to the superior colliculus"]'::jsonb, 'The LGN to the primary visual cortex', 'The optic radiation (Meyer loop: inferior fibers, anterior temporal loop; superior fibers: direct parietal path).'),
('103b4929-b4bc-5f7a-a2ca-f7942efee791'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Meyer loop (the anterior temporal loop of the optic radiation) carries:', '["Peripheral fibers and its associated anatomical structures","Inferior quadrant (superior visual field) fibers that loop anteriorly into the temporal lobe","Superior quadrant fibers and its associated anatomical structures","Macular fibers and its associated anatomical structures","Central vision fibers and its associated anatomical structures"]'::jsonb, 'Inferior quadrant (superior visual field) fibers that loop anteriorly into the temporal lobe', 'Damage to Meyer loop causes a contralateral superior quadrantanopia (''pie in the sky'' defect).'),
('c3ab58ea-d3db-5fd9-9b92-0a170e845e1d'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The auditory radiation projects from:', '["The cochlea to the cochlear nucleus","The MGN to the primary auditory cortex","The cochlear nucleus to the superior olive","The superior olive to the lateral lemniscus","The inferior colliculus to the MGN"]'::jsonb, 'The MGN to the primary auditory cortex', 'Auditory radiation (in the sublenticular part of the internal capsule) carries fibers for hearing.'),
('22bcbf5f-f587-5ae6-8802-255cd6ac64b8'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The trigeminal lemniscus carries:', '["Motor fibers to the face and its associated anatomical structures","Taste and its associated anatomical structures","Sensation from the face (pain, temperature, and touch from the trigeminal sensory nuclei to the V","Vision and its associated anatomical structures","Pain from the body and its associated anatomical structures"]'::jsonb, 'Sensation from the face (pain, temperature, and touch from the trigeminal sensory nuclei to the V', 'The trigeminal lemniscus (quintothalamic tract) decussates in the pons and medulla and ascends to the VPM.'),
('4566cdc1-e439-56a5-bf1f-55e073e7e724'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The lateral lemniscus carries:', '["Visual information and its associated anatomical structures","Olfactory information and its associated anatomical structures","Pain and temperature from the body and its associated anatomical structures","Motor fibers and its associated anatomical structures","Auditory information (from the cochlear nuclei and the superior olivary complex to the inferior c"]'::jsonb, 'Auditory information (from the cochlear nuclei and the superior olivary complex to the inferior c', 'The lateral lemniscus (the main auditory tract) runs in the lateral tegmentum of the pons and the midbrain.'),
('f63693a6-1447-560f-9c1c-f40afa2e316a'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The medial longitudinal fasciculus (MLF):', '["Connects the CN III, IV, VI, and VIII nuclei for coordinated eye movements (conjugate gaze","Connects the hypothalamus to the pituitary and its associated anatomical structures","Connects the motor cortex to the spinal cord and its associated anatomical structures","Connects the sensory cortex to the thalamus and its associated anatomical structures","Connects the cerebellum to the cerebral cortex and its associated anatomical structures"]'::jsonb, 'Connects the CN III, IV, VI, and VIII nuclei for coordinated eye movements (conjugate gaze', 'MLF lesion causes internuclear ophthalmoplegia (INO: impaired adduction on the ipsilateral side).'),
('5b2ac0f0-39a9-5017-99e2-225ef2b30a9a'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The red nucleus is located in:', '["The midbrain","The hypothalamus","The thalamus","The pons","The medulla"]'::jsonb, 'The midbrain', 'The red nucleus (a subcortical motor nucleus) gives rise to the rubrospinal tract (flexor tone facilitator).'),
('f8b6bf43-cbcc-59ed-8e33-b91f518cee53'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The rubrospinal tract originates from:', '["The tectum","The reticular formation","The motor cortex","The vestibular nucleus","The red nucleus"]'::jsonb, 'The red nucleus', 'The rubrospinal tract (small in humans) modulates flexor muscle tone.'),
('9ca77323-386a-5eaf-9f5d-0f2de9c86f8d'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The vestibulospinal tracts (medial and lateral) originate from:', '["The vestibular nuclei","The tectum","The reticular formation","The motor cortex","The red nucleus"]'::jsonb, 'The vestibular nuclei', 'The lateral vestibulospinal tract (from Deiters nucleus) facilitates antigravity (extensor) muscles.'),
('698866e0-eb76-5ac8-9bfe-7cfc2a568bcb'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The tectospinal tract originates from:', '["The motor cortex","The inferior colliculus","The superior colliculus","The vestibular nucleus","The red nucleus"]'::jsonb, 'The superior colliculus', 'The tectospinal tract (the ''visual reflex tract'') decussates in the midbrain and descends to the cervical spinal cord.'),
('629d91c0-1e4d-5d58-a777-961e2ae9ab46'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The reticulospinal tracts (pontine and medullary) originate from:', '["The tectum","The motor cortex","The red nucleus","The vestibular nucleus","The reticular formation"]'::jsonb, 'The reticular formation', 'Reticulospinal tracts modulate muscle tone (pontine = antigravity, medullary = flexor).'),
('4e74c51a-d9e9-5a0e-80e3-cfa70caf40a2'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The spinocerebellar tracts carry:', '["Pain and temperature and its associated anatomical structures","Visual information and its associated anatomical structures","Proprioception from the spinal cord to the cerebellum","Auditory information and its associated anatomical structures","Motor commands and its associated anatomical structures"]'::jsonb, 'Proprioception from the spinal cord to the cerebellum', 'DSCT (from Clarke column, ipsilateral, uncrossed) enters the cerebellum via the ICP. VSCT (crossed) enters via the SCP.'),
('ee3e4b0c-19bd-58d4-a940-678e5d2f7dd6'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The dorsal (posterior) spinocerebellar tract (DSCT) originates from:', '["Clarke column","The dorsal root ganglion","The sacral spinal cord","The ventral horn","The lateral horn"]'::jsonb, 'Clarke column', 'DSCT (Flechsig tract) runs in the lateral funiculus (posterior part) and enters the cerebellum via the inferior cerebellar peduncle.'),
('05f88c80-2b90-5d08-a030-7104f63b111c'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The cuneocerebellar tract is analogous to the DSCT for:', '["The trunk","The thorax","The upper limb","The face","The lower limb"]'::jsonb, 'The upper limb', 'The cuneocerebellar tract carries proprioception from the upper limb to the cerebellum (via the ICP).'),
('3490b4bb-0f4c-57fb-b46e-804f32d6d3da'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The ventral (anterior) spinocerebellar tract (VSCT) originates from:', '["The ventral horn (spinal border cells, L4-S1, crosses and ascends, enters the SCP","The sacral cord and its associated anatomical structures","Clarke column and its associated anatomical structures","The dorsal root ganglion and its associated anatomical structures","The lateral horn and its associated anatomical structures"]'::jsonb, 'The ventral horn (spinal border cells, L4-S1, crosses and ascends, enters the SCP', 'VSCT (Gowers tract) carries information from the lower limb to the cerebellum. It crosses twice (in the spinal cord and the cerebellum).'),
('5a810a69-1e25-5408-a189-4c29aa78505f'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The inferior cerebellar peduncle (ICP, restiform body) contains:', '["The CST and its associated anatomical structures","The pontocerebellar fibers and its associated anatomical structures","DSCT, cuneocerebellar, olivocerebellar, vestibulocerebellar, and reticulocerebellar fibers (affer","The efferent fibers from the cerebellum and its associated anatomical structures","The VSCT and its associated anatomical structures"]'::jsonb, 'DSCT, cuneocerebellar, olivocerebellar, vestibulocerebellar, and reticulocerebellar fibers (affer', 'ICP (afferent to the cerebellum) is the largest of the three cerebellar peduncles in terms of afferents.'),
('777df1bb-216a-5c46-a591-6f2ddf68e5f2'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The middle cerebellar peduncle (MCP, brachium pontis) contains:', '["The spinocerebellar tracts and its associated anatomical structures","The efferent fibers from the cerebellum and its associated anatomical structures","The vestibulocerebellar fibers and its associated anatomical structures","The olivocerebellar fibers and its associated anatomical structures","The pontocerebellar fibers (from the contralateral pontine nuclei, the largest afferent input to"]'::jsonb, 'The pontocerebellar fibers (from the contralateral pontine nuclei, the largest afferent input to', 'MCP (afferent, crossed) is the largest of the three cerebellar peduncles. It forms the lateral wall of the pontine tegmentum.'),
('f89f24b7-40af-5bea-9bd8-d5d87db4da90'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The superior cerebellar peduncle (SCP, brachium conjunctivum) contains:', '["Afferent fibers to the cerebellum and its associated anatomical structures","The efferent fibers from the cerebellar nuclei (mainly dentate) to the red nucleus and the thalam","The pontocerebellar fibers and its associated anatomical structures","The VSCT and its associated anatomical structures","The olivocerebellar fibers and its associated anatomical structures"]'::jsonb, 'The efferent fibers from the cerebellar nuclei (mainly dentate) to the red nucleus and the thalam', 'SCP (efferent, crosses in the midbrain) decussates at the level of the inferior colliculus.'),
('d5c61ef5-501f-5c1a-b3bc-4203429c3f8d'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The central sulcus (of Rolando) separates:', '["The temporal lobe from the frontal lobe","The parietal lobe from the occipital lobe","The cerebrum from the cerebellum","The frontal lobe from the parietal lobe","The two cerebral hemispheres"]'::jsonb, 'The frontal lobe from the parietal lobe', 'The central sulcus (between the precentral and postcentral gyri) is a key landmark on the lateral surface.'),
('7f0b9dfb-1c47-5629-af0a-61a52498de11'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The lateral sulcus (Sylvian fissure) separates:', '["The parietal lobe from the occipital lobe","The cerebrum from the cerebellum","The frontal lobe from the parietal lobe","The two hemispheres","The temporal lobe from the frontal and parietal lobes"]'::jsonb, 'The temporal lobe from the frontal and parietal lobes', 'The lateral sulcus (Sylvian fissure) divides the insula from the opercula and contains the MCA.'),
('c18b60cc-6d75-517e-8b21-6da214e3dbaf'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The parieto-occipital sulcus separates:', '["The two hemispheres","The parietal lobe from the occipital lobe","The frontal lobe from the parietal lobe","The cerebrum from the cerebellum","The temporal lobe from the occipital lobe"]'::jsonb, 'The parietal lobe from the occipital lobe', 'The parieto-occipital sulcus (on the medial surface) separates the precuneus from the cuneus.'),
('8d7e6f9d-58d3-50d2-b677-3fce0cb97b28'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The calcarine sulcus is located:', '["In the insula","In the temporal lobe","In the frontal lobe","In the occipital lobe","In the parietal lobe"]'::jsonb, 'In the occipital lobe', 'The calcarine sulcus (deep, on the medial surface) is surrounded by the cuneus (superior) and the lingual gyrus (inferior).'),
('5f64c652-620c-5a9d-a965-c8c446062968'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The supramarginal gyrus (Brodmann area 40) is located:', '["In the frontal lobe and its associated anatomical structures","In the occipital lobe and its associated anatomical structures","In the temporal lobe and its associated anatomical structures","In the parietal lobe, surrounding the posterior end of the lateral sulcus","In the insula and its associated anatomical structures"]'::jsonb, 'In the parietal lobe, surrounding the posterior end of the lateral sulcus', 'The supramarginal gyrus (inferior parietal lobule) is involved in language (phonological processing).'),
('dd944639-4617-512e-837f-2016b85d45f9'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The angular gyrus (Brodmann area 39) is located:', '["In the temporal lobe and its associated anatomical structures","In the frontal lobe and its associated anatomical structures","In the insula and its associated anatomical structures","In the parietal lobe, surrounding the posterior end of the superior temporal sulcus","In the occipital lobe and its associated anatomical structures"]'::jsonb, 'In the parietal lobe, surrounding the posterior end of the superior temporal sulcus', 'Angular gyrus (inferior parietal lobule) is involved in semantic processing, reading, and calculation (Gerstmann syndrome).'),
('53543097-733b-5630-bd76-2e86c57e4dc5'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Gerstmann syndrome (dominant angular gyrus lesion) includes:', '["Amnesia and its associated anatomical structures","Agnosia and its associated anatomical structures","Aphasia and its associated anatomical structures","Finger agnosia, right-left confusion, agraphia, and acalculia","Apraxia and its associated anatomical structures"]'::jsonb, 'Finger agnosia, right-left confusion, agraphia, and acalculia', 'Gerstmann syndrome (parietal lobe, dominant hemisphere) is characterized by the ''4 As'' mentioned.'),
('f31f9503-542a-5f73-b574-087c703b380c'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The precuneus is located:', '["In the temporal lobe and its associated anatomical structures","In the occipital lobe and its associated anatomical structures","On the medial surface of the parietal lobe","In the insula and its associated anatomical structures","In the frontal lobe and its associated anatomical structures"]'::jsonb, 'On the medial surface of the parietal lobe', 'The precuneus (in the superior parietal lobule, medial surface) is involved in visuospatial imagery, memory, and self-awareness.'),
('d0e55dc6-7d45-5644-9233-623063066f38'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The cuneus is located:', '["In the temporal lobe","In the frontal lobe","In the occipital lobe","In the insula","In the parietal lobe"]'::jsonb, 'In the occipital lobe', 'The cuneus (the ''wedge'' between the parieto-occipital and calcarine sulci) contains part of the primary visual cortex.'),
('3e7a096a-d9db-531c-9701-623297ad867c'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The lingual gyrus is located:', '["In the parietal lobe","In the insula","In the frontal lobe","In the occipital lobe","In the temporal lobe"]'::jsonb, 'In the occipital lobe', 'The lingual gyrus (the ''tongue-shaped'' gyrus) is part of the ventral stream (object recognition and face processing).'),
('1686315d-0284-55c8-ad5a-e09d68edf622'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The fusiform gyrus (occipitotemporal gyrus) is located:', '["In the frontal lobe and its associated anatomical structures","On the inferior surface of the temporal and occipital lobes","In the parietal lobe and its associated anatomical structures","In the thalamus and its associated anatomical structures","In the insula and its associated anatomical structures"]'::jsonb, 'On the inferior surface of the temporal and occipital lobes', 'The fusiform face area (FFA, in the fusiform gyrus) is specialized for face recognition. Damage causes prosopagnosia.'),
('d889c12a-b391-5d08-81c7-158927e58d0a'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The parahippocampal gyrus is located:', '["On the medial surface of the temporal lobe","In the insula and its associated anatomical structures","In the parietal lobe and its associated anatomical structures","In the frontal lobe and its associated anatomical structures","In the occipital lobe and its associated anatomical structures"]'::jsonb, 'On the medial surface of the temporal lobe', 'The parahippocampal gyrus (part of the limbic system) contains the entorhinal cortex (input to the hippocampus).'),
('17ef4e92-694a-5e8e-adbd-a298ae03e3d4'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The uncus is located:', '["At the anterior end of the parahippocampal gyrus","In the frontal lobe and its associated anatomical structures","In the parietal lobe and its associated anatomical structures","In the occipital lobe and its associated anatomical structures","In the insula and its associated anatomical structures"]'::jsonb, 'At the anterior end of the parahippocampal gyrus', 'The uncus (the medial part of the temporal lobe) contains the olfactory cortex (primary olfactory area).'),
('27cd0731-bbb5-52e2-b4ee-7be9f72d245b'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The hippocampal formation consists of:', '["Dentate gyrus, hippocampus proper (CA1-CA3), subiculum, and the entorhinal cortex","Only the subiculum and its associated anatomical structures","Only the hippocampus proper and its associated anatomical structures","Only the entorhinal cortex and its associated anatomical structures","Only the dentate gyrus and its associated anatomical structures"]'::jsonb, 'Dentate gyrus, hippocampus proper (CA1-CA3), subiculum, and the entorhinal cortex', 'The hippocampal formation (memory center) is a three-layered allocortex (archicortex).'),
('de49db11-e3df-5abd-a978-14f40adaf481'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The dentate gyrus is:', '["A narrow, toothed band of gray matter between the hippocampus proper and the parahippocampal gyru","A ventricle and its associated anatomical structures","A white matter tract and its associated anatomical structures","A basal ganglion and its associated anatomical structures","A cranial nerve and its associated anatomical structures"]'::jsonb, 'A narrow, toothed band of gray matter between the hippocampus proper and the parahippocampal gyru', 'The dentate gyrus (the ''granule cell layer'') receives input from the entorhinal cortex via the perforant pathway.'),
('7fa08e4e-fe97-5733-a9cc-15e01b0f0266'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The trisynaptic circuit of the hippocampus:', '["Dentate -> CA1 -> subiculum and its associated anatomical structures","Subiculum -> dentate -> CA3 -> CA1 and its associated anatomical structures","Entorhinal -> CA1 -> CA3 -> dentate and its associated anatomical structures","CA1 -> CA3 -> dentate and its associated anatomical structures","Perforant path -> dentate granule cells (mossy fibers) -> CA3 (Schaffer collaterals"]'::jsonb, 'Perforant path -> dentate granule cells (mossy fibers) -> CA3 (Schaffer collaterals', 'The trisynaptic circuit (the basic functional unit of the hippocampus) is essential for long-term potentiation (LTP) and memory.'),
('c5245fa0-3eab-512e-9737-bb851e58ded2'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Long-term potentiation (LTP) in the hippocampus is mediated by:', '["Dopamine receptors and its associated anatomical structures","Serotonin receptors and its associated anatomical structures","NMDA receptors (calcium influx) and AMPA receptors (sodium influx) at the CA1 synapse","GABA receptors and its associated anatomical structures","Acetylcholine receptors and its associated anatomical structures"]'::jsonb, 'NMDA receptors (calcium influx) and AMPA receptors (sodium influx) at the CA1 synapse', 'LTP (the cellular basis of learning and memory) involves the strengthening of synapses through repeated stimulation.'),
('43443352-c269-5ecc-8ea5-787eb806497b'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The Papez circuit (emotion and memory) includes:', '["Hippocampus -> amygdala -> hypothalamus and its associated anatomical structures","Cerebellum -> thalamus -> motor cortex and its associated anatomical structures","Hippocampus -> fornix -> mammillary bodies -> mammillothalamic tract -> anterior thalamus -> cing","Thalamus -> cortex -> basal ganglia and its associated anatomical structures","Basal ganglia -> thalamus -> cortex and its associated anatomical structures"]'::jsonb, 'Hippocampus -> fornix -> mammillary bodies -> mammillothalamic tract -> anterior thalamus -> cing', 'The Papez circuit (the ''emotional circuit'' of the brain) is interconnected with the amygdala and the prefrontal cortex.'),
('3d3192ee-731d-5981-928a-becf962590bc'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The prefrontal cortex is responsible for:', '["Executive functions","Language production","Memory formation","Motor control","Sensory processing"]'::jsonb, 'Executive functions', 'Prefrontal cortex (the most anterior part of the frontal lobe) is the ''CEO of the brain''.'),
('5b4e97c7-a82c-5c72-8a45-b7048dbda90b'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The orbitofrontal cortex is:', '["The sensory cortex","The motor cortex","The dorsal part of the prefrontal cortex","The ventral part of the prefrontal cortex","The visual cortex"]'::jsonb, 'The ventral part of the prefrontal cortex', 'Orbitofrontal cortex (OFC) is involved in value-based decision-making and the regulation of emotional responses.'),
('6a48db6a-fcb1-5c14-9425-d2fb6ec81913'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The anterior cingulate cortex (ACC) is:', '["Part of the motor cortex","Part of the sensory cortex","Part of the limbic system","Part of the language cortex","Part of the visual cortex"]'::jsonb, 'Part of the limbic system', 'ACC (the ''executive'' part of the limbic system) is activated by tasks requiring cognitive control.'),
('6f15a83c-ea1f-5cca-9711-0536b25a3411'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The insula (anterior part) is involved in:', '["Motor control and its associated anatomical structures","Hearing and its associated anatomical structures","Vision and its associated anatomical structures","Language and its associated anatomical structures","Interoception (awareness of body sensations), taste, pain, and empathy"]'::jsonb, 'Interoception (awareness of body sensations), taste, pain, and empathy', 'The anterior insula (the ''insula of the limbic system'') integrates body sensations with emotional awareness.'),
('e34df96e-c2fc-5af5-8edf-0d5ab3f3f3a4'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The default mode network (DMN) includes:', '["Motor cortex and its associated anatomical structures","Medial prefrontal cortex, posterior cingulate cortex, and the angular gyrus (active at rest","Auditory cortex and its associated anatomical structures","Visual cortex and its associated anatomical structures","Sensory cortex and its associated anatomical structures"]'::jsonb, 'Medial prefrontal cortex, posterior cingulate cortex, and the angular gyrus (active at rest', 'The DMN (task-negative network) is active during daydreaming, self-reflection, and mind-wandering.'),
('cf8c3f64-993a-5d57-8e3b-320e2db81606'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The salience network includes:', '["The visual cortex and its associated anatomical structures","The motor cortex and its associated anatomical structures","The auditory cortex and its associated anatomical structures","The sensory cortex and its associated anatomical structures","The anterior insula and the anterior cingulate cortex"]'::jsonb, 'The anterior insula and the anterior cingulate cortex', 'The salience network (task-positive network) switches between the DMN and the central executive network.'),
('57005352-3d57-530d-9394-4bcf9d20680b'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The arcuate nucleus of the hypothalamus controls:', '["The circadian rhythm","Appetite and energy balance","The growth hormone release","The stress response","The thirst center"]'::jsonb, 'Appetite and energy balance', 'The arcuate nucleus (at the base of the hypothalamus) integrates signals from the blood (ghrelin, leptin, insulin).'),
('27c2627a-a079-5f45-86da-46a1f0db42b6'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The suprachiasmatic nucleus (SCN) of the hypothalamus controls:', '["Temperature and its associated anatomical structures and its associated structures","The circadian rhythm (the ''master clock'', receives input from the retina via the retinohypothalam","Appetite and its associated anatomical structures and its associated structures","Thirst and its associated anatomical structures and its associated structures","Stress and its associated anatomical structures and its associated structures"]'::jsonb, 'The circadian rhythm (the ''master clock'', receives input from the retina via the retinohypothalam', 'The SCN (above the optic chiasm) is entrained by light (melanopsin-containing retinal ganglion cells).'),
('d7bbb31c-1205-5053-9b72-b15e6279068e'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The paraventricular nucleus (PVN) of the hypothalamus produces:', '["Oxytocin and ADH (vasopressin), and controls the autonomic nervous system and the HPA axis","TSH and its associated anatomical structures","Prolactin and its associated anatomical structures","Growth hormone and its associated anatomical structures","FSH and LH and its associated anatomical structures"]'::jsonb, 'Oxytocin and ADH (vasopressin), and controls the autonomic nervous system and the HPA axis', 'PVN (periventricular zone): magnocellular (oxytocin/ADH) and parvocellular (CRH, TRH) neurons.'),
('1facce59-ab4c-5a03-91ca-d29fc41994e5'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The supraoptic nucleus (SON) of the hypothalamus produces:', '["FSH and LH and its associated anatomical structures","Oxytocin and ADH (vasopressin) - transported to the posterior pituitary via the hypothalamohypoph","Growth hormone and its associated anatomical structures","TSH and its associated anatomical structures","Prolactin and its associated anatomical structures"]'::jsonb, 'Oxytocin and ADH (vasopressin) - transported to the posterior pituitary via the hypothalamohypoph', 'SON (above the optic tract) contains magnocellular neurons that project directly to the posterior pituitary.'),
('ffd27baa-4464-5072-b892-f1a06addd645'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The ventromedial nucleus (VMN) of the hypothalamus:', '["The ''thirst center''","The ''hunger center''","The ''satiety center''","The ''temperature center''","The ''sex center''"]'::jsonb, 'The ''satiety center''', 'VMN (the ''satiety center''): integrates leptin and insulin signals. Lesion causes uncontrollable eating (hyperphagia).'),
('c689010e-3975-57a9-8ace-af174c3d58cb'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The lateral hypothalamic area (LHA):', '["The ''temperature center''","The ''satiety center''","The ''thirst center''","The ''sleep center''","The ''hunger center''"]'::jsonb, 'The ''hunger center''', 'LHA (the ''feeding center''): contains neurons that express orexin (wakefulness and appetite).'),
('e7649061-c926-58b4-96fe-5d8dd087e627'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The preoptic area (POA) of the hypothalamus controls:', '["Hunger","Thirst","Sleep","Thermoregulation","Sexual behavior"]'::jsonb, 'Thermoregulation', 'The POA (the ''thermostat'' of the brain) receives temperature signals from the blood and the skin.'),
('cf328bd2-ede5-5a02-ad1f-ee43eb4ca12a'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The median eminence of the hypothalamus:', '["The thirst center and its associated anatomical structures","The final common pathway (hypothalamic releasing/inhibiting hormones enter the hypothalamic-hypop","The hunger center and its associated anatomical structures","The temperature center and its associated anatomical structures","The sleep center and its associated anatomical structures"]'::jsonb, 'The final common pathway (hypothalamic releasing/inhibiting hormones enter the hypothalamic-hypop', 'The median eminence (at the base of the hypothalamus, above the pituitary) is a circumventricular organ (lacks BBB).'),
('7de9448a-26bd-50f9-8d43-0a86341227f6'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The area postrema (in the medulla) is the:', '["Vasomotor center and its associated anatomical structures","Chemoreceptor trigger zone (CTZ) for vomiting","Cardiac center and its associated anatomical structures","Swallowing center and its associated anatomical structures","Respiratory center and its associated anatomical structures"]'::jsonb, 'Chemoreceptor trigger zone (CTZ) for vomiting', 'The area postrema (a CVO, lacks BBB) detects emetic stimuli in the blood (e.g., chemotherapy, opioids).'),
('b237af4c-c1eb-5404-960d-673ea32d83f9'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The nucleus solitarius (solitary nucleus) is:', '["A cranial nerve nucleus and its associated anatomical structures","A basal ganglion and its associated anatomical structures","An autonomic nucleus and its associated anatomical structures","A sensory nucleus in the medulla (taste from CN VII, IX, X, and visceral sensation from the thora","A motor nucleus and its associated anatomical structures"]'::jsonb, 'A sensory nucleus in the medulla (taste from CN VII, IX, X, and visceral sensation from the thora', 'The solitary nucleus (gustatory and visceral sensory) receives input via the chorda tympani, the greater petrosal, and the vagus nerves.'),
('cbac4096-31e9-5587-b15a-8e331229bff7'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The nucleus ambiguus is:', '["A sensory nucleus and its associated anatomical structures","A basal ganglion and its associated anatomical structures","A cranial nerve and its associated anatomical structures","An autonomic nucleus and its associated anatomical structures","A motor nucleus in the medulla (innervates the muscles of the pharynx, larynx"]'::jsonb, 'A motor nucleus in the medulla (innervates the muscles of the pharynx, larynx', 'The nucleus ambiguus (''uncertain nucleus'') gives rise to the branchial efferent fibers of CN IX, X, and XI.'),
('d794ba46-27a8-5f7f-9191-cae2b1b67978'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The dorsal motor nucleus of the vagus (DMNV):', '["Provides parasympathetic (preganglionic) output to the thoracic and abdominal viscera","Motor to the tongue and its associated anatomical structures","Motor to the larynx and its associated anatomical structures","Sensory from the pharynx and its associated anatomical structures","Motor to the face and its associated anatomical structures"]'::jsonb, 'Provides parasympathetic (preganglionic) output to the thoracic and abdominal viscera', 'DMNV (in the medulla, floor of the 4th ventricle) controls the heart, lungs, and GI tract.'),
('cac683cb-cdf4-598f-a911-9925a6ccec57'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The Edinger-Westphal nucleus is:', '["The sensory nucleus of CN V and its associated anatomical structures","The parasympathetic nucleus of CN III (located in the midbrain, controls pupil constriction and a","The motor nucleus of CN VII and its associated anatomical structures","The motor nucleus of CN III and its associated anatomical structures","The autonomic nucleus of CN VII and its associated anatomical structures"]'::jsonb, 'The parasympathetic nucleus of CN III (located in the midbrain, controls pupil constriction and a', 'The Edinger-Westphal nucleus (the ''accommodation center'') provides preganglionic parasympathetic fibers to the ciliary ganglion.'),
('5785ac34-bb8c-5d4f-bba7-7daa344f9836'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The ciliary ganglion is located:', '["In the submandibular region","In the parotid gland","In the pterygopalatine fossa","In the infratemporal fossa","In the posterior orbit"]'::jsonb, 'In the posterior orbit', 'The ciliary ganglion (parasympathetic) receives input from the Edinger-Westphal nucleus (CN III). Postganglionic fibers innervate the sphincter pupillae and the ciliary muscle.'),
('f84dfe90-336b-522e-a301-80247cf06113'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The pterygopalatine (sphenopalatine) ganglion is located:', '["In the parotid gland and its associated anatomical structures","In the pterygopalatine fossa (parasympathetic, receives input from CN VII via the greater petrosa","In the orbit and its associated anatomical structures","In the infratemporal fossa and its associated anatomical structures","In the submandibular region and its associated anatomical structures"]'::jsonb, 'In the pterygopalatine fossa (parasympathetic, receives input from CN VII via the greater petrosa', 'The pterygopalatine ganglion (the ''sphenopalatine'' ganglion) innervates the lacrimal gland and the nasal/palatine glands.'),
('52625fff-7a29-51bf-803a-b40b8c466b22'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The submandibular ganglion is located:', '["In the parotid gland","Above the submandibular gland","In the infratemporal fossa","In the orbit","In the pterygopalatine fossa"]'::jsonb, 'Above the submandibular gland', 'The submandibular ganglion (parasympathetic) innervates the submandibular and sublingual salivary glands.'),
('283bea3d-d2eb-5d07-80ca-92e542fe046a'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The otic ganglion is located:', '["In the parotid gland and its associated anatomical structures","In the infratemporal fossa (below the foramen ovale, parasympathetic, receives input from CN IX v","In the submandibular region and its associated anatomical structures","In the pterygopalatine fossa and its associated anatomical structures","In the orbit and its associated anatomical structures"]'::jsonb, 'In the infratemporal fossa (below the foramen ovale, parasympathetic, receives input from CN IX v', 'The otic ganglion (parasympathetic) innervates the parotid gland (secretomotor).'),
('38abd0d4-e6bf-586f-92b6-e9cd4f0e45e6'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The cerebellopontine angle (CPA) is:', '["The region between the cerebellum and the tentorium","The region between the cerebellum and the occipital bone","The region between the pons, the medulla, and the cerebellum (the CPA cistern contains CN V, VII","The region between the medulla and the spinal cord","The region between the pons and the midbrain"]'::jsonb, 'The region between the pons, the medulla, and the cerebellum (the CPA cistern contains CN V, VII', 'CPA tumors (e.g., vestibular schwannoma, meningioma) cause hearing loss, tinnitus, and facial numbness.'),
('b914380a-68a5-5153-bca0-0b5f28796a71'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The most common tumor of the cerebellopontine angle is:', '["Meningioma","Facial nerve schwannoma","Epidermoid cyst","Trigeminal schwannoma","Vestibular schwannoma"]'::jsonb, 'Vestibular schwannoma', 'Vestibular schwannoma (benign, slow-growing) presents with unilateral sensorineural hearing loss, tinnitus, and imbalance.'),
('58e63ced-71fd-50f1-8404-ce6d7e3f2397'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The foramen of Luschka (lateral aperture) opens into:', '["The cisterna magna and its associated anatomical structures","The ambient cistern and its associated anatomical structures","The quadrigeminal cistern and its associated anatomical structures","The cerebellopontine angle (the lateral recess of the 4th ventricle, allowing CSF to enter the su","The suprasellar cistern and its associated anatomical structures"]'::jsonb, 'The cerebellopontine angle (the lateral recess of the 4th ventricle, allowing CSF to enter the su', 'The foramina of Luschka (paired) and the foramen of Magendie (single) are the exits for CSF from the 4th ventricle.'),
('e5a21a38-b3f0-5bfc-a8c7-fc945f2898da'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The trigeminal nerve (CN V) leaves the pons:', '["From the dorsal pons and its associated anatomical structures","From the ventral pons and its associated anatomical structures","From the medulla and its associated anatomical structures","From the lateral aspect of the pons (the motor root and the sensory root","From the midbrain and its associated anatomical structures"]'::jsonb, 'From the lateral aspect of the pons (the motor root and the sensory root', 'The trigeminal ganglion (the ''Gasserian ganglion'', the equivalent of the dorsal root ganglion) lies in Meckel cave (the trigeminal impression).'),
('bde96ff0-b97d-56b6-b9f8-9b42c5fcd204'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Meckel cave (the trigeminal cave) is located:', '["In the foramen magnum","In the posterior cranial fossa","In the middle cranial fossa","In the anterior cranial fossa","In the sella turcica"]'::jsonb, 'In the middle cranial fossa', 'Meckel cave (cavum trigeminale) is a CSF-filled space that contains the trigeminal ganglion and the proximal roots.'),
('63c43b31-1f1d-5efc-a18a-04376cdfc3f5'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The trigeminal ganglion gives rise to:', '["Only V2 and V3 and its associated anatomical structures","Only V1 and V3 and its associated anatomical structures","All three plus the motor root and its associated anatomical structures","Only V1 and V2 and its associated anatomical structures","The three divisions: V1 (ophthalmic), V2 (maxillary), V3"]'::jsonb, 'The three divisions: V1 (ophthalmic), V2 (maxillary), V3', 'The trigeminal (Gasserian) ganglion (semilunar, crescent-shaped) contains the cell bodies of the sensory fibers of CN V.'),
('f36e90ac-e4b1-5c5e-b34b-d147d89ad964'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The motor root of the trigeminal nerve:', '["Joins V2 and its associated anatomical structures","Joins V3 (the mandibular division) through the foramen ovale","Runs separately and its associated anatomical structures","Does not exist and its associated anatomical structures","Joins V1 and its associated anatomical structures"]'::jsonb, 'Joins V3 (the mandibular division) through the foramen ovale', 'The motor root (portio minor) of CN V bypasses the trigeminal ganglion and only runs with V3.'),
('23d10d7b-64b8-5e56-940d-8eb2bd92b341'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The muscles of mastication (supplied by V3):', '["The buccinator and the orbicularis oris and its associated anatomical structures","Temporalis, masseter, medial and lateral pterygoids (and the tensor tympani and tensor veli palat","Only the tensor tympani and its associated anatomical structures","Only the pterygoids and its associated anatomical structures","Only the temporalis and masseter and its associated anatomical structures"]'::jsonb, 'Temporalis, masseter, medial and lateral pterygoids (and the tensor tympani and tensor veli palat', 'The motor root of CN V3 supplies 8 muscles in total: muscles of mastication and the tensors.'),
('838878b0-7dd6-5b86-bab3-d3f9e7ec82a5'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The tentorium cerebelli is attached to:', '["The ethmoid bone and its associated anatomical structures","The anterior clinoid processes, the petrous ridges, and the transverse sinuses (forming the ''tent","The sphenoid bone and its associated anatomical structures","The frontal bone and its associated anatomical structures","The occipital bone and its associated anatomical structures"]'::jsonb, 'The anterior clinoid processes, the petrous ridges, and the transverse sinuses (forming the ''tent', 'The tentorium cerebelli (the ''tent of the cerebellum'') separates the cerebrum from the cerebellum.'),
('45359a62-784f-5c91-85da-5c25200a1df3'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The diaphragma sellae is:', '["The floor of the sella turcica and its associated anatomical structures","A part of the falx cerebri and its associated anatomical structures","The roof of the cavernous sinus and its associated anatomical structures","A small circular fold of dura covering the pituitary fossa","The wall of the cavernous sinus and its associated anatomical structures"]'::jsonb, 'A small circular fold of dura covering the pituitary fossa', 'The diaphragma sellae (the ''roof'' of the pituitary fossa) is the superior (roof) of the cavernous sinus.'),
('7318a1da-ec3e-59bc-a4dd-a9e8d5e0d54c'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The abducens nerve (CN VI) is at risk in:', '["Cavernous sinus thrombosis and its associated anatomical structures","Aneurysm of the ICA and its associated anatomical structures","Meningitis and its associated anatomical structures","Raised intracranial pressure (can be compressed against the clivus, causing a false localizing si","Orbital fracture and its associated anatomical structures"]'::jsonb, 'Raised intracranial pressure (can be compressed against the clivus, causing a false localizing si', 'CN VI palsy (the ''false localizing sign'') is a common non-specific sign of raised ICP (due to its long intracranial course).'),
('66d48cf8-6c9b-56e6-8462-30f778876faa'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The facial nerve (CN VII) is at risk in:', '["Orbital surgery and its associated anatomical structures","Thyroid surgery and its associated anatomical structures","Dental surgery and its associated anatomical structures","Nasal surgery and its associated anatomical structures","Parotid surgery (the nerve divides the gland into superficial and deep lobes), Bell palsy"]'::jsonb, 'Parotid surgery (the nerve divides the gland into superficial and deep lobes), Bell palsy', 'CN VII (facial) has a complex course: through the facial canal, giving off the chorda tympani, and the nerve to the stapedius.'),
('ee2274cb-d046-56d7-b875-9dfd2483f21d'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Bell palsy is:', '["A trigeminal nerve lesion and its associated anatomical structures","A vestibular schwannoma and its associated anatomical structures","An idiopathic, acute, peripheral facial nerve paralysis (CN VII) - presents with sudden unilatera","A central facial nerve paralysis and its associated anatomical structures","A Ramsey Hunt syndrome and its associated anatomical structures"]'::jsonb, 'An idiopathic, acute, peripheral facial nerve paralysis (CN VII) - presents with sudden unilatera', 'Bell palsy (Bell phenomenon: eye rolls up on attempted closure) is treated with steroids and antivirals. 70% recover fully.'),
('f1181cfc-6795-59eb-94af-5a29292ac0a4'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Ramsey Hunt syndrome (herpes zoster oticus):', '["Varicella-zoster infection of the geniculate ganglion (CN VII) causing facial palsy, ear pain","Vestibular schwannoma and its associated anatomical structures","Trigeminal neuralgia and its associated anatomical structures","Meniere disease and its associated anatomical structures","Bell palsy and its associated anatomical structures"]'::jsonb, 'Varicella-zoster infection of the geniculate ganglion (CN VII) causing facial palsy, ear pain', 'Ramsey Hunt syndrome has a worse prognosis than Bell palsy (treatment: antiviral + steroid).'),
('fb5ab850-4d2b-5957-b383-ca9dae10dd34'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The intermediate nerve (nervus intermedius) of CN VII carries:', '["Sensory fibers from the external ear and its associated anatomical structures","Taste fibers from the anterior 2/3 of the tongue and parasympathetic fibers to the salivary and l","Motor fibers to the face and its associated anatomical structures","Motor fibers to the stapedius and its associated anatomical structures","Taste from the posterior 1/3 of the tongue and its associated anatomical structures"]'::jsonb, 'Taste fibers from the anterior 2/3 of the tongue and parasympathetic fibers to the salivary and l', 'The nervus intermedius (the sensory/parasympathetic part of CN VII) runs between the motor root and CN VIII in the CPA.'),
('457aade3-47b9-5f8a-be7f-66891de681ed'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The chorda tympani (from CN VII) carries:', '["Sensory fibers from the external ear and its associated anatomical structures","Taste from the posterior 1/3 of the tongue and its associated anatomical structures","Motor fibers to the face and its associated anatomical structures","Taste from the anterior 2/3 of the tongue and parasympathetic fibers to the submandibular and sub","Motor fibers to the stapes and its associated anatomical structures"]'::jsonb, 'Taste from the anterior 2/3 of the tongue and parasympathetic fibers to the submandibular and sub', 'The chorda tympani (a branch of the facial nerve in the facial canal) transverses the middle ear and exits via the petrotympanic fissure.'),
('125dc486-750a-5a85-9b59-57570d87b0e6'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The greater petrosal nerve (from CN VII) carries:', '["Sensory fibers from the ear and its associated anatomical structures","Motor fibers to the stapedius and its associated anatomical structures","Parasympathetic fibers to the lacrimal gland (via the pterygopalatine ganglion","Taste from the anterior 2/3 and its associated anatomical structures","Motor fibers to the face and its associated anatomical structures"]'::jsonb, 'Parasympathetic fibers to the lacrimal gland (via the pterygopalatine ganglion', 'The greater petrosal nerve (the first branch of CN VII in the facial canal) arises from the geniculate ganglion.'),
('e2c85f51-f075-5a9c-95f8-de490721ba8e'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The nerve to the stapedius (from CN VII):', '["Innervates the muscles of the face and its associated anatomical structures","Innervates the soft palate and its associated anatomical structures","Innervates the stapedius muscle (tensing the stapes, dampening loud sounds","Innervates the tongue and its associated anatomical structures","Innervates the tensor tympani and its associated anatomical structures"]'::jsonb, 'Innervates the stapedius muscle (tensing the stapes, dampening loud sounds', 'Stapedius reflex (the ''acoustic reflex''): contraction of the stapedius muscle in response to loud sound (protects the inner ear).'),
('a5c888de-9285-58ce-b92a-dec76265a851'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The trigeminal nerve (sensory distribution):', '["V1: entire face; V2: neck; V3: scalp and its associated anatomical structures","V1: no sensory distribution and its associated anatomical structures","V1: ear; V2: nose; V3: chin and its associated anatomical structures","V1: eye; V2: ear; V3: all of face and its associated anatomical structures","V1: forehead, eye, nose (ophthalmic). V2: cheek, upper lip, maxilla (maxillary). V3: lower jaw"]'::jsonb, 'V1: forehead, eye, nose (ophthalmic). V2: cheek, upper lip, maxilla (maxillary). V3: lower jaw', 'The three divisions of CN V (the ''triplet'' nerve) are the main sensory supply to the face.'),
('4bac4f7d-eaf3-5692-aa26-15b7d1cdd7f3'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Trigeminal neuralgia (tic douloureux) is:', '["Facial twitching and its associated anatomical structures","Facial numbness and its associated anatomical structures","Facial weakness and its associated anatomical structures","Paroxysmal, severe, electric-shock-like pain in the distribution of CN V","Headache and its associated anatomical structures"]'::jsonb, 'Paroxysmal, severe, electric-shock-like pain in the distribution of CN V', 'Trigeminal neuralgia (the ''suicide disease'') is most often caused by vascular compression of the trigeminal root (by the SCA or AICA).'),
('ac21d291-db83-5388-aeca-0422c2314a4e'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The first-line treatment for trigeminal neuralgia is:', '["Gabapentin","Carbamazepine","Amitriptyline","Surgery","NSAIDs"]'::jsonb, 'Carbamazepine', 'Carbamazepine (Na-channel blocker) is the drug of choice. Refractory cases: microvascular decompression (MVD) or radiofrequency rhizotomy.'),
('2170f46a-845d-56c6-bb7b-1cb97ed7d638'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The retropharyngeal space (the ''danger space''):', '["Between the pharynx and the esophagus and its associated anatomical structures","Between the dura and the arachnoid and its associated anatomical structures","Between the prevertebral and the buccopharyngeal fascia (allows spread of infection from the skul","Between the trachea and the esophagus and its associated anatomical structures","Between the skull and the scalp and its associated anatomical structures"]'::jsonb, 'Between the prevertebral and the buccopharyngeal fascia (allows spread of infection from the skul', 'The retropharyngeal space (the ''danger space'') is the plane of spread of retropharyngeal abscess (mediastinitis).'),
('619d9242-a219-5d0b-a14a-df5d376328de'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The sphenopalatine foramen is located:', '["At the junction of the pterygopalatine fossa and the nasal cavity (transmits the sphenopalatine a","In the foramen ovale and its associated anatomical structures","In the foramen magnum and its associated anatomical structures","In the anterior cranial fossa and its associated anatomical structures","In the floor of the orbit and its associated anatomical structures"]'::jsonb, 'At the junction of the pterygopalatine fossa and the nasal cavity (transmits the sphenopalatine a', 'The sphenopalatine foramen (the ''gate'' of the nose) is a key surgical landmark for epistaxis (sphenopalatine artery ligation).'),
('02c3c1a8-405a-59c4-b6d9-f011c7c250b4'::uuid, 'Anatomy (Paper 2)', 'Brain', 'With respect to management, The pterygopalatine fossa communicates with:', '["The parotid space and its associated anatomical structures","The nasal cavity (sphenopalatine foramen), the orbit","The infratemporal fossa and its associated anatomical structures","The retropharyngeal space and its associated anatomical structures","The submandibular space and its associated anatomical structures"]'::jsonb, 'The nasal cavity (sphenopalatine foramen), the orbit', 'The pterygopalatine fossa (the ''vascular crossroads of the midface'') contains the maxillary nerve (V2) and the pterygopalatine ganglion.'),
('934896ab-732d-54d0-a793-744d1f53aa0a'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The infratemporal fossa contains:', '["The facial nerve and its associated anatomical structures","The submandibular gland and its associated anatomical structures","The parotid gland and its associated anatomical structures","The medial and lateral pterygoid muscles, the mandibular nerve (V3), the maxillary artery","The external carotid artery and its associated anatomical structures"]'::jsonb, 'The medial and lateral pterygoid muscles, the mandibular nerve (V3), the maxillary artery', 'The infratemporal fossa (below the skull base, deep to the ramus of the mandible) is a major anatomical compartment.'),
('1f3f9a87-4923-5d49-9f1e-f1802aefb3f8'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The maxillary artery (the terminal branch of the ECA) gives off:', '["The middle meningeal artery (enters the skull via the foramen spinosum), the infratemporal branches","Only the middle meningeal and its associated anatomical structures","The occipital artery and its associated anatomical structures","Only the infratemporal branches and its associated anatomical structures","Only the pterygopalatine branches and its associated anatomical structures"]'::jsonb, 'The middle meningeal artery (enters the skull via the foramen spinosum), the infratemporal branches', 'The maxillary artery (the largest terminal branch of the ECA) is the primary blood supply of the deep face.'),
('43b5c01a-3760-57da-8fcc-1bb006427744'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The middle meningeal artery enters the skull through:', '["The jugular foramen and its associated anatomical structures","The foramen spinosum (in the greater wing of the sphenoid, supplying the dura mater and the calva","The foramen ovale and its associated anatomical structures","The carotid canal and its associated anatomical structures","The foramen rotundum and its associated anatomical structures"]'::jsonb, 'The foramen spinosum (in the greater wing of the sphenoid, supplying the dura mater and the calva', 'The middle meningeal artery (the ''epidural artery'') is the most important artery in the skull (extradural hematoma).'),
('4e21672d-d111-5a26-ac7c-5d18771a828a'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The accessory meningeal artery enters the skull through:', '["The foramen spinosum","The foramen rotundum","The carotid canal","The foramen ovale","The jugular foramen"]'::jsonb, 'The foramen ovale', 'The accessory meningeal artery (a branch of the maxillary artery) is a small but clinically important artery.'),
('86ebdff9-0950-5dd4-9468-5f9953110f3d'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The pterygoid venous plexus communicates with:', '["The cavernous sinus (via the foramen ovale, the foramen lacerum, and the superior orbital fissure","The straight sinus and its associated anatomical structures","The internal jugular vein and its associated anatomical structures","The sigmoid sinus and its associated anatomical structures","The superior sagittal sinus and its associated anatomical structures"]'::jsonb, 'The cavernous sinus (via the foramen ovale, the foramen lacerum, and the superior orbital fissure', 'The pterygoid plexus (between the pterygoid muscles) is connected to the facial vein and the cavernous sinus.'),
('b699b3c9-e261-5b3e-94c3-9c01d1d86370'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The danger triangle of the face is:', '["The cheek and its associated anatomical structures and its associated structures","The forehead and its associated anatomical structures and its associated structures","The chin and its associated anatomical structures and its associated structures","The ear and its associated anatomical structures and its associated structures","The area from the nose to the angle of the mouth (the facial vein connects to the cavernous sinus"]'::jsonb, 'The area from the nose to the angle of the mouth (the facial vein connects to the cavernous sinus', 'The ''danger triangle'' (nasolabial area): infections in this area can spread retrograde to the cavernous sinus (cavernous sinus thrombosis).'),
('fb5f6755-32d1-5582-b0c0-056c3ef1fec4'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The facial vein drains into:', '["The subclavian vein and its associated anatomical structures","The internal jugular vein (via the common facial vein, formed by the facial vein and the retroman","The azygos vein and its associated anatomical structures","The external jugular vein and its associated anatomical structures","The brachiocephalic vein and its associated anatomical structures"]'::jsonb, 'The internal jugular vein (via the common facial vein, formed by the facial vein and the retroman', 'The facial vein (the main vein of the face) has valveless connections to the cavernous sinus (the ''danger triangle'').'),
('c076241d-ba8c-5af0-8e3c-4f9011f3d5f6'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The retromandibular vein is formed by:', '["The union of the superficial temporal vein and the maxillary vein","The occipital vein and the superficial temporal vein","The maxillary vein and the facial vein","The facial vein and the superficial temporal vein","The superficial temporal vein and the posterior auricular vein"]'::jsonb, 'The union of the superficial temporal vein and the maxillary vein', 'The retromandibular vein (the ''parotid vein'') divides into an anterior (joining the facial vein -> IJV) and a posterior branch (joining the EJV).'),
('4ade35cb-f96b-5546-ae4d-712a55051e13'::uuid, 'Anatomy (Paper 2)', 'Brain', 'For a patient presenting with symptoms, The external jugular vein is formed by:', '["The superficial temporal vein and the maxillary vein","The occipital vein and the superficial temporal vein","The internal jugular vein and the subclavian vein","The facial vein and the retromandibular vein","The union of the posterior auricular vein and the retromandibular vein"]'::jsonb, 'The union of the posterior auricular vein and the retromandibular vein', 'The EJV (the ''external'' jugular) runs over the sternocleidomastoid and drains into the subclavian vein.'),
('e1125bbf-82f2-53ee-9b83-90d4108b2f4f'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The internal jugular vein (IJV) is formed at:', '["The jugular foramen","The superior vena cava","The transverse sinus","The subclavian vein","The confluence of sinuses"]'::jsonb, 'The jugular foramen', 'The IJV (the largest vein of the head and neck) runs in the carotid sheath and joins the subclavian vein to form the brachiocephalic vein.'),
('8a1fc3f6-69f9-5bd6-bf47-368d546a095b'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The hypoglossal nerve (CN XII) runs:', '["In the submandibular gland and its associated anatomical structures","In the infratemporal fossa and its associated anatomical structures","In the pterygoid fossa and its associated anatomical structures","In the parotid gland and its associated anatomical structures","In the carotid sheath (between the ICA and the IJV, loops around the occipital artery"]'::jsonb, 'In the carotid sheath (between the ICA and the IJV, loops around the occipital artery', 'The hypoglossal nerve (CN XII) the ''tongue nerve'' supplies all the intrinsic and extrinsic tongue muscles (except palatoglossus, CN X).'),
('c85029b1-c796-574d-8b79-17daa765ec6f'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The ansa cervicalis (C1-C3) innervates:', '["The muscles of the tongue","The suprahyoid muscles","The muscles of the pharynx","The infrahyoid muscles","The muscles of the larynx"]'::jsonb, 'The infrahyoid muscles', 'The ansa cervicalis (the ''nerve loop'' of the neck) has a superior root (C1, from the hypoglossal) and an inferior root (C2-C3).'),
('bf7c713d-83aa-5fda-8582-58c7a60aaeae'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The phrenic nerve (C3-C5) is:', '["A branch of the brachial plexus and its associated anatomical structures","A nerve of the upper limb and its associated anatomical structures","A nerve of the back and its associated anatomical structures","The motor nerve of the diaphragm (descends on the anterior scalene, runs through the chest","The sensory nerve of the neck and its associated anatomical structures"]'::jsonb, 'The motor nerve of the diaphragm (descends on the anterior scalene, runs through the chest', 'The phrenic nerve (C3-C5, the ''nerve of the diaphragm'') also provides sensory innervation to the pericardium and the central diaphragm.'),
('706900bb-a5bc-5e32-b993-2a7e174d5d57'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The vagus nerve (CN X) gives off the following in the neck:', '["Only the pharyngeal branches and its associated anatomical structures","Only the cardiac branches and its associated anatomical structures","The pharyngeal branches, the superior laryngeal nerve, the recurrent laryngeal nerve","Only the superior laryngeal nerve and its associated anatomical structures","Only the recurrent laryngeal nerve and its associated anatomical structures"]'::jsonb, 'The pharyngeal branches, the superior laryngeal nerve, the recurrent laryngeal nerve', 'The vagus nerve (CN X) descends in the carotid sheath and gives off many branches in the neck, thorax, and abdomen.'),
('45f2910a-8b89-5df8-ad51-92f78040820b'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The recurrent laryngeal nerve (RLN) loops around:', '["The vertebral artery and its associated anatomical structures","The subclavian artery on the right and the aortic arch on the left (ascending in the tracheoesoph","The thyrocervical trunk and its associated anatomical structures","The IJV and its associated anatomical structures","The carotid artery and its associated anatomical structures"]'::jsonb, 'The subclavian artery on the right and the aortic arch on the left (ascending in the tracheoesoph', 'The RLN (a branch of CN X) supplies all the intrinsic laryngeal muscles (except the cricothyroid, supplied by the external laryngeal nerve).'),
('fd2d8a17-2d2c-5126-8387-2d47d335ab5d'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The superior laryngeal nerve (from CN X) divides into:', '["The recurrent laryngeal nerve and its associated anatomical structures","The internal laryngeal nerve (sensory to the supraglottic larynx) and the external laryngeal nerv","Only the external laryngeal nerve and its associated anatomical structures","The pharyngeal nerve and its associated anatomical structures","Only the internal laryngeal nerve and its associated anatomical structures"]'::jsonb, 'The internal laryngeal nerve (sensory to the supraglottic larynx) and the external laryngeal nerv', 'Injury to the external laryngeal nerve (a risk in thyroid surgery) causes a weak voice (inability to tense the vocal cords).'),
('e617cc8c-b09a-5d01-a388-e89eb7ed9813'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The superior cervical ganglion is:', '["The largest ganglion of the sympathetic trunk (at C2-C3, providing postganglionic sympathetic fib","At L1-L2 and its associated anatomical structures and its associated structures","At C7-T1 and its associated anatomical structures and its associated structures","At T2-T4 and its associated anatomical structures and its associated structures","At S2-S4 and its associated anatomical structures and its associated structures"]'::jsonb, 'The largest ganglion of the sympathetic trunk (at C2-C3, providing postganglionic sympathetic fib', 'The superior cervical ganglion (the ''head ganglion'') gives rise to the internal carotid nerve (sympathetic plexus).'),
('05c0dd63-a8de-5f15-8c69-6d2896a0f0ff'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Horner syndrome (from disruption of the cervical sympathetic chain) includes:', '["Exophthalmos and its associated anatomical structures","Ptosis, miosis, anhidrosis, and enophthalmos","Lid lag and its associated anatomical structures","Hyperhidrosis and its associated anatomical structures","Mydriasis and its associated anatomical structures"]'::jsonb, 'Ptosis, miosis, anhidrosis, and enophthalmos', 'Horner syndrome: interruption of the sympathetic supply to the head (ptosis = Muller muscle; miosis = dilator pupillae; anhidrosis = sweat glands).'),
('e5a2d216-7076-587d-8ac7-f8e42015dc78'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The sphenoid bone (the ''butterfly bone'') contains:', '["The sella turcica, the sphenoid sinus, the optic canals, the foramen rotundum, the foramen ovale","The sinuses only and its associated anatomical structures","The pituitary fossa only and its associated anatomical structures","The foramina only and its associated anatomical structures","The canals only and its associated anatomical structures"]'::jsonb, 'The sella turcica, the sphenoid sinus, the optic canals, the foramen rotundum, the foramen ovale', 'The sphenoid bone (the ''keystone'' of the skull) articulates with all the other cranial bones.'),
('e0b442bf-4a33-5aa5-b65d-3ae445d611f8'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The sella turcica (the ''Turkish saddle'') contains:', '["The cavernous sinus","The pituitary gland","The sphenoid sinus","The trigeminal ganglion","The optic chiasm"]'::jsonb, 'The pituitary gland', 'The sella turcica (the hypophyseal fossa) is located in the sphenoid bone, in the middle cranial fossa.'),
('996c5ba1-dd19-5223-b98d-5d68b206c9f7'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The anterior clinoid process is:', '["A part of the ethmoid bone and its associated anatomical structures","A part of the greater wing of the sphenoid and its associated anatomical structures","A part of the temporal bone and its associated anatomical structures","A bony projection from the lesser wing of the sphenoid (attaches the tentorium cerebelli and over","A part of the frontal bone and its associated anatomical structures"]'::jsonb, 'A bony projection from the lesser wing of the sphenoid (attaches the tentorium cerebelli and over', 'The anterior clinoid process (''clinoid'' = bedpost) is a surgical landmark for the ICA (the ICA is medial to it).'),
('00059338-36e9-57bb-9497-7a0edbadb6b9'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The posterior clinoid process is:', '["A part of the temporal bone","A part of the greater wing of the sphenoid","A bony projection from the dorsum sellae","A part of the occipital bone","A part of the lesser wing of the sphenoid"]'::jsonb, 'A bony projection from the dorsum sellae', 'The posterior clinoid processes (the ''bedposts'' of the sella) are at the posterior limit of the pituitary fossa.'),
('ee95700e-b3fc-5f5f-9ce5-8f9855ebdd1f'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The sphenoid sinus is divided by:', '["The ethmoid bone","The palatine bone","The maxilla","The vomer","A midline septum"]'::jsonb, 'A midline septum', 'The sphenoid sinus (an air sinus within the sphenoid bone) is related to the pituitary, the optic chiasm, and the ICA.'),
('625a7e6a-2291-540f-bd2d-0c716fc013db'::uuid, 'Anatomy (Paper 2)', 'Brain', 'Transsphenoidal surgery for pituitary tumors uses:', '["A maxillotomy and its associated anatomical structures","A submandibular approach and its associated anatomical structures","The transsphenoidal approach (through the nasal cavity, the sphenoid sinus","An orbital approach and its associated anatomical structures","A craniotomy and its associated anatomical structures"]'::jsonb, 'The transsphenoidal approach (through the nasal cavity, the sphenoid sinus', 'Transsphenoidal surgery (the ''endoscopic endonasal approach'') is the standard approach for pituitary adenomas.'),
('c402549a-10da-5033-8d22-ff4f8495a2c2'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The cribriform plate of the ethmoid bone:', '["A horizontal plate perforated by foramina for the olfactory nerves (CN I","The floor of the anterior cranial fossa and its associated anatomical structures","A part of the sphenoid bone and its associated anatomical structures","The roof of the nose and its associated anatomical structures","The wall of the orbit and its associated anatomical structures"]'::jsonb, 'A horizontal plate perforated by foramina for the olfactory nerves (CN I', 'The cribriform plate (a part of the ethmoid bone) is the weakest part of the skull base (fractures cause CSF rhinorrhea).'),
('c53c94cd-1133-521b-a9b6-d5e748c9424a'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The crista galli is:', '["A ridge of the frontal bone","A ridge of the temporal bone","A midline ridge of the ethmoid bone","A ridge of the occipital bone","A ridge of the sphenoid bone"]'::jsonb, 'A midline ridge of the ethmoid bone', 'The crista galli (the ''cock''s comb'') is a bony projection from the ethmoid bone (the attachment of the falx cerebri).'),
('810da0e3-9fa9-58c4-b7df-56c180388eea'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The olfactory bulb and tract lie on:', '["The temporal bone","The occipital bone","The cribriform plate","The sphenoid bone","The frontal bone"]'::jsonb, 'The cribriform plate', 'The olfactory bulb (a structure of the CNS, part of the brain) is located in the olfactory groove of the anterior cranial fossa.'),
('cd400709-01ac-56db-802e-e9c5c1cf21b0'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The optic chiasm is located above:', '["The clivus and its associated anatomical structures","The sella turcica (the pituitary fossa), in the suprasellar cistern","The cavernous sinus and its associated anatomical structures","The foramen magnum and its associated anatomical structures","The sphenoid sinus and its associated anatomical structures"]'::jsonb, 'The sella turcica (the pituitary fossa), in the suprasellar cistern', 'The optic chiasm (where the nasal optic fibers cross) is located 10-15 mm above the pituitary.'),
('fa4d6002-08e1-502b-8365-0b1c36301df7'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The circle of Willis is located:', '["In the sylvian fissure and its associated anatomical structures","In the interhemispheric fissure and its associated anatomical structures","In the suprasellar cistern (at the base of the brain, surrounding the optic chiasm and the pituit","In the cerebellopontine angle and its associated anatomical structures","In the quadrigeminal cistern and its associated anatomical structures"]'::jsonb, 'In the suprasellar cistern (at the base of the brain, surrounding the optic chiasm and the pituit', 'The circle of Willis (an anastomotic ring) connects the ICA and the vertebrobasilar systems.'),
('ab3da686-ed0b-5bda-96e4-12c22e8bb2d7'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The A1 segment of the ACA runs from:', '["The ICA to the MCA","The PCA to the posterior communicating artery","The basilar to the SCA","The ICA bifurcation to the anterior communicating artery","The ACom to the pericallosal artery"]'::jsonb, 'The ICA bifurcation to the anterior communicating artery', 'A1 (pre-communicating segment): hypoplasia is associated with ACom aneurysm.'),
('a8ae2dcd-5ccd-5ddd-b897-42d84c701865'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The M1 segment of the MCA runs from:', '["ACA to MCA junction and its associated anatomical structures","Sylvian fissure to the lateral cortex and its associated anatomical structures","PCA to MCA and its associated anatomical structures","ICA to ACA and its associated anatomical structures","The ICA bifurcation to the sylvian fissure (the ''horizontal'' segment, gives off the lenticulostri"]'::jsonb, 'The ICA bifurcation to the sylvian fissure (the ''horizontal'' segment, gives off the lenticulostri', 'M1 (sphenoidal segment) is the site of the first MCA bifurcation (the ''M1 bifurcation'' is a common site for aneurysms).'),
('4607efa1-53fa-5ad8-9aa1-baa3688697df'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The P1 segment of the PCA runs from:', '["The ACA to the PCA","The basilar bifurcation to the PCom","The PCom to the lateral cortex","The ICA to the PCA","The MCA to the PCA"]'::jsonb, 'The basilar bifurcation to the PCom', 'P1 (pre-communicating segment) connects the basilar artery to the posterior communicating artery.'),
('53c2d31d-10df-5806-85ef-8c507e83ac0b'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The ophthalmic artery arises from:', '["The external carotid artery and its associated anatomical structures","The middle meningeal artery and its associated anatomical structures","The maxillary artery and its associated anatomical structures","The ICA (just after it enters the cranium, above the cavernous sinus, in the region of the anteri","The facial artery and its associated anatomical structures"]'::jsonb, 'The ICA (just after it enters the cranium, above the cavernous sinus, in the region of the anteri', 'The ophthalmic artery (the first major branch of the ICA) enters the orbit through the optic canal, along with the optic nerve.'),
('b55c77f1-c57b-5974-a29e-488715586d78'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The ophthalmic artery gives off:', '["The anterior choroidal artery and its associated anatomical structures","Only the ciliary arteries and its associated anatomical structures","The central retinal artery (the end artery of the retina), the lacrimal artery","Only the lacrimal artery and its associated anatomical structures","Only the central retinal artery and its associated anatomical structures"]'::jsonb, 'The central retinal artery (the end artery of the retina), the lacrimal artery', 'The central retinal artery (a branch of the ophthalmic artery) is the only blood supply to the retina (retinal artery occlusion causes blindness).'),
('5405ae36-2b83-5dbd-9eef-b87c8d4b1520'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The anterior choroidal artery arises from:', '["The PCA and its associated anatomical structures","The ICA (just distal to the PCom, supplying the choroid plexus, the optic tract","The basilar artery and its associated anatomical structures","The ACA and its associated anatomical structures","The MCA and its associated anatomical structures"]'::jsonb, 'The ICA (just distal to the PCom, supplying the choroid plexus, the optic tract', 'The anterior choroidal artery (a small but important branch) supplies the choroid plexus of the lateral ventricle and the posterior limb of the internal capsule.'),
('958f82cf-117d-5ceb-8393-29bb5a228016'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The posterior communicating artery (PCom) connects:', '["The ACA and the MCA","The ICA and the ACA","The ICA and the PCA","The basilar and the PCA","The MCA and the PCA"]'::jsonb, 'The ICA and the PCA', 'The PCom (the posterior communicating artery) is a common site for aneurysms (presents with CN III palsy).'),
('8b063e53-1187-5f88-b4bc-44eb2daee48f'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The labyrinthine artery (the internal auditory artery) arises from:', '["The SCA and its associated anatomical structures","The PICA and its associated anatomical structures","The AICA (a branch of the basilar artery), supplying the inner ear","The basilar artery directly and its associated anatomical structures","The PCA and its associated anatomical structures"]'::jsonb, 'The AICA (a branch of the basilar artery), supplying the inner ear', 'The labyrinthine artery (the ''auditory artery'') is an end artery. Occlusion causes sudden hearing loss and vertigo.'),
('c43bd031-000f-5ba6-be10-44ae14a59129'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The pontine arteries (paramedian, short circumferential, and long circumferential):', '["From the vertebral artery and its associated anatomical structures","From the PCA and its associated anatomical structures","From the SCA and its associated anatomical structures","Small branches from the basilar artery that supply the pons (paramedian: medial pons","From the AICA and its associated anatomical structures"]'::jsonb, 'Small branches from the basilar artery that supply the pons (paramedian: medial pons', 'Lacunar strokes in the pons (from small vessel disease/HTN) can cause ''pure motor stroke'' or ''ataxic hemiparesis''.'),
('d29b1cb6-d128-5abb-b560-1394f0f66cd8'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The superior medullary velum is:', '["A thin layer of white matter between the superior cerebellar peduncles (forming the roof of the 4","A part of the midbrain and its associated anatomical structures","A part of the medulla and its associated anatomical structures","A part of the pons and its associated anatomical structures","A part of the cerebellum and its associated anatomical structures"]'::jsonb, 'A thin layer of white matter between the superior cerebellar peduncles (forming the roof of the 4', 'The superior medullary velum (the ''anterior medullary velum'') contains the lingula of the cerebellum.'),
('9efe6dff-d0d3-5bab-94f8-400aca66dd6a'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The inferior medullary velum is:', '["A part of the superior cerebellar peduncle and its associated anatomical structures","A part of the middle cerebellar peduncle and its associated anatomical structures","A part of the medulla and its associated anatomical structures","A part of the inferior cerebellar peduncle and its associated anatomical structures","A thin layer of white matter attached to the nodule of the cerebellum (forming part of the roof o"]'::jsonb, 'A thin layer of white matter attached to the nodule of the cerebellum (forming part of the roof o', 'The inferior medullary velum (the ''posterior medullary velum'') contains the choroid plexus of the 4th ventricle.'),
('8da547aa-6efa-51c0-8245-ccb3e8fb3689'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The tela choroidea of the 4th ventricle:', '["The lining of the 4th ventricle and its associated anatomical structures","A thin membrane (pia + ependyma) in the roof of the 4th ventricle that gives rise to the choroid","The wall of the 4th ventricle and its associated anatomical structures","The floor of the 4th ventricle and its associated anatomical structures","The outflow of the 4th ventricle and its associated anatomical structures"]'::jsonb, 'A thin membrane (pia + ependyma) in the roof of the 4th ventricle that gives rise to the choroid', 'The tela choroidea (''the choroid web'') of the 4th ventricle is attached to the inferior medullary velum and forms the choroid plexus.'),
('0def2015-0b1c-5d2c-a7ee-b27d18f86945'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The rhomboid fossa (the floor of the 4th ventricle):', '["The central canal of the spinal cord and its associated anatomical structures","The aqueduct and its associated anatomical structures","A diamond-shaped area on the dorsal surface of the pons and the medulla (contains the cranial ner","The wall of the 4th ventricle and its associated anatomical structures","The roof of the 4th ventricle and its associated anatomical structures"]'::jsonb, 'A diamond-shaped area on the dorsal surface of the pons and the medulla (contains the cranial ner', 'The rhomboid fossa (the ''diamond-shaped'' floor of the 4th ventricle) is formed by the pons (upper half) and the medulla (lower half).'),
('8cc59241-a8e3-5c21-8ad1-2627fbcf27c9'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The facial colliculus is:', '["The CN VII nucleus and its associated anatomical structures","The CN VIII nucleus and its associated anatomical structures","The CN VI nucleus and its associated anatomical structures","The CN V nucleus and its associated anatomical structures","An elevation in the floor of the 4th ventricle (produced by the CN VI nucleus and the fibers of C"]'::jsonb, 'An elevation in the floor of the 4th ventricle (produced by the CN VI nucleus and the fibers of C', 'The facial colliculus (at the pontine level of the rhomboid fossa) is a key landmark. Compression causes CN VI and CN VII palsy.'),
('4229da19-cef8-5e7e-af18-5b3dd22ea285'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The hypoglossal trigone is:', '["An elevation in the floor of the 4th ventricle","The CN IX nucleus and its associated anatomical structures","The CN X nucleus and its associated anatomical structures","The CN XII nucleus and its associated anatomical structures","The CN XI nucleus and its associated anatomical structures"]'::jsonb, 'An elevation in the floor of the 4th ventricle', 'The hypoglossal trigone (the ''tongue triangle'') is located in the medullary part of the rhomboid fossa.'),
('e88b28c7-d694-50d1-94f2-9eadb06d7ca1'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The vagal trigone is:', '["The CN X nucleus and its associated anatomical structures","The CN XII nucleus and its associated anatomical structures","The CN XI nucleus and its associated anatomical structures","An elevation in the floor of the 4th ventricle (overlies the dorsal motor nucleus of the vagus ne","The CN IX nucleus and its associated anatomical structures"]'::jsonb, 'An elevation in the floor of the 4th ventricle (overlies the dorsal motor nucleus of the vagus ne', 'The vagal trigone (the ''vagus triangle'') is located lateral to the hypoglossal trigone in the medulla.'),
('b585f932-9531-5dff-abb0-2a5ccdf8be11'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The obex is:', '["The lateral angle of the rhomboid fossa and its associated anatomical structures","The floor of the 4th ventricle and its associated anatomical structures","The roof of the 4th ventricle and its associated anatomical structures","The caudal angle of the rhomboid fossa (the apex of the 4th ventricle, continuous with the centra","The rostral angle of the rhomboid fossa and its associated anatomical structures"]'::jsonb, 'The caudal angle of the rhomboid fossa (the apex of the 4th ventricle, continuous with the centra', 'The obex (the ''stopper'' or ''barrier'') is the constriction where the 4th ventricle narrows to become the central canal of the spinal cord.'),
('505a13ef-10cf-5121-b53f-0e6024eaf5e7'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The Luschka foramina (lateral apertures) open into:', '["The suprasellar cistern","The ambient cistern","The cisterna magna","The cerebellopontine angle","The quadrigeminal cistern"]'::jsonb, 'The cerebellopontine angle', 'The foramina of Luschka (paired) are located at the lateral recesses of the 4th ventricle.'),
('24e7aa87-31c9-544b-8fd3-700a2de5b38c'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The foramen of Magendie (median aperture) opens into:', '["The ambient cistern","The quadrigeminal cistern","The suprasellar cistern","The cisterna magna","The cerebellopontine angle"]'::jsonb, 'The cisterna magna', 'The foramen of Magendie (the median aperture of the 4th ventricle) is located at the caudal end of the roof of the 4th ventricle.'),
('4e7da9a3-6c83-530b-bda9-833f76571c64'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The quadrigeminal cistern (cisterna ambiens) contains:', '["The vertebral artery and its associated anatomical structures","The basilar artery and its associated anatomical structures","The ICA and its associated anatomical structures","The MCA and its associated anatomical structures","The great cerebral vein (of Galen), the PCA, and the SCA (located between the splenium of the cor"]'::jsonb, 'The great cerebral vein (of Galen), the PCA, and the SCA (located between the splenium of the cor', 'The quadrigeminal cistern (the ''ambient cistern'') surrounds the midbrain and contains the basal vein of Rosenthal.'),
('933e2233-7c25-59e1-8595-8f0273c097ad'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The cerebellomedullary cistern (cisterna magna) is located:', '["In the interhemispheric fissure and its associated anatomical structures","Between the cerebellum and the medulla (below the foramen of Magendie, the largest subarachnoid c","Above the cerebellum and its associated anatomical structures","At the base of the brain and its associated anatomical structures","In the sylvian fissure and its associated anatomical structures"]'::jsonb, 'Between the cerebellum and the medulla (below the foramen of Magendie, the largest subarachnoid c', 'The cisterna magna (the ''great cistern'') can be accessed for CSF collection (cisternal puncture) or for posterior fossa surgery.'),
('22271367-e07f-52e9-aaaf-d2e0bea54bfc'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The subarachnoid cisterns include:', '["Cisterna magna, prepontine cistern, quadrigeminal cistern, ambient cistern, suprasellar cistern","Only the cerebellopontine angle cistern and its associated anatomical structures","Only the cisterna magna and the prepontine cistern and its associated anatomical structures","Only the quadrigeminal and ambient cisterns and its associated anatomical structures","Only the suprasellar and sylvian cisterns and its associated anatomical structures"]'::jsonb, 'Cisterna magna, prepontine cistern, quadrigeminal cistern, ambient cistern, suprasellar cistern', 'The subarachnoid cisterns (widened areas of the subarachnoid space) contain the major cerebral arteries and cranial nerves.'),
('3f1590fb-0b31-585c-95e7-084991ccb6bf'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The prepontine cistern contains:', '["The basilar artery","The MCA","The vertebral artery","The ICA","The ACA"]'::jsonb, 'The basilar artery', 'The prepontine cistern (anterior to the pons) communicates with the cerebellopontine angle cistern.'),
('8d0c9f3b-2607-5350-b4f7-eb2de895cc80'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The suprasellar cistern contains:', '["The vertebral artery and its associated anatomical structures","The circle of Willis, the optic chiasm, and the pituitary stalk","The MCA and its associated anatomical structures","The ACA and its associated anatomical structures","The basilar artery and its associated anatomical structures"]'::jsonb, 'The circle of Willis, the optic chiasm, and the pituitary stalk', 'The suprasellar cistern (the ''chiasmatic cistern'') is located above the sella turcica, around the optic chiasm.'),
('83a3318d-7040-54ad-a015-323f46139b4c'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The sylvian cistern (the cistern of the lateral sulcus) contains:', '["The basilar artery","The ACA","The MCA","The PCA","The ICA"]'::jsonb, 'The MCA', 'The sylvian cistern (in the sylvian fissure) is the space around the MCA.'),
('d8208a43-8ef1-5780-99d9-346ac8fd086b'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The ambient cistern (the ''wing'' of the ambient cistern) contains:', '["The ICA and its associated structures","The ACA and its associated structures","The basilar artery and its associated structures","The MCA and its associated structures","The basal vein of Rosenthal and the PCA"]'::jsonb, 'The basal vein of Rosenthal and the PCA', 'The ambient cistern (the lateral extension of the quadrigeminal cistern) is located around the midbrain.'),
('a389c2b5-5f51-5960-b71f-b2e764a25432'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The circumflex branches of the PCA supply:', '["The cerebellum","The internal capsule","The occipital lobe","The thalamus","The midbrain"]'::jsonb, 'The midbrain', 'The thalamoperforating arteries (from the P1 segment of the PCA) supply the thalamus and the midbrain.'),
('19a7ba88-d889-57d9-bf1d-e09c4249dbee'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The artery of Percheron is:', '["A single thalamoperforating artery (from the P1 segment of the PCA) that supplies both thalami (o","A vertebral branch and its associated anatomical structures","A ACA branch and its associated anatomical structures","A MCA branch and its associated anatomical structures","A basilar branch and its associated anatomical structures"]'::jsonb, 'A single thalamoperforating artery (from the P1 segment of the PCA) that supplies both thalami (o', 'Artery of Percheron (an anatomical variant): occlusion causes bilateral paramedian thalamic infarction (altered consciousness, memory loss).'),
('0ed8d743-5430-5d58-9cde-f24ae60a825d'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The Heubner artery (recurrent artery of Heubner) supplies:', '["The head of the caudate nucleus and the anterior limb of the internal capsule (a medial lenticulo","The globus pallidus and its associated anatomical structures","The cerebral cortex and its associated anatomical structures","The thalamus and its associated anatomical structures","The putamen and its associated anatomical structures"]'::jsonb, 'The head of the caudate nucleus and the anterior limb of the internal capsule (a medial lenticulo', 'Heubner artery occlusion causes contralateral faciobrachial weakness (supplying the anterior limb of the internal capsule).'),
('cfc89f3c-3bd8-5b12-ba20-486f347ae091'::uuid, 'Anatomy (Paper 2)', 'Brain', 'The medial and lateral lenticulostriate arteries supply:', '["The striatum (caudate and putamen), the globus pallidus, and the internal capsule (the ''Charcot a","The thalamus and its associated anatomical structures","The cerebral cortex and its associated anatomical structures","The hippocampus and its associated anatomical structures","The cerebellum and its associated anatomical structures"]'::jsonb, 'The striatum (caudate and putamen), the globus pallidus, and the internal capsule (the ''Charcot a', 'The lenticulostriate arteries (the ''arteries of the basal ganglia'') are the most common site of hypertensive intracerebral hemorrhage.'),
('ce19794c-de28-511d-8607-bec8b9cd063e'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The vertebral column consists of:', '["33 vertebrae","36 vertebrae","24 vertebrae","26 vertebrae","30 vertebrae"]'::jsonb, '33 vertebrae', 'The spine (the ''backbone'') is divided into the cervical, thoracic, lumbar, sacral, and coccygeal regions.'),
('da597221-b882-5ba9-8fa8-8ae28abbffcb'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The typical vertebra consists of:', '["Only the vertebral arch","Body, vertebral arch (pedicles, laminae), and 7 processes","Body and transverse processes only","Body and spinous process only","Body and vertebral arch only"]'::jsonb, 'Body, vertebral arch (pedicles, laminae), and 7 processes', 'The vertebral arch (formed by the 2 pedicles and 2 laminae) encloses the vertebral foramen.'),
('dfa7d1a9-923f-5ff6-92bc-c65321504815'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The vertebral foramen contains:', '["The vertebral vessels and its associated anatomical structures","The spinal cord (the cauda equina below L1-L2) and the meninges","The intervertebral discs and its associated anatomical structures","The sympathetic trunk and its associated anatomical structures","The spinal nerves and its associated anatomical structures"]'::jsonb, 'The spinal cord (the cauda equina below L1-L2) and the meninges', 'The vertebral canal (spinal canal) is formed by the sum of the vertebral foramina.'),
('b7fda4b3-b2e9-5224-98f0-00052ff13ea5'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The intervertebral foramen transmits:', '["The spinal nerve root and the radicular vessels","The vertebral artery and its associated anatomical structures","The cauda equina and its associated anatomical structures","The spinal cord and its associated anatomical structures","The spinal artery and its associated anatomical structures"]'::jsonb, 'The spinal nerve root and the radicular vessels', 'The intervertebral foramen (IVF) is bounded by the pedicles (superior and inferior), the disc (anterior), and the facet joint (posterior).'),
('e376b29f-e504-56af-85d3-9e9023f950bb'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The intervertebral discs constitute:', '["25% of the total height of the vertebral column","50% and its associated anatomical structures","10% and its associated anatomical structures","75% and its associated anatomical structures","5% and its associated anatomical structures"]'::jsonb, '25% of the total height of the vertebral column', 'The intervertebral discs (the ''shock absorbers'' of the spine) are composed of the annulus fibrosus and the nucleus pulposus.'),
('f40c4cfe-f241-5fe6-b0ca-3d7e172f67fe'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The annulus fibrosus is:', '["The hyaline cartilage endplate and its associated anatomical structures","The ligament and its associated anatomical structures","The outer, fibrous ring of the intervertebral disc (composed of concentric lamellae of collagen f","The vertebral body and its associated anatomical structures","The inner gelatinous core and its associated anatomical structures"]'::jsonb, 'The outer, fibrous ring of the intervertebral disc (composed of concentric lamellae of collagen f', 'The annulus (a ''ring'' of fibrocartilage) resists tensile and torsional forces. It is innervated (pain in discogenic back pain).'),
('89824f63-6ef5-528a-a2ca-2c96e414fc14'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The nucleus pulposus is:', '["The spinal nerve and its associated anatomical structures","The hyaline cartilage endplate and its associated anatomical structures","The outer fibrous ring and its associated anatomical structures","The vertebral body and its associated anatomical structures","The central, gelatinous core of the intervertebral disc (a remnant of the notochord"]'::jsonb, 'The central, gelatinous core of the intervertebral disc (a remnant of the notochord', 'The nucleus pulposus (80-90% water at birth) dehydrates with age. Disc herniation (prolapse) is the displacement of the nucleus pulposus through a tear in the annulus.'),
('6a82e017-619a-5613-9b21-c716302c5ecb'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The most common site of lumbar disc herniation is:', '["L2-L3","L3-L4","T12-L1","L1-L2","L4-L5 and L5-S1"]'::jsonb, 'L4-L5 and L5-S1', 'L4-L5 (L5 nerve root compression) and L5-S1 (S1 nerve root compression) are the most common levels.'),
('15fd19bc-7f1f-508d-86b3-1d9d188529cd'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The spinal curvatures (primary and secondary):', '["Primary (thoracic and sacral, present at birth) and secondary (cervical and lumbar","Only the cervical and thoracic and its associated anatomical structures","All develop after birth and its associated anatomical structures","All are present at birth and its associated anatomical structures","Only the lumbar and sacral and its associated anatomical structures"]'::jsonb, 'Primary (thoracic and sacral, present at birth) and secondary (cervical and lumbar', 'The primary curves (kyphotic) are present at birth. The secondary curves (lordotic) develop postnatally.'),
('4cd8bfe1-0634-5182-a440-0862444cab96'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'Cervical lordosis develops at:', '["6-9 months","At birth","3-4 months of age","12-18 months","2-3 years"]'::jsonb, '3-4 months of age', 'Cervical lordosis (the ''reversal'' of the fetal kyphosis) is maintained by the intervertebral discs and the muscles.'),
('97469684-c26d-54b3-a495-6c42a76feace'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'Lumbar lordosis develops at:', '["3-4 months","2-3 years","6-9 months","At birth","12-18 months of age"]'::jsonb, '12-18 months of age', 'Lumbar lordosis (the anterior convexity of the lumbar spine) varies between individuals (more pronounced in females).'),
('d2a8f680-d344-5c0c-b63f-577e0b7eb4b7'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The primary curves (kyphotic) are:', '["The thoracic and sacral curves","The lumbar and sacral","All four curves","The cervical and lumbar curves","The cervical and thoracic"]'::jsonb, 'The thoracic and sacral curves', 'The thoracic kyphosis (20-40 degrees) and the sacral kyphosis are the ''residual'' fetal curves.'),
('67b810df-a10d-5c0f-9f78-28a90b289992'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The secondary curves (lordotic) are:', '["The cervical and thoracic","The lumbar and sacral","The cervical and lumbar curves","The thoracic and sacral curves","All four curves"]'::jsonb, 'The cervical and lumbar curves', 'The cervical lordosis (20-40 degrees) and the lumbar lordosis (40-60 degrees) are ''acquired'' curves.'),
('07fa544d-156d-5abb-9086-ec7dba8934af'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The vertebral body (typical):', '["The posterior part and its associated anatomical structures","The transverse process and its associated anatomical structures","The anterior, weight-bearing part of the vertebra","The spinous process and its associated anatomical structures","The lateral part and its associated anatomical structures"]'::jsonb, 'The anterior, weight-bearing part of the vertebra', 'The vertebral body (the ''centrum'') is the largest and strongest part of the vertebra. It is composed of cancellous bone (red bone marrow).'),
('d96fad23-7daa-55b3-9074-1d905890900e'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The pedicles of the vertebra:', '["Connect the laminae to the spinous process","Connect the vertebral body to the transverse processes","Attach the muscles","Form the intervertebral foramen","Form the facet joints"]'::jsonb, 'Connect the vertebral body to the transverse processes', 'The pedicles (the ''little feet'') are the strongest part of the vertebra (used for pedicle screw fixation).'),
('de99839b-b4ef-5626-a83d-70cfbe397f48'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The laminae of the vertebra:', '["Connect the body to the pedicles and its associated anatomical structures","Form the intervertebral foramen and its associated anatomical structures","Form the facet joints and its associated anatomical structures","Attach the paraspinal muscles and its associated anatomical structures","Connect the transverse processes to the spinous process (form the posterior wall of the vertebral"]'::jsonb, 'Connect the transverse processes to the spinous process (form the posterior wall of the vertebral', 'The laminae (the ''flat plates'') are the posterior part of the vertebral arch. The ligamentum flavum connects adjacent laminae.'),
('d7802bbf-14c6-5ec0-a51b-39149520e0c3'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The transverse processes of the vertebra:', '["Project superiorly and its associated anatomical structures","Project inferiorly and its associated anatomical structures","Project posteriorly and its associated anatomical structures","Project anteriorly and its associated anatomical structures","Project laterally from the junction of the pedicles and the laminae (attach the paraspinal muscle"]'::jsonb, 'Project laterally from the junction of the pedicles and the laminae (attach the paraspinal muscle', 'The transverse processes (the ''lateral processes'') are the attachment points for the intertransverse ligaments and the deep back muscles.'),
('21e6fe65-b3b1-53f4-93b8-4933c1ea8557'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The spinous process of the vertebra:', '["Projects laterally and its associated anatomical structures","Projects inferiorly and its associated anatomical structures","Projects posteriorly from the junction of the two laminae","Projects anteriorly and its associated anatomical structures","Projects superiorly and its associated anatomical structures"]'::jsonb, 'Projects posteriorly from the junction of the two laminae', 'The spinous processes (palpable as ''bumps'' in the midline) are the attachment points for the supraspinous and interspinous ligaments.'),
('2224256a-637f-51d2-ac6d-41fde94df067'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The superior and inferior articular processes:', '["Form the intervertebral foramen and its associated anatomical structures","Attach the paraspinal muscles and its associated anatomical structures","Form the zygapophyseal (facet) joints between adjacent vertebrae (synovial joints","Attach the ribs and its associated anatomical structures","Attach the vertebral arch to the body and its associated anatomical structures"]'::jsonb, 'Form the zygapophyseal (facet) joints between adjacent vertebrae (synovial joints', 'The facet joints (the ''zygapophyseal joints'') are innervated by the medial branches of the dorsal primary rami (pain in facet syndrome).'),
('b946c40e-0a98-5ae8-9e80-8241d9301801'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The cervical vertebrae (C3-C6, typical) are characterized by:', '["A small body, a transverse foramen (for the vertebral artery), and a bifid spinous process","A large body and its associated anatomical structures","No transverse foramen and its associated anatomical structures","A large spinous process and its associated anatomical structures","No facet joints and its associated anatomical structures"]'::jsonb, 'A small body, a transverse foramen (for the vertebral artery), and a bifid spinous process', 'Cervical vertebrae (the smallest) have a triangular vertebral foramen and a foramen transversarium for the vertebral artery.'),
('9f231d56-0fd3-5633-ac6a-195ad9f2b033'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The transverse foramen (foramen transversarium) of the cervical vertebrae transmits:', '["The spinal nerve and its associated anatomical structures","The vertebral artery, the vertebral vein, and the sympathetic plexus","The vagus nerve and its associated anatomical structures","The internal jugular vein and its associated anatomical structures","The carotid artery and its associated anatomical structures"]'::jsonb, 'The vertebral artery, the vertebral vein, and the sympathetic plexus', 'The vertebral artery (from the subclavian) ascends through the transverse foramina of C6-C1. It does NOT pass through C7.'),
('ebe1d1ee-c813-54a4-a76c-1e5d86a88e1d'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The Atlas (C1) is unique because:', '["It has a large body","It has a transverse foramen only","It has no body and no spinous process","It has no transverse processes","It has a long spinous process"]'::jsonb, 'It has no body and no spinous process', 'The Atlas (C1, named after the Titan Atlas) supports the skull. It has 2 lateral masses and 2 arches.'),
('e7296fb5-3967-59f1-bf42-6800ef84077e'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The anterior arch of the Atlas has:', '["A transverse foramen and its associated anatomical structures","A facet for the dens of the Axis (the odontoid process) and a tubercle for the anterior longitudi","A vertebral foramen and its associated anatomical structures","A facet for the occipital condyles and its associated anatomical structures","A spinous process and its associated anatomical structures"]'::jsonb, 'A facet for the dens of the Axis (the odontoid process) and a tubercle for the anterior longitudi', 'The atlas (C1) articulates with the dens (the ''odontoid process'') of the axis (C2) at the atlantoaxial joint.'),
('cb16c983-7575-5626-8b97-8652cd4053df'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The posterior arch of the Atlas has:', '["A transverse foramen","A spinous process","A groove for the vertebral artery","A facet for the occipital condyles","A dens"]'::jsonb, 'A groove for the vertebral artery', 'The groove for the vertebral artery (the ''sulcus arteriae vertebralis'') on the posterior arch of C1 is an important landmark.'),
('64efe359-778d-53ee-a92c-beba409f8ed2'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The Axis (C2) is characterized by:', '["A bifid spinous process only and its associated anatomical structures","A transverse process only and its associated anatomical structures","The dens (odontoid process) projecting superiorly from the body (the ''pivot'' for the rotation of","A large body only and its associated anatomical structures","A long spinous process only and its associated anatomical structures"]'::jsonb, 'The dens (odontoid process) projecting superiorly from the body (the ''pivot'' for the rotation of', 'The dens (the ''tooth'' of the axis) is a remnant of the body of the atlas. Fracture of the dens (a ''hangman fracture'') is an unstable injury.'),
('472727b1-967b-5996-8abf-66a7e8c72671'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The atlanto-occipital joint is:', '["A pivot joint and its associated anatomical structures","A hinge joint and its associated anatomical structures","A ball-and-socket joint and its associated anatomical structures","A condylar synovial joint (the occipital condyles articulate with the superior facets of the Atla","A saddle joint and its associated anatomical structures"]'::jsonb, 'A condylar synovial joint (the occipital condyles articulate with the superior facets of the Atla', 'The atlanto-occipital joint (C0-C1) allows flexion/extension (''yes'' nodding). The ''no'' rotation occurs at the atlantoaxial joint (C1-C2).'),
('517ea2d7-3638-50a6-8adb-8a22099e6fc4'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The atlantoaxial joint (C1-C2) is:', '["A pivot joint (the dens of the Axis articulates with the anterior arch of the Atlas - rotation (''","A hinge joint and its associated anatomical structures","A condylar joint and its associated anatomical structures","A plane joint and its associated anatomical structures","A saddle joint and its associated anatomical structures"]'::jsonb, 'A pivot joint (the dens of the Axis articulates with the anterior arch of the Atlas - rotation (''', 'The atlantoaxial joint (the ''pivot'' of the neck) allows 50% of the cervical rotation (the ''no'' movement).'),
('54d67ac9-4025-5dcf-bbe3-3bc2a3cd91de'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'Regarding clinical scenarios, The transverse ligament of the Atlas:', '["Connects the transverse processes and its associated anatomical structures","Connects the spinous processes and its associated anatomical structures","Connects the axis to the atlas and its associated anatomical structures","Holds the dens of the Axis against the anterior arch of the Atlas (preventing posterior displacem","Connects the atlas to the occiput and its associated anatomical structures"]'::jsonb, 'Holds the dens of the Axis against the anterior arch of the Atlas (preventing posterior displacem', 'The transverse atlantal ligament (a thick band) is the strongest ligament of the atlantoaxial complex. Rupture can cause odontoid instability.'),
('92f7226e-7ba2-5c01-a686-6967e90c5996'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'In a surgical context, The alar ligaments:', '["Connect the atlas to the occiput and its associated anatomical structures","Connect the dens to the occipital condyles (limit rotation and side-bending of the head at the at","Connect the spinous processes and its associated anatomical structures","Connect the atlas to the axis and its associated anatomical structures","Connect the axis to the occiput and its associated anatomical structures"]'::jsonb, 'Connect the dens to the occipital condyles (limit rotation and side-bending of the head at the at', 'The alar ligaments (''the ''check ligaments'' of the dens'') are the secondary restraints to rotation. They are assessed in the ''alar ligament test''.'),
('05e5a685-b474-5987-a2ec-4eb63323653c'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'On diagnostic evaluation, The apical ligament of the dens:', '["Connects the axis to the atlas and its associated anatomical structures","Connects the tip of the dens to the occipital bone (a small, weak ligament - a remnant of the not","Connects the dens to the anterior arch of the atlas and its associated anatomical structures","Connects the dens to the posterior arch of the atlas and its associated anatomical structures","Connects the dens to the transverse ligament and its associated anatomical structures"]'::jsonb, 'Connects the tip of the dens to the occipital bone (a small, weak ligament - a remnant of the not', 'The apical ligament (a ''vestigial'' structure) is not clinically significant (a remnant of the notochord).'),
('86f5f55d-23ec-56c0-acb3-a922b9e68dcd'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'Regarding the anatomical aspect, With respect to management, The tectorial membrane:', '["A ligament between the atlas and the occiput and its associated anatomical structures","A ligament of the spinal canal and its associated anatomical structures","A ligament between the atlas and the axis and its associated anatomical structures","The upward continuation of the posterior longitudinal ligament (from the axis to the occipital bone","A ligament between the axis and the occiput and its associated anatomical structures"]'::jsonb, 'The upward continuation of the posterior longitudinal ligament (from the axis to the occipital bone', 'The tectorial membrane (the ''membrana tectoria'') is the deep layer of the dura-posterior longitudinal ligament complex.'),
('77db0bf0-18ac-5017-9171-0bfe548fa9ca'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The cruciform ligament of the atlas:', '["The transverse atlantal ligament (the horizontal bar) + the superior and inferior bands (the vert","A ligament that connects the atlas to the occiput and its associated anatomical structures","A ligament that connects the dens to the atlas and its associated anatomical structures","A ligament that connects the axis to the atlas and its associated anatomical structures","A ligament of the spinal canal and its associated anatomical structures"]'::jsonb, 'The transverse atlantal ligament (the horizontal bar) + the superior and inferior bands (the vert', 'The cruciform ligament (the ''cross-shaped'' ligament) is composed of the transverse ligament and the longitudinal bands (the ''vertical'' part).'),
('99f29751-823c-5b72-ad8b-b15faf667738'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The thoracic vertebrae (T1-T12) are characterized by:', '["A large vertebral foramen","A small body and no costal facets","A large body and a short spinous process","Heart-shaped body, costal facets (for the ribs), a long spinous process, and a small","A small body, a bifid spinous process, and a transverse foramen"]'::jsonb, 'Heart-shaped body, costal facets (for the ribs), a long spinous process, and a small', 'Thoracic vertebrae have facets for the ribs (costal facets) on the body (T1-T10) and the transverse processes (T1-T10).'),
('5755b11c-09f7-5da0-8596-9a794c24020c'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The costal facets on the thoracic vertebrae articulate with:', '["The necks of the ribs","The heads of the ribs","The angles of the ribs","The shafts of the ribs","The tubercles of the ribs"]'::jsonb, 'The heads of the ribs', 'The costovertebral joint (the joint of the head of the rib) is a synovial joint between the rib head and the vertebral body.'),
('d6213c4b-96fe-56d2-a214-f88c0330d1d3'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The costotransverse joint is:', '["The articulation between the two adjacent ribs","The articulation between the rib head and the vertebral body","The articulation between the costal facet on the transverse process and the tubercle of the rib (","The articulation between the rib angle and the transverse process","The articulation between the rib neck and the transverse process"]'::jsonb, 'The articulation between the costal facet on the transverse process and the tubercle of the rib (', 'The costotransverse joint (at the neck of the rib) is stabilized by the costotransverse ligaments.'),
('e21ff91b-4af1-55c6-8cb9-85ee9e2edbb9'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The lumbar vertebrae (L1-L5) are characterized by:', '["A small body and a transverse foramen and its associated anatomical structures","A large, kidney-shaped body, a triangular vertebral foramen, short transverse processes","A large body and a long spinous process and its associated anatomical structures","A heart-shaped body and costal facets and its associated anatomical structures","A small body and a bifid spinous process and its associated anatomical structures"]'::jsonb, 'A large, kidney-shaped body, a triangular vertebral foramen, short transverse processes', 'Lumbar vertebrae (the largest) bear the most weight. The transverse processes (the ''costal processes'') are the homologs of the ribs.'),
('7092a75c-a5df-5129-80bb-facca7c5931e'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The mamillary processes of the lumbar vertebrae are:', '["The spinous processes and its associated anatomical structures","Small tubercles on the posterior aspect of the superior articular processes (attachment for the m","The accessory processes and its associated anatomical structures","The transverse processes and its associated anatomical structures","The pars interarticularis and its associated anatomical structures"]'::jsonb, 'Small tubercles on the posterior aspect of the superior articular processes (attachment for the m', 'Mamillary processes (''nipple-like'') are unique to the lumbar vertebrae (they are the attachment of the lumbar multifidus).'),
('48005619-89db-5b7f-b649-6a38a3e180d8'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The accessory processes of the lumbar vertebrae are:', '["The spinous processes and its associated anatomical structures","The pars interarticularis and its associated anatomical structures","Small tubercles on the posterior aspect of the base of the transverse processes (attachment of th","The transverse processes and its associated anatomical structures","The mamillary processes and its associated anatomical structures"]'::jsonb, 'Small tubercles on the posterior aspect of the base of the transverse processes (attachment of th', 'Accessory processes (''extra processes'') are found on the lumbar vertebrae (may be palpable in thin individuals).'),
('ff4c6759-6413-5fbf-8ce9-15993b3058f4'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The pars interarticularis of the lumbar vertebra is:', '["The part of the lamina between the superior and the inferior articular processes (the ''isthmus'' o","The transverse process and its associated anatomical structures","The vertebral body and its associated anatomical structures","The spinous process and its associated anatomical structures","The pedicle and its associated anatomical structures"]'::jsonb, 'The part of the lamina between the superior and the inferior articular processes (the ''isthmus'' o', 'The pars interarticularis (the ''isthmus'') is the site of spondylolysis (a stress fracture, common in gymnasts and weightlifters).'),
('2a23b4c5-1f81-5563-bdea-4b0cf1e117b1'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'Spondylolysis is:', '["A spinal tumor and its associated anatomical structures","A herniated disc and its associated anatomical structures","A defect (fracture) of the pars interarticularis (often L5, usually due to repetitive hyperextens","A vertebral fracture and its associated anatomical structures","A dislocation of the facet joint and its associated anatomical structures"]'::jsonb, 'A defect (fracture) of the pars interarticularis (often L5, usually due to repetitive hyperextens', 'Spondylolysis (a ''pars defect'') is a common cause of low back pain in adolescents. Spondylolisthesis is the forward slippage of the vertebra above.'),
('e36f74d0-f1f1-5748-a34e-adba5604546f'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'Spondylolisthesis is:', '["A fracture of the transverse process and its associated anatomical structures","A spinal stenosis and its associated anatomical structures","A herniated disc and its associated anatomical structures","The forward (or backward) slippage of one vertebra over the one below","A dislocation of the spine and its associated anatomical structures"]'::jsonb, 'The forward (or backward) slippage of one vertebra over the one below', 'Spondylolisthesis (graded I-IV) may cause nerve root compression (radiculopathy) and neurogenic claudication.'),
('06645dc7-b20f-5dca-8535-7607f5f720a9'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The sacrum is formed by:', '["The fusion of 7 sacral vertebrae and its associated anatomical structures","A single bone and its associated anatomical structures","The fusion of 4 sacral vertebrae and its associated anatomical structures","The fusion of 5 sacral vertebrae (S1-S5) at 18-25 years of age","The fusion of 3 sacral vertebrae and its associated anatomical structures"]'::jsonb, 'The fusion of 5 sacral vertebrae (S1-S5) at 18-25 years of age', 'The sacrum (the ''sacred bone'') is the posterior wall of the pelvis and the keystone of the pelvic ring.'),
('87f92cde-5fd1-5c62-91ba-c520f8305185'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The sacrum has the following surfaces:', '["Four surfaces","Only the pelvic surface","The pelvic (anterior) surface","Two surfaces only","Only the dorsal surface"]'::jsonb, 'The pelvic (anterior) surface', 'The sacrum (the base at S1, the apex at S5) articulates with the L5 vertebra (lumbosacral joint) and the coccyx.'),
('0761db27-6bf7-5ed9-b949-8573d53a5c9e'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The sacral canal is the continuation of:', '["The intervertebral foramen","The spinal cord","The vertebral canal","The central canal","The transverse foramen"]'::jsonb, 'The vertebral canal', 'The sacral canal (the ''sacral vertebral canal'') contains the cauda equina and the epidural fat. It ends at the sacral hiatus.'),
('a528a428-ee1c-5d20-9811-89cb073ceb83'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The sacral hiatus is:', '["The opening at the inferior end of the sacral canal","The opening at the posterior end","The opening at the superior end","The opening at the lateral end","The opening at the anterior end"]'::jsonb, 'The opening at the inferior end of the sacral canal', 'The sacral hiatus (the ''inferior aperture'' of the sacral canal) is covered by the sacrococcygeal ligament.'),
('0a034820-7e3a-51ce-bead-4f922ff3221d'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The sacral cornua are:', '["The apex of the sacrum and its associated anatomical structures","The transverse processes of S5 and its associated anatomical structures","Two bony prominences on either side of the sacral hiatus (the inferior articular processes of S5","The spinous process of S5 and its associated anatomical structures","The auricular surface of the sacrum and its associated anatomical structures"]'::jsonb, 'Two bony prominences on either side of the sacral hiatus (the inferior articular processes of S5', 'The sacral cornua (the ''horns'' of the sacrum) are palpable on either side of the sacral hiatus.'),
('20a179b4-e896-568f-8758-aadcf6f9a9b0'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'For a patient presenting with symptoms, The sacral promontory is:', '["The anterosuperior margin of the S1 vertebral body (a landmark for the pelvic inlet and for the m","The iliac crest and its associated anatomical structures","The pubic symphysis and its associated anatomical structures","The tip of the coccyx and its associated anatomical structures","The ischial spine and its associated anatomical structures"]'::jsonb, 'The anterosuperior margin of the S1 vertebral body (a landmark for the pelvic inlet and for the m', 'The sacral promontory (the ''projecting'' part of the sacrum) is an important obstetric and surgical landmark.'),
('37f65ce2-035e-59bc-a7e8-650cdd2b41eb'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The coccyx is formed by:', '["A single bone","The fusion of 5 vertebrae","The fusion of 2 vertebrae","The fusion of 4 rudimentary vertebrae","The fusion of 3 vertebrae"]'::jsonb, 'The fusion of 4 rudimentary vertebrae', 'The coccyx (a triangular bone) is the remnant of the embryonic tail. It is a vestigial structure.'),
('20028285-3686-547d-9ac6-bb1a3fceb20b'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The coccyx articulates with:', '["The lumbar spine","The pubis","The ischium","The sacrum","The ilium"]'::jsonb, 'The sacrum', 'The sacrococcygeal joint (a secondary cartilaginous joint) can be a source of pain (coccydynia) after a fall.'),
('a356c8f7-84e1-5d36-9ad5-39c2ef3f91b4'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The anterior longitudinal ligament (ALL) runs:', '["Along the transverse processes","Along the spinous processes","Inside the spinal canal","Along the posterior surface of the vertebral bodies","Along the anterior surface of the vertebral bodies (from the occiput to the sacrum"]'::jsonb, 'Along the anterior surface of the vertebral bodies (from the occiput to the sacrum', 'The ALL (a strong, broad band) is a ''continuous'' ligament that is thicker in the thoracic region.'),
('affb8373-1e6b-5a1b-b8ba-acd07c7c682b'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The posterior longitudinal ligament (PLL) runs:', '["Along the anterior surface of the vertebral bodies","Outside the spinal canal","Along the transverse processes","Along the posterior surface of the vertebral bodies (inside the vertebral canal","Along the spinous processes"]'::jsonb, 'Along the posterior surface of the vertebral bodies (inside the vertebral canal', 'The PLL (a narrow, weaker band) is located within the spinal canal, behind the vertebral bodies. It is innervated (sensitive to disc herniation).'),
('afef8c33-665e-5ed3-9a54-a28d2d23193a'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ligamentum flavum connects:', '["The vertebral bodies and its associated anatomical structures","The spinous processes and its associated anatomical structures","The transverse processes and its associated anatomical structures","The pedicles and its associated anatomical structures","The laminae of adjacent vertebrae (a thick, yellow, elastic ligament - maintains the smooth conto"]'::jsonb, 'The laminae of adjacent vertebrae (a thick, yellow, elastic ligament - maintains the smooth conto', 'The ligamentum flavum (the ''yellow ligament'') is composed of 80% elastin. Hypertrophy of the ligamentum flavum causes spinal stenosis.'),
('63c032b5-b4f7-55be-bd70-32e81d7437ef'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The interspinous ligament connects:', '["The vertebral bodies","The laminae","The pedicles","The spinous processes of adjacent vertebrae","The transverse processes"]'::jsonb, 'The spinous processes of adjacent vertebrae', 'The interspinous ligament (a thin, membranous band) limits flexion. It is pierced by the needle during lumbar puncture.'),
('19070090-b7c9-5236-8046-f6115ef3a3d8'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The supraspinous ligament connects:', '["The laminae","The vertebral bodies","The pedicles","The tips of the spinous processes","The transverse processes"]'::jsonb, 'The tips of the spinous processes', 'The supraspinous ligament (the ''posterior longitudinal'' of the back) is continuous with the ligamentum nuchae in the neck.'),
('ca92486d-f429-5db2-93e7-26a813f267f7'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ligamentum nuchae is:', '["A ligament of the coccyx and its associated anatomical structures","A ligament of the sacrum and its associated anatomical structures","A ligament of the occiput and its associated anatomical structures","A ligament of the lumbar spine and its associated anatomical structures","The upward continuation of the supraspinous ligament in the cervical region (a triangular fibroel"]'::jsonb, 'The upward continuation of the supraspinous ligament in the cervical region (a triangular fibroel', 'The ligamentum nuchae (the ''nuchal ligament'') is a strong, fibroelastic septum that helps maintain the cervical lordosis.'),
('60add2dd-0466-54b5-8a0f-928475dd5f66'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The intertransverse ligaments connect:', '["The vertebral bodies and its associated anatomical structures","The pedicles and its associated anatomical structures","The spinous processes and its associated anatomical structures","The transverse processes of adjacent vertebrae","The laminae and its associated anatomical structures"]'::jsonb, 'The transverse processes of adjacent vertebrae', 'The intertransverse ligaments (the ''lateral limits'' of the spine) are thickest in the lumbar region.'),
('2d20b684-dc66-56c2-b45f-0e40a6ab0b71'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The anterior longitudinal ligament (ALL) is innervated by:', '["The dorsal rami and its associated anatomical structures","The phrenic nerve and its associated anatomical structures","The sympathetic trunk and its associated anatomical structures","The vagus nerve and its associated anatomical structures","The sinuvertebral nerve (the recurrent meningeal nerve) and the ventral rami"]'::jsonb, 'The sinuvertebral nerve (the recurrent meningeal nerve) and the ventral rami', 'The ALL (and the PLL) are innervated by the sinuvertebral nerve (the ''nerve of Luschka'').'),
('e3f88d30-afbb-584f-ad1f-1bd13dcb1329'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The sinuvertebral nerve (the recurrent meningeal nerve) innervates:', '["The organs in the chest and its associated anatomical structures","The skin of the back and its associated anatomical structures","The paraspinal muscles and its associated anatomical structures","The posterior longitudinal ligament, the dura, and the outer annulus fibrosus (carrying nocicepti","The facet joints and its associated anatomical structures"]'::jsonb, 'The posterior longitudinal ligament, the dura, and the outer annulus fibrosus (carrying nocicepti', 'The sinuvertebral nerve (the ''nerve of von Luschka'') is a sensory nerve that provides the innervation for the intervertebral disc (the ''discogenic pain'').'),
('82dbfd56-08d6-5b2b-ac33-354ce0d9665b'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The spinal cord ends at:', '["The T12-L1 level","The L1-L2 level in adults","The C7-T1 level","The L3-L4 level","The S1-S2 level"]'::jsonb, 'The L1-L2 level in adults', 'At birth, the spinal cord ends at L3. In adults, it ends at L1-L2 (the conus medullaris). Below this, the cauda equina is located.'),
('73a06967-7f72-5bcf-b2d6-20ab454b3a30'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'Regarding clinical scenarios, The cauda equina consists of:', '["The lumbar, sacral, and coccygeal nerve roots","The spinal cord only","The cervical nerve roots only","The spinal nerves only","The filum terminale only"]'::jsonb, 'The lumbar, sacral, and coccygeal nerve roots', 'The cauda equina (the ''horse''s tail'') is a bundle of nerve roots in the lumbar cistern (from L2 to S5).'),
('f5d59055-4e7f-530b-8070-e4c34e24801e'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The filum terminale is:', '["A delicate, fibrous strand from the conus medullaris to the coccyx (anchors the spinal cord","A part of the cauda equina and its associated anatomical structures","A ligament of the spine and its associated anatomical structures","A part of the spinal cord and its associated anatomical structures","A dural sinus and its associated anatomical structures"]'::jsonb, 'A delicate, fibrous strand from the conus medullaris to the coccyx (anchors the spinal cord', 'The filum terminale (the ''terminal thread'') is divided into the filum terminale internum (within the dural sac) and externum (beyond).'),
('1b944f11-7061-522b-b213-c61a7c97c57a'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The denticulate ligaments are:', '["Part of the dura mater and its associated anatomical structures","Part of the epidural fat and its associated anatomical structures","Part of the arachnoid mater and its associated anatomical structures","Extensions of the pia mater that attach the spinal cord to the dura mater (on either side","Part of the white matter and its associated anatomical structures"]'::jsonb, 'Extensions of the pia mater that attach the spinal cord to the dura mater (on either side', 'The denticulate ligaments (the ''toothed'' ligaments) stabilize the spinal cord within the spinal canal.'),
('4e049ef3-0aad-5695-9aba-078147b4158e'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The meninges of the spinal cord (outer to inner):', '["Pia, Arachnoid, Dura and its associated anatomical structures","Dura, Pia, Arachnoid and its associated anatomical structures","Arachnoid, Dura, Pia and its associated anatomical structures","Spinal dura mater, spinal arachnoid mater, and spinal pia mater (continuous with the cerebral men","Pia, Dura, Arachnoid and its associated anatomical structures"]'::jsonb, 'Spinal dura mater, spinal arachnoid mater, and spinal pia mater (continuous with the cerebral men', 'The spinal meninges (continuous with the cranial meninges) invest the spinal cord and the nerve roots.'),
('4c3e9bb7-d73a-5d05-8b06-4f65b9df6146'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The epidural space (of the spinal cord) is:', '["The space around the cauda equina and its associated anatomical structures","The space within the spinal cord and its associated anatomical structures","The space between the spinal dura and the vertebral canal (contains epidural fat","The space between the arachnoid and the pia and its associated anatomical structures","The space between the dura and the arachnoid and its associated anatomical structures"]'::jsonb, 'The space between the spinal dura and the vertebral canal (contains epidural fat', 'The epidural space (the ''extra-dural'' space) is the site of epidural anesthesia and of epidural abscesses.'),
('d824fe2d-3b24-559a-a32a-6f8bf125d754'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The subdural space (of the spinal cord) is:', '["The space between the dura and the vertebral canal","The space between the arachnoid and the pia","The space within the spinal cord","The space around the cauda equina","A potential space between the spinal dura and the arachnoid mater (not normally present"]'::jsonb, 'A potential space between the spinal dura and the arachnoid mater (not normally present', 'The subdural space (the ''subdural'' space) is a potential space that can be opened in spinal subdural hematoma (rare).'),
('a2fe3c5b-0d6b-558a-96ac-897fccadb82f'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The subarachnoid space (of the spinal cord) contains:', '["The ligamentum flavum and its associated anatomical structures","The spinal nerves and its associated anatomical structures","CSF, the spinal cord, the cauda equina, and the radicular vessels","Epidural fat and its associated anatomical structures","The epidural venous plexus and its associated anatomical structures"]'::jsonb, 'CSF, the spinal cord, the cauda equina, and the radicular vessels', 'The lumbar subarachnoid space (the lumbar cistern, from L2 to S2) is the site of CSF collection (lumbar puncture).'),
('b490604a-c770-59f6-9005-84bdbd87e306'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'Lumbar puncture is performed at:', '["The L3-L4 or L4-L5 interspace","The L1-L2 interspace","The C1-C2 interspace","The T12-L1 interspace","The S1-S2 interspace"]'::jsonb, 'The L3-L4 or L4-L5 interspace', 'Lumbar puncture is performed between L3-L4 (or L4-L5) in the midline, with the patient in the lateral decubitus position.'),
('f0d32f1f-2694-5ca8-9a73-2c8fb1ed959b'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The needle in lumbar puncture passes through (superficial to deep):', '["Skin, dura, arachnoid and its associated anatomical structures","Skin, muscle, bone and its associated anatomical structures","Skin, subcutaneous tissue, supraspinous ligament, interspinous ligament, ligamentum flavum","Skin, fascia, bone and its associated anatomical structures","Skin, subcutaneous, bone and its associated anatomical structures"]'::jsonb, 'Skin, subcutaneous tissue, supraspinous ligament, interspinous ligament, ligamentum flavum', 'The ''pop'' of the ligamentum flavum is felt (loss of resistance) when entering the epidural space.'),
('7d8ea15b-ecca-58c0-b5cc-854d7f78c795'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The conus medullaris syndrome (compression of the sacral cord) causes:', '["Paralysis of the lower limbs","Saddle anesthesia, bowel/bladder dysfunction","Respiratory failure","Cauda equina syndrome","Paralysis of the upper limbs"]'::jsonb, 'Saddle anesthesia, bowel/bladder dysfunction', 'Conus medullaris syndrome (an acute surgical emergency) requires emergent decompression.'),
('6496407f-2917-5a85-88e1-392c0d320466'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'Cauda equina syndrome (compression of the cauda equina) causes:', '["Respiratory failure and its associated anatomical structures","Upper extremity symptoms and its associated anatomical structures","Cranial nerve symptoms and its associated anatomical structures","Low back pain, sciatica, saddle anesthesia, bowel/bladder dysfunction, and lower extremity weakne","Headache and its associated anatomical structures"]'::jsonb, 'Low back pain, sciatica, saddle anesthesia, bowel/bladder dysfunction, and lower extremity weakne', 'Cauda equina syndrome (from a massive L4-L5 or L5-S1 disc herniation) is a neurosurgical emergency (decompression within 24 hours).'),
('f0d032f9-b2a0-5fbd-b498-ea12be4e12e9'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The spinal nerves are formed by the union of:', '["The spinal cord and the cauda equina and its associated anatomical structures","The nerve rootlets and its associated anatomical structures","The dorsal root (sensory, with the dorsal root ganglion) and the ventral root","The dorsal and ventral rami and its associated anatomical structures","The dorsal and ventral horns and its associated anatomical structures"]'::jsonb, 'The dorsal root (sensory, with the dorsal root ganglion) and the ventral root', 'The spinal nerve (31 pairs: 8 cervical, 12 thoracic, 5 lumbar, 5 sacral, 1 coccygeal) is a ''mixed'' nerve.'),
('8b6d642b-4595-5213-82d0-b74907c21c2f'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The dorsal root ganglion (DRG) contains:', '["The cell bodies of the autonomic neurons","The cell bodies of the glial cells","The cell bodies of the motor neurons","The cell bodies of the interneurons","The cell bodies of the sensory (afferent) neurons"]'::jsonb, 'The cell bodies of the sensory (afferent) neurons', 'The DRG (the ''spinal ganglion'') is located in the intervertebral foramen. It is the site of the sensory neuron cell bodies.'),
('a327d575-ef8e-56de-a501-11a632c41687'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ventral root contains:', '["The cell bodies of the sensory neurons and its associated anatomical structures","The cell bodies of the motor neurons and its associated anatomical structures","Axons of the motor (efferent) neurons (the alpha motor neurons, the gamma motor neurons","The cell bodies of the autonomic neurons and its associated anatomical structures","The dendrites of the motor neurons and its associated anatomical structures"]'::jsonb, 'Axons of the motor (efferent) neurons (the alpha motor neurons, the gamma motor neurons', 'The ventral root (the ''anterior nerve root'') carries the motor fibers from the spinal cord to the spinal nerve.'),
('4797dbf9-a04c-5b8e-a2e8-94b74d14521a'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The spinal nerve divides into:', '["The spinal and cranial nerves","The motor and sensory parts","The dorsal and ventral roots","The cauda equina and the conus medullaris","The dorsal primary ramus (dorsal ramus) and the ventral primary ramus"]'::jsonb, 'The dorsal primary ramus (dorsal ramus) and the ventral primary ramus', 'The dorsal ramus (posterior) supplies the deep back muscles and the skin of the back. The ventral ramus (anterior) supplies the anterolateral body and the limbs.'),
('7697e1de-96e0-5613-bd42-b8775fd57ceb'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The dorsal ramus of the spinal nerve innervates:', '["The limb muscles and its associated anatomical structures","The intercostal muscles and its associated anatomical structures","The abdominal muscles and its associated anatomical structures","The deep (intrinsic) muscles of the back (the erector spinae, transversospinalis","The diaphragm and its associated anatomical structures"]'::jsonb, 'The deep (intrinsic) muscles of the back (the erector spinae, transversospinalis', 'The dorsal ramus (the ''posterior branch'') divides into the medial branch (supplying the multifidus and interspinalis) and the lateral branch (supplying the longissimus).'),
('060792e0-08ca-579a-8a70-11412430057d'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ventral ramus of the spinal nerve innervates:', '["The anterolateral muscles (including the limbs and the anterior trunk), and the skin of the anter","Only the viscera and its associated anatomical structures","Only the deep back muscles and its associated anatomical structures","Only the skin of the back and its associated anatomical structures","Only the paraspinal muscles and its associated anatomical structures"]'::jsonb, 'The anterolateral muscles (including the limbs and the anterior trunk), and the skin of the anter', 'The ventral rami (the ''anterior branches'') form the nerve plexuses (cervical, brachial, lumbar, sacral).'),
('b11e2ab6-9561-5a6d-9a48-550ffba9eb6a'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The cervical plexus (C1-C4) innervates:', '["The muscles of the neck","The muscles of the chest","The entire upper limb","The muscles of the back","The shoulder girdle only"]'::jsonb, 'The muscles of the neck', 'The cervical plexus (C1-C4) also gives sensory supply to the neck and the scalp (lesser occipital, great auricular, transverse cervical, supraclavicular nerves).'),
('7d9c3295-c74a-54fc-a266-c0a633b48fdb'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The brachial plexus (C5-T1) innervates:', '["The chest wall and its associated structures","The back and its associated structures","The upper limb and the shoulder girdle","The neck and its associated structures","The lower limb and its associated structures"]'::jsonb, 'The upper limb and the shoulder girdle', 'The brachial plexus (the ''arm plexus'') has 5 roots, 3 trunks, 6 divisions, 3 cords, and 5 terminal branches.'),
('4eb38797-9f74-55aa-a003-a3ca1c5f3a27'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The lumbar plexus (L1-L4) innervates:', '["The buttock and its associated anatomical structures","The perineum and its associated anatomical structures","The entire lower limb and its associated anatomical structures","The foot and its associated anatomical structures","The lower abdomen, the anterior and medial thigh, and the hip (the ''plexus of the lower abdomen a"]'::jsonb, 'The lower abdomen, the anterior and medial thigh, and the hip (the ''plexus of the lower abdomen a', 'The lumbar plexus (within the psoas major) gives rise to the iliohypogastric, ilioinguinal, genitofemoral, lateral femoral cutaneous, obturator, and femoral nerves.'),
('382b89d4-c0a0-5c5e-9818-4a99a8e77f33'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The sacral plexus (L4-S4) innervates:', '["The posterior thigh, the lower leg, and the foot","The head and its associated anatomical structures","The upper limb and its associated anatomical structures","The abdomen and its associated anatomical structures","The chest and its associated anatomical structures"]'::jsonb, 'The posterior thigh, the lower leg, and the foot', 'The sacral plexus (in front of the piriformis) gives rise to the sciatic, superior/inferior gluteal, pudendal, and posterior femoral cutaneous nerves.'),
('eddedc21-61f4-5be2-80cb-b7158427a63e'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The internal vertebral venous plexus (Batson plexus) is:', '["A part of the dural sinus system and its associated anatomical structures","A part of the portal system and its associated anatomical structures","A valveless venous network within the epidural space (connecting the pelvic, abdominal","A part of the lymphatic system and its associated anatomical structures","A part of the azygos system and its associated anatomical structures"]'::jsonb, 'A valveless venous network within the epidural space (connecting the pelvic, abdominal', 'The Batson plexus (a ''valveless'' venous network) allows the spread of infection and metastases (e.g., prostate cancer) to the spine.'),
('f0b5c1b5-a08c-5e36-b42b-dc0258c66d1a'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The artery of the spinal cord (the great anterior radicular artery, artery of Adamkiewicz) arises from:', '["The vertebral artery and its associated anatomical structures","The basilar artery and its associated anatomical structures","A lumbar or lower intercostal artery (usually left-sided, at T9-T12, supplying the lower 2/3 of t","The subclavian artery and its associated anatomical structures","The internal iliac artery and its associated anatomical structures"]'::jsonb, 'A lumbar or lower intercostal artery (usually left-sided, at T9-T12, supplying the lower 2/3 of t', 'The artery of Adamkiewicz (the ''great anterior radiculomedullary artery'') is the major blood supply to the anterior spinal artery. Occlusion causes anterior spinal artery syndrome.'),
('e74ec140-fe8d-5fd2-9eba-2efd07e0bb45'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The anterior spinal artery syndrome (occlusion of the ASA) causes:', '["Loss of all sensory modalities and its associated anatomical structures","Paralysis (bilateral loss of motor function) and loss of pain/temperature (spinothalamic","Loss of proprioception only and its associated anatomical structures","Loss of pain and temperature only and its associated anatomical structures","Loss of motor function only and its associated anatomical structures"]'::jsonb, 'Paralysis (bilateral loss of motor function) and loss of pain/temperature (spinothalamic', 'Anterior spinal artery syndrome (the ''Beck syndrome'') spares the dorsal columns (proprioception and vibration).'),
('b15551a0-cfb2-5639-9a77-c391e5b049d7'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The blood supply of the spinal cord is from:', '["The radicular arteries only and its associated anatomical structures","Only the anterior spinal artery and its associated anatomical structures","The anterior spinal artery (from the vertebral arteries and the radicular arteries","Only the posterior spinal arteries and its associated anatomical structures","The vertebral arteries only and its associated anatomical structures"]'::jsonb, 'The anterior spinal artery (from the vertebral arteries and the radicular arteries', 'The anterior spinal artery (ASA) supplies the anterior 2/3 of the spinal cord. The posterior spinal arteries (PSA) supply the posterior 1/3.'),
('2c13292c-0d28-5339-9222-3138a3502cab'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The cervical enlargement of the spinal cord is at:', '["C1-C4","C3-T2","L1-S3","T6-T12","T1-T6"]'::jsonb, 'C3-T2', 'The cervical enlargement (the ''cervical plexus and brachial plexus level'') is due to the large number of motor neurons for the upper limb.'),
('ca009756-4975-5cf0-aa10-631aac2e4043'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The lumbosacral enlargement of the spinal cord is at:', '["T1-T6","T6-T12","L1-S3","T9-L1","C3-T2"]'::jsonb, 'T9-L1', 'The lumbosacral enlargement (the ''lower limb level'') is located at T9-L1 (the conus medullaris is nearby).'),
('4dbfbb22-7fd7-5ee7-90b3-0f971d56cf42'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The spinal cord segment L1 is located at the vertebral level:', '["T10-T11 (the vertebral column is longer than the spinal cord, so the spinal segments are more ros","T12-L1 and its associated anatomical structures and its associated structures","T9-T10 and its associated anatomical structures and its associated structures","L1-L2 and its associated anatomical structures and its associated structures","L2-L3 and its associated anatomical structures and its associated structures"]'::jsonb, 'T10-T11 (the vertebral column is longer than the spinal cord, so the spinal segments are more ros', 'The spinal cord segments (the ''neurological levels'') are not at the same level as the corresponding vertebrae (the ''vertebral levels'').'),
('ab9048c6-4030-5c33-bb30-4f926268a011'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The spinal cord segment S1 is located at the vertebral level:', '["L5-S1","S1-S2","T11-T12","T12-L1","L1-L2"]'::jsonb, 'T12-L1', 'The conus medullaris (the terminal part of the spinal cord, containing the sacral segments) is at L1-L2.'),
('5274a8e3-f043-5856-b8ab-0c0145e0f91c'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The conus medullaris is located at:', '["L1-L2","L4-L5","L3-L4","L2-L3","T12-L1"]'::jsonb, 'L1-L2', 'The conus medullaris (the ''cone-shaped'' end of the spinal cord) is at the level of the L1-L2 intervertebral disc.'),
('2874e1bc-1c8e-51dd-85fb-677e3c892485'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The spinal cord occupies the vertebral canal from:', '["The foramen magnum to the L1-L2 level","The C1 to the L5 level","The C1 to the S5 level","The C1 to the T12 level","The foramen magnum to the S1 level"]'::jsonb, 'The foramen magnum to the L1-L2 level', 'The spinal cord (about 45 cm long) extends from the craniocervical junction to the conus medullaris.'),
('4eca80ae-2766-55ce-9219-c453a65b2061'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The spinal nerve roots (the C8 root) exit:', '["Through the C7-T1 disc","Above the C7 vertebra","Below the C7 vertebra","Through the C8-T1 disc","Through the C6-C7 disc"]'::jsonb, 'Below the C7 vertebra', 'Cervical nerve roots exit above the corresponding vertebra (C1 exits above C1, C8 exits below C7).'),
('6e65bbaa-baba-5c31-b5b4-b07931c90c5b'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The thoracic, lumbar, and sacral nerve roots exit:', '["Above the corresponding vertebra","Through the spinal canal","Through the transverse foramen","Through the disc","Below the corresponding vertebra"]'::jsonb, 'Below the corresponding vertebra', 'The ''above-below'' rule: cervical nerves exit above their corresponding vertebrae, except C8 which exits below C7.'),
('c0584ce7-a627-5d6a-b1bd-d73f3d1a5f57'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The costovertebral angle (CVA) is:', '["The angle between the 12th rib and the vertebral column (the area of the renal angle","The angle between the costal margin and the spine","The angle between the ribs and the sternum","The angle between the clavicle and the spine","The angle between the ribs"]'::jsonb, 'The angle between the 12th rib and the vertebral column (the area of the renal angle', 'CVA tenderness (the ''Murphy punch'') is a classic sign of acute pyelonephritis.'),
('5d48bf60-ddc4-5ffe-99ee-d324cae9f98d'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The clinical landmark for the C7 spinous process (vertebra prominens) is:', '["The most prominent spinous process at the base of the neck","The L1 spinous process and its associated anatomical structures","The T6 spinous process and its associated anatomical structures","The S1 spinous process and its associated anatomical structures","The C3 spinous process and its associated anatomical structures"]'::jsonb, 'The most prominent spinous process at the base of the neck', 'The C7 (or T1) spinous process (the ''vertebra prominens'') is a palpable landmark for counting the cervical and upper thoracic vertebrae.'),
('6a78611c-392e-52eb-bb95-dc8e51a84119'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The clinical landmark for the T3 spinous process is:', '["The level of the jugular notch","The level of the spine of the scapula","The level of the xiphoid process","The level of the angle of Louis","The level of the iliac crest"]'::jsonb, 'The level of the spine of the scapula', 'The spine of the scapula (the ''triangular ridge'' on the dorsum of the scapula) is at the T3 level.'),
('9a433ff8-b037-558b-9c11-589c1d019093'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The clinical landmark for the T7 spinous process is:', '["The level of the inferior angle of the scapula","The level of the umbilicus","The level of the angle of Louis","The level of the iliac crest","The level of the jugular notch"]'::jsonb, 'The level of the inferior angle of the scapula', 'The inferior angle of the scapula (the ''bottom tip'' of the shoulder blade) is at the T7 level.'),
('e015cd2e-1d5b-5ce9-b542-cb4e0d78b9d2'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The clinical landmark for the L4 spinous process is:', '["The level of the umbilicus","The level of the iliac crest","The level of the xiphoid process","The level of the pubic symphysis","The level of the greater trochanter"]'::jsonb, 'The level of the iliac crest', 'The iliac crest (the ''L4/L5'' level) is the palpated landmark for performing a lumbar puncture (the intercristal line).'),
('8adbc0f1-cbb6-5427-8b82-bda9b3b8d13b'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The intercristal line (Tuffier''s line) connects:', '["The highest points of the iliac crests","The greater trochanters","The pubic tubercles","The iliac spines","The ischial tuberosities"]'::jsonb, 'The highest points of the iliac crests', 'Tuffier line (the ''intercristal line'') is a clinical landmark for the subarachnoid space (lumbar puncture).'),
('18a5779c-fe6f-59c7-b195-1ed440ec3b95'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The cervical spine has a lordotic curve of:', '["0-10 degrees","20-40 degrees","40-60 degrees","60-80 degrees","10-20 degrees"]'::jsonb, '20-40 degrees', 'Cervical lordosis (the normal ''C-shaped'' curve) may be lost in trauma or muscle spasm (''military neck'').'),
('83392150-1e6b-517e-b842-b6bb329921a4'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The thoracic spine has a kyphotic curve of:', '["0-10 degrees","60-80 degrees","20-40 degrees","40-60 degrees","10-20 degrees"]'::jsonb, '20-40 degrees', 'Thoracic kyphosis (the normal ''round back'') increases with age (especially in women, osteoporosis).'),
('b09e3e6b-6b2e-5b7d-af85-73432eb1e65c'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The lumbar spine has a lordotic curve of:', '["60-80 degrees","40-60 degrees","0-10 degrees","10-20 degrees","20-40 degrees"]'::jsonb, '40-60 degrees', 'Lumbar lordosis (the normal ''sway back'') varies with posture and the pelvic tilt.'),
('d2520e71-c4ab-594d-9bce-4c177549fbc0'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The sacrum has a kyphotic curve of:', '["60-80 degrees","40-60 degrees","20-40 degrees","10-20 degrees","0-10 degrees"]'::jsonb, '40-60 degrees', 'The sacral kyphosis (the ''fixed'' curve of the sacrum) is determined by the shape of the sacrum.'),
('fc2533c6-42de-5c93-a3f2-054c4c3048fd'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'Abnormal spinal curvatures include:', '["Scoliosis (lateral curvature), kyphosis (increased thoracic curve), and lordosis (increased lumba","Flat back and its associated anatomical structures","Only scoliosis and its associated anatomical structures","Only lordosis and its associated anatomical structures","Only kyphosis and its associated anatomical structures"]'::jsonb, 'Scoliosis (lateral curvature), kyphosis (increased thoracic curve), and lordosis (increased lumba', 'Scoliosis (Cobb angle >10 degrees) may be structural (idiopathic, neuromuscular, congenital) or functional (postural).'),
('6d469b5b-1441-5f6f-96ba-245b74658ab3'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The Schmori node is:', '["A fracture of the vertebra and its associated anatomical structures","A herniation of the nucleus pulposus through the endplate of the vertebral body (into the cancell","An infection of the vertebra and its associated anatomical structures","A tumor of the vertebra and its associated anatomical structures","A malformation of the vertebra and its associated anatomical structures"]'::jsonb, 'A herniation of the nucleus pulposus through the endplate of the vertebral body (into the cancell', 'Schmori nodes (often seen on MRI) are the result of disc herniation through the vertebral endplate. They are usually asymptomatic.'),
('f0f45568-926f-5a99-b668-a37933d6e163'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Rust'' sign (of cervical instability) is:', '["A sign of coccyx fracture and its associated anatomical structures","The patient supporting the head with the hands (indicating a fracture or instability of the cervi","A sign of sacral fracture and its associated anatomical structures","A sign of thoracic instability and its associated anatomical structures","A sign of lumbar instability and its associated anatomical structures"]'::jsonb, 'The patient supporting the head with the hands (indicating a fracture or instability of the cervi', 'Rust sign (the ''head-holding'' sign): the patient places their hands on their head to support it (seen in atlantoaxial instability).'),
('eb8c2bbc-7a4d-5ede-9c9c-acb5812c7250'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Adam''s forward bend test'' is used for:', '["Screening for lordosis and its associated anatomical structures","Screening for a herniated disc and its associated anatomical structures","Screening for scoliosis (scoliosis is visible as a ''rib hump'' or ''lumbar hump'' when the patient b","Screening for kyphosis and its associated anatomical structures","Screening for spinal stenosis and its associated anatomical structures"]'::jsonb, 'Screening for scoliosis (scoliosis is visible as a ''rib hump'' or ''lumbar hump'' when the patient b', 'The forward bend test (the ''Adams test'') is used for the early detection of scoliosis (the ''rib hump sign'').'),
('892362ff-3908-51bb-817f-104101bed3ca'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Straight leg raise'' (SLR) test is:', '["A test for knee arthritis and its associated anatomical structures","A test for hip arthritis and its associated anatomical structures","A nerve root tension sign (reproduces sciatica by stretching the L5 and S1 nerve roots - positive","A test for lumbar instability and its associated anatomical structures","A test for sacroiliac joint dysfunction and its associated anatomical structures"]'::jsonb, 'A nerve root tension sign (reproduces sciatica by stretching the L5 and S1 nerve roots - positive', 'SLR (the ''Lasegue sign''): dorsiflexion of the ankle (Braggard sign) exacerbates the pain. The crossed SLR is more specific for a disc herniation.'),
('53316859-5c2f-5ffb-802f-45015b01831b'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Femoral nerve stretch test'' is:', '["A test for the S1 root and its associated anatomical structures","A test for the S2 root and its associated anatomical structures","A test for the L5 root and its associated anatomical structures","A nerve root tension sign for the L2, L3, and L4 roots (reproduces anterior thigh pain by extendi","A test for the C5 root and its associated anatomical structures"]'::jsonb, 'A nerve root tension sign for the L2, L3, and L4 roots (reproduces anterior thigh pain by extendi', 'The femoral nerve stretch test (the ''reverse SLR'') is the equivalent of the SLR for the upper lumbar roots.'),
('a7ea2e75-9c2c-514d-b707-a1e40f815626'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Milgram test'' (or the ''Valsalva maneuver''):', '["A test for a fracture and its associated anatomical structures","A test for a muscle strain and its associated anatomical structures","Increases the intrathecal pressure (reproduces pain if there is a space-occupying lesion or a her","A test for a ligament sprain and its associated anatomical structures","A test for a tumor and its associated anatomical structures"]'::jsonb, 'Increases the intrathecal pressure (reproduces pain if there is a space-occupying lesion or a her', 'The Valsalva maneuver (forced expiration against a closed glottis) increases CSF pressure and may reproduce radicular pain.'),
('1787ad6c-2c5f-5ab6-9ab2-1289d2fc19b0'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Hoffmann sign'' (or the ''Hoffmann reflex''):', '["A sign of disc herniation and its associated anatomical structures","A lower motor neuron sign and its associated anatomical structures","An upper motor neuron sign (the ''thumb flexion'' elicited by flicking the middle finger - indicate","A cerebellar sign and its associated anatomical structures","A sensory sign and its associated anatomical structures"]'::jsonb, 'An upper motor neuron sign (the ''thumb flexion'' elicited by flicking the middle finger - indicate', 'Hoffmann sign (the ''finger jerk''): a positive sign indicates UMN pathology (e.g., cervical myelopathy or spinal cord compression).'),
('9c85fa9b-58a8-5964-912a-fa0bd11659aa'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Babinski sign'' (the ''plantar response''):', '["A cerebellar sign and its associated anatomical structures","An upper motor neuron sign (the extension of the great toe and the fanning of the other toes in r","A sign of a herniated disc and its associated anatomical structures","A lower motor neuron sign and its associated anatomical structures","A sensory sign and its associated anatomical structures"]'::jsonb, 'An upper motor neuron sign (the extension of the great toe and the fanning of the other toes in r', 'The Babinski sign (the ''extensor plantar response''): a normal response is the flexion of the toes (the ''flexor plantar response'').'),
('2825fa66-fd81-5c6f-aa36-424089aa33d9'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Clonus'' (sustained, rhythmic muscle contraction):', '["A sensory sign and its associated anatomical structures","A basal ganglia sign and its associated anatomical structures","A lower motor neuron sign and its associated anatomical structures","An upper motor neuron sign - indicates UMN lesion of the corticospinal tract)","A cerebellar sign and its associated anatomical structures"]'::jsonb, 'An upper motor neuron sign - indicates UMN lesion of the corticospinal tract)', 'Sustained clonus (>3 beats) is pathologic (UMN lesion). Ankle clonus is the most common (the ''Achilles clonus'').'),
('d97f1b5a-4f08-52de-946b-ed4820c0a949'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Lhermitte sign'' (the ''barber chair sign''):', '["A sign of spinal stenosis and its associated anatomical structures","A sign of sciatica and its associated anatomical structures","A sign of a spinal tumor and its associated anatomical structures","An electric shock-like sensation down the spine and the limbs on flexing the neck (indicating a d","A sign of a herniated disc and its associated anatomical structures"]'::jsonb, 'An electric shock-like sensation down the spine and the limbs on flexing the neck (indicating a d', 'Lhermitte sign (the ''Lhermitte phenomenon''): classically described in multiple sclerosis, but also seen in cervical myelopathy.'),
('f607ef32-1aee-5f2d-a949-4919870eeb09'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The spinal shock (the ''spinal concussion''):', '["A permanent loss of spinal cord function and its associated anatomical structures","A temporary (hours to weeks) loss of all spinal cord function below the level of a severe injury","An irreversible paralysis and its associated anatomical structures","A sign of recovery and its associated anatomical structures","A sign of a herniated disc and its associated anatomical structures"]'::jsonb, 'A temporary (hours to weeks) loss of all spinal cord function below the level of a severe injury', 'Spinal shock (a ''neurogenic shock'') is followed by the recovery of the reflex arcs (hyperreflexia, spasticity) in UMN injury.'),
('1b692c14-2162-55a4-bc88-7afda2cd6639'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The neurogenic shock (in cervical or high thoracic spinal cord injury):', '["Hypotension with bradycardia (the loss of the sympathetic outflow from T1-L2","Hypertension with tachycardia and its associated anatomical structures","Hypotension with tachycardia and its associated anatomical structures","Normal blood pressure and its associated anatomical structures","Hypertension with bradycardia and its associated anatomical structures"]'::jsonb, 'Hypotension with bradycardia (the loss of the sympathetic outflow from T1-L2', 'Neurogenic shock (the ''loss of the sympathetic tone'') is treated with vasopressors (not with fluids, which can cause pulmonary edema).'),
('3b2268b5-2384-5ebe-ac35-ba6c9c056dd9'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The Brown-Sequard syndrome (hemisection of the spinal cord):', '["Ipsilateral loss of proprioception only and its associated anatomical structures","Ipsilateral paralysis (corticospinal), ipsilateral loss of proprioception/vibration (dorsal columns","Contralateral paralysis only and its associated anatomical structures","Ipsilateral loss of pain and temperature only and its associated anatomical structures","Loss of all modalities on both sides and its associated anatomical structures"]'::jsonb, 'Ipsilateral paralysis (corticospinal), ipsilateral loss of proprioception/vibration (dorsal columns', 'Brown-Sequard syndrome (the ''hemicord syndrome''): a classic, textbook spinal cord syndrome.'),
('13309e0c-f2e8-55b0-ac56-ad3f430bb744'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The central cord syndrome (the most common incomplete cervical cord injury):', '["Affects only the corticospinal tracts and its associated anatomical structures","Affects only the spinothalamic tracts and its associated anatomical structures","Affects only the dorsal columns and its associated anatomical structures","Affects the central gray matter and the crossing spinothalamic fibers (causing a ''cape-like'' dist","Affects only the motor neurons and its associated anatomical structures"]'::jsonb, 'Affects the central gray matter and the crossing spinothalamic fibers (causing a ''cape-like'' dist', 'Central cord syndrome (the ''syringomyelia-like'' syndrome): the upper limbs are more affected than the lower limbs (the ''man in a barrel'' distribution).'),
('8496d6ef-406c-5637-92b9-3a468596424f'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The anterior cord syndrome (the ''anterior spinal artery syndrome''):', '["Loss of proprioception only and its associated anatomical structures","Loss of pain and temperature only and its associated anatomical structures","Loss of motor function (corticospinal) and pain/temperature (spinothalamic) below the lesion","Loss of motor function only and its associated anatomical structures","Loss of all sensory modalities and its associated anatomical structures"]'::jsonb, 'Loss of motor function (corticospinal) and pain/temperature (spinothalamic) below the lesion', 'Anterior cord syndrome (the ''anterior 2/3'' syndrome): the best prognosis is for the recovery of the dorsal column function.'),
('5e970ece-4d86-52fe-8fef-26c0d7f19ed0'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The posterior cord syndrome (the ''dorsal column syndrome''):', '["Paralysis and its associated anatomical structures","Loss of pain and temperature and its associated anatomical structures","Loss of motor function and its associated anatomical structures","Loss of proprioception and vibration below the lesion (with preservation of motor function and pa","Loss of all modalities and its associated anatomical structures"]'::jsonb, 'Loss of proprioception and vibration below the lesion (with preservation of motor function and pa', 'Posterior cord syndrome (the ''posterior 1/3'' syndrome): a ''sensory ataxia'' (the patient cannot feel the position of the limbs).'),
('df7158ba-3c33-5d65-99a7-61addb53f76d'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The conus medullaris syndrome (the ''cone'' syndrome):', '["Paralysis of the upper limbs and its associated anatomical structures","Early bladder and bowel dysfunction (with saddle anesthesia) and areflexia of the anal and bladde","Sensory loss in the lower limbs and its associated anatomical structures","Motor loss in the lower limbs and its associated anatomical structures","Paralysis of the lower limbs and its associated anatomical structures"]'::jsonb, 'Early bladder and bowel dysfunction (with saddle anesthesia) and areflexia of the anal and bladde', 'Conus medullaris syndrome (the ''sacral cord'' syndrome): the ''early and severe'' loss of bowel/bladder function (vs. the ''late'' loss in the cauda equina syndrome).'),
('8f613a07-37f8-5570-848b-2a136d05eeee'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The cauda equina syndrome (the ''horse tail'' syndrome):', '["Paralysis of the upper limbs and its associated anatomical structures","Paralysis of the lower limbs and its associated anatomical structures","Motor loss in the lower limbs and its associated anatomical structures","Sensory loss in the lower limbs and its associated anatomical structures","Lower (radicular) motor and sensory loss in the lower limbs (with ''late'' and less severe bladder/"]'::jsonb, 'Lower (radicular) motor and sensory loss in the lower limbs (with ''late'' and less severe bladder/', 'Cauda equina syndrome (the ''herniated disc'' syndrome): the ''late'' loss of bowel/bladder function (vs. ''early'' in the conus syndrome).'),
('3148a4c2-5824-5180-b525-bf898d77cee5'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The spinal arteries (the segmental arteries) include:', '["The posterior intercostal arteries (in the thorax), the lumbar arteries","Only the lumbar arteries and its associated anatomical structures","The vertebral arteries and its associated anatomical structures","Only the posterior intercostal arteries and its associated anatomical structures","Only the lateral sacral arteries and its associated anatomical structures"]'::jsonb, 'The posterior intercostal arteries (in the thorax), the lumbar arteries', 'The segmental arteries (the ''radicular'' or ''medullary'' arteries) are the main blood supply to the spinal cord in the thoracolumbar region.'),
('7728c45d-815d-5284-9c7f-48ab20131e3f'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''critical vascular zone'' of the spinal cord (the watershed area) is at:', '["T4-T9 (the ''thoracic watershed zone'', the most vulnerable area for spinal cord ischemia in the se","L1-S2 and its associated anatomical structures and its associated structures","C5-T2 and its associated anatomical structures and its associated structures","C1-C4 and its associated anatomical structures and its associated structures","T10-L2 and its associated anatomical structures and its associated structures"]'::jsonb, 'T4-T9 (the ''thoracic watershed zone'', the most vulnerable area for spinal cord ischemia in the se', 'The thoracic watershed zone (T4-T9) is the ''watershed area'' between the anterior spinal artery and the radicular arteries (the ''artery of Adamkiewicz'').'),
('81b55419-c7eb-5193-84f8-2193388f032a'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Cord level'' of the spinal cord segment T10 is located at the vertebral level:', '["T9-T10","T8-T9","T10-T11","T7-T8","T12-L1"]'::jsonb, 'T7-T8', 'The spinal cord level T10 (the vertebral level T7-T8) is 3 levels above the vertebral level.'),
('bd5d822e-eae7-51b7-9c10-9dcf56b74192'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The spinal cord segments (the ''neurological levels'') are used for:', '["Describing the level of a spinal cord injury","Describing the level of a spinal tumor","Describing the level of a spinal infection","Describing the level of a fracture","Describing the level of a disc herniation"]'::jsonb, 'Describing the level of a spinal cord injury', 'The neurological level (the ''most caudal segment with normal motor and sensory function'') determines the clinical syndrome of the spinal cord injury.'),
('e32d557d-4155-5c33-a3f9-96330ed39c4d'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ASIA Impairment Scale (AIS) grades:', '["complete, B: incomplete and its associated anatomical structures","complete (no motor or sensory below the lesion), B: sensory incomplete","sensory, B: motor and its associated anatomical structures","incomplete, B: complete and its associated anatomical structures","mild, B: moderate, C: severe and its associated anatomical structures"]'::jsonb, 'complete (no motor or sensory below the lesion), B: sensory incomplete', 'The AIS (the ''Frankel scale'' modified) is the standard for the neurological classification of the spinal cord injury (SCI).'),
('14b1e2cf-abd4-5e41-9d4f-5e7b6abb192f'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The term ''tetraplegia'' (quadriplegia) indicates:', '["Paralysis of the lower limbs only","Paralysis of one side of the body","Paralysis of one limb only","Paralysis of all 4 limbs","Paralysis of the upper limbs only"]'::jsonb, 'Paralysis of all 4 limbs', 'Tetraplegia (the ''four'' paralysis): an injury of the cervical spinal cord. Paraplegia: an injury of the thoracic, lumbar, or sacral spinal cord.'),
('b1faf04c-65f7-569c-ac25-470db7fbdd22'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The term ''paraplegia'' indicates:', '["Paralysis of one side of the body","Paralysis of the lower limbs","Paralysis of all 4 limbs","Paralysis of one limb only","Paralysis of the upper limbs only"]'::jsonb, 'Paralysis of the lower limbs', 'Paraplegia (the ''half'' paralysis): the upper limbs are NOT affected. The trunk AND the lower limbs are affected.'),
('b43f97e9-4856-5266-aed8-5f7be2a8113b'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''C5'' tetraplegia (the most common cervical level of injury) has:', '["Preserved all upper limb function","Preserved elbow flexion (C5, biceps) and shoulder abduction","Preserved only the wrist function","Preserved only the shoulder function","Preserved only the hand function"]'::jsonb, 'Preserved elbow flexion (C5, biceps) and shoulder abduction', 'The C5 tetraplegia (the ''biceps'' level) requires a powered wheelchair and an electric hand splint.'),
('8c01e769-0908-5ae0-b1ca-676e691de997'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''C7'' tetraplegia (the ''key'' level for independent living) has:', '["Preserved only the wrist function and its associated anatomical structures","Preserved elbow extension (C7, triceps) and the ability to perform a ''tenodesis'' grip (extension","Preserved all upper limb function and its associated anatomical structures","Preserved only the hand function and its associated anatomical structures","Preserved only the shoulder function and its associated anatomical structures"]'::jsonb, 'Preserved elbow extension (C7, triceps) and the ability to perform a ''tenodesis'' grip (extension', 'C7 tetraplegia (the ''triceps'' level) allows the patient to be independent in self-care, transfers, and wheelchair mobility.'),
('1bd82c41-ca18-5b6d-8f60-d9d0e83412ff'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''T1'' paraplegia (the lowest level of tetraplegia) has:', '["Preserved trunk control and its associated anatomical structures","Paralysis of the upper limbs and its associated anatomical structures","Preserved all body function and its associated anatomical structures","Preserved full upper limb function (T1, the intrinsic hand muscles), but NO trunk control (the ''p","Paralysis of the lower limbs only and its associated anatomical structures"]'::jsonb, 'Preserved full upper limb function (T1, the intrinsic hand muscles), but NO trunk control (the ''p', 'T1 paraplegia: the last segment of the brachial plexus (the ''C8-T1'' level for the hand intrinsic muscles).'),
('e8aa8668-5dd3-5f08-99e9-748f1175b85d'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''T6'' paraplegia (the ''high'' paraplegia) has:', '["Preserved all trunk control and its associated anatomical structures","Preserved diaphragm function only and its associated anatomical structures","Preserved all body function and its associated anatomical structures","Preserved upper limb function, but NO trunk control (the ''thoracic'' level","Preserved intercostal function and its associated anatomical structures"]'::jsonb, 'Preserved upper limb function, but NO trunk control (the ''thoracic'' level', 'T6 paraplegia (the ''nipple'' level): the intercostal muscles are paralyzed (the diaphragm is C3-C5, so breathing is intact).'),
('a8bae720-bce2-5274-bb50-3b305946ed1d'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''T12'' paraplegia (the ''low'' paraplegia) has:', '["Preserved the control of the lower limbs","Preserved all body function","Preserved upper limb function and TRUNK control","Preserved the ability to walk","Preserved lower limb function"]'::jsonb, 'Preserved upper limb function and TRUNK control', 'T12 paraplegia (the ''T12-L1'' level): the abdominal muscles are intact (good trunk control).'),
('bbe81f0e-1e86-5488-9d2c-da4ffb11b804'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''L1'' paraplegia (the ''lumbar'' level) has:', '["Preserved the ability to run and its associated anatomical structures","Preserved all lower limb function and its associated anatomical structures","Preserved upper limb, trunk, and HIP FLEXION (L1-L2, the iliopsoas), but NO knee extension (L3","Preserved the ability to stand and its associated anatomical structures","Preserved the ability to walk and its associated anatomical structures"]'::jsonb, 'Preserved upper limb, trunk, and HIP FLEXION (L1-L2, the iliopsoas), but NO knee extension (L3', 'L1 paraplegia (the ''hip flexion'' level): the patient can use a long-leg brace (KAFO) and crutches.'),
('3aef69d4-ee93-52ce-a42d-2691c793dcbe'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''L3'' paraplegia (the ''knee extension'' level) has:', '["Preserved the ability to run and its associated anatomical structures","Preserved the ability to walk without aids and its associated anatomical structures","Preserved the ability to stand and its associated anatomical structures","Preserved quadriceps function (L3, knee extension), allowing the patient to walk with a short-leg","Preserved all lower limb function and its associated anatomical structures"]'::jsonb, 'Preserved quadriceps function (L3, knee extension), allowing the patient to walk with a short-leg', 'L3 paraplegia: the patient may be a community ambulator (a ''KAFO'' brace).'),
('c7744596-039e-56b9-863f-928597cc9458'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''S1'' paraplegia (the ''ankle plantar flexion'' level) has:', '["Preserved the ability to stand and its associated anatomical structures","Preserved all body function and its associated anatomical structures","Preserved all lower limb function and its associated anatomical structures","Preserved the ability to walk with a minimal ankle-foot orthosis (AFO), but with a ''foot drop'' (L","Preserved the ability to run and its associated anatomical structures"]'::jsonb, 'Preserved the ability to walk with a minimal ankle-foot orthosis (AFO), but with a ''foot drop'' (L', 'S1 paraplegia: the patient is a community ambulator with a ''drop foot'' (the peroneal nerve weakness).'),
('00c9c191-200d-54f7-bd72-c3bd14be040d'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''S2'' and below (the ''sacral'' level of injury):', '["A ''mixed'' injury","A ''complete'' injury","A ''upper motor neuron'' injury","A ''incomplete'' injury","A ''lower motor neuron'' cauda equina injury"]'::jsonb, 'A ''lower motor neuron'' cauda equina injury', 'The sacral (conus) injury is a ''lower motor neuron'' (LMN) type of injury (the ''areflexic'' bladder).'),
('35cd072e-a1dd-5485-92c6-fe5042953e60'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''autonomic dysreflexia'' (the ''autonomic hyperreflexia''):', '["A medical emergency in patients with a spinal cord injury above T6 (severe hypertension","A life-threatening decrease in blood pressure and its associated anatomical structures","A life-threatening increase in heart rate and its associated anatomical structures","A life-threatening decrease in heart rate and its associated anatomical structures","A life-threatening increase in body temperature and its associated anatomical structures"]'::jsonb, 'A medical emergency in patients with a spinal cord injury above T6 (severe hypertension', 'Autonomic dysreflexia (the ''spinal autonomic storm''): triggered by a noxious stimulus below the level of the lesion (e.g., a distended bladder).'),
('a5bd11d1-b404-5ce8-be3f-dbde1010383d'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''posterior ligamentous complex'' (PLC) of the spine (the ''osteoligamentous complex''):', '["The intertransverse ligaments and its associated anatomical structures","The disc and its associated anatomical structures","The facet capsules and its associated anatomical structures","The supraspinous ligament, the interspinous ligament, and the ligamentum flavum (the ''posterior t","The ALL and the PLL and its associated anatomical structures"]'::jsonb, 'The supraspinous ligament, the interspinous ligament, and the ligamentum flavum (the ''posterior t', 'The PLC (the ''posterior ligamentous complex'') is a critical determinant of spinal stability in a vertebral fracture.'),
('deef57e6-3c40-559c-b604-11ae54cbc764'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''three-column spine'' concept (Denis classification) describes:', '["The disc, the body, and the facet joint","The spinal cord, the canal, and the nerve roots","The ALL, the PLL, and the ligamentum flavum","The anterior column (ALL, anterior 2/3 of the body), the middle column (PLL","The vertebral body, the pedicles, and the spinous process"]'::jsonb, 'The anterior column (ALL, anterior 2/3 of the body), the middle column (PLL', 'The Denis three-column model (the ''anatomy of spinal stability''): a burst fracture (involving the middle column) is unstable.'),
('bfafd49f-e11c-5ced-b6fd-bf008cd70b8a'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'A ''compression fracture'' (wedge fracture) involves:', '["Only the posterior column","The middle and posterior columns","The anterior and middle columns","The ANTERIOR column only","All 3 columns"]'::jsonb, 'The ANTERIOR column only', 'Compression fractures (the ''wedge fracture''): common in osteoporosis (the ''osteoporotic vertebral fracture'').'),
('72b1d2d4-57a8-5900-aee2-b3a69fc82aa4'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'A ''burst fracture'' involves:', '["Only the middle column","All 3 columns are always involved","Only the posterior column","Only the anterior column","The anterior and middle columns"]'::jsonb, 'The anterior and middle columns', 'Burst fractures (the ''explosion'' fracture of the vertebral body) often require surgical stabilization.'),
('19daffec-e348-5bf1-9fc8-0ec551b8674e'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'A ''Chance fracture'' (the ''seatbelt fracture''):', '["A fracture of the transverse process and its associated anatomical structures","A burst fracture and its associated anatomical structures","A fracture of the spinous process and its associated anatomical structures","A compression fracture and its associated anatomical structures","A horizontal fracture through the vertebral body AND the posterior elements (a ''flexion-distracti"]'::jsonb, 'A horizontal fracture through the vertebral body AND the posterior elements (a ''flexion-distracti', 'The Chance fracture (the ''lap-belt'' injury) is associated with intra-abdominal injuries (the ''seatbelt sign'').'),
('c926aa52-bafa-574c-9cd6-94271523f0d5'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'A ''Jefferson fracture'' (the ''burst fracture of the atlas''):', '["A fracture of the anterior and posterior arches of the Atlas (a ''burst'' of the C1 ring","A fracture of the C7 spinous process and its associated anatomical structures","A fracture of the C3 body and its associated anatomical structures","A fracture of the axis and its associated anatomical structures","A fracture of the dens and its associated anatomical structures"]'::jsonb, 'A fracture of the anterior and posterior arches of the Atlas (a ''burst'' of the C1 ring', 'Jefferson fracture (the ''C1 burst''): often stable if the transverse ligament is intact.'),
('74cb4410-dc92-5659-9859-110dacaf03cb'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'A ''Hangman fracture'' (the ''traumatic spondylolisthesis of the axis''):', '["A dislocation of C1 and C2 and its associated anatomical structures","A fracture of the dens of C2 and its associated anatomical structures","A fracture of the C1 body and its associated anatomical structures","A bilateral fracture of the pars interarticularis of C2 (from hyperextension","A fracture of the C7 vertebra and its associated anatomical structures"]'::jsonb, 'A bilateral fracture of the pars interarticularis of C2 (from hyperextension', 'The Hangman fracture (the ''C2 pars'' fracture): the ''typical'' hangman fracture is a hyperextension injury (the ''judicial hanging'').'),
('9a0953de-bb02-549b-a49c-83834d70b036'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'An ''odontoid fracture'' (a fracture of the dens of the Axis):', '["A fracture through the lamina of C2","A fracture through the tip of the dens","A fracture through the body of C2","A fracture through the base of the dens","A fracture through the transverse process of C2"]'::jsonb, 'A fracture through the base of the dens', 'Odontoid fractures (Type II: through the base of the dens) have a HIGH rate of non-union (surgical fixation is often needed).'),
('95f8ff45-bf17-57fe-be5b-1207e86869eb'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''spondylolysis'' is:', '["A fracture of the vertebral body and its associated anatomical structures","A fracture of the spinous process and its associated anatomical structures","A herniated disc and its associated anatomical structures","A defect (a ''pars defect'') in the pars interarticularis of the lumbar vertebra (often L5","A dislocation of the facet joint and its associated anatomical structures"]'::jsonb, 'A defect (a ''pars defect'') in the pars interarticularis of the lumbar vertebra (often L5', 'Spondylolysis (the ''pars defect''): a ''Scottie dog'' sign on the oblique X-ray view. Usually asymptomatic, but can cause low back pain.'),
('2cd91598-f4ad-5176-8d70-6688e9a7ad7e'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''spondylolisthesis'' (the ''slippage'' of a vertebra) is graded by:', '["The Denis classification and its associated anatomical structures","The McRae classification and its associated anatomical structures","The Frankel classification and its associated anatomical structures","The Meyerding classification (Grade I: 0-25% slippage, II: 25-50%, III: 50-75%, IV: 75-100%","The ASIA classification and its associated anatomical structures"]'::jsonb, 'The Meyerding classification (Grade I: 0-25% slippage, II: 25-50%, III: 50-75%, IV: 75-100%', 'The Meyerding grading (the ''percentage slippage'' on the lateral X-ray) is the most widely used classification of spondylolisthesis.'),
('1de98ec9-49fd-54f2-8880-78ecb1cbbbfc'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''isthmic'' spondylolisthesis (Type II, common in adolescents):', '["Caused by a congenital defect of the L5-S1 facet joint","Caused by a degenerative disc and facet joints","Caused by a defect (a ''pars'' fracture) in the pars interarticularis (the most common type in youn","Caused by a fracture of the vertebral body","Caused by a tumor"]'::jsonb, 'Caused by a defect (a ''pars'' fracture) in the pars interarticularis (the most common type in youn', 'Isthmic spondylolisthesis (the ''pars'' type): the pars defect is visible on the oblique X-ray (''the collar of the Scottie dog'').'),
('596ac112-7303-5805-bd8b-42b62dc5ad44'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''degenerative'' spondylolisthesis (Type III, common in older adults):', '["Caused by a pars defect and its associated anatomical structures","Caused by an infection and its associated anatomical structures","Caused by a tumor and its associated anatomical structures","Caused by a trauma and its associated anatomical structures","Caused by the degenerative changes in the disc and the facet joints (the pars is intact"]'::jsonb, 'Caused by the degenerative changes in the disc and the facet joints (the pars is intact', 'Degenerative spondylolisthesis (the ''pseudospondylolisthesis''): the L4 vertebra slips forward on the L5 vertebra (the ''L4-L5'' level).'),
('68003c39-8b8e-5736-b62b-8510fceb2f20'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''spinal stenosis'' (the narrowing of the spinal canal) is most common in:', '["The coccyx","The thoracic spine","The lumbar spine","The cervical spine","The sacral spine"]'::jsonb, 'The lumbar spine', 'Lumbar spinal stenosis (the ''spinal narrowing''): the patient has pain in the legs on walking (the ''neurogenic claudication'') that is relieved by sitting or bending forward.'),
('7581420c-ea95-5671-8f62-8203762c79a9'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''cervical spondylotic myelopathy'' (CSM) is:', '["The most common cause of spinal cord dysfunction in adults over 55 years (the ''cervical spinal st","A cause of tetraplegia and its associated anatomical structures","A rare cause of spinal cord dysfunction and its associated anatomical structures","A cause of paraplegia and its associated anatomical structures","A cause of cauda equina syndrome and its associated anatomical structures"]'::jsonb, 'The most common cause of spinal cord dysfunction in adults over 55 years (the ''cervical spinal st', 'CSM (the ''cervical myelopathy''): the MRI shows the narrowing of the cervical spinal canal (the ''Torg-Pavlov ratio'').'),
('f0575744-eb74-5c44-a7eb-84bb1171f32f'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Torg-Pavlov ratio'' (the ratio of the spinal canal to the vertebral body):', '["A ratio of >1.0 is indicative of stenosis","A ratio of <0.5 is indicative of stenosis","A ratio of <0.8 is indicative of cervical spinal stenosis","A ratio of <0.6 is indicative of stenosis","A ratio of <0.7 is indicative of stenosis"]'::jsonb, 'A ratio of <0.8 is indicative of cervical spinal stenosis', 'The Torg-Pavlov ratio (the ''canal-to-body ratio''): used to assess the risk of a spinal cord injury in athletes.'),
('c5897e48-d189-5c53-bd80-8d0308fe7b73'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''ossification of the posterior longitudinal ligament'' (OPLL):', '["A condition of the supraspinous ligament and its associated anatomical structures","A condition in which the PLL becomes ossified, causing a ''bamboo spine'' appearance on X-ray","A condition of the ALL and its associated anatomical structures","A condition of the ligamentum flavum and its associated anatomical structures","A condition of the interspinous ligament and its associated anatomical structures"]'::jsonb, 'A condition in which the PLL becomes ossified, causing a ''bamboo spine'' appearance on X-ray', 'OPLL (the ''Japanese disease''): more common in East Asian populations. The MRI shows a ''double line'' sign (the ''PLL'' ossification).'),
('fb0d6b58-b582-518c-a758-b4a4e879f5aa'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''ossification of the ligamentum flavum'' (OLF):', '["A condition of the supraspinous ligament and its associated anatomical structures","A condition (more common in the thoracic spine) in which the ligamentum flavum becomes ossified","A condition of the PLL and its associated anatomical structures","A condition of the interspinous ligament and its associated anatomical structures","A condition of the ALL and its associated anatomical structures"]'::jsonb, 'A condition (more common in the thoracic spine) in which the ligamentum flavum becomes ossified', 'OLF (the ''ligamentum flavum ossification''): a rare cause of thoracic myelopathy (the ''Japanese'' disease).'),
('ddfedf4f-c018-5e10-b8db-c25c416040a4'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''diffuse idiopathic skeletal hyperostosis'' (DISH, Forestier disease):', '["A condition of the interspinous ligament","A condition of the PLL","A ''flowing'' ossification of the ALL","A condition of the supraspinous ligament","A condition of the ligamentum flavum"]'::jsonb, 'A ''flowing'' ossification of the ALL', 'DISH (the ''Forestier disease''): the ''bamboo spine'' appearance (but with NO sacroiliitis).'),
('f406e620-19b2-53ed-b3ff-3dcebd53eb84'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''ankylosing spondylitis'' (AS):', '["A degenerative condition and its associated anatomical structures","A traumatic condition and its associated anatomical structures","A chronic, inflammatory, autoimmune spondyloarthropathy that causes the fusion of the sacroiliac","An infectious condition and its associated anatomical structures","A metabolic condition and its associated anatomical structures"]'::jsonb, 'A chronic, inflammatory, autoimmune spondyloarthropathy that causes the fusion of the sacroiliac', 'AS (the ''Marie-Strumpell disease''): the ''bamboo spine'' on the X-ray AND the sacroiliitis (the ''squaring'' of the vertebral bodies).'),
('c173bad7-fe12-5dae-8229-972b29193954'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''bamboo spine'' (a classic radiographic sign of AS):', '["The ''tram track'' sign and its associated anatomical structures","The ''double line'' sign and its associated anatomical structures","The ''flowing'' ossification of the ALL and its associated anatomical structures","The ''Scottie dog'' sign and its associated anatomical structures","The continuous, syndesmophyte formation (the ''bamboo'' appearance) bridging the intervertebral dis"]'::jsonb, 'The continuous, syndesmophyte formation (the ''bamboo'' appearance) bridging the intervertebral dis', 'The bamboo spine (the ''syndesmophyte'' formation) is the hallmark of the late-stage ankylosing spondylitis.'),
('b9da07bb-90c1-5f5d-b8c0-dfa9e4e4b05b'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Scheuermann disease'' (the ''juvenile kyphosis''):', '["A developmental, ''osteochondrosis'' of the thoracic spine (three or more adjacent vertebrae with >","An infectious condition and its associated anatomical structures","An inflammatory condition and its associated anatomical structures","A malignant condition and its associated anatomical structures","A traumatic condition and its associated anatomical structures"]'::jsonb, 'A developmental, ''osteochondrosis'' of the thoracic spine (three or more adjacent vertebrae with >', 'Scheuermann disease (the ''juvenile kyphosis''): the ''endplate irregularities'' (the ''Schmori nodes'') on the MRI.'),
('a554935b-eacd-59ac-8643-16ae190a4972'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''vertebra plana'' (the ''flat vertebra''):', '["A ''coin-on-edge'' radiographic appearance (the collapse of the entire vertebral body","An infection of the vertebra and its associated anatomical structures","A malformation of the vertebra and its associated anatomical structures","A tumor of the vertebra and its associated anatomical structures","A fracture of the vertebra and its associated anatomical structures"]'::jsonb, 'A ''coin-on-edge'' radiographic appearance (the collapse of the entire vertebral body', 'Vertebra plana (the ''Calve disease''): the most common cause in children is the eosinophilic granuloma (the ''LCH'').'),
('114b0989-98fd-5d6d-9726-1408720a8893'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Pott disease'' (the ''tuberculosis of the spine''):', '["A viral infection of the spine and its associated anatomical structures","A parasitic infection of the spine and its associated anatomical structures","A fungal infection of the spine and its associated anatomical structures","A pyogenic infection of the spine and its associated anatomical structures","The most common form of the ''skeletal tuberculosis'', affecting the lower thoracic and lumbar spin"]'::jsonb, 'The most common form of the ''skeletal tuberculosis'', affecting the lower thoracic and lumbar spin', 'Pott disease (the ''spinal TB''): the ''anterior'' vertebral body destruction, the ''paravertebral abscess'' (the ''cold abscess''), and the ''gibbus'' (the ''kyphotic'' deformity).'),
('10de7df0-6e17-587e-86f1-756a0ab26bcd'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Pott paraplegia'' is:', '["Paraplegia caused by a spinal tumor and its associated anatomical structures","Paraplegia caused by a spinal injury and its associated anatomical structures","Paraplegia caused by a spinal infection and its associated anatomical structures","Paraplegia caused by the compression of the spinal cord in Pott disease (the ''spinal TB''","Paraplegia caused by a herniated disc and its associated anatomical structures"]'::jsonb, 'Paraplegia caused by the compression of the spinal cord in Pott disease (the ''spinal TB''', 'Pott paraplegia (the ''early'' vs. ''late'' onset): the ''early'' type (reversible, from the inflammation) and the ''late'' type (irreversible, from the mechanical compression).'),
('0d2ae346-dd70-54e8-9e8b-81f9aedda245'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''pyogenic spondylodiscitis'' (the ''infection of the disc space''):', '["A fungal infection and its associated anatomical structures","A bacterial infection of the intervertebral disc and the adjacent vertebral bodies","A parasitic infection and its associated anatomical structures","A non-infectious inflammation and its associated anatomical structures","A viral infection and its associated anatomical structures"]'::jsonb, 'A bacterial infection of the intervertebral disc and the adjacent vertebral bodies', 'Pyogenic spondylodiscitis (the ''discitis''): the MRI shows the ''endplate'' edema and the ''paravertebral'' abscess.'),
('e2f00dbd-9d6f-5497-9761-c528730ab1a1'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''epidural abscess'' (the ''spinal epidural abscess''):', '["A collection of pus in the epidural space (a neurosurgical emergency, with the ''classic triad'' of","A collection of pus in the subdural space and its associated anatomical structures","A collection of pus in the subarachnoid space and its associated anatomical structures","A collection of pus in the paravertebral space and its associated anatomical structures","A collection of pus in the intramedullary space and its associated anatomical structures"]'::jsonb, 'A collection of pus in the epidural space (a neurosurgical emergency, with the ''classic triad'' of', 'The epidural abscess (the ''SEA''): the ''urgent'' decompression and the ''systemic'' antibiotics are needed.'),
('8a298cc6-d933-5da0-94f1-be08500a9fd9'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''spinal cord herniation'' (the ''idiopathic spinal cord herniation''):', '["A herniated disc and its associated anatomical structures","A rare condition in which the spinal cord is ''herniated'' through a defect in the dura","A spinal tumor and its associated anatomical structures","A spinal infection and its associated anatomical structures","A spinal injury and its associated anatomical structures"]'::jsonb, 'A rare condition in which the spinal cord is ''herniated'' through a defect in the dura', 'The spinal cord herniation (the ''transdural'' herniation): the MRI shows the ''kink'' or the ''C-shape'' of the spinal cord.'),
('f1cb212a-a363-57e8-bd75-95c317634fa9'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''tethered cord syndrome'' (the ''tethered conus''):', '["A congenital condition in which the conus medullaris is ''tethered'' (attached to the thecal sac","A herniated disc and its associated anatomical structures","A spinal tumor and its associated anatomical structures","A spinal infection and its associated anatomical structures","A spinal injury and its associated anatomical structures"]'::jsonb, 'A congenital condition in which the conus medullaris is ''tethered'' (attached to the thecal sac', 'The tethered cord syndrome (the ''low conus'', the ''conus below L2''): the ''release'' of the filum (the ''untethering'' surgery) is needed.'),
('59b3a2d5-8fef-570a-b047-b0da2c518cec'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''diastematomyelia'' (the ''split cord malformation''):', '["A spinal infection and its associated anatomical structures","A spinal injury and its associated anatomical structures","A spinal tumor and its associated anatomical structures","A congenital condition in which the spinal cord is ''split'' into 2 hemi-cords by a bony or a fibro","A herniated disc and its associated anatomical structures"]'::jsonb, 'A congenital condition in which the spinal cord is ''split'' into 2 hemi-cords by a bony or a fibro', 'Diastematomyelia (the ''split cord''): the ''type I'' (the ''double'' dural sac) and the ''type II'' (the ''single'' dural sac without the septum).'),
('ce1836b4-2d92-5292-bc90-30b82b87ab5e'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''myelomeningocele'' (the ''open neural tube defect''):', '["A herniated disc and its associated anatomical structures","A spinal injury and its associated anatomical structures","A spinal tumor and its associated anatomical structures","A spinal infection and its associated anatomical structures","The ''spina bifida aperta'', in which the ''neural tube'' (the spinal cord and the meninges"]'::jsonb, 'The ''spina bifida aperta'', in which the ''neural tube'' (the spinal cord and the meninges', 'Myelomeningocele (the ''open'' spinal dysraphism): the ''most severe'' form of the spina bifida (the ''Arnold-Chiari Type II'' malformation).'),
('7bec9a44-e2db-5395-8d65-563914eb7f0e'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''spina bifida occulta'' (the ''closed'' neural tube defect):', '["A spinal tumor and its associated anatomical structures","An open defect and its associated anatomical structures","A spinal injury and its associated anatomical structures","A herniated disc and its associated anatomical structures","A ''hidden'' defect of the vertebral arch (usually L5 or S1), with NO herniation of the neural tiss"]'::jsonb, 'A ''hidden'' defect of the vertebral arch (usually L5 or S1), with NO herniation of the neural tiss', 'Spina bifida occulta (the ''occult'' spinal dysraphism): often an incidental finding (the ''hair patch'', the ''sinus tract'', or the ''lipoma'' on the skin).'),
('f7968c2a-7fce-52d2-a04a-5861a77f3ec4'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''anterior sacral meningocele'':', '["A herniated disc and its associated anatomical structures","A herniation of the meninges through a defect in the anterior sacrum (a ''rare'' cause of a pelvic","A spinal tumor and its associated anatomical structures","A spinal infection and its associated anatomical structures","A spinal injury and its associated anatomical structures"]'::jsonb, 'A herniation of the meninges through a defect in the anterior sacrum (a ''rare'' cause of a pelvic', 'The anterior sacral meningocele (the ''ASM''): the ''scimitar sign'' on the X-ray of the pelvis.'),
('f18ce153-56e1-5edd-ad03-950048acf415'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''vertebral hemangioma'' (the ''hemangioma of the spine''):', '["An infection of the spine and its associated anatomical structures","A traumatic lesion of the spine and its associated anatomical structures","A malignant tumor of the spine and its associated anatomical structures","A metabolic lesion of the spine and its associated anatomical structures","A common, benign, ''vascular'' tumor of the vertebral body (the ''jail-bar'' or the ''polka-dot'' sign"]'::jsonb, 'A common, benign, ''vascular'' tumor of the vertebral body (the ''jail-bar'' or the ''polka-dot'' sign', 'The vertebral hemangioma (the ''VH''): an incidental finding in 10% of the autopsies. The aggressive type (the ''compressive'' type) may need a treatment.'),
('ec199162-0a39-5f98-bcaf-694e2b573bc3'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''vertebral metastasis'' (the ''metastatic'' tumor of the spine):', '["The SINISTER (the ''spinal'' +/- the ''neurologic'' deficit, the ''intractable'' pain","A metabolic bone disease of the spine and its associated anatomical structures","A primary bone tumor of the spine and its associated anatomical structures","An infection of the spine and its associated anatomical structures","A benign tumor of the spine and its associated anatomical structures"]'::jsonb, 'The SINISTER (the ''spinal'' +/- the ''neurologic'' deficit, the ''intractable'' pain', 'Vertebral metastasis (the ''spinal SECONDARY''): the most common tumors are the lung, the breast, the prostate, the kidney, and the thyroid.'),
('e40035ae-b64f-5a15-b112-b09e3a3c4ff2'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''multiple myeloma'' (the ''myeloma'' of the spine):', '["A metastatic tumor of the spine and its associated anatomical structures","A bone infection of the spine and its associated anatomical structures","A benign tumor of the spine and its associated anatomical structures","A primary bone tumor of the spine and its associated anatomical structures","A malignant, ''plasma cell'' tumor of the bone marrow (the ''lytic'' lesions"]'::jsonb, 'A malignant, ''plasma cell'' tumor of the bone marrow (the ''lytic'' lesions', 'Multiple myeloma (the ''Kahler disease''): the ''lytic'' lesions, the ''punched-out'' lesions, the ''crush'' fractures, the ''plasmacytoma''.'),
('3a6bbafc-5630-5e05-9f77-0274e495e20a'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''osteosarcoma'' (the ''osteogenic sarcoma'' of the spine):', '["A metabolic bone disease of the spine","A benign tumor of the spine","An infection of the spine","A MALIGNANT, ''primary'' bone tumor","A malignant tumor of the spine"]'::jsonb, 'A MALIGNANT, ''primary'' bone tumor', 'Osteosarcoma (the ''Osteogenic'' sarcoma): the ''most common'' primary malignant bone tumor in CHILDREN (the ''distal femur'', the ''proximal tibia'').'),
('b43b0401-62d0-5ba8-805f-ca58be3fe96d'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Ewing sarcoma'' (the ''Ewing tumor'' of the spine):', '["An infection of the spine and its associated anatomical structures","A MALIGNANT, ''small round cell'' tumor (the ''onion-skin'' or the ''lamellated'' periosteal reaction o","A metabolic bone disease of the spine and its associated anatomical structures","A malignant tumor of the spine and its associated anatomical structures","A benign tumor of the spine and its associated anatomical structures"]'::jsonb, 'A MALIGNANT, ''small round cell'' tumor (the ''onion-skin'' or the ''lamellated'' periosteal reaction o', 'Ewing sarcoma (the ''PNET''): the CD99+ (MIC2) is the immunohistochemical marker.'),
('3c6e9527-6c0e-5e91-af78-05154d11a1f9'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''chordoma'' (the ''notochordal'' tumor of the spine):', '["A malignant tumor of the spine and its associated anatomical structures","An infection of the spine and its associated anatomical structures","A benign tumor of the spine and its associated anatomical structures","A metabolic bone disease of the spine and its associated anatomical structures","A MALIGNANT, ''low-grade'' tumor arising from the ''notochordal'' remnants (the ''physaliphorous'' cells"]'::jsonb, 'A MALIGNANT, ''low-grade'' tumor arising from the ''notochordal'' remnants (the ''physaliphorous'' cells', 'Chordoma (the ''notochordal'' tumor): the ''brachyury'' is the immunohistochemical marker.'),
('5ec88567-1159-563a-a28a-471039aff655'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''osteoid osteoma'' (a benign bone tumor of the spine):', '["A malignant tumor of the spine and its associated anatomical structures","An infection of the spine and its associated anatomical structures","A metabolic bone disease of the spine and its associated anatomical structures","A traumatic lesion of the spine and its associated anatomical structures","A SMALL (<2 cm), benign, ''osteoid-forming'' tumor (the ''nidus'' on the CT scan"]'::jsonb, 'A SMALL (<2 cm), benign, ''osteoid-forming'' tumor (the ''nidus'' on the CT scan', 'The osteoid osteoma (the ''OO''): the ''nidus'' (the ''radiolucent'' center with the ''sclerotic'' margin) on the CT scan.'),
('dee90cf7-315b-5a46-933e-6b7d43cd965b'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''osteoblastoma'' (a benign bone tumor of the spine):', '["A different tumor from the osteoid osteoma","A LARGER (>2 cm) version of the osteoid osteoma","A malignant tumor of the spine","An infection of the spine","A metabolic bone disease of the spine"]'::jsonb, 'A LARGER (>2 cm) version of the osteoid osteoma', 'The osteoblastoma (the ''giant'' osteoid osteoma): the ''expansile'' and the ''aggressive'' type may need a surgical treatment.'),
('add2ce06-3f2f-53fc-ab9f-41b93346c971'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''osteoporosis'' (a metabolic bone disease of the spine):', '["A benign tumor of the spine","A malignant tumor of the spine","A ''decrease'' in the bone MASS","An infection of the spine","A traumatic lesion of the spine"]'::jsonb, 'A ''decrease'' in the bone MASS', 'Osteoporosis (the ''porous'' bone): the ''T-score'' of <-2.5 (the ''dual-energy X-ray absorptiometry'' (DEXA) scan).'),
('f912dbdd-fb90-513f-aa59-6641dbfd8078'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Paget disease of bone'' (the ''osteitis deformans''):', '["An infection of the bone and its associated anatomical structures","A malignant tumor of the bone and its associated anatomical structures","A traumatic lesion of the bone and its associated anatomical structures","A metabolic bone disease with the ''increased'' bone turnover","A benign tumor of the bone and its associated anatomical structures"]'::jsonb, 'A metabolic bone disease with the ''increased'' bone turnover', 'Paget disease (the ''osteitis deformans''): the ''alkaline phosphatase'' (ALP) is INCREASED. The ''sarcoma'' can develop in 1% of the cases.'),
('39520618-3937-5514-9c36-e6beac2bb9dd'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Paget disease of the spine'' (the ''vertebral Paget disease''):', '["A collapsed vertebra and its associated anatomical structures","A fracture of the vertebra and its associated anatomical structures","A lytic lesion of the vertebra and its associated anatomical structures","A normal vertebra and its associated anatomical structures","The ''picture frame'' vertebra (the ''thickened'' and the ''sclerotic'' cortex), the ''ivory'' vertebra"]'::jsonb, 'The ''picture frame'' vertebra (the ''thickened'' and the ''sclerotic'' cortex), the ''ivory'' vertebra', 'Paget disease (the ''vertebral Paget disease''): the ''pagetic'' bone is SOFT but THICKENED (the ''spinal stenosis'' is a common complication).'),
('20dcb70e-36ef-58ba-b2ae-63ae927e8b60'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''osteomalacia'' (a metabolic bone disease of the spine):', '["A benign tumor of the spine and its associated anatomical structures","A malignant tumor of the spine and its associated anatomical structures","The ''softening'' of the bone due to the ''inadequate'' MINERALIZATION of the osteoid (the ''rickets''","A traumatic lesion of the spine and its associated anatomical structures","An infection of the spine and its associated anatomical structures"]'::jsonb, 'The ''softening'' of the bone due to the ''inadequate'' MINERALIZATION of the osteoid (the ''rickets''', 'Osteomalacia (the ''Looser zones'' or the ''pseudofractures''): the ''vitamin D DEFICIENCY'' (the ''low'' 25-OH vitamin D).'),
('57ad31f8-c679-5817-b9eb-644c5a41ecdb'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''renal osteodystrophy'' (a metabolic bone disease of the spine):', '["A benign tumor of the spine and its associated anatomical structures","An infection of the spine and its associated anatomical structures","A malignant tumor of the spine and its associated anatomical structures","A ''high-turnover'' bone disease (the ''osteitis fibrosa cystica'') caused by the ''secondary'' hyperpa","A traumatic lesion of the spine and its associated anatomical structures"]'::jsonb, 'A ''high-turnover'' bone disease (the ''osteitis fibrosa cystica'') caused by the ''secondary'' hyperpa', 'Renal osteodystrophy (the ''rugger jersey'' spine): the ''sclerotic'' endplates with the ''lucent'' center (the ''alternating'' bands).'),
('e421dca5-886a-58fd-bf40-aa424877cfb3'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''rugger jersey'' spine sign is characteristic of:', '["Renal osteodystrophy (the ''alternating'' bands of increased and decreased bone density on the X-ra","Ankylosing spondylitis and its associated anatomical structures","Osteoporosis and its associated anatomical structures","Osteomalacia and its associated anatomical structures","Paget disease and its associated anatomical structures"]'::jsonb, 'Renal osteodystrophy (the ''alternating'' bands of increased and decreased bone density on the X-ra', 'The rugger jersey spine (the ''striped'' jersey of the rugby player) is a classic sign of renal osteodystrophy.'),
('bd94ee94-46b4-55b8-9f81-9be8e2161508'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''ivory'' vertebra sign is:', '["A ''malformation'' of the vertebra and its associated anatomical structures","A ''normal'' variant and its associated anatomical structures","A SINGLE, dense, ''white'' vertebra on the X-ray (indicating a ''sclerotic'' process: PAGET disease","A ''compression'' fracture and its associated anatomical structures","A ''lytic'' process and its associated anatomical structures"]'::jsonb, 'A SINGLE, dense, ''white'' vertebra on the X-ray (indicating a ''sclerotic'' process: PAGET disease', 'The ivory vertebra sign (the ''white'' vertebra): the most common causes are the ''Paget disease'' and the ''prostate'' or the ''breast'' METASTASIS.'),
('387b3ae4-8942-5092-b5de-ba83843758cb'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''rim'' sign (the ''hollow'' vertebral body):', '["A ''lytic'' lesion of the vertebra with the ''cortex'' intact (a ''geographic'' lysis of the vertebral","A ''benign'' lesion and its associated anatomical structures","A ''compression'' fracture and its associated anatomical structures","A ''malignant'' lesion and its associated anatomical structures","A ''sclerotic'' lesion and its associated anatomical structures"]'::jsonb, 'A ''lytic'' lesion of the vertebra with the ''cortex'' intact (a ''geographic'' lysis of the vertebral', 'The rim sign (the ''ABC'' or the ''GCT'' of the spine): the ''soap bubble'' appearance on the X-ray.'),
('a6a9b257-e993-52d8-82e4-45f9c10d6e5a'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''vertebra magna'' (a ''large'' vertebra):', '["A ''traumatic'' change and its associated anatomical structures","A ''normal'' variant and its associated anatomical structures","A ''congenital'' anomaly and its associated anatomical structures","A ''tumor'' of the spine and its associated anatomical structures","An ''enlarged'' vertebral body (due to a ''long-standing'' spondylolisthesis, a ''hemangioma''"]'::jsonb, 'An ''enlarged'' vertebral body (due to a ''long-standing'' spondylolisthesis, a ''hemangioma''', 'The vertebra magna (the ''large'' vertebra): the ''compensatory'' enlargement of a vertebra adjacent to a ''collapsed'' vertebra.'),
('a263bb52-a233-5e22-847a-ae0c0913a2ef'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''block vertebra'' (a ''fused'' vertebra):', '["A ''degenerative'' fusion and its associated anatomical structures","A ''traumatic'' fusion and its associated anatomical structures","A ''congenital'' fusion of TWO or MORE vertebrae","A ''infectious'' fusion and its associated anatomical structures","A ''tumor-related'' fusion and its associated anatomical structures"]'::jsonb, 'A ''congenital'' fusion of TWO or MORE vertebrae', 'The block vertebra (the ''congenital'' fusion): the Klippel-Feil syndrome (the ''short neck'', the ''low hairline'', the ''limited'' neck motion).'),
('66593b44-507e-5350-8431-93ee3a00e7ce'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''butterfly'' vertebra (a ''sagittal cleft'' vertebra):', '["A ''degenerative'' change of the vertebra and its associated anatomical structures","A ''traumatic'' fracture of the vertebra and its associated anatomical structures","A ''congenital'' anomaly in which the vertebral body is ''cleft'' in the sagittal plane (the ''butterf","A ''stress'' fracture of the vertebra and its associated anatomical structures","A ''tumor'' of the vertebra and its associated anatomical structures"]'::jsonb, 'A ''congenital'' anomaly in which the vertebral body is ''cleft'' in the sagittal plane (the ''butterf', 'The butterfly vertebra (the ''anterior'' rachischisis): an ''incidental'' finding. The ''butterfly'' shape is due to the ''persistent'' notochord.'),
('e5800e12-13bc-5603-b152-4525ed412f9a'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Klippel-Feil syndrome'' (the ''congenital fusion'' of the cervical vertebrae):', '["A ''degenerative'' fusion of the cervical spine and its associated anatomical structures","A ''congenital'' fusion of TWO or more CERVICAL vertebrae (the ''classic triad'': short neck","A ''traumatic'' fusion of the cervical spine and its associated anatomical structures","A ''tumor-related'' fusion of the cervical spine and its associated anatomical structures","A ''infectious'' fusion of the cervical spine and its associated anatomical structures"]'::jsonb, 'A ''congenital'' fusion of TWO or more CERVICAL vertebrae (the ''classic triad'': short neck', 'The Klippel-Feil syndrome: associated with the ''Sprengel deformity'' (the ''congenital'' elevation of the scapula), the ''scoliosis'', and the ''renal'' anomalies.'),
('ace8f5d9-8ec0-5ffa-aca1-7be7735c5c3d'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Sprengel deformity'' (the ''congenital'' elevation of the scapula):', '["A ''traumatic'' condition of the scapula and its associated anatomical structures","A ''congenital'' condition in which the scapula is ''high-riding'' (the ''omovertebral bone'' may conne","A ''degenerative'' condition of the scapula and its associated anatomical structures","A ''postural'' condition of the scapula and its associated anatomical structures","A ''tumor'' of the scapula and its associated anatomical structures"]'::jsonb, 'A ''congenital'' condition in which the scapula is ''high-riding'' (the ''omovertebral bone'' may conne', 'Sprengel deformity (the ''congenital'' high scapula): often associated with the ''Klippel-Feil syndrome''.'),
('d04ee84e-03aa-5aaf-9644-4485da212f96'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''atlantoaxial instability'' (the ''atlantodens interval'', ADI):', '["A measurement of the spinous processes and its associated anatomical structures","An INCREASE in the distance between the anterior arch of the Atlas and the dens of the Axis (>3 m","A measurement of the lateral joint and its associated anatomical structures","A measurement of the transverse processes and its associated anatomical structures","A measurement of the posterior joint and its associated anatomical structures"]'::jsonb, 'An INCREASE in the distance between the anterior arch of the Atlas and the dens of the Axis (>3 m', 'The ADI (the ''atlantodens interval''): a ''critical'' measurement on the LATERAL X-ray of the cervical spine (the ''flexion and extension'' views).'),
('999547ca-960a-5bc3-87aa-457623278039'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''space available for the cord'' (SAC) at the C1-C2 level:', '["The distance between the dens and the posterior arch of the Atlas (the ''mid-sagittal'' diameter of","The disc height and its associated anatomical structures","The ADI and its associated anatomical structures","The vertebral body height and its associated anatomical structures","The facet joint width and its associated anatomical structures"]'::jsonb, 'The distance between the dens and the posterior arch of the Atlas (the ''mid-sagittal'' diameter of', 'The SAC (the ''space available for the cord''): a SAC of < 13 mm at C1-C2 is associated with a ''high'' risk of a spinal cord injury.'),
('2a013a74-8192-52f2-9cd6-ace5daa0f70d'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Chamberlain line'' (a palato-occipital line for the ''basilar invagination''):', '["A line from the C2 to the C3 and its associated anatomical structures","A line from the occiput to the atlas and its associated anatomical structures","A line from the ''hard palate'' to the ''posterior margin of the foramen magnum'' (the ''odontoid tip''","A line from the occiput to the C2 and its associated anatomical structures","A line from the C1 to the C2 and its associated anatomical structures"]'::jsonb, 'A line from the ''hard palate'' to the ''posterior margin of the foramen magnum'' (the ''odontoid tip''', 'The Chamberlain line (the ''palato-occipital'' line): the ''standard'' for the diagnosis of the ''basilar invagination'' (the ''odontoid'' above the line).'),
('1ad58dfe-ef16-588c-be22-09720c8cd2a5'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''McRae line'' (the line of the foramen magnum):', '["A line between the ''anterior'' and the ''posterior'' margins of the foramen magnum (the ''odontoid'' s","A line from the hard palate to the C2 and its associated anatomical structures","A line from the occiput to the C2 and its associated anatomical structures","A line from the C1 to the C2 and its associated anatomical structures","A line from the C2 to the C3 and its associated anatomical structures"]'::jsonb, 'A line between the ''anterior'' and the ''posterior'' margins of the foramen magnum (the ''odontoid'' s', 'The McRae line (the ''line of the foramen magnum''): the odontoid tip ABOVE this line indicates the ''basilar invagination'' (the ''Chiari'' malformation).'),
('bb890973-4717-5fe1-af7f-df493cbf5cf4'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Wackenheim clivus-canal line'' (a line for the ''basilar invagination''):', '["A line from the C2 to the C3 and its associated anatomical structures","A line from the occiput to the C2 and its associated anatomical structures","A line from the occiput to the atlas and its associated anatomical structures","A line from the C1 to the C2 and its associated anatomical structures","A line along the ''clivus'' (the ''sloping'' surface of the occipital bone) and the ''spinal canal'' (t"]'::jsonb, 'A line along the ''clivus'' (the ''sloping'' surface of the occipital bone) and the ''spinal canal'' (t', 'The Wackenheim line (the ''clivus-canal'' line): the odontoid ANTERIOR to this line indicates the ''basilar invagination''.'),
('586359ba-144b-5efd-ac9b-83d4271238bf'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''basilar invagination'' (the ''atlanto-axial'' invagination):', '["An infection of the odontoid and its associated anatomical structures","The PROTRUSION of the ODONTOID process into the FORAMEN MAGNUM (a ''congenital'' or an ''acquired'' c","A fracture of the odontoid and its associated anatomical structures","A tumor of the odontoid and its associated anatomical structures","A dislocation of the C1-C2 joint and its associated anatomical structures"]'::jsonb, 'The PROTRUSION of the ODONTOID process into the FORAMEN MAGNUM (a ''congenital'' or an ''acquired'' c', 'Basilar invagination (the ''primary'' vs. the ''secondary'' type): the ''primary'' type (congenital) and the ''secondary'' type (Paget disease, rickets, osteomalacia).'),
('dd57a2cd-82af-5dad-b03c-2d1bd6816aae'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Chiari malformation'' (Type I, the ''cerebellar tonsillar ectopia''):', '["A herniated disc in the cervical spine and its associated anatomical structures","A traumatic injury of the posterior fossa and its associated anatomical structures","An infection of the posterior fossa and its associated anatomical structures","A tumor of the cerebellum and its associated anatomical structures","The ''herniation'' of the CEREBELLAR TONSILS (>5 mm below the foramen magnum"]'::jsonb, 'The ''herniation'' of the CEREBELLAR TONSILS (>5 mm below the foramen magnum', 'Chiari (Arnold-Chiari) malformation, Type I: the ''syringomyelia'' (a ''fluid-filled'' cavity in the spinal cord) is a common ASSOCIATED finding.'),
('ad3eba1e-bb7c-5c46-b0c7-4e8d3e6cf804'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''syringomyelia'' (a ''fluid-filled'' cavity in the spinal cord):', '["A herniated disc and its associated anatomical structures","A ''syrinx'' (a ''CSF-like'' cavity) in the CENTRAL gray matter of the SPINAL CORD (causing a ''cape-l","A spinal injury and its associated anatomical structures","A spinal tumor and its associated anatomical structures","A spinal infection and its associated anatomical structures"]'::jsonb, 'A ''syrinx'' (a ''CSF-like'' cavity) in the CENTRAL gray matter of the SPINAL CORD (causing a ''cape-l', 'Syringomyelia (the ''syrinx''): the ''CM-I'' is the most common associated condition. The MRI shows the ''dilated'' central canal.'),
('1b52edad-1457-5955-bcb1-9266d6362b89'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''syringobulbia'' (a ''syrinx'' in the MEDULLA):', '["A tumor of the medulla and its associated anatomical structures","An infection of the medulla and its associated anatomical structures","The ''extension'' of the syrinx into the MEDULLA (causing the ''bulbar'' symptoms: the dysphagia","A herniated disc in the cervical spine and its associated anatomical structures","A traumatic injury of the medulla and its associated anatomical structures"]'::jsonb, 'The ''extension'' of the syrinx into the MEDULLA (causing the ''bulbar'' symptoms: the dysphagia', 'Syringobulbia (the ''syrinx'' in the medulla): the ''deficit'' in the medullary cranial nerve nuclei (CN IX, X, XI, XII).'),
('680f758f-7151-57df-a4b7-e7eda995e08f'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The vertebral column in the sagittal plane has how many curves?', '["4","2","3","5","6"]'::jsonb, '4', 'The vertebral column has 4 curves: cervical lordosis, thoracic kyphosis, lumbar lordosis, and sacral kyphosis.'),
('300a5328-8921-57b1-8834-f1c818086500'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The secondary curves of the vertebral column develop due to:', '["Genetic programming","Hormonal influences","Intrauterine positioning","Erect posture and bipedal locomotion","Nutritional factors"]'::jsonb, 'Erect posture and bipedal locomotion', 'Cervical lordosis develops with head lifting and lumbar lordosis with standing/walking.'),
('bc91e4e1-4046-5286-a817-ea727d0f97cd'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The intervertebral discs are absent between which vertebrae?', '["T1-T2","C1-C2","All cervical vertebrae","C2-C3","L5-S1"]'::jsonb, 'C1-C2', 'There is no intervertebral disc between the atlas (C1) and axis (C2).'),
('e52a6a1f-5067-5357-b7cf-648175f0d053'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The uncovertebral joints (joints of Luschka) are found in:', '["The coccyx","The lumbar spine","The cervical spine","The sacrum","The thoracic spine"]'::jsonb, 'The cervical spine', 'Uncovertebral joints are small synovial joints between the uncinate processes of cervical vertebrae.'),
('5e80e2e5-7d0a-538b-8540-861019c209d6'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The uncinate processes are found on:', '["The superior surface of cervical vertebral bodies","The spinous processes and its associated anatomical structures","The pedicles and its associated anatomical structures","The laminae and its associated anatomical structures","The transverse processes and its associated anatomical structures"]'::jsonb, 'The superior surface of cervical vertebral bodies', 'Uncinate processes project upward from the posterolateral margins of cervical vertebral bodies.'),
('7bd4ad8e-4b36-5e9e-b473-8ad627cd3170'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The zygapophyseal (facet) joints are:', '["Synovial joints between superior and inferior articular processes of adjacent vertebrae","Syndesmoses and its associated anatomical structures","Symphyses and its associated anatomical structures","Cartilaginous joints and its associated anatomical structures","Fibrous joints and its associated anatomical structures"]'::jsonb, 'Synovial joints between superior and inferior articular processes of adjacent vertebrae', 'Facet joints are diarthrodial (synovial) joints that guide and limit spinal motion.'),
('d9e98c83-aaca-52b7-a990-8edb05103a33'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The lumbosacral angle is the angle between:', '["The cervical spine and the thoracic spine","The thoracic spine and the lumbar spine","The sacrum and the coccyx","The lumbar spine and the femur","The long axis of the lumbar spine and the sacrum"]'::jsonb, 'The long axis of the lumbar spine and the sacrum', 'The lumbosacral angle (lumbosacral kyphosis) is important in assessing spinal balance.'),
('e938fd72-a06a-5a6f-b8e1-80978ab7eb29'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The sacralization of L5 is:', '["A tumor of L5 and its associated anatomical structures","The fusion of the L5 transverse process to the sacrum","A dislocation of L5 and its associated anatomical structures","An infection of L5 and its associated anatomical structures","A fracture of L5 and its associated anatomical structures"]'::jsonb, 'The fusion of the L5 transverse process to the sacrum', 'Sacralization (transitional vertebra) can cause biomechanical changes and low back pain.'),
('5c89fcf5-5548-58ce-baa0-ccb40928eb9c'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The lumbarization of S1 is:', '["A dislocation of S1 and its associated structures","A tumor of S1 and its associated structures","A fracture of S1 and its associated structures","The separation of S1 from the sacrum","An infection of S1 and its associated structures"]'::jsonb, 'The separation of S1 from the sacrum', 'Lumbarization is a congenital anomaly where S1 fails to fuse with the rest of the sacrum.'),
('a24951cf-9474-5075-9213-47c2daf5c95f'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The absolute canal stenosis is defined as:', '["A spinal canal diameter of <8 mm","A spinal canal diameter of <12 mm","A spinal canal diameter of <6 mm","A spinal canal diameter of <14 mm","A spinal canal diameter of <10 mm"]'::jsonb, 'A spinal canal diameter of <10 mm', 'Absolute spinal stenosis is <10 mm; relative stenosis is 10-13 mm on MRI.'),
('eaf6d19f-7f64-5808-98f2-fc02660c361a'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The normal sagittal diameter of the cervical spinal canal is:', '["14-16 mm","17-18 mm","20-22 mm","10-12 mm","12-14 mm"]'::jsonb, '17-18 mm', 'A sagittal diameter <13 mm in the cervical spine indicates stenosis.'),
('00f98d20-ef7d-5185-b857-c0ba038e4bb4'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The normal sagittal diameter of the lumbar spinal canal is:', '["25-30 mm","12-14 mm","14-16 mm","15-25 mm","10-12 mm"]'::jsonb, '15-25 mm', 'The lumbar spinal canal is wider than the cervical and thoracic canals.'),
('3f1d97bd-5f1a-5f68-a93a-d0c74dc14025'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ligamentum flavum is thickest in:', '["The cervical spine","The coccyx","The sacrum","The lumbar spine","The thoracic spine"]'::jsonb, 'The lumbar spine', 'The ligamentum flavum is thickest in the lumbar region and hypertrophies with age.'),
('d8225c75-ca6d-53d9-a756-d4a0c4149d07'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The iliolumbar ligament connects:', '["The L1-L2 transverse processes","The sacrum to the ilium","The L5-S1 facet joint","The L5 vertebra to the coccyx","The L4-L5 transverse processes to the iliac crest"]'::jsonb, 'The L4-L5 transverse processes to the iliac crest', 'The iliolumbar ligament stabilizes the lumbosacral junction.'),
('8b5f3365-509a-51d3-b89d-b11abc8e372d'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The sacrotuberous ligament connects:', '["The sacrum to the femur","The sacrum to the pubis","The sacrum to the ilium","The sacrum to the coccyx","The sacrum to the ischial tuberosity"]'::jsonb, 'The sacrum to the ischial tuberosity', 'The sacrotuberous ligament (along with the sacrospinous ligament) converts the sciatic notch into the greater and lesser sciatic foramina.'),
('6940f9b4-dc32-554f-8b32-00bcd799304c'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The sacrospinous ligament connects:', '["The sacrum to the femur","The sacrum to the coccyx","The sacrum to the ischial tuberosity","The sacrum to the pubis","The sacrum to the ischial spine"]'::jsonb, 'The sacrum to the ischial spine', 'The sacrospinous ligament divides the sciatic notch into greater and lesser sciatic foramina.'),
('45d4f0c0-cdc9-5e25-8d34-792458e26cc6'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The greater sciatic foramen transmits:', '["The piriformis muscle, the sciatic nerve, the superior and inferior gluteal vessels and nerves","The common peroneal nerve and its associated anatomical structures","The saphenous nerve and its associated anatomical structures","The obturator nerve and its associated anatomical structures","The femoral nerve and its associated anatomical structures"]'::jsonb, 'The piriformis muscle, the sciatic nerve, the superior and inferior gluteal vessels and nerves', 'The greater sciatic foramen is the major gateway between the pelvis and the gluteal region.'),
('5361f946-50b8-58a5-8cc4-65478b1bdbea'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'In a surgical context, The lesser sciatic foramen transmits:', '["The sciatic nerve and its associated anatomical structures","The obturator internus tendon, the pudendal nerve, and the internal pudendal vessels","The femoral nerve and its associated anatomical structures","The gluteal nerves and its associated anatomical structures","The piriformis muscle and its associated anatomical structures"]'::jsonb, 'The obturator internus tendon, the pudendal nerve, and the internal pudendal vessels', 'The lesser sciatic foramen connects the gluteal region to the perineum.'),
('f04abfed-8388-5402-995e-f3195b5db124'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The most common level for a lumbar puncture is:', '["T12-L1","L2-L3","L1-L2","L3-L4 or L4-L5","L5-S1"]'::jsonb, 'L3-L4 or L4-L5', 'Lumbar puncture is performed at L3-L4 or L4-L5 to avoid the conus medullaris at L1-L2.'),
('ff15288c-9ba7-5990-a40a-557e107e2345'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The CSF pressure in the lumbar cistern in the lateral decubitus position is:', '["30-40 cm H2O","40-50 cm H2O","5-10 cm H2O","10-20 cm H2O","20-30 cm H2O"]'::jsonb, '10-20 cm H2O', 'Normal CSF opening pressure is 10-20 cm H2O (lateral decubitus position).'),
('58c55657-e43b-5ece-bde3-f8c055f9ac89'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The Queckenstedt test (jugular compression test) assesses:', '["The function of the spinal nerves","The patency of the vertebral artery","The patency of the carotid artery","The patency of the spinal subarachnoid space","The function of the cranial nerves"]'::jsonb, 'The patency of the spinal subarachnoid space', 'The Queckenstedt test: compression of the jugular veins increases the CSF pressure; lack of rise indicates a block in the spinal canal.'),
('495edc4e-854c-5bb3-9ba6-e11c686a7d7a'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The conus medullaris contains the spinal segments:', '["T1-L1 and its associated structures","S1-S2 and its associated structures","C1-T1 and its associated structures","S2-S5 and the coccygeal segments","L1-L5 and its associated structures"]'::jsonb, 'S2-S5 and the coccygeal segments', 'The conus medullaris contains the sacral and coccygeal segments of the spinal cord.'),
('f78ffe78-9875-5208-94af-9f0657872381'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The cauda equina syndrome is most commonly caused by:', '["An epidural abscess of the thoracic spine","A thoracic disc herniation","A cervical disc herniation","A large central L4-L5 or L5-S1 disc herniation","A spinal tumor of the cervical region"]'::jsonb, 'A large central L4-L5 or L5-S1 disc herniation', 'Cauda equina syndrome is a surgical emergency requiring decompression within 24-48 hours.'),
('d77f5b7d-2a9c-5e78-b351-bcd49ba6352b'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''red flag'' for cauda equina syndrome includes:', '["Unilateral leg pain and its associated anatomical structures","Neck pain and its associated anatomical structures","Headache and its associated anatomical structures","Saddle anesthesia, bladder/bowel dysfunction, and bilateral sciatica","Shoulder pain and its associated anatomical structures"]'::jsonb, 'Saddle anesthesia, bladder/bowel dysfunction, and bilateral sciatica', 'Saddle anesthesia (perineal numbness) is the most sensitive sign of cauda equina compression.'),
('84161c21-cde0-5e46-ad25-1b5e28f7e791'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The C6 nerve root exits the spinal canal:', '["Through the C7-T1 foramen","Through the C6-C7 disc","Below the C6 vertebra","Through the C5-C6 disc","Above the C6 vertebra"]'::jsonb, 'Above the C6 vertebra', 'Cervical roots exit above the pedicle of the same-numbered vertebra; C8 exits below C7.'),
('e6396d46-7d7d-53cd-9c76-a5a7cc95c53b'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The T1 nerve root exits the spinal canal:', '["Through the T1-T2 disc","Through the T2-T3 foramen","Below the T1 vertebra","Through the C7-T1 disc","Above the T1 vertebra"]'::jsonb, 'Below the T1 vertebra', 'Thoracic nerve roots exit below the corresponding vertebra.'),
('af1e3b82-e1db-5f5b-b2c2-1cdeb1138afa'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The L5 nerve root exits the spinal canal:', '["Through the L3-L4 foramen","Above the L5 vertebra","Below the L5 vertebra","Through the L5-S1 disc","Through the L4-L5 disc"]'::jsonb, 'Below the L5 vertebra', 'L5 nerve root exits at L5-S1 foramen; the L4 nerve root exits at L4-L5.'),
('248eb343-afd5-5eaf-b346-b5b215d75922'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The most common level of cervical disc herniation is:', '["C3-C4","C6-C7","C4-C5","C7-T1","C5-C6"]'::jsonb, 'C5-C6', 'C5-C6 and C6-C7 account for the majority of cervical disc herniations.'),
('ea5cca94-3e5d-5c53-916b-83009cc93051'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The most common level of lumbar disc herniation is:', '["L3-L4","L1-L2","L2-L3","L4-L5 (L5 root) and L5-S1","T12-L1"]'::jsonb, 'L4-L5 (L5 root) and L5-S1', 'L4-L5 and L5-S1 account for >90% of lumbar disc herniations.'),
('58cad8f3-ffea-5be6-b631-7aff8c33802a'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'A herniated disc at L4-L5 typically compresses which nerve root?', '["L2","S1","L3","L4","L5"]'::jsonb, 'L5', 'The L4-L5 disc herniation compresses the L5 root (which exits at L5-S1), not the L4 root.'),
('5942efbb-811a-5093-807a-11deb21f1bb3'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'A herniated disc at L5-S1 typically compresses which nerve root?', '["L5","S1","L4","S2","L3"]'::jsonb, 'S1', 'The L5-S1 disc herniation compresses the S1 nerve root (exiting at S1-S2).'),
('450b5d45-92f5-5221-aee2-4fc55bb73024'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''far lateral'' disc herniation in the lumbar spine compresses:', '["The conus medullaris","The nerve root at the level below","The nerve root at two levels below","The nerve root at the same level","The cauda equina"]'::jsonb, 'The nerve root at the same level', 'Far lateral disc herniations compress the nerve root at the same level (the exiting root), unlike the typical posterolateral herniation.'),
('4220e9e1-0b54-5b19-a337-eb1223a67cd8'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''central'' disc herniation in the lumbar spine may cause:', '["Compression of the conus medullaris","Cauda equina syndrome","Spondylolisthesis","Spinal stenosis","Compression of a single nerve root"]'::jsonb, 'Cauda equina syndrome', 'A large central disc herniation can compress the cauda equina, causing bowel and bladder dysfunction.'),
('452bb4c5-bdfc-596b-bdfb-be7cba033abb'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''annular tear'' (a tear in the annulus fibrosus) is:', '["A tear of the PLL","A herniation of the nucleus pulposus","A tear of the ligamentum flavum","A fracture of the vertebral body","A disruption of the collagen fibers of the annulus"]'::jsonb, 'A disruption of the collagen fibers of the annulus', 'Annular tears (high-intensity zones, HIZ, on T2 MRI) are associated with discogenic low back pain.'),
('68c7d897-ddf1-5e59-bad7-33ce1baa49da'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''disc protrusion'' (a type of disc herniation) involves:', '["The nucleus pulposus extruding through the PLL and its associated anatomical structures","The expansion of the annulus without rupture and its associated anatomical structures","The nucleus pulposus detaching as a free fragment and its associated anatomical structures","The nucleus pulposus protruding through a tear in the annulus but remaining contained by the PLL","The complete collapse of the disc space and its associated anatomical structures"]'::jsonb, 'The nucleus pulposus protruding through a tear in the annulus but remaining contained by the PLL', 'Disc protrusion is a broad-based herniation with the outer annulus intact.'),
('aa92ea33-6f49-5aa0-9397-5b9da5558155'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''disc extrusion'' (a type of disc herniation) involves:', '["The migration of the disc away from the space","The disc space collapse","The annular tear without herniation","The nucleus pulposus contained by the annulus","The nucleus pulposus extruding through a tear in the annulus and the PLL"]'::jsonb, 'The nucleus pulposus extruding through a tear in the annulus and the PLL', 'Disc extrusion is a focal herniation through the PLL, often causing nerve root compression.'),
('844624c0-64ad-56a0-b3c2-c45c06340a2d'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''disc sequestration'' (a type of disc herniation) involves:', '["A disc bulge and its associated anatomical structures","A contained herniation and its associated anatomical structures","An annular tear and its associated anatomical structures","A free fragment of the nucleus pulposus that has separated from the disc and migrated into the sp","A disc protrusion and its associated anatomical structures"]'::jsonb, 'A free fragment of the nucleus pulposus that has separated from the disc and migrated into the sp', 'Sequestration (free fragment) may migrate cranially or caudally within the spinal canal.'),
('35d855b7-16d9-5d91-882f-8f15f3856f17'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Modic changes'' (endplate changes on MRI) indicate:', '["A fracture of the endplate","A tumor of the endplate","A herniated disc","Degenerative changes in the vertebral endplates","An infection of the endplate"]'::jsonb, 'Degenerative changes in the vertebral endplates', 'Modic changes are associated with degenerative disc disease and low back pain.'),
('d78a1104-c273-5598-8d93-edff4c02137a'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''high-intensity zone'' (HIZ) in the annulus fibrosus on T2 MRI indicates:', '["An annular tear","A vertebral hemangioma","An endplate fracture","A Modic change","A disc herniation"]'::jsonb, 'An annular tear', 'The HIZ sign has high specificity (>90%) for a painful disc (discography-positive).'),
('ea5aa1fe-06fd-57a0-b911-bf5953333692'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''vacuum disc phenomenon'' on X-ray or CT indicates:', '["A congenital anomaly of the disc","Gas (nitrogen) accumulation within the disc space","A disc infection","A fracture through the disc","A disc herniation"]'::jsonb, 'Gas (nitrogen) accumulation within the disc space', 'The vacuum disc sign is a classic finding of degenerative disc disease (the ''gas'' within the disc).'),
('41653bfb-82b9-5307-82e9-49b19b1df5ef'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''cocktail vertebra'' sign on PET-CT:', '["A congenital anomaly and its associated anatomical structures","A normal variant and its associated anatomical structures","A sign of osteoporosis and its associated anatomical structures","A ''cold'' vertebra and its associated anatomical structures","A ''hot'' vertebra (increased FDG uptake) due to metastasis, infection, or fracture"]'::jsonb, 'A ''hot'' vertebra (increased FDG uptake) due to metastasis, infection, or fracture', 'The cocktail vertebra sign indicates a hypermetabolic lesion in the spine.'),
('12a3e77d-b3d3-5f01-bbea-f0730be0f850'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''vertebral scalloping'' (the ''scalloping'' of the posterior vertebral body) is associated with:', '["A fracture","An infection","A rapid-growing tumor","A slow-growing intraspinal tumor","A degenerative change"]'::jsonb, 'A slow-growing intraspinal tumor', 'Posterior vertebral scalloping is a ''pressure erosion'' from long-standing intraspinal mass.'),
('f7b2dbee-fcac-50e1-b014-0b58dd02e2d6'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''anterior vertebral scalloping'' is associated with:', '["A congenital anomaly","An intraspinal tumor","Abdominal aortic aneurysm","An infection","A fracture"]'::jsonb, 'Abdominal aortic aneurysm', 'Anterior vertebral scalloping can also be seen in neurofibromatosis and Marfan syndrome.'),
('a46e77ef-357d-573b-a6eb-0d61170f99d8'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''neurofibromatosis'' (NF1, von Recklinghausen disease) spinal manifestations include:', '["Kyphosis only and its associated anatomical structures","Scoliosis only and its associated anatomical structures","Fractures and its associated anatomical structures","Dural ectasia, posterior vertebral scalloping, and ''dumbbell'' neurofibromas","Spondylolisthesis and its associated anatomical structures"]'::jsonb, 'Dural ectasia, posterior vertebral scalloping, and ''dumbbell'' neurofibromas', 'NF1 has characteristic spinal findings: scalloping, kyphoscoliosis, and dumbbell-shaped nerve sheath tumors.'),
('dbe21f6c-c788-5ed2-87e4-dda8cb6f0f40'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''dural ectasia'' (a ''ballooning'' of the dural sac) is characteristic of:', '["Rheumatoid arthritis and its associated anatomical structures","Paget disease and its associated anatomical structures","Ankylosing spondylitis and its associated anatomical structures","Osteoporosis and its associated anatomical structures","Neurofibromatosis (NF1) and Marfan syndrome"]'::jsonb, 'Neurofibromatosis (NF1) and Marfan syndrome', 'Dural ectasia (widening of the dural sac) causes posterior vertebral scalloping and widening of the spinal canal.'),
('39d94456-a137-5ccf-a0a4-dcf7023755e5'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Marfan syndrome'' spinal manifestations include:', '["Osteosclerosis and its associated anatomical structures","Osteoporosis and its associated anatomical structures","Osteomalacia and its associated anatomical structures","Paget disease and its associated anatomical structures","Dural ectasia, scoliosis, and spondylolisthesis"]'::jsonb, 'Dural ectasia, scoliosis, and spondylolisthesis', 'Marfan syndrome patients have a high prevalence of scoliosis and dural ectasia.'),
('31998ea5-3cbf-58c3-ad23-2700fc9435b2'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''achondroplasia'' (a form of dwarfism) spinal manifestations include:', '["Osteosclerosis and its associated anatomical structures","Spinal stenosis (a ''narrow'' spinal canal), thoracolumbar kyphosis, and a ''bullet-shaped'' vertebra","An enlarged spinal canal and its associated anatomical structures","Osteoporosis and its associated anatomical structures","A wide spinal canal and its associated anatomical structures"]'::jsonb, 'Spinal stenosis (a ''narrow'' spinal canal), thoracolumbar kyphosis, and a ''bullet-shaped'' vertebra', 'Achondroplasia patients have a congenitally narrowed spinal canal (a ''small'' spinal canal).'),
('c949a5dd-4caa-5df6-a98c-30e13bcea4b6'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Down syndrome'' (trisomy 21) spinal manifestations include:', '["Kyphosis","Osteoporosis","Scoliosis","Atlantoaxial instability","Spinal stenosis"]'::jsonb, 'Atlantoaxial instability', 'Children with Down syndrome should be screened for atlantoaxial instability before participating in sports.'),
('434495c7-bc50-5372-bb3b-c4739a144771'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''rheumatoid arthritis'' (RA) of the cervical spine most commonly causes:', '["Sacral fracture","Coccyx fracture","Thoracic kyphosis","Lumbar spinal stenosis","Atlantoaxial instability"]'::jsonb, 'Atlantoaxial instability', 'RA causes the erosion of the transverse ligament of the atlas, leading to C1-C2 instability.'),
('620aa4c2-cba2-5353-a0d2-ac6c156a5854'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''vertical subluxation'' (the ''cranial settling'') in rheumatoid arthritis:', '["The ''migration'' of the odontoid process into the foramen magnum","The ''anterior'' subluxation of C1 on C2","The ''rotatory'' subluxation of C1 on C2","The ''posterior'' subluxation of C1 on C2","The ''lateral'' subluxation of C1 on C2"]'::jsonb, 'The ''migration'' of the odontoid process into the foramen magnum', 'Cranial settling (the ''vertical translocation'') is the most dangerous type of RA instability.'),
('d14c2e52-dac6-5514-bca5-e1c34c8703ae'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''subaxial subluxation'' (in RA):', '["A deformity of the C1-C2 joint and its associated anatomical structures","A deformity of the sacrum and its associated anatomical structures","A deformity of the lumbar spine and its associated anatomical structures","The ''step-ladder'' deformity of the C3-C7 subaxial cervical spine","A deformity of the thoracic spine and its associated anatomical structures"]'::jsonb, 'The ''step-ladder'' deformity of the C3-C7 subaxial cervical spine', 'Subaxial subluxation (the ''staircase'' sign) is a late finding in rheumatoid arthritis.'),
('1b8b8227-93ce-5e49-aef4-d293172adf75'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''cervical myelopathy'' (the ''myelopathy hand''):', '["Loss of motor function of the lower limb","Loss of sensory function of the hand","The loss of fine motor control of the hand","Loss of autonomic function","Loss of cranial nerve function"]'::jsonb, 'The loss of fine motor control of the hand', 'The myelopathy hand (the ''Claw hand'') is a sign of severe cervical cord compression.'),
('a20737c8-4ab2-5e7b-844d-2b81de47cfab'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''finger escape sign'' (the ''Wartenberg sign''):', '["The inability to flex the little finger","The inability to extend the little finger","The inability to ADDUCT the little finger","The inability to oppose the thumb","The inability to abduct the little finger"]'::jsonb, 'The inability to ADDUCT the little finger', 'The finger escape sign (the ''Wartenberg sign'') is a classic sign of cervical myelopathy.'),
('d88d9c42-c185-5a3d-8732-1f833deedc1f'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''grip and release test'' (the ''10-second test''):', '["A test of the triceps strength and its associated anatomical structures","A test of the wrist flexion and its associated anatomical structures","The patient opens and closes the fist 20 times in 10 seconds (a ''normal'' result","A test of the grip strength and its associated anatomical structures","A strength test of the biceps and its associated anatomical structures"]'::jsonb, 'The patient opens and closes the fist 20 times in 10 seconds (a ''normal'' result', 'The grip and release test is a simple, bedside screen for cervical myelopathy.'),
('84bb1c7d-08e0-5ad1-922c-fdc498ed6e06'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Hoffmann sign'' is elicited by:', '["Tapping the patellar tendon and its associated anatomical structures","Stroking the lateral sole of the foot and its associated anatomical structures","Tapping the Achilles tendon and its associated anatomical structures","Stroking the palm of the hand and its associated anatomical structures","Flicking the volar surface of the middle finger (a positive sign is the flexion of the thumb and"]'::jsonb, 'Flicking the volar surface of the middle finger (a positive sign is the flexion of the thumb and', 'Hoffmann sign (the ''finger jerk'') is an UMN sign that indicates cervical cord compression.'),
('ce6ce1fb-b7c7-5639-8c95-383e5ef8bde6'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''inverted radial reflex'' (the ''inverted brachioradialis reflex''):', '["Elbow extension and its associated anatomical structures","Wrist extension and its associated anatomical structures","Elbow flexion and its associated anatomical structures","Finger FLEXION (not elbow flexion) when the brachioradialis tendon is tapped (indicating a C5-C6","Shoulder abduction and its associated anatomical structures"]'::jsonb, 'Finger FLEXION (not elbow flexion) when the brachioradialis tendon is tapped (indicating a C5-C6', 'The inverted radial reflex indicates a C5-C6 segmental lesion with UMN findings below.'),
('24374a49-1b8f-5174-b14e-ad4b1755d11b'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Babinski sign'' in the upper limb is called:', '["The ''clonus''","The ''Hoffmann sign''","The ''inverted radial reflex''","The ''finger escape sign''","The ''grip and release test''"]'::jsonb, 'The ''Hoffmann sign''', 'The Hoffmann sign is considered the upper limb equivalent of the Babinski sign.'),
('f8b0e783-1d9f-5d34-ae43-d24c8eb43477'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''crossed adductor reflex'' (the ''crossed adductor jerk''):', '["The ADDUCTION of the contralateral (opposite) thigh when the patellar tendon is tapped (indicatin","The abduction of the contralateral thigh and its associated anatomical structures","The flexion of the contralateral knee and its associated anatomical structures","The extension of the contralateral knee and its associated anatomical structures","The adduction of the ipsilateral thigh and its associated anatomical structures"]'::jsonb, 'The ADDUCTION of the contralateral (opposite) thigh when the patellar tendon is tapped (indicatin', 'The crossed adductor reflex is a sign of UMN lesion (the ''corticospinal tract'' involvement).'),
('21612a15-c71a-57d1-bcab-6210b616fb37'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''pendular knee jerk'' (the ''swinging'' patellar reflex) is characteristic of:', '["An LMN lesion","A sensory lesion","A basal ganglia lesion","A CEREBELLAR lesion","An UMN lesion"]'::jsonb, 'A CEREBELLAR lesion', 'The pendular knee jerk (the ''hung-up'' or the ''swinging'' reflex) is seen in cerebellar disease.'),
('4910832c-e7dd-546a-a0b0-6fb280921a99'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''spinal level'' of the C5 root is MOST tested by:', '["The triceps and its associated anatomical structures","The wrist extensors and its associated anatomical structures","The finger flexors and its associated anatomical structures","The deltoid (shoulder abduction) and the biceps","The hand intrinsics and its associated anatomical structures"]'::jsonb, 'The deltoid (shoulder abduction) and the biceps', 'C5: deltoid (axillary nerve) and biceps (musculocutaneous nerve) are the key muscles.'),
('b41cea1a-1bc1-590a-b7ad-9b361af45df0'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''spinal level'' of the C6 root is MOST tested by:', '["The deltoid and its associated anatomical structures","The finger flexors and its associated anatomical structures","The extensor carpi radialis longus and brevis (wrist extension) and the biceps","The triceps and its associated anatomical structures","The hand intrinsics and its associated anatomical structures"]'::jsonb, 'The extensor carpi radialis longus and brevis (wrist extension) and the biceps', 'C6: wrist extension (radial nerve) and supination are the key motor functions.'),
('85f0787f-1155-5483-95f6-2786fa6bd19a'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''spinal level'' of the C7 root is MOST tested by:', '["The deltoid and its associated anatomical structures","The finger extensors and its associated anatomical structures","The biceps and its associated anatomical structures","The triceps (elbow extension) and the flexor carpi radialis","The hand intrinsics and its associated anatomical structures"]'::jsonb, 'The triceps (elbow extension) and the flexor carpi radialis', 'C7: triceps (radial nerve) and wrist/finger flexion are the key motor functions.'),
('6e94aae5-71ec-5f77-90fc-2f58e0c51d14'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''spinal level'' of the C8 root is MOST tested by:', '["The flexor digitorum profundus (the ''finger flexion'') and the hand intrinsics","The wrist extensors and its associated anatomical structures","The biceps and its associated anatomical structures","The triceps and its associated anatomical structures","The deltoid and its associated anatomical structures"]'::jsonb, 'The flexor digitorum profundus (the ''finger flexion'') and the hand intrinsics', 'C8: finger flexion (the ''grip strength'') and the intrinsic hand muscles (T1).'),
('03112195-9f5c-51af-9e83-fbda57f72f38'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''spinal level'' of the T1 root is MOST tested by:', '["The triceps and its associated anatomical structures","The interossei (finger abduction/adduction) and the abductor pollicis brevis","The wrist extensors and its associated anatomical structures","The biceps and its associated anatomical structures","The deltoid and its associated anatomical structures"]'::jsonb, 'The interossei (finger abduction/adduction) and the abductor pollicis brevis', 'T1: the intrinsic hand muscles (the ''ulnar'' and the ''median'' innervated muscles).'),
('732403d5-da82-5f18-b3a9-d5a6313835c2'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''spinal level'' of the L2 root is MOST tested by:', '["The gastrocnemius","The tibialis anterior","The quadriceps","The iliopsoas","The extensor hallucis longus"]'::jsonb, 'The iliopsoas', 'L2/L3: hip flexion (the ''iliopsoas'' muscle, innervated by the femoral nerve).'),
('09538e25-b7ca-5be9-b3a8-e4af80dd71b3'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''spinal level'' of the L3 root is MOST tested by:', '["The gluteus maximus","The gastrocnemius","The extensor hallucis longus","The tibialis anterior","The quadriceps (knee extension) and the iliopsoas"]'::jsonb, 'The quadriceps (knee extension) and the iliopsoas', 'L3/L4: knee extension (the ''quadriceps'' muscle, innervated by the femoral nerve).'),
('a9bb234e-130a-54a9-8def-1771e3cf959e'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''spinal level'' of the L4 root is MOST tested by:', '["The iliopsoas and its associated anatomical structures","The tibialis anterior (ankle dorsiflexion) and the quadriceps","The extensor hallucis longus and its associated anatomical structures","The gluteus maximus and its associated anatomical structures","The gastrocnemius and its associated anatomical structures"]'::jsonb, 'The tibialis anterior (ankle dorsiflexion) and the quadriceps', 'L4: ankle dorsiflexion (tibialis anterior, deep peroneal nerve) and knee extension.'),
('5601602c-6b37-5d98-9b3c-e691b268fec6'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''spinal level'' of the L5 root is MOST tested by:', '["The extensor hallucis longus (great toe extension) and the gluteus medius","The gluteus maximus and its associated anatomical structures","The iliopsoas and its associated anatomical structures","The gastrocnemius and its associated anatomical structures","The quadriceps and its associated anatomical structures"]'::jsonb, 'The extensor hallucis longus (great toe extension) and the gluteus medius', 'L5: great toe extension (EHL, deep peroneal nerve) and hip abduction (gluteus medius).'),
('3ad2174b-9d61-51e0-b989-5901d8d2e28b'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''spinal level'' of the S1 root is MOST tested by:', '["The gastrocnemius/soleus (ankle plantarflexion) and the gluteus maximus","The tibialis anterior and its associated anatomical structures","The iliopsoas and its associated anatomical structures","The extensor hallucis longus and its associated anatomical structures","The quadriceps and its associated anatomical structures"]'::jsonb, 'The gastrocnemius/soleus (ankle plantarflexion) and the gluteus maximus', 'S1: ankle plantarflexion (the ''calf'' muscle) and the Achilles reflex.'),
('07377906-8950-53cf-808c-081e9f6a6a6b'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''spinal level'' of the S2-S4 roots is MOST tested by:', '["The knee extensors and its associated anatomical structures","The ankle plantarflexors and its associated anatomical structures","The hip flexors and its associated anatomical structures","The bladder and bowel function (the ''sacral'' function) and the anal sphincter tone","The ankle dorsiflexors and its associated anatomical structures"]'::jsonb, 'The bladder and bowel function (the ''sacral'' function) and the anal sphincter tone', 'S2-S4 (the ''conus''): the parasympathetic outflow (the ''sacral'' function) and the sacral reflexes.'),
('74e3c3fb-5ab4-5038-8120-75a1d0b63a2b'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''deep tendon reflex'' (DTR) of the C5 root is:', '["The triceps reflex","The Achilles reflex","The brachioradialis reflex","The biceps reflex","The patellar reflex"]'::jsonb, 'The biceps reflex', 'The biceps reflex (C5, musculocutaneous nerve): the ''biceps jerk''.'),
('ab7b83f3-ca22-5218-82b6-ff9ed72dce1a'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''deep tendon reflex'' (DTR) of the C7 root is:', '["The patellar reflex","The brachioradialis reflex","The Achilles reflex","The triceps reflex","The biceps reflex"]'::jsonb, 'The triceps reflex', 'The triceps reflex (C7, radial nerve): the ''triceps jerk''.'),
('67beda3c-7bec-5591-9656-2008d7a5dd49'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''deep tendon reflex'' (DTR) of the L4 root is:', '["The patellar reflex","The brachioradialis reflex","The Achilles reflex","The biceps reflex","The triceps reflex"]'::jsonb, 'The patellar reflex', 'The patellar reflex (L4, femoral nerve): the ''knee jerk''.'),
('b0960381-cf3f-5ee2-96d4-ceefcd7bae75'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''deep tendon reflex'' (DTR) of the S1 root is:', '["The Achilles reflex","The triceps reflex","The patellar reflex","The brachioradialis reflex","The biceps reflex"]'::jsonb, 'The Achilles reflex', 'The Achilles reflex (S1, tibial nerve): the ''ankle jerk''.'),
('4f274f78-452c-548f-babf-7f745d0c1313'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''bulbocavernosus reflex'' (the ''sacral reflex''):', '["The Achilles reflex and its associated anatomical structures","The contraction of the anal sphincter in response to squeezing the glans penis or the clitoris (t","The patellar reflex and its associated anatomical structures","The biceps reflex and its associated anatomical structures","The Babinski reflex and its associated anatomical structures"]'::jsonb, 'The contraction of the anal sphincter in response to squeezing the glans penis or the clitoris (t', 'The bulbocavernosus reflex (the ''BC reflex''): the first reflex to return after the ''spinal shock''.'),
('9418e18a-4bea-5167-9be9-0ff9405ab94f'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''anal reflex'' (the ''anal wink''):', '["The Babinski reflex and its associated anatomical structures","The patellar reflex and its associated anatomical structures","The contraction of the external anal sphincter in response to stroking the perianal skin (the S2-","The Achilles reflex and its associated anatomical structures","The biceps reflex and its associated anatomical structures"]'::jsonb, 'The contraction of the external anal sphincter in response to stroking the perianal skin (the S2-', 'The anal reflex (the ''anal wink'') is a sacral reflex (S2-S4).'),
('86f0a206-8e1d-5828-9951-3f15faea4a94'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''cremasteric reflex'' (the ''L1-L2'' reflex):', '["The contraction of the calf and its associated anatomical structures","The contraction of the biceps and its associated anatomical structures","The contraction of the anal sphincter and its associated anatomical structures","The elevation of the ipsilateral testicle in response to stroking the medial thigh (the L1-L2 ref","The contraction of the quadriceps and its associated anatomical structures"]'::jsonb, 'The elevation of the ipsilateral testicle in response to stroking the medial thigh (the L1-L2 ref', 'The cremasteric reflex (L1-L2): the ''genitofemoral nerve''.'),
('012aca63-c6db-5df5-97f0-9d4446d9ade8'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''abdominal reflex'' (the ''upper'' and the ''lower'' abdominal reflex):', '["The contraction of the quadriceps and its associated anatomical structures","The contraction of the abdominal muscles in response to stroking the skin of the abdomen (the T7-","The contraction of the priformis and its associated anatomical structures","The contraction of the gluteus and its associated anatomical structures","The contraction of the calf and its associated anatomical structures"]'::jsonb, 'The contraction of the abdominal muscles in response to stroking the skin of the abdomen (the T7-', 'The abdominal reflex (the ''superficial'' reflex): lost in UMN lesions (the ''corticospinal'' tract).'),
('0920c19f-1f57-58c1-8257-e471f91affec'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Beevor sign'' (the ''Beevor'' sign of the abdominal muscles):', '["The DOWNWARD migration of the umbilicus and its associated anatomical structures","The retraction of the umbilicus and its associated anatomical structures","The UPWARD migration of the umbilicus when the patient lifts the head (indicating a T10-T11 spina","The protrusion of the umbilicus and its associated anatomical structures","The lateral deviation of the umbilicus and its associated anatomical structures"]'::jsonb, 'The UPWARD migration of the umbilicus when the patient lifts the head (indicating a T10-T11 spina', 'Beevor sign: the umbilicus moves upward (the lower abdominal muscles are paralyzed; the upper abdominal muscles are intact).'),
('3f842840-de49-5481-bf31-2361722a6ef1'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Gowers sign'' (the ''Gowers'' maneuver''):', '["A sign of spinal cord injury and its associated anatomical structures","A sign of cervical myelopathy and its associated anatomical structures","The patient ''climbs'' up the thighs with the hands when rising from the floor (a sign of Duchenne","A sign of the cauda equina syndrome and its associated anatomical structures","A sign of lumbar radiculopathy and its associated anatomical structures"]'::jsonb, 'The patient ''climbs'' up the thighs with the hands when rising from the floor (a sign of Duchenne', 'Gowers sign: the child ''walks up'' the thighs to stand due to the weakness of the proximal hip muscles.'),
('79a542d7-9981-5900-99a6-5dd2e233b6f0'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Trendelenburg sign'' (the ''Trendelenburg gait''):', '["The PELVIS DROPS to the OPPOSITE side when standing on one leg (indicating a WEAKNESS of the hip","The trunk leans to the same side and its associated anatomical structures","The pelvis rises to the opposite side and its associated anatomical structures","The trunk leans to the opposite side and its associated anatomical structures","The pelvis tilts anteriorly and its associated anatomical structures"]'::jsonb, 'The PELVIS DROPS to the OPPOSITE side when standing on one leg (indicating a WEAKNESS of the hip', 'The Trendelenburg sign (the ''gluteus medius lurch''): the patient ''lurches'' to the affected side.'),
('cb18a7ff-9729-55a9-8000-c05d9a74c651'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Romberg test'' (the ''Romberg sign''):', '["The patient sways with the eyes open and its associated anatomical structures","The patient sways or falls with the eyes closed (indicating a LOSS of the PROPIOCEPTION","The patient cannot walk and its associated anatomical structures","The patient cannot stand and its associated anatomical structures","The patient has nystagmus and its associated anatomical structures"]'::jsonb, 'The patient sways or falls with the eyes closed (indicating a LOSS of the PROPIOCEPTION', 'The Romberg sign: the patient stands with the feet together, first with eyes open, then closed. The ''positive'' Romberg: the patient falls with eyes closed.'),
('7ba832e0-1f0e-5903-baae-8815ab8c57a6'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Lasegue sign'' (the ''straight leg raise'' test):', '["The REPRODUCTION of the radicular pain in the sciatic distribution when the leg is raised to <70","A test for the hip joint and its associated anatomical structures","A test for the cervical root and its associated anatomical structures","A test for the L3-L4 root and its associated anatomical structures","A test for the knee joint and its associated anatomical structures"]'::jsonb, 'The REPRODUCTION of the radicular pain in the sciatic distribution when the leg is raised to <70', 'The Lasegue sign (the ''SLR''): the ''crossed'' SLR is more specific (the ''Fajersztajn sign'').'),
('f91aaf22-9f5a-53f8-b9b7-27fe6befc1ce'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''bowstring sign'' (the ''popliteal compression'' test):', '["The reproduction of the sciatica when the popliteal fossa is compressed in the ''SLR'' position (a","A test for the hip joint and its associated anatomical structures","A test for the sacroiliac joint and its associated anatomical structures","A test for the lumbar facet syndrome and its associated anatomical structures","A test for the cervical radiculopathy and its associated anatomical structures"]'::jsonb, 'The reproduction of the sciatica when the popliteal fossa is compressed in the ''SLR'' position (a', 'The bowstring sign (the ''projectile'' sign): the pain is ''projected'' distally when the tibial nerve is compressed.'),
('b2e9acf7-0fe0-5170-836c-0fe2fd3c031b'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Fajersztajn sign'' (the ''crossed'' SLR):', '["A test for the hip joint and its associated anatomical structures","The ''crossed'' straight leg raise: the reproduction of the contralateral (opposite","A test for the lumbar facet syndrome and its associated anatomical structures","A test for the sacroiliac joint and its associated anatomical structures","A test for the cervical radiculopathy and its associated anatomical structures"]'::jsonb, 'The ''crossed'' straight leg raise: the reproduction of the contralateral (opposite', 'The crossed SLR (the ''well-leg'' SLR): a ''false positive'' rate is LOW (highly specific).'),
('6a458000-8bbd-570c-91d2-1f62c57c3e98'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''femoral nerve stretch test'' (the ''reverse SLR''):', '["The same as the SLR and its associated anatomical structures","The ''Patrick'' test and its associated anatomical structures","The ''crossed'' SLR and its associated anatomical structures","The ''bowstring'' test and its associated anatomical structures","The extension of the hip with the knee flexed (the ''prone position''), reproducing the ''anterior''"]'::jsonb, 'The extension of the hip with the knee flexed (the ''prone position''), reproducing the ''anterior''', 'The femoral nerve stretch test (the ''reverse SLR''): the patient is in the ''lateral'' or ''prone'' position.'),
('0d68ad45-366b-5ed1-8da9-d85b1655aec2'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Patrick test'' (the ''FABER'' test):', '["A test for the lumbar facet syndrome and its associated anatomical structures","A test for the spinal stenosis and its associated anatomical structures","The ''Flexion, ABduction, External Rotation'' of the hip (a test for the SACROILIAC joint or the HI","A test for the cervical radiculopathy and its associated anatomical structures","A test for the lumbar disc herniation and its associated anatomical structures"]'::jsonb, 'The ''Flexion, ABduction, External Rotation'' of the hip (a test for the SACROILIAC joint or the HI', 'The FABER test (the ''Patrick'' test): pain in the ''groin'' (the ''hip'') vs ''sacroiliac'' (the ''SI'') joint.'),
('7400e901-1d18-56af-9c90-9dacd40e62bc'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Gaenslen test'' (the ''Gaenslen'' maneuver):', '["The hyperextension of the hip with the patient in the ''lateral'' position (a test for the SACROILI","A test for the spinal stenosis and its associated anatomical structures","A test for the lumbar facet syndrome and its associated anatomical structures","A test for the lumbar disc herniation and its associated anatomical structures","A test for the cervical radiculopathy and its associated anatomical structures"]'::jsonb, 'The hyperextension of the hip with the patient in the ''lateral'' position (a test for the SACROILI', 'Gaenslen test: the patient lies on the edge of the table, with one leg hanging down (hyperextension) and the other leg flexed.'),
('282c3ffb-0db4-51b0-b04e-ab784e0a3fff'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Yeoman test'' (the ''Yeoman'' maneuver):', '["The hyperextension of the hip with the patient in the ''prone'' position (a test for the SACROILIAC","A test for the lumbar disc herniation and its associated anatomical structures","A test for the spinal stenosis and its associated anatomical structures","A test for the lumbar facet syndrome and its associated anatomical structures","A test for the cervical radiculopathy and its associated anatomical structures"]'::jsonb, 'The hyperextension of the hip with the patient in the ''prone'' position (a test for the SACROILIAC', 'Yeoman test: the examiner extends the patient''s hip while stabilizing the sacrum.'),
('720d2d60-83e1-561c-966c-4086f30befdb'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Ely test'' (the ''Ely'' maneuver):', '["A test for the spinal stenosis and its associated anatomical structures","The flexion of the knee in the ''prone'' position (a test for the RECTUS FEMORIS tightness","A test for the lumbar facet syndrome and its associated anatomical structures","A test for the cervical radiculopathy and its associated anatomical structures","A test for the lumbar disc herniation and its associated anatomical structures"]'::jsonb, 'The flexion of the knee in the ''prone'' position (a test for the RECTUS FEMORIS tightness', 'Ely test (the ''femoral nerve'' or the ''rectus femoris'' test): the patient''s heel touches the buttock.'),
('82184fb6-e901-5c84-b978-151b35786132'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Thomas test'' (the ''Thomas'' maneuver):', '["A test for the lumbar facet syndrome and its associated anatomical structures","A test for the spinal stenosis and its associated anatomical structures","A test for the lumbar disc herniation and its associated anatomical structures","The flexion of one hip to the chest while observing the ''extension'' of the opposite hip (a test f","A test for the cervical radiculopathy and its associated anatomical structures"]'::jsonb, 'The flexion of one hip to the chest while observing the ''extension'' of the opposite hip (a test f', 'Thomas test: a ''positive'' test is the ''lifting'' of the thigh off the table (a ''fixed'' flexion deformity of the hip).'),
('b0974155-a38e-503f-a709-29f24c2d8ac9'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Ober test'' (the ''Ober'' maneuver):', '["A test for the cervical radiculopathy","A test for the lumbar disc herniation","A test for the lumbar facet syndrome","A test for the spinal stenosis","The ABDUCTION and EXTENSION of the hip"]'::jsonb, 'The ABDUCTION and EXTENSION of the hip', 'Ober test: the patient lies on the side; the examiner abducts and extends the hip, then allows the leg to drop.'),
('41d312ea-e901-5250-b401-d8c42ffde57e'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''scapular winging'' is caused by the paralysis of:', '["The serratus anterior","The trapezius","The rhomboids","The supraspinatus","The deltoid"]'::jsonb, 'The serratus anterior', 'Scapular winging: the ''medial'' winging (the ''serratus anterior'') vs the ''lateral'' winging (the ''trapezius'').'),
('39aed6e7-0162-57fd-a160-8aa099c10dee'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''shoulder drop'' is caused by the paralysis of:', '["The rhomboids","The serratus anterior","The trapezius","The deltoid","The supraspinatus"]'::jsonb, 'The trapezius', 'The shoulder drop (the ''shoulder depression''): the patient cannot ''shrug'' the shoulder.'),
('485a37e1-df15-5d13-a2cc-c45111ca2f77'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''foot drop'' is caused by the paralysis of:', '["The flexor hallucis longus","The gastrocnemius","The peroneus longus","The extensor digitorum brevis","The tibialis anterior"]'::jsonb, 'The tibialis anterior', 'Foot drop: the patient cannot ''dorsiflex'' the foot (the ''steppage'' gait).'),
('14e75aa4-ceea-5c38-95ef-b41f4925f814'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''Trendelenburg gait'' (the ''lurching'' gait) is caused by the weakness of:', '["The quadriceps","The iliopsoas","The gluteus maximus","The gluteus medius","The hamstrings"]'::jsonb, 'The gluteus medius', 'The Trendelenburg gait: the pelvis ''drops'' to the opposite side during the ''stance'' phase of gait.'),
('85cc9220-c1d5-5fdd-bab8-55f327f6ede8'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''gluteus maximus lurch'' (the ''extensor'' lurch) is caused by the weakness of:', '["The gluteus medius","The hamstrings","The gluteus maximus","The iliopsoas","The quadriceps"]'::jsonb, 'The gluteus maximus', 'The gluteus maximus lurch: the patient ''lurches'' backward during the ''stance'' phase.'),
('0f443459-6459-5f75-8616-798a35465d6f'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''crouch gait'' (the ''flexed'' gait) is caused by the weakness of:', '["The iliopsoas only","The hamstrings only","The gastrocnemius only","The gluteus maximus AND the quadriceps","The gluteus medius only"]'::jsonb, 'The gluteus maximus AND the quadriceps', 'The crouch gait: the patient walks with the hips and the knees in the flexion (the ''flexed'' posture).'),
('785c2f80-55ac-5d39-bfb8-0dc92e796aa6'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''waddling gait'' (the ''myopathic'' gait) is caused by:', '["The weakness of the hamstrings and its associated anatomical structures","The weakness of the gastrocnemius and its associated anatomical structures","The weakness of the quadriceps and its associated anatomical structures","The weakness of the tibialis anterior and its associated anatomical structures","The bilateral weakness of the hip abductors (the ''gluteus medius'' weakness"]'::jsonb, 'The bilateral weakness of the hip abductors (the ''gluteus medius'' weakness', 'The waddling gait (the ''duck-like'' gait): the patient ''rolls'' the pelvis from side to side.'),
('037505d2-91fa-5bbd-aa76-c3e80d839abe'::uuid, 'Anatomy (Paper 2)', 'Vertebral Column', 'The ''spastic gait'' (the ''hemiplegic'' or the ''scissoring'' gait) is caused by:', '["A LOWER MOTOR NEURON lesion and its associated anatomical structures","A BASAL GANGLIA lesion and its associated anatomical structures","An UPPER MOTOR NEURON lesion (the ''spasticity'' of the lower limbs, the ''scissoring'' of the legs","A CEREBELLAR lesion and its associated anatomical structures","A MUSCULAR lesion and its associated anatomical structures"]'::jsonb, 'An UPPER MOTOR NEURON lesion (the ''spasticity'' of the lower limbs, the ''scissoring'' of the legs', 'The spastic gait: the patient walks with the ''stiff'' leg (the ''circumduction'' gait) - the ''UMN'' sign.'),
('a29ed110-5329-5e1d-8a93-15e31292dec6'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The central nervous system (CNS) consists of:', '["The cranial and spinal nerves","The spinal cord and the spinal nerves","The brain and the spinal cord","The brain and the cranial nerves","The brain and the peripheral nerves"]'::jsonb, 'The brain and the spinal cord', 'The CNS includes the brain (cerebrum, cerebellum, brainstem) and the spinal cord.'),
('eb88a3b6-4f00-5b60-a14f-e4e47a8d91d8'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The peripheral nervous system (PNS) consists of:', '["Only the spinal nerves and its associated anatomical structures","Only the cranial nerves and its associated anatomical structures","The brain and the spinal cord and its associated anatomical structures","Only the autonomic ganglia and its associated anatomical structures","The cranial nerves, the spinal nerves, and the peripheral ganglia"]'::jsonb, 'The cranial nerves, the spinal nerves, and the peripheral ganglia', 'The PNS connects the CNS to the limbs and organs.'),
('58bfec87-e966-574b-84ba-9df6ffb0f93c'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The neuron (the nerve cell) consists of:', '["Only the cell body","The cell body and the myelin sheath","The cell body (soma), the dendrites (receiving), and the axon","Only the dendrites","Only the axon"]'::jsonb, 'The cell body (soma), the dendrites (receiving), and the axon', 'The neuron is the structural and functional unit of the nervous system.'),
('7c562c4b-84a5-5045-af24-80a4c6d62790'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The myelin sheath in the CNS is produced by:', '["Oligodendrocytes","Ependymal cells","Microglia","Astrocytes","Schwann cells"]'::jsonb, 'Oligodendrocytes', 'Oligodendrocytes (CNS) myelinate multiple axons; Schwann cells (PNS) myelinate a single axon.'),
('dff8f0dd-f4d7-5f36-b146-5aedbf200fd6'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The myelin sheath in the PNS is produced by:', '["Astrocytes","Microglia","Schwann cells","Ependymal cells","Oligodendrocytes"]'::jsonb, 'Schwann cells', 'Schwann cells (the neurolemmocytes) form the myelin sheath around PNS axons.'),
('090153fa-bd61-5420-85e6-0287b5434efe'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The nodes of Ranvier are:', '["The dendrites of the neuron","The gaps between adjacent myelin sheaths","The synapses between the neurons","The cell bodies of the neurons","The terminal boutons of the axon"]'::jsonb, 'The gaps between adjacent myelin sheaths', 'Saltatory conduction (the jumping of the action potential) occurs at the nodes of Ranvier.'),
('cd4f27a3-cdff-5590-a899-2feac5b0bb76'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The synapse is:', '["The cell body of the neuron and its associated anatomical structures","The axon of the neuron and its associated anatomical structures","The dendrite of the neuron and its associated anatomical structures","The junction between two neurons (or a neuron and a target cell), where the signal is transmitted","The myelin sheath of the neuron and its associated anatomical structures"]'::jsonb, 'The junction between two neurons (or a neuron and a target cell), where the signal is transmitted', 'The synapse (the synaptic cleft) transmits the signal via a neurotransmitter (chemical synapse).'),
('3186e64a-0207-5b1c-bf65-b85f8e9b5000'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The neurotransmitter at the neuromuscular junction is:', '["Norepinephrine","Acetylcholine","Dopamine","Serotonin","Glutamate"]'::jsonb, 'Acetylcholine', 'ACh (the muscle activator) is released from the motor neuron at the NMJ.'),
('a6c3a037-d1c3-51d3-86d5-61c8484b280d'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The inhibitory neurotransmitter in the CNS is:', '["Acetylcholine","Norepinephrine","Dopamine","Glutamate","GABA"]'::jsonb, 'GABA', 'GABA (the calming neurotransmitter) is the major inhibitory neurotransmitter in the brain.'),
('845a3343-7515-5f24-aaae-39df4d8e1c38'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The excitatory neurotransmitter in the CNS is:', '["Serotonin","Glutamate","Acetylcholine","Dopamine","GABA"]'::jsonb, 'Glutamate', 'Glutamate (the learning neurotransmitter) is the major excitatory neurotransmitter in the brain.'),
('217ae1fb-c00c-560d-af0c-2ffa2a8fbe96'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The cerebrum (telencephalon) consists of:', '["The brainstem","The two cerebral hemispheres","The diencephalon","The spinal cord","The cerebellum"]'::jsonb, 'The two cerebral hemispheres', 'The cerebrum (the largest part of the brain) is divided into the left and right hemispheres.'),
('8f355d31-bcd2-501d-93c7-fbcca601b52b'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The cerebral cortex (the gray matter of the cerebrum) has how many layers?', '["7 layers","5 layers","4 layers","3 layers","6 layers"]'::jsonb, '6 layers', 'The neocortex (the new cortex) has 6 layers.'),
('3e6db8c3-fdd5-5369-b3d2-27e4def2edc8'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The primary motor cortex (the precentral gyrus) is located in:', '["The temporal lobe","The frontal lobe","The parietal lobe","The insula","The occipital lobe"]'::jsonb, 'The frontal lobe', 'The precentral gyrus (the motor strip) controls voluntary movement (the homunculus).'),
('069cf0f8-bd85-59d6-ac64-6bb1ff0e6fde'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The primary somatosensory cortex (the postcentral gyrus) is located in:', '["The temporal lobe","The insula","The occipital lobe","The parietal lobe","The frontal lobe"]'::jsonb, 'The parietal lobe', 'The postcentral gyrus (the sensory strip) receives sensory input from the body.'),
('eead36a5-faef-579f-bab6-1eee99730019'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The primary visual cortex (the striate cortex) is located in:', '["The parietal lobe","The frontal lobe","The occipital lobe","The insula","The temporal lobe"]'::jsonb, 'The occipital lobe', 'The calcarine sulcus (the striate cortex, area 17) is the primary visual area.'),
('b4cbdb07-4137-589c-bfa9-ceb50e8f45b4'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The primary auditory cortex (Heschl gyrus) is located in:', '["The parietal lobe","The frontal lobe","The temporal lobe","The occipital lobe","The insula"]'::jsonb, 'The temporal lobe', 'The Heschl gyrus (the transverse temporal gyrus) receives auditory input.'),
('7184155a-a7d7-5d14-aa4c-351350f64469'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The Broca area (the motor speech area) is located in:', '["The inferior frontal gyrus","The supramarginal gyrus","The precentral gyrus","The angular gyrus","The superior temporal gyrus"]'::jsonb, 'The inferior frontal gyrus', 'Broca aphasia (expressive aphasia): the patient cannot speak but can comprehend.'),
('cc7e2835-0572-5eb7-8491-0f914045f190'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The Wernicke area (the sensory speech area) is located in:', '["The angular gyrus","The precentral gyrus","The inferior frontal gyrus","The superior temporal gyrus","The supramarginal gyrus"]'::jsonb, 'The superior temporal gyrus', 'Wernicke aphasia (receptive aphasia): the patient can speak but cannot comprehend.'),
('33e9cbd1-cc91-5709-96b4-1c1eee6a3e8d'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'On diagnostic evaluation, The arcuate fasciculus connects:', '["The temporal and the occipital lobes","The Broca area and the Wernicke area","The cerebellum and the cerebrum","The frontal and the occipital lobes","The parietal and the frontal lobes"]'::jsonb, 'The Broca area and the Wernicke area', 'The arcuate fasciculus (the language tract): a lesion causes conduction aphasia.'),
('13ddf699-7df0-5c8c-8faa-093e40c09d41'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Conduction aphasia (a lesion of the arcuate fasciculus) is characterized by:', '["The inability to COMPREHEND speech","The inability to SPEAK","The inability to write","The inability to read","The inability to REPEAT spoken language"]'::jsonb, 'The inability to REPEAT spoken language', 'Conduction aphasia: the patient can understand and speak, but cannot REPEAT.'),
('de153910-11e8-589f-a5fd-6283850f71c0'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'With respect to management, The corpus callosum is:', '["The largest commissure connecting the two cerebral hemispheres","The tract connecting the thalamus to the cortex","The tract connecting the cerebellum to the brainstem","The tract connecting the basal ganglia","The tract connecting the frontal lobe to the temporal lobe"]'::jsonb, 'The largest commissure connecting the two cerebral hemispheres', 'The corpus callosum allows interhemispheric communication.'),
('69b44780-2232-50a8-82e6-d51a21d46d8c'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'For a patient presenting with symptoms, The internal capsule is:', '["The tract connecting the thalamus to the hypothalamus and its associated anatomical structures","The tract connecting the two hemispheres and its associated anatomical structures","A white matter tract containing fibers between the cerebral cortex and the brainstem/spinal cord","The tract connecting the cerebellum to the cerebrum and its associated anatomical structures","The tract connecting the basal ganglia and its associated anatomical structures"]'::jsonb, 'A white matter tract containing fibers between the cerebral cortex and the brainstem/spinal cord', 'The internal capsule is the site of the lacunar stroke.'),
('780739ff-40c2-5f12-b02c-3f554288351d'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The anterior limb of the internal capsule contains:', '["The frontopontine fibers","The optic radiation","The corticobulbar tract","The thalamocortical fibers","The corticospinal tract"]'::jsonb, 'The frontopontine fibers', 'The anterior limb is between the caudate nucleus and the putamen.'),
('63664a7f-0319-5827-8bf2-3b64cbf9cad0'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The genu of the internal capsule contains:', '["The optic radiation","The auditory radiation","The thalamocortical fibers","The corticospinal tract","The corticobulbar tract"]'::jsonb, 'The corticobulbar tract', 'The genu (the knee of the internal capsule) is the bend between the anterior and posterior limbs.'),
('8dacb123-c47c-5a32-95b7-16bec9371ec7'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The posterior limb of the internal capsule contains:', '["The auditory radiation and its associated anatomical structures","Only the thalamocortical fibers and its associated anatomical structures","Only the corticospinal tract and its associated anatomical structures","The corticospinal tract, thalamocortical fibers, and corticorubral fibers","The optic radiation and its associated anatomical structures"]'::jsonb, 'The corticospinal tract, thalamocortical fibers, and corticorubral fibers', 'The posterior limb is between the putamen and the thalamus.'),
('cb98c9a3-43b9-5dda-9e13-d878eef58dfb'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The lacunar stroke most commonly affects:', '["The spinal cord","The cerebral cortex","The internal capsule","The brainstem","The cerebellum"]'::jsonb, 'The internal capsule', 'Lacunar strokes are small (<15 mm) infarcts in the deep structures of the brain.'),
('c3fd5b0c-c0d2-535e-8486-fdc42c8d4233'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The basal ganglia (basal nuclei) include:', '["Only the globus pallidus and its associated anatomical structures","The caudate nucleus, putamen, globus pallidus, substantia nigra, and subthalamic nucleus","Only the caudate and the putamen and its associated anatomical structures","Only the subthalamic nucleus and its associated anatomical structures","Only the substantia nigra and its associated anatomical structures"]'::jsonb, 'The caudate nucleus, putamen, globus pallidus, substantia nigra, and subthalamic nucleus', 'The basal ganglia are involved in motor control (initiation and coordination).'),
('c2016d2b-06b2-554d-b524-fbec89befaff'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The striatum (corpus striatum) consists of:', '["The amygdala only","The caudate nucleus and the putamen","The globus pallidus only","The substantia nigra only","The subthalamic nucleus only"]'::jsonb, 'The caudate nucleus and the putamen', 'The striatum (neostriatum) is the input nucleus of the basal ganglia.'),
('e81fadba-6574-5d89-a6a0-42aebd1152b6'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Regarding clinical scenarios, The globus pallidus (pallidum) is divided into:', '["The external segment (GPe) and the internal segment","The subthalamic nucleus only","The caudate and the putamen","The putamen only","The substantia nigra pars compacta and pars reticulata"]'::jsonb, 'The external segment (GPe) and the internal segment', 'The globus pallidus is the output nucleus of the basal ganglia.'),
('9a202fe7-5f07-588a-a279-f09491992659'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The substantia nigra is located in:', '["The diencephalon","The medulla oblongata","The midbrain","The cerebellum","The pons"]'::jsonb, 'The midbrain', 'The substantia nigra is divided into pars compacta (dopaminergic) and pars reticulata (GABAergic).'),
('fec91a19-122b-5c7f-9d14-8eafd427e0e2'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The neurotransmitter of the substantia nigra pars compacta (SNc) is:', '["GABA","Serotonin","Acetylcholine","Glutamate","Dopamine"]'::jsonb, 'Dopamine', 'The SNc (the dopamine center) projects to the striatum (the nigrostriatal pathway).'),
('56cbe8e9-3c61-583c-a3ed-3544375dfe58'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The degeneration of the substantia nigra pars compacta causes:', '["Amyotrophic lateral sclerosis","Multiple sclerosis","Alzheimer disease","Parkinson disease","Huntington disease"]'::jsonb, 'Parkinson disease', 'Parkinson disease: the loss of dopamine neurons in the SNc.'),
('3ea6a93a-566d-5fa4-ac06-49f188871346'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The direct pathway of the basal ganglia (the GO pathway):', '["Cortex -> cerebellum -> thalamus -> cortex","Cortex -> brainstem -> spinal cord","Cortex -> striatum -> GPe -> STN -> GPi/SNr -> thalamus -> cortex","Cortex -> basal ganglia -> spinal cord","Cortex -> striatum -> GPi/SNr -> thalamus -> cortex"]'::jsonb, 'Cortex -> striatum -> GPi/SNr -> thalamus -> cortex', 'The direct pathway (D1 receptor pathway) releases the brake on movement.'),
('307d995f-7622-5b5a-974f-435a4ccd1c0b'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The indirect pathway of the basal ganglia (the NO-GO pathway):', '["Cortex -> brainstem -> spinal cord","Cortex -> striatum -> GPe -> STN -> GPi/SNr -> thalamus -> cortex","Cortex -> striatum -> GPi -> thalamus -> cortex","Cortex -> cerebellum -> thalamus -> cortex","Cortex -> basal ganglia -> spinal cord"]'::jsonb, 'Cortex -> striatum -> GPe -> STN -> GPi/SNr -> thalamus -> cortex', 'The indirect pathway (D2 receptor pathway) applies the brake on movement.'),
('d21b24fc-9ca3-5379-af92-a742d3a1ca00'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The hyperdirect pathway of the basal ganglia:', '["Cortex -> STN -> GPi/SNr -> thalamus -> cortex","Cortex -> basal ganglia -> spinal cord","Cortex -> brainstem -> spinal cord","Cortex -> striatum -> GPi -> thalamus -> cortex","Cortex -> cerebellum -> thalamus -> cortex"]'::jsonb, 'Cortex -> STN -> GPi/SNr -> thalamus -> cortex', 'The hyperdirect pathway (cortico-subthalamic pathway) provides global inhibition of motor output.'),
('191592fc-ed87-5465-9675-0765eff4b042'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The thalamus (dorsal thalamus) is:', '["A large, ovoid mass of gray matter in the diencephalon (the relay station for sensory and motor s","A part of the brainstem and its associated anatomical structures","A part of the basal ganglia and its associated anatomical structures","A part of the spinal cord and its associated anatomical structures","A part of the cerebellum and its associated anatomical structures"]'::jsonb, 'A large, ovoid mass of gray matter in the diencephalon (the relay station for sensory and motor s', 'The thalamus is the major gateway to the cerebral cortex.'),
('12fa3775-d584-54d0-9439-aba74a96cf79'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The specific sensory nuclei of the thalamus include:', '["Only the MGN and its associated anatomical structures","Only the VPM and its associated anatomical structures","Only the LGN and its associated anatomical structures","VPL (body), VPM (face), LGN (vision), and MGN","Only the VPL and its associated anatomical structures"]'::jsonb, 'VPL (body), VPM (face), LGN (vision), and MGN', 'The specific sensory nuclei project to the specific sensory areas of the cortex.'),
('c0550c75-083d-52ee-bd3e-8623a8a0865a'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The VPL nucleus of the thalamus receives:', '["The trigeminothalamic tract and its associated anatomical structures","The auditory pathway and its associated anatomical structures","The optic tract and its associated anatomical structures","The medial lemniscus (touch, proprioception, vibration) and the spinothalamic tract (pain and tem","The olfactory pathway and its associated anatomical structures"]'::jsonb, 'The medial lemniscus (touch, proprioception, vibration) and the spinothalamic tract (pain and tem', 'The VPL (ventral posterolateral nucleus) is the sensory relay for the BODY.'),
('cb11d659-7e0d-503a-88dd-059d24bcb2f1'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The VPM nucleus of the thalamus receives:', '["The auditory pathway","The trigeminothalamic tract","The medial lemniscus","The optic tract","The spinothalamic tract"]'::jsonb, 'The trigeminothalamic tract', 'The VPM (ventral posteromedial nucleus) is the sensory relay for the FACE.'),
('c4a4e6cd-ae2d-56b3-9e9a-eb572092c7d4'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The LGN (lateral geniculate nucleus) of the thalamus receives:', '["The gustatory pathway","The somatosensory pathway","The olfactory pathway","The optic tract","The auditory pathway"]'::jsonb, 'The optic tract', 'The LGN (lateral geniculate body) is the visual relay nucleus of the thalamus.'),
('2fd5d9e3-775c-5a87-9c79-5c7ab75dce0b'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The MGN (medial geniculate nucleus) of the thalamus receives:', '["The somatosensory pathway","The olfactory pathway","The optic tract","The gustatory pathway","The auditory pathway"]'::jsonb, 'The auditory pathway', 'The MGN (medial geniculate body) is the auditory relay nucleus of the thalamus.'),
('09843d0b-c914-5219-838d-67161563887f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The hypothalamus is located:', '["In the brainstem and its associated anatomical structures","Behind the thalamus and its associated anatomical structures","Above the thalamus and its associated anatomical structures","Below the thalamus, forming the floor and walls of the third ventricle","In the spinal cord and its associated anatomical structures"]'::jsonb, 'Below the thalamus, forming the floor and walls of the third ventricle', 'The hypothalamus controls autonomic, endocrine, and visceral functions.'),
('5eaecee5-25d5-52a0-a4a7-04a668f682d2'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The hypothalamus controls the autonomic nervous system:', '["Only the somatic outflow and its associated anatomical structures","The sympathetic (fight or flight) and the parasympathetic (rest and digest) outflow","Only the parasympathetic outflow and its associated anatomical structures","Only the enteric outflow and its associated anatomical structures","Only the sympathetic outflow and its associated anatomical structures"]'::jsonb, 'The sympathetic (fight or flight) and the parasympathetic (rest and digest) outflow', 'The hypothalamus coordinates the stress and relaxation responses.'),
('a55d7b79-90b8-51db-9c2c-38ace8ce92d6'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The hypothalamus produces the following hormones:', '["TSH and its associated structures","ACTH and its associated structures","FSH and its associated structures","ADH (antidiuretic hormone) and oxytocin","GH and its associated structures"]'::jsonb, 'ADH (antidiuretic hormone) and oxytocin', 'The hypothalamus produces ADH and oxytocin, stored in the posterior pituitary.'),
('b84b37e8-d4a2-5a22-9069-3f1c319c5186'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The hypothalamus regulates body temperature via:', '["The posterior hypothalamus","The medial hypothalamus","The dorsal hypothalamus","The preoptic area","The lateral hypothalamus"]'::jsonb, 'The preoptic area', 'The preoptic area is the cooling center; the posterior hypothalamus is the heating center.'),
('ec6ae7a3-8d3e-59c1-b62f-8e5820e74e4d'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The hypothalamus regulates hunger and satiety via:', '["The preoptic area and its associated anatomical structures","The posterior hypothalamus and its associated anatomical structures","The lateral hypothalamus (feeding center) and the ventromedial hypothalamus","The anterior hypothalamus and its associated anatomical structures","The dorsal hypothalamus and its associated anatomical structures"]'::jsonb, 'The lateral hypothalamus (feeding center) and the ventromedial hypothalamus', 'The lateral hypothalamus is the hunger center; the ventromedial hypothalamus is the satiety center.'),
('db9a28ea-450f-525a-9f95-77216896e4ac'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The hypothalamus regulates the circadian rhythm via:', '["The posterior hypothalamus","The lateral hypothalamus","The suprachiasmatic nucleus","The preoptic area","The ventromedial hypothalamus"]'::jsonb, 'The suprachiasmatic nucleus', 'The SCN receives input from the retina (the light signal).'),
('c0c84cd9-3a5a-50b7-b885-a87189ff07b9'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The pineal gland (epiphysis) produces:', '["Melatonin","ADH","Growth hormone","Oxytocin","Cortisol"]'::jsonb, 'Melatonin', 'The pineal gland: melatonin is secreted during the NIGHT (the dark).'),
('9e5f3db0-c1df-5e71-aca9-700dfd3bfaed'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'In a surgical context, The pituitary gland (hypophysis) is located:', '["In the middle cranial fossa","In the sella turcica of the sphenoid bone","In the foramen magnum","In the anterior cranial fossa","In the posterior cranial fossa"]'::jsonb, 'In the sella turcica of the sphenoid bone', 'The pituitary gland is connected to the hypothalamus by the pituitary stalk (infundibulum).'),
('61e79370-fcdc-504d-a724-205fe78fc442'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The anterior pituitary (adenohypophysis) produces:', '["Only FSH and LH","Only TSH and ACTH","ADH and oxytocin","Only GH and prolactin","GH, TSH, ACTH, FSH, LH, and prolactin"]'::jsonb, 'GH, TSH, ACTH, FSH, LH, and prolactin', 'The anterior pituitary is regulated by hypothalamic-releasing and inhibiting hormones.'),
('9fbef5d2-2e2b-530f-aa14-20b6cfd4cbcf'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The posterior pituitary (neurohypophysis) produces:', '["GH","TSH","Prolactin","ACTH","ADH (vasopressin) and oxytocin"]'::jsonb, 'ADH (vasopressin) and oxytocin', 'The posterior pituitary is the storage site for hypothalamic hormones.'),
('4142d93e-8044-5a7e-b80c-975f68f0ead9'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The cerebellum (little brain) is located:', '["In the posterior cranial fossa","In the anterior cranial fossa","In the spinal canal","In the supratentorial compartment","In the middle cranial fossa"]'::jsonb, 'In the posterior cranial fossa', 'The cerebellum is the coordinator of motor function.'),
('bd5157b1-681c-5b86-ab6b-18d809f65384'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'On diagnostic evaluation, The cerebellum consists of:', '["The cerebellar hemispheres, the vermis (midline), and the flocculonodular lobe","Only the cerebellar hemispheres and its associated anatomical structures","Only the vermis and its associated anatomical structures","The cerebellar peduncles and its associated anatomical structures","Only the flocculonodular lobe and its associated anatomical structures"]'::jsonb, 'The cerebellar hemispheres, the vermis (midline), and the flocculonodular lobe', 'The cerebellum has 3 lobes: anterior, posterior, and flocculonodular.'),
('52fa0703-69c1-5556-8d7c-c4d425b2f8f2'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The phylogenetic divisions of the cerebellum are:', '["Archicerebellum (flocculonodular - vestibular), paleocerebellum","Left and right hemispheres and its associated anatomical structures","Dentate and interposed nuclei and its associated anatomical structures","Vermis and paravermis and its associated anatomical structures","Cortex and white matter and its associated anatomical structures"]'::jsonb, 'Archicerebellum (flocculonodular - vestibular), paleocerebellum', 'Archicerebellum (balance), paleocerebellum (posture), neocerebellum (coordination).'),
('7972adaa-e96c-5885-a206-3eaa6824d3dc'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The deep cerebellar nuclei include:', '["The caudate and the putamen and its associated anatomical structures","Only the dentate nucleus and its associated anatomical structures","The dentate, emboliform, globose, and fastigial nuclei","Only the interposed nuclei and its associated anatomical structures","Only the fastigial nucleus and its associated anatomical structures"]'::jsonb, 'The dentate, emboliform, globose, and fastigial nuclei', 'The dentate is the largest deep cerebellar nucleus.'),
('20e6f7b2-04ae-57cb-8aee-06e5a45054a2'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The dentate nucleus projects to:', '["The brainstem and its associated anatomical structures","The contralateral cerebellum and its associated anatomical structures","The ipsilateral thalamus and its associated anatomical structures","The contralateral thalamus (dentato-thalamic tract) and then to the contralateral motor cortex","The ipsilateral motor cortex and its associated anatomical structures"]'::jsonb, 'The contralateral thalamus (dentato-thalamic tract) and then to the contralateral motor cortex', 'The dentate nucleus is involved in planning and coordination of voluntary movements.'),
('f6a672c1-eabd-57d2-b65a-97c7538b6a53'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Cerebellar ataxia includes:', '["Waddling gait and its associated anatomical structures","Wide-based gait, intention tremor, dysmetria, dysdiadochokinesia, and nystagmus","Narrow-based gait and its associated anatomical structures","Scissoring gait and its associated anatomical structures","Steppage gait and its associated anatomical structures"]'::jsonb, 'Wide-based gait, intention tremor, dysmetria, dysdiadochokinesia, and nystagmus', 'Cerebellar ataxia: DANISH (Dysdiadochokinesia, Ataxia, Nystagmus, Intention tremor, Slurred speech, Hypotonia).'),
('13952447-6283-5844-b746-da1df50e2815'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The Romberg sign is positive in:', '["A lesion of the dorsal columns (proprioception loss), NOT the cerebellum","A basal ganglia lesion and its associated anatomical structures","A cerebellar lesion and its associated anatomical structures","A motor cortex lesion and its associated anatomical structures","A brainstem lesion and its associated anatomical structures"]'::jsonb, 'A lesion of the dorsal columns (proprioception loss), NOT the cerebellum', 'Romberg sign: patient sways with eyes CLOSED (sensory ataxia), not with eyes OPEN (cerebellar ataxia).'),
('d7a83b06-7070-5891-b3df-472010cfa01f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The intention tremor (a cerebellar sign) is:', '["A tremor present with walking","A tremor present at rest","A tremor that WORSENS with purposeful movement","A tremor present with standing","A tremor present with posture holding"]'::jsonb, 'A tremor that WORSENS with purposeful movement', 'Intention tremor is distinguished from the resting tremor of Parkinson disease.'),
('0daedf80-d0f4-5d64-b5b3-ba0ff11298b2'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Dysdiadochokinesia (a cerebellar sign) is:', '["The inability to perform fine movements","The inability to perform strong movements","The inability to perform rapid, alternating movements","The inability to perform slow movements","The inability to perform coordinated movements"]'::jsonb, 'The inability to perform rapid, alternating movements', 'Dysdiadochokinesia is a classic cerebellar sign.'),
('cb0bab4c-8c0a-500e-a573-c07d8f56c81f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Dysmetria (a cerebellar sign) is:', '["Inability to move the finger and its associated anatomical structures","Past-pointing (overshoot or undershoot) in the finger-to-nose or heel-to-shin test","Inability to coordinate eye movements and its associated anatomical structures","Inability to point to the target and its associated anatomical structures","Inability to move the heel and its associated anatomical structures"]'::jsonb, 'Past-pointing (overshoot or undershoot) in the finger-to-nose or heel-to-shin test', 'Dysmetria is due to loss of the check (rebound phenomenon).'),
('b26ffaba-2c81-5584-ae2f-a8086a348e70'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Cerebellar nystagmus is:', '["Vertical nystagmus and its associated anatomical structures","Positional nystagmus and its associated anatomical structures","Horizontal nystagmus, with the fast phase TOWARD the side of the cerebellar lesion","Pendular nystagmus and its associated anatomical structures","Rotatory nystagmus and its associated anatomical structures"]'::jsonb, 'Horizontal nystagmus, with the fast phase TOWARD the side of the cerebellar lesion', 'Cerebellar nystagmus: the fast phase is TOWARD the side of the lesion.'),
('45de6c8f-b926-5d26-8dc3-03345ebdca3b'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'With respect to management, The brainstem consists of:', '["The thalamus and the hypothalamus and its associated anatomical structures","Only the pons and its associated anatomical structures","Only the medulla oblongata and its associated anatomical structures","Only the midbrain and its associated anatomical structures","The midbrain (mesencephalon), the pons (metencephalon), and the medulla oblongata"]'::jsonb, 'The midbrain (mesencephalon), the pons (metencephalon), and the medulla oblongata', 'The brainstem connects the cerebrum and cerebellum to the spinal cord.'),
('0e034d06-509c-5477-813a-350b90f4cdcd'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'For a patient presenting with symptoms, The midbrain (mesencephalon) contains:', '["The cerebral peduncles, tegmentum, tectum","Only the tectum","Only the cerebral peduncles","Only the aqueduct","Only the tegmentum"]'::jsonb, 'The cerebral peduncles, tegmentum, tectum', 'The midbrain is the center for eye and ear reflexes.'),
('2011d6fc-d061-5024-adb7-81de4a8ceb47'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Regarding clinical scenarios, The cerebral peduncles (crus cerebri) contain:', '["Only the cerebellar tracts and its associated anatomical structures","The corticospinal tract, corticobulbar tract, and corticopontine fibers","Only the sensory tracts and its associated anatomical structures","Only the corticospinal tract and its associated anatomical structures","Only the corticobulbar tract and its associated anatomical structures"]'::jsonb, 'The corticospinal tract, corticobulbar tract, and corticopontine fibers', 'The crus cerebri is the motor pathway of the midbrain.'),
('b54d7076-4e6d-58d4-b9b2-806c7ead23ad'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The superior colliculi (tectum of midbrain) are the center for:', '["Auditory reflexes","Vestibular reflexes","Olfactory reflexes","Visual reflexes","Somatosensory reflexes"]'::jsonb, 'Visual reflexes', 'The superior colliculi coordinate eye and head movements.'),
('a2f142ac-161f-59e0-a3fd-bdf59cdeebed'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The inferior colliculi (tectum of midbrain) are the center for:', '["Somatosensory reflexes","Olfactory reflexes","Visual reflexes","Vestibular reflexes","Auditory reflexes"]'::jsonb, 'Auditory reflexes', 'The inferior colliculi are part of the central auditory pathway.'),
('490c5c19-6010-54ab-884a-d45606510b8d'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The red nucleus (in the midbrain tegmentum) is involved in:', '["Motor coordination","Auditory processing","Sensory processing","Visual processing","Autonomic control"]'::jsonb, 'Motor coordination', 'The red nucleus (rubrospinal tract) is an extrapyramidal motor pathway.'),
('21f8232a-31e4-5267-82d7-092ed0fc174b'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The substantia nigra is involved in motor control via:', '["The reticulospinal pathway","The rubrospinal pathway","The corticospinal pathway","The corticobulbar pathway","The nigrostriatal pathway"]'::jsonb, 'The nigrostriatal pathway', 'The substantia nigra uses dopamine as its neurotransmitter.'),
('26ed983a-467c-50fb-a84b-ffc3b75d7376'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'In a surgical context, The oculomotor nerve (CN III) nucleus is located in:', '["The medulla oblongata","The pons","The cerebellum","The diencephalon","The midbrain"]'::jsonb, 'The midbrain', 'The CN III nucleus is in the periaqueductal gray of the midbrain.'),
('87af7354-a1f8-56a0-b5b5-9f9ca196e7ef'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'On diagnostic evaluation, The trochlear nerve (CN IV) nucleus is located in:', '["The cerebellum","The midbrain","The diencephalon","The pons","The medulla oblongata"]'::jsonb, 'The midbrain', 'CN IV is the ONLY cranial nerve that exits from the dorsal surface of the brainstem.'),
('627bb71d-fdcf-5eeb-8d6c-19bf636b0f9b'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The pons (the bridge) contains:', '["Only the CN VI nucleus and its associated anatomical structures","Only the CN V nucleus and its associated anatomical structures","Only the CN VII nucleus and its associated anatomical structures","Only the CN VIII nucleus and its associated anatomical structures","Pontine nuclei (corticopontocerebellar pathway), CN V, VI, VII, and VIII nuclei"]'::jsonb, 'Pontine nuclei (corticopontocerebellar pathway), CN V, VI, VII, and VIII nuclei', 'The pons is the bridge between the cerebrum and the cerebellum.'),
('1ddbaef2-bd30-532b-8b9f-1b5b8a884fc3'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'With respect to management, The trigeminal nerve (CN V) nuclei are located in:', '["Only the pons and its associated anatomical structures","Only the midbrain and its associated anatomical structures","Only the medulla and its associated anatomical structures","Only the spinal cord and its associated anatomical structures","The midbrain (mesencephalic nucleus), the pons"]'::jsonb, 'The midbrain (mesencephalic nucleus), the pons', 'CN V has 3 sensory divisions: V1, V2, V3.'),
('4ad159e0-34b0-5e3a-82fa-9e02ed50a117'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'For a patient presenting with symptoms, The abducens nerve (CN VI) nucleus is located in:', '["The diencephalon","The midbrain","The pons","The medulla oblongata","The cerebellum"]'::jsonb, 'The pons', 'The CN VI nucleus is in the dorsal pons (facial colliculus).'),
('588ef58d-c8ad-5d5a-9d67-a25aa471c23a'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Regarding clinical scenarios, The facial nerve (CN VII) nucleus is located in:', '["The pons","The midbrain","The cerebellum","The medulla oblongata","The diencephalon"]'::jsonb, 'The pons', 'CN VII: motor (face), sensory (taste), and parasympathetic (salivation and lacrimation).'),
('45e4dd98-96b7-58b4-bd42-e2df0dc47c72'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'In a surgical context, The vestibulocochlear nerve (CN VIII) nuclei are located in:', '["The pons and the medulla","The midbrain","Only the pons","The cerebellum","Only the medulla"]'::jsonb, 'The pons and the medulla', 'CN VIII: cochlear (hearing) and vestibular (balance).'),
('b52ee5c7-0ebc-5b31-b0dc-82381c6390aa'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The medulla oblongata contains:', '["Only the olives and its associated anatomical structures","Only the pyramids and its associated anatomical structures","Only CN IX and X nuclei and its associated anatomical structures","Only the respiratory center and its associated anatomical structures","CN IX, X, XI, XII nuclei, the pyramids (corticospinal tracts), the olives"]'::jsonb, 'CN IX, X, XI, XII nuclei, the pyramids (corticospinal tracts), the olives', 'The medulla is the vital center (cardiac, respiratory, vasomotor).'),
('58fe4554-9aec-5acc-abae-70605621bacc'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The pyramids of the medulla contain:', '["The corticobulbar tracts","The dorsal columns","The medial lemniscus","The corticospinal tracts","The spinothalamic tract"]'::jsonb, 'The corticospinal tracts', 'The pyramids are the motor pathway. The decussation of the pyramids is the crossing of the corticospinal tract.'),
('6d642873-75b8-5e80-965f-5a2ec1d4b2d7'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The decussation of the pyramids (motor decussation) occurs at:', '["The caudal medulla","The pons","The spinal cord","The midbrain","The rostral medulla"]'::jsonb, 'The caudal medulla', 'The decussation of the pyramids occurs at the caudal medulla.'),
('1794eec6-5cba-58ef-a56f-b671cfcadd24'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The olives (inferior olivary nuclei) of the medulla are involved in:', '["Autonomic control","Visual processing","Cerebellar coordination","Motor execution","Sensory processing"]'::jsonb, 'Cerebellar coordination', 'The inferior olive projects to the cerebellum via the inferior cerebellar peduncle.'),
('90efed60-3100-5c9d-a28c-2f6c44fd8fb7'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The glossopharyngeal nerve (CN IX) nucleus is located in:', '["The cerebellum","The midbrain","The pons","The diencephalon","The medulla"]'::jsonb, 'The medulla', 'CN IX: taste (posterior 1/3 of tongue) and sensation (pharynx).'),
('58f4c5cb-75c0-52cb-b6bf-89885a6bc69e'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The vagus nerve (CN X) nucleus is located in:', '["The midbrain","The cerebellum","The diencephalon","The medulla","The pons"]'::jsonb, 'The medulla', 'CN X: the wandering nerve, parasympathetic outflow to thoracic and abdominal viscera.'),
('f6e65ede-907e-5c53-8b74-b7e2d25e9759'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'On diagnostic evaluation, The accessory nerve (CN XI) nucleus is located in:', '["Only the spinal cord and its associated structures","The pons and its associated structures","The midbrain and its associated structures","Only the medulla and its associated structures","The medulla and the cervical spinal cord"]'::jsonb, 'The medulla and the cervical spinal cord', 'CN XI: the spinal root innervates the SCM and the trapezius.'),
('685f7aff-0e1e-5e19-9704-c56ef91e07a9'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'With respect to management, The hypoglossal nerve (CN XII) nucleus is located in:', '["The midbrain","The medulla","The diencephalon","The pons","The cerebellum"]'::jsonb, 'The medulla', 'CN XII: motor innervation of the intrinsic and extrinsic muscles of the tongue.'),
('aa904ec9-d563-510f-8296-f4b167bc51eb'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The reticular formation (RF) is:', '["A discrete nucleus in the brainstem and its associated anatomical structures","A layer of the cortex and its associated anatomical structures","A diffuse network of neurons in the brainstem (arousal, consciousness, sleep-wake cycle","A tract in the brainstem and its associated anatomical structures","A nucleus in the thalamus and its associated anatomical structures"]'::jsonb, 'A diffuse network of neurons in the brainstem (arousal, consciousness, sleep-wake cycle', 'The reticular activating system (RAS) is responsible for wakefulness.'),
('e54f9ad5-ac9e-506d-8bca-6646d8b79cbb'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The reticular activating system (RAS) is responsible for:', '["Motor control","Sensory processing","Autonomic control","The sleep state","Arousal and consciousness"]'::jsonb, 'Arousal and consciousness', 'A lesion of the RAS causes coma (loss of consciousness).'),
('15383573-3e67-536d-a4c2-c636d4489b96'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The locked-in syndrome (a lesion of the ventral pons) is characterized by:', '["Persistent vegetative state and its associated anatomical structures","Coma and its associated anatomical structures","Catatonia and its associated anatomical structures","Quadriplegia and mutism, but preserved consciousness and vertical eye movements","Brain death and its associated anatomical structures"]'::jsonb, 'Quadriplegia and mutism, but preserved consciousness and vertical eye movements', 'Locked-in syndrome: the patient is awake and alert but cannot move or speak.'),
('e087afaf-3e15-5d8b-bfe1-a83aede080ef'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The persistent vegetative state (PVS) is characterized by:', '["Minimally conscious state and its associated anatomical structures","Locked-in syndrome and its associated anatomical structures","Wakefulness (eye-opening and sleep-wake cycles), but NO awareness","Brain death and its associated anatomical structures","Coma and its associated anatomical structures"]'::jsonb, 'Wakefulness (eye-opening and sleep-wake cycles), but NO awareness', 'PVS: the brainstem is intact, but the cortex is not functioning.'),
('d6886398-159c-56c4-b61d-431723697e69'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Brain death is characterized by:', '["Complete and irreversible loss of all brain function (cortex AND brainstem), with apnea","Loss of cortical function only and its associated anatomical structures","Locked-in syndrome and its associated anatomical structures","Loss of brainstem function only and its associated anatomical structures","Coma with preserved brainstem reflexes and its associated anatomical structures"]'::jsonb, 'Complete and irreversible loss of all brain function (cortex AND brainstem), with apnea', 'Brain death: no pupillary, corneal, oculocephalic, cough, or gag reflex.'),
('e8f2344a-9d2b-50b6-ab04-36e053a2c942'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The meninges from outer to inner are:', '["Dura mater, arachnoid mater, and pia mater","Pia, arachnoid, and dura","Pia, dura, and arachnoid","Dura, pia, and arachnoid","Arachnoid, dura, and pia"]'::jsonb, 'Dura mater, arachnoid mater, and pia mater', 'The meninges: tough mother (dura), spider-like (arachnoid), gentle mother (pia).'),
('3b4ab02d-3884-5c4d-8e5d-4c1160d3b2b9'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The dura mater of the brain has:', '["2 layers: the periosteal (outer) and the meningeal (inner), with dural venous sinuses in between","4 layers and its associated anatomical structures","5 layers and its associated anatomical structures","A single layer and its associated anatomical structures","3 layers and its associated anatomical structures"]'::jsonb, '2 layers: the periosteal (outer) and the meningeal (inner), with dural venous sinuses in between', 'The cranial dura: the periosteal layer is the endosteum of the skull.'),
('5ae48875-fdac-58f1-9212-721fe1445393'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'For a patient presenting with symptoms, The falx cerebri is:', '["A dural fold covering the pituitary gland","A dural fold separating the two cerebellar hemispheres","A sickle-shaped dural fold that SEPARATES the two cerebral hemispheres","A dural fold separating the cerebrum from the cerebellum","A dural fold covering the olfactory bulb"]'::jsonb, 'A sickle-shaped dural fold that SEPARATES the two cerebral hemispheres', 'The falx cerebri is a vertical dural fold in the longitudinal fissure.'),
('9907b74f-e8d1-5ee4-9492-12e7a0da7efd'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The tentorium cerebelli is:', '["A tent-shaped dural fold that SEPARATES the cerebrum from the cerebellum","A dural fold separating the two cerebellar hemispheres","A dural fold separating the two cerebral hemispheres","A dural fold covering the olfactory bulb","A dural fold covering the pituitary gland"]'::jsonb, 'A tent-shaped dural fold that SEPARATES the cerebrum from the cerebellum', 'The tentorium cerebelli is a horizontal dural fold.'),
('9a843b0b-50b2-513e-971d-240d43dd2a3a'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The falx cerebelli is:', '["A small sickle-shaped dural fold that SEPARATES the two cerebellar hemispheres","A dural fold covering the pituitary gland","A dural fold separating the cerebrum from the cerebellum","A dural fold separating the two cerebral hemispheres","A dural fold covering the olfactory bulb"]'::jsonb, 'A small sickle-shaped dural fold that SEPARATES the two cerebellar hemispheres', 'The falx cerebelli is a small vertical dural fold.'),
('ddedcc4a-feed-579b-8ba2-933826b6e440'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Regarding clinical scenarios, The diaphragma sellae is:', '["A dural fold separating the two cerebellar hemispheres","A dural fold covering the olfactory bulb","A dural fold separating the two cerebral hemispheres","A dural fold separating the cerebrum from the cerebellum","A circular dural fold covering the pituitary gland"]'::jsonb, 'A circular dural fold covering the pituitary gland', 'The diaphragma sellae is the roof of the sella turcica.'),
('4003a11c-e710-56c2-937d-f8441a9d34ea'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The supratentorial and infratentorial compartments are separated by:', '["The diaphragma sellae","The falx cerebelli","The tentorium cerebelli","The cavernous sinus","The falx cerebri"]'::jsonb, 'The tentorium cerebelli', 'Herniation of the brain through the tentorial notch is transtentorial herniation.'),
('2022e17a-a14e-5e85-8313-214ca0410eb7'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The superior sagittal sinus is located:', '["In the tentorium cerebelli","In the transverse sinus","In the attached margin of the falx cerebri","In the free margin of the falx cerebri","In the cavernous sinus"]'::jsonb, 'In the attached margin of the falx cerebri', 'The falx cerebri contains the SSS in the superior (attached) border.'),
('5dc97a22-f2b1-59ee-972e-2a8b38ff3b93'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The cavernous sinus is located:', '["On either side of the sella turcica","In the tentorium cerebelli","In the falx cerebri","In the foramen magnum","In the falx cerebelli"]'::jsonb, 'On either side of the sella turcica', 'CN III, IV, V1, V2, VI and the ICA pass through the cavernous sinus.'),
('0e6e5322-f945-5f82-889a-3669089d8e45'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The internal carotid artery (ICA) enters the cranial cavity via:', '["The foramen magnum","The foramen spinosum","The foramen ovale","The carotid canal","The foramen rotundum"]'::jsonb, 'The carotid canal', 'The ICA passes through the cavernous sinus (C-shaped siphon).'),
('c61db746-7f06-59ed-b1c5-e2967cb77cee'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The vertebral artery enters the cranial cavity via:', '["The carotid canal","The foramen magnum","The foramen rotundum","The foramen ovale","The foramen spinosum"]'::jsonb, 'The foramen magnum', 'The vertebral artery ascends through the transverse foramina of C6-C1 and enters via foramen magnum.');
insert into fcps_mcq_stage (id, subject_name, chapter_name, question, options, correct_answer, explanation) values
('b5e034e0-1c06-5475-9ac0-061797a36c42'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'In a surgical context, The circle of Willis is formed by:', '["Only basilar artery and PCA","Only vertebral artery and basilar artery","Only ACA and PCA","ACA, AComA, ICA, PCA, and PComA","Only ICA and ACA"]'::jsonb, 'ACA, AComA, ICA, PCA, and PComA', 'Circle of Willis: ACA (anterior cerebral), AComA (anterior communicating), ICA, PCA (posterior cerebral), PComA (posterior communicating).'),
('944f1896-93fc-5005-9038-996465aacb2a'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'On diagnostic evaluation, The anterior cerebral artery (ACA) supplies:', '["The medial surface of the frontal and parietal lobes","The occipital lobe","The cerebellum","The lateral surface of the frontal and parietal lobes","The temporal lobe"]'::jsonb, 'The medial surface of the frontal and parietal lobes', 'ACA stroke: contralateral motor and sensory loss of the LEG (lower limb).'),
('b5edc902-fb35-5571-a8b2-418f267e9d3d'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'With respect to management, The middle cerebral artery (MCA) supplies:', '["The cerebellum and its associated anatomical structures","The brainstem and its associated anatomical structures","The medial surface of the brain and its associated anatomical structures","The occipital lobe and its associated anatomical structures","The lateral surface of the frontal, parietal, and temporal lobes (face and arm area of motor and"]'::jsonb, 'The lateral surface of the frontal, parietal, and temporal lobes (face and arm area of motor and', 'MCA stroke: contralateral motor and sensory loss of the FACE and ARM plus aphasia.'),
('b5397036-2640-5d2d-b46f-4b60265c5681'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'For a patient presenting with symptoms, The posterior cerebral artery (PCA) supplies:', '["The occipital lobe (primary visual cortex) and the medial temporal lobe","The brainstem and its associated anatomical structures","The cerebellum and its associated anatomical structures","The frontal lobe and its associated anatomical structures","The parietal lobe and its associated anatomical structures"]'::jsonb, 'The occipital lobe (primary visual cortex) and the medial temporal lobe', 'PCA stroke: contralateral homonymous hemianopsia (visual field defect).'),
('4e34c302-ec70-5992-8e59-909c5d33bdfb'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Regarding the anatomical aspect, Regarding clinical scenarios, The basilar artery is formed by:', '["The union of the two vertebral arteries","The union of the ACA and MCA","The union of the vertebral and carotid arteries","The union of the two ICAs","The union of the PCA and PComA"]'::jsonb, 'The union of the two vertebral arteries', 'The basilar artery gives off pontine branches, SCA, AICA, and PICA.'),
('ff785e03-4079-528f-8d90-7aee900945c3'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Vertebrobasilar insufficiency (posterior circulation TIA) causes:', '["Seizures and its associated anatomical structures","Hemianopsia and its associated anatomical structures","Diplopia, dysarthria, dysphagia, vertigo, ataxia, and drop attacks","Aphasia and its associated anatomical structures","Hemiparesis and its associated anatomical structures"]'::jsonb, 'Diplopia, dysarthria, dysphagia, vertigo, ataxia, and drop attacks', 'VBI: the 5 Ds - dizziness, diplopia, dysarthria, dysphagia, and drop attacks.'),
('878b9701-5e86-5e2c-bb13-91fac4ad9a49'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The anterior spinal artery (ASA) supplies:', '["The anterior 2/3 of the spinal cord","The cerebellum","The brainstem","The posterior 1/3 of the spinal cord","The entire spinal cord"]'::jsonb, 'The anterior 2/3 of the spinal cord', 'ASA syndrome: bilateral loss of motor and pain/temperature with preserved proprioception and vibration.'),
('eedb7544-00a5-5508-9084-b06a4a7607a5'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The posterior spinal artery (PSA) supplies:', '["The anterior 2/3 of the spinal cord","The entire spinal cord","The posterior 1/3 of the spinal cord","The cerebellum","The brainstem"]'::jsonb, 'The posterior 1/3 of the spinal cord', 'PSA syndrome: loss of proprioception and vibration with preserved motor and pain/temperature.'),
('e0264567-eef0-5919-907c-ed0792f8236e'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Cerebrospinal fluid (CSF) is produced by:', '["The arachnoid granulations","The astrocytes","The ependymal cells","The microglia","The choroid plexus"]'::jsonb, 'The choroid plexus', 'CSF: total volume about 150 mL; production rate about 500 mL/day.'),
('f64d0ad7-2efa-58d7-90c7-92447dcf36af'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The circulation of CSF:', '["4th ventricle -> 3rd ventricle -> lateral ventricles and its associated anatomical structures","Lateral ventricles -> interventricular foramina (Monro) -> 3rd ventricle -> cerebral aqueduct ->","Subarachnoid space -> ventricles and its associated anatomical structures","Lateral ventricles -> 4th ventricle -> 3rd ventricle and its associated anatomical structures","3rd ventricle -> 4th ventricle -> lateral ventricles and its associated anatomical structures"]'::jsonb, 'Lateral ventricles -> interventricular foramina (Monro) -> 3rd ventricle -> cerebral aqueduct ->', 'Hydrocephalus is the excess CSF in the ventricular system.'),
('649f1a67-c494-5dea-ba64-1cc03360bd0a'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Arachnoid granulations (Pacchionian granulations) are:', '["The storage site of CSF and its associated anatomical structures","The filtration site of CSF and its associated anatomical structures","The circulation site of CSF and its associated anatomical structures","Projections of the arachnoid mater into the superior sagittal sinus","The production site of CSF and its associated anatomical structures"]'::jsonb, 'Projections of the arachnoid mater into the superior sagittal sinus', 'Arachnoid granulations allow one-way flow of CSF into the venous system.'),
('ba71592e-928f-5eb8-8d9d-a9d7e623cb5c'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Hydrocephalus ex vacuo is:', '["Communicating hydrocephalus and its associated anatomical structures","Congenital hydrocephalus and its associated anatomical structures","Normal pressure hydrocephalus and its associated anatomical structures","Enlargement of ventricles due to brain atrophy, NOT increased CSF pressure","Obstructive hydrocephalus and its associated anatomical structures"]'::jsonb, 'Enlargement of ventricles due to brain atrophy, NOT increased CSF pressure', 'Hydrocephalus ex vacuo is seen in Alzheimer disease, stroke, trauma.'),
('f82d3909-8345-5567-9eeb-e3e280db582a'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Normal pressure hydrocephalus (NPH) is characterized by:', '["Headache, vomiting, and papilledema and its associated anatomical structures","The classic triad: gait apraxia, urinary incontinence, and dementia","Coma and its associated anatomical structures","Ataxia and its associated anatomical structures","Seizures and its associated anatomical structures"]'::jsonb, 'The classic triad: gait apraxia, urinary incontinence, and dementia', 'NPH: gait disturbance is the first and most reversible symptom.'),
('086755ad-7a77-5d2f-bda4-cb876c7ddbe8'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The limbic system (emotional brain) includes:', '["Only the hypothalamus and its associated anatomical structures","Only the amygdala and its associated anatomical structures","Only the cingulate gyrus and its associated anatomical structures","Only the hippocampus and its associated anatomical structures","The hippocampus, amygdala, cingulate gyrus, fornix, mammillary bodies, and hypothalamus"]'::jsonb, 'The hippocampus, amygdala, cingulate gyrus, fornix, mammillary bodies, and hypothalamus', 'The limbic system is involved in emotion, memory, learning, and behavior.'),
('2208a3ae-96e8-5d57-b811-0c6b10057f53'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The hippocampus is involved in:', '["Emotion only and its associated anatomical structures","Sensory processing only and its associated anatomical structures","Motor control only and its associated anatomical structures","Autonomic control only and its associated anatomical structures","Memory (declarative and episodic memory) and learning"]'::jsonb, 'Memory (declarative and episodic memory) and learning', 'Bilateral lesion of the hippocampus causes anterograde amnesia.'),
('edd84611-32b1-5fcd-bbfa-68ce1e29cd52'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The amygdala is involved in:', '["Memory only and its associated anatomical structures","Motor control only and its associated anatomical structures","Sensory processing only and its associated anatomical structures","Autonomic control only and its associated anatomical structures","Emotion (fear, anxiety, and aggression) and social behavior"]'::jsonb, 'Emotion (fear, anxiety, and aggression) and social behavior', 'Bilateral lesion of the amygdala causes Kluver-Bucy syndrome.'),
('1a2eff77-303c-52ec-8a80-1880412cb31e'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Kluver-Bucy syndrome (bilateral lesion of the amygdala) is characterized by:', '["Aphasia and its associated anatomical structures","Amnesia and its associated anatomical structures","Hyperphagia, hypersexuality, hyperorality, and visual agnosia","Agnosia and its associated anatomical structures","Apraxia and its associated anatomical structures"]'::jsonb, 'Hyperphagia, hypersexuality, hyperorality, and visual agnosia', 'Kluver-Bucy syndrome: psychic blindness and placidity.'),
('2ab038af-406c-5f27-8d52-3d95fe2a9c87'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The cingulate gyrus (part of the limbic system) is involved in:', '["Memory only and its associated anatomical structures","Emotion, pain processing, and cognitive control","Sensory processing only and its associated anatomical structures","Motor control only and its associated anatomical structures","Vision only and its associated anatomical structures"]'::jsonb, 'Emotion, pain processing, and cognitive control', 'The anterior cingulate (ACC) is involved in emotion and pain.'),
('0abc887e-aaa7-5e62-8a7a-733ebce7df0e'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The fornix (part of the limbic system) connects:', '["The amygdala to the hypothalamus","The cerebellum to the brainstem","The hippocampus to the mammillary bodies","The thalamus to the cortex","The basal ganglia to the cortex"]'::jsonb, 'The hippocampus to the mammillary bodies', 'The fornix is the major output pathway from the hippocampus.'),
('fd8014d0-9f3e-5739-b72c-81b63cfffc57'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The mammillary bodies (part of the hypothalamus) are involved in:', '["Emotion only","Vision only","Memory (Papez circuit) and learning","Motor control only","Sensory processing only"]'::jsonb, 'Memory (Papez circuit) and learning', 'Lesion of the mammillary bodies is seen in Wernicke-Korsakoff syndrome.'),
('b0525e4f-40f1-5512-8182-95598358e777'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Wernicke-Korsakoff syndrome (thiamine deficiency) is characterized by:', '["Confusion, ataxia, and ophthalmoplegia (Wernicke encephalopathy) + amnesia and confabulation (Kor","Dementia and its associated anatomical structures and its associated structures","Apraxia and its associated anatomical structures and its associated structures","Aphasia and its associated anatomical structures and its associated structures","Agnosia and its associated anatomical structures and its associated structures"]'::jsonb, 'Confusion, ataxia, and ophthalmoplegia (Wernicke encephalopathy) + amnesia and confabulation (Kor', 'Wernicke-Korsakoff syndrome: chronic alcohol use. Treatment is thiamine (vitamin B1).'),
('b40f32a1-f9b7-50a3-9db5-d6642a267213'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The sympathetic nervous system (fight or flight) is characterized by:', '["Long preganglionic and short postganglionic fibers","The enteric nervous system","Craniosacral outflow","Acetylcholine as the postganglionic neurotransmitter","Thoracolumbar outflow (T1-L2), short preganglionic and long postganglionic fibers"]'::jsonb, 'Thoracolumbar outflow (T1-L2), short preganglionic and long postganglionic fibers', 'Preganglionic neurotransmitter is ACh; postganglionic is NE (except sweat glands).'),
('eacef82a-cc9b-5df2-b97f-1db0c245ef78'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The parasympathetic nervous system (rest and digest) is characterized by:', '["Craniosacral outflow (CN III, VII, IX, X and S2-S4), long preganglionic and short postganglionic","Short preganglionic and long postganglionic fibers and its associated anatomical structures","Thoracolumbar outflow and its associated anatomical structures","The enteric nervous system and its associated anatomical structures","Norepinephrine as the postganglionic neurotransmitter and its associated anatomical structures"]'::jsonb, 'Craniosacral outflow (CN III, VII, IX, X and S2-S4), long preganglionic and short postganglionic', 'Both preganglionic and postganglionic neurotransmitters are ACh.'),
('3a72f962-f637-5b5e-94bf-3ba70f892f73'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The sympathetic chain (sympathetic trunk) is located:', '["In the cranial ganglia","On either side of the vertebral column","In the prevertebral ganglia","In the dorsal root ganglia","In the terminal ganglia"]'::jsonb, 'On either side of the vertebral column', 'The sympathetic chain extends from the base of the skull to the coccyx.'),
('977a3b57-dec5-5b60-aa25-1ffb13dc64a9'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The celiac ganglion (a prevertebral ganglion) innervates:', '["The midgut","The kidney","The foregut","The adrenal gland","The hindgut"]'::jsonb, 'The foregut', 'The celiac ganglion (solar plexus) is at the root of the celiac artery.'),
('ca78f16f-f6ec-5ebb-ac37-a37e8036c4bf'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The superior mesenteric ganglion innervates:', '["The adrenal gland","The midgut","The hindgut","The foregut","The kidney"]'::jsonb, 'The midgut', 'The superior mesenteric artery supplies the midgut.'),
('60327090-29ef-53f9-ab10-ba60f9eeb9ed'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The inferior mesenteric ganglion innervates:', '["The foregut","The midgut","The kidney","The adrenal gland","The hindgut"]'::jsonb, 'The hindgut', 'The inferior mesenteric artery supplies the hindgut.'),
('ea7b3dbd-8738-5524-a635-6aa2a17d0c94'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The adrenal medulla is innervated by:', '["Preganglionic parasympathetic fibers","Postganglionic parasympathetic fibers","Somatic nerves","Preganglionic sympathetic fibers","Postganglionic sympathetic fibers"]'::jsonb, 'Preganglionic sympathetic fibers', 'The adrenal medulla releases epinephrine and norepinephrine into the bloodstream.'),
('684a85d8-441c-5b81-9a00-798336eb6b15'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The enteric nervous system (ENS) is:', '["A part of the somatic nervous system","A part of the parasympathetic nervous system","A part of the central nervous system","The third division of the ANS","A part of the sympathetic nervous system"]'::jsonb, 'The third division of the ANS', 'The ENS: myenteric (Auerbach) plexus and submucosal (Meissner) plexus.'),
('806d917a-14f4-5890-a8d8-0880ac4edb8c'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The corticospinal tract (pyramidal tract) is:', '["The motor pathway from the cortex to the spinal cord","The cerebellar pathway","The basal ganglia pathway","The sensory pathway from the spinal cord to the cortex","The autonomic pathway"]'::jsonb, 'The motor pathway from the cortex to the spinal cord', 'The corticospinal tract decussates at the caudal medulla (pyramidal decussation).'),
('a7b79dfe-fe5f-5452-ac46-7d8988cf9548'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The corticobulbar tract is:', '["The sensory pathway from the face to the cortex","The motor pathway from the cortex to the spinal cord","The motor pathway from the cortex to the cranial nerve motor nuclei","The cerebellar pathway","The autonomic pathway"]'::jsonb, 'The motor pathway from the cortex to the cranial nerve motor nuclei', 'Corticobulbar tract: bilateral innervation of most CN motor nuclei (except lower facial nucleus and CN XII).'),
('286f6819-f975-5682-8ceb-4d50d9e52ec4'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'An UMN (upper motor neuron) lesion is characterized by:', '["Extrapyramidal signs","Spasticity, hyperreflexia, Babinski sign, and muscle weakness","Ataxia","Sensory loss","Flaccidity, hyporeflexia, fasciculations, and muscle atrophy"]'::jsonb, 'Spasticity, hyperreflexia, Babinski sign, and muscle weakness', 'UMN lesion: corticospinal tract lesion ABOVE the anterior horn cell.'),
('f29636c4-a701-5281-90ef-4b3cb99289ca'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'An LMN (lower motor neuron) lesion is characterized by:', '["Extrapyramidal signs","Flaccidity, hyporeflexia, fasciculations, fibrillations, and muscle atrophy","Sensory loss","Spasticity, hyperreflexia, and Babinski sign","Ataxia"]'::jsonb, 'Flaccidity, hyporeflexia, fasciculations, fibrillations, and muscle atrophy', 'LMN lesion: anterior horn cell or cranial nerve nucleus lesion.'),
('32311966-d64e-5e29-b9d1-5d743a056c2e'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The dorsal column-medial lemniscus (DCML) pathway carries:', '["Pain and temperature and its associated anatomical structures","Motor output and its associated anatomical structures","Itch and its associated anatomical structures","Discriminative touch, proprioception, and vibration","Crude touch and its associated anatomical structures"]'::jsonb, 'Discriminative touch, proprioception, and vibration', 'DCML: fasciculus gracilis (lower body) and fasciculus cuneatus (upper body).'),
('288524b6-4c26-5fd1-8768-ad017969c064'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The fasciculus gracilis carries sensation from:', '["The neck","The upper half of the body","The lower half of the body","The head","The face"]'::jsonb, 'The lower half of the body', 'The fasciculus gracilis is the medial part of the dorsal column.'),
('ad322996-1953-5945-a7c3-112d0c1c99bf'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The fasciculus cuneatus carries sensation from:', '["The upper half of the body","The lower half of the body","The face","The neck","The head"]'::jsonb, 'The upper half of the body', 'The fasciculus cuneatus is the lateral part of the dorsal column.'),
('db1a9c92-55c2-5fb5-98f8-9dabd0b684f2'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The spinothalamic tract (anterolateral system) carries:', '["Pain and temperature","Vibration","Autonomic output","Touch and proprioception","Motor output"]'::jsonb, 'Pain and temperature', 'Spinothalamic tract: lateral STT (pain/temperature) and anterior STT (crude touch).'),
('d01d9b32-f28f-5195-98cb-0dfb5fd4ccb8'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'In a surgical context, The spinocerebellar tracts carry:', '["Motor output to the muscles and its associated anatomical structures","Autonomic output to the viscera and its associated anatomical structures","Unconscious proprioception from muscle spindles and Golgi tendon organs to the cerebellum","Conscious sensation to the cortex and its associated anatomical structures","Pain and temperature to the thalamus and its associated anatomical structures"]'::jsonb, 'Unconscious proprioception from muscle spindles and Golgi tendon organs to the cerebellum', 'Spinocerebellar tracts: dorsal (posterior) and ventral (anterior).'),
('384962f5-16c1-5187-8f4a-0828659aff17'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The dorsal spinocerebellar tract enters the cerebellum via:', '["The medulla","The superior cerebellar peduncle","The inferior cerebellar peduncle","The spinal cord","The middle cerebellar peduncle"]'::jsonb, 'The inferior cerebellar peduncle', 'The dorsal SCT (Flechsig tract) is an ipsilateral (uncrossed) pathway from Clarke column.'),
('6d913698-4e4f-5e59-8a09-25434e7a3e38'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The ventral spinocerebellar tract enters the cerebellum via:', '["The spinal cord","The medulla","The superior cerebellar peduncle","The inferior cerebellar peduncle","The middle cerebellar peduncle"]'::jsonb, 'The superior cerebellar peduncle', 'The ventral SCT (Gower tract) is a contralateral (crossed) pathway.'),
('59ed30ab-9808-5a42-92e0-4549ef4aa9d2'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The trigeminal nerve (CN V) carries sensation from:', '["The trunk","The face","The scalp","The limbs","The neck"]'::jsonb, 'The face', 'CN V has 3 divisions: ophthalmic (V1), maxillary (V2), and mandibular (V3).'),
('4cac83f5-ef97-55fd-9ca6-cb841249b58a'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The facial nerve (CN VII) carries motor innervation to:', '["The muscles of the larynx and its associated anatomical structures","The muscles of the tongue and its associated anatomical structures","The muscles of the FACE (mimetic muscles: frontalis, orbicularis oculi, orbicularis oris","The muscles of the pharynx and its associated anatomical structures","The muscles of mastication and its associated anatomical structures"]'::jsonb, 'The muscles of the FACE (mimetic muscles: frontalis, orbicularis oculi, orbicularis oris', 'CN VII: LMN lesion (Bell palsy) vs UMN lesion (CVA).'),
('15bbe3c5-2ca9-5945-b1dd-b295704dae36'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Bell palsy (idiopathic facial nerve palsy) is:', '["An LMN lesion of CN VII, causing ipsilateral paralysis of the ENTIRE hemi-face","An UMN lesion of CN VII and its associated anatomical structures","A brainstem lesion and its associated anatomical structures","A basal ganglia lesion and its associated anatomical structures","A cerebellar lesion and its associated anatomical structures"]'::jsonb, 'An LMN lesion of CN VII, causing ipsilateral paralysis of the ENTIRE hemi-face', 'Bell palsy: the forehead is WEAK (orbicularis oculi and frontalis affected).'),
('9b7a91e4-0c78-5ae3-9d48-e6701e99454d'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'An UMN facial palsy (central facial palsy) is:', '["A basal ganglia lesion and its associated anatomical structures","An LMN lesion of CN VII and its associated anatomical structures","A brainstem lesion and its associated anatomical structures","A lesion ABOVE the facial nucleus (corticobulbar tract), causing contralateral paralysis of the L","A cerebellar lesion and its associated anatomical structures"]'::jsonb, 'A lesion ABOVE the facial nucleus (corticobulbar tract), causing contralateral paralysis of the L', 'The central facial palsy: forehead is SPARED (bilateral innervation of upper face).'),
('f9afa975-60ec-51a6-990e-2ab550382740'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The vestibulocochlear nerve (CN VIII) carries:', '["Taste and its associated structures","Only balance and its associated structures","Hearing (cochlear division) and balance","Only hearing and its associated structures","Vision and its associated structures"]'::jsonb, 'Hearing (cochlear division) and balance', 'CN VIII: cochlear nerve (spiral ganglion) and vestibular nerve (Scarpa ganglion).'),
('e251f8b8-bfe3-5fd4-a191-b11e4c9981cd'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The glossopharyngeal nerve (CN IX) carries:', '["Taste (posterior 1/3 of tongue), sensation (pharynx), and parasympathetic","Motor to the face and its associated anatomical structures","Vision and its associated anatomical structures","Hearing and its associated anatomical structures","Motor to the tongue and its associated anatomical structures"]'::jsonb, 'Taste (posterior 1/3 of tongue), sensation (pharynx), and parasympathetic', 'CN IX: the afferent limb of the gag reflex.'),
('af42fe26-ac3c-542a-b179-1c80794d116d'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The vagus nerve (CN X) carries:', '["Motor to the tongue and its associated anatomical structures","Parasympathetic (thoracic and abdominal viscera), motor","Vision and its associated anatomical structures","Motor to the face and its associated anatomical structures","Hearing and its associated anatomical structures"]'::jsonb, 'Parasympathetic (thoracic and abdominal viscera), motor', 'CN X: the recurrent laryngeal nerve (motor to the vocal cords).'),
('3b2d9ae0-bc31-5782-b206-68edb3a7e09a'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The accessory nerve (CN XI) innervates:', '["The sternocleidomastoid and trapezius muscles","The muscles of the face","The muscles of the larynx","The muscles of the tongue","The muscles of the pharynx"]'::jsonb, 'The sternocleidomastoid and trapezius muscles', 'CN XI: spinal part (C1-C5) innervates SCM and trapezius.'),
('b6b72dfb-fc8b-577f-82b4-4adc5efc1244'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The hypoglossal nerve (CN XII) innervates:', '["The muscles of the larynx and its associated anatomical structures","The muscles of the neck and its associated anatomical structures","The muscles of the face and its associated anatomical structures","The muscles of the pharynx and its associated anatomical structures","The intrinsic and extrinsic muscles of the TONGUE"]'::jsonb, 'The intrinsic and extrinsic muscles of the TONGUE', 'CN XII: LMN lesion causes tongue deviation TOWARD the weak side (genioglossus).'),
('46a1b863-0c14-58ac-ac74-36236c753380'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The pupillary light reflex is mediated by:', '["CN VIII and CN IX and its associated anatomical structures","CN II only and its associated anatomical structures","CN III only and its associated anatomical structures","CN II (afferent) and CN III (efferent) - optic and oculomotor nerves","CN V and CN VII and its associated anatomical structures"]'::jsonb, 'CN II (afferent) and CN III (efferent) - optic and oculomotor nerves', 'Pupillary light reflex: direct (ipsilateral) and consensual (contralateral) constriction.'),
('ca272070-f6bd-5fc6-90aa-434e82830181'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The accommodation reflex (near response) is mediated by:', '["CN IV only and its associated anatomical structures","CN III (oculomotor) - ciliary muscle, sphincter pupillae, and medial rectus","CN V and CN VII and its associated anatomical structures","CN II only and its associated anatomical structures","CN VI only and its associated anatomical structures"]'::jsonb, 'CN III (oculomotor) - ciliary muscle, sphincter pupillae, and medial rectus', 'Accommodation reflex: constriction of pupil, convergence of eyes, thickening of lens.'),
('23699443-6422-543e-b965-3964a783edbc'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The corneal reflex (blink reflex) is mediated by:', '["CN VIII and CN IX and its associated anatomical structures","CN V (afferent - ophthalmic division) and CN VII","CN II and CN III and its associated anatomical structures","CN III and CN IV and its associated anatomical structures","CN VI and CN VII and its associated anatomical structures"]'::jsonb, 'CN V (afferent - ophthalmic division) and CN VII', 'The corneal reflex: touch to cornea causes blink (CN V -> CN VII arc).'),
('50ab5159-433c-528b-b6b5-eea774623772'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'On diagnostic evaluation, The gag reflex is mediated by:', '["CN IX (afferent - pharyngeal sensation) and CN X","CN VI and CN VII and its associated anatomical structures","CN VIII and CN IX and its associated anatomical structures","CN III and CN IV and its associated anatomical structures","CN V and CN VII and its associated anatomical structures"]'::jsonb, 'CN IX (afferent - pharyngeal sensation) and CN X', 'Gag reflex: CN IX is the sensory limb; CN X is the motor limb.'),
('5d348625-81e6-5644-a6f3-c9ea91390ca4'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The jaw jerk reflex is mediated by:', '["CN X","CN IX","CN XII","CN VII","CN V"]'::jsonb, 'CN V', 'The jaw jerk (masseter reflex): hyperactive in pseudobulbar palsy (UMN sign).'),
('2f9267cc-3f7a-5a42-aaa1-e0ee3816d230'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The oculocephalic reflex (dolls eye maneuver) tests:', '["Cerebellar function","Brainstem function","Spinal cord function","Cortical function","Basal ganglia function"]'::jsonb, 'Brainstem function', 'Oculocephalic reflex: eyes move opposite to head rotation (intact brainstem).'),
('5e27d635-a9e1-5239-907a-25fbe148053c'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The caloric reflex (caloric test) tests:', '["Cerebellar function","Cortical function","Spinal cord function","Brainstem function","Basal ganglia function"]'::jsonb, 'Brainstem function', 'Caloric test: warm water (toward the side) and cold water (away from the side).'),
('6b4136f5-8d57-5a45-879d-f2e43443e841'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Horner syndrome (oculosympathetic palsy) is characterized by:', '["Exophthalmos and its associated anatomical structures","Mydriasis and its associated anatomical structures","Ptosis, miosis (pinpoint pupil), anhidrosis, and enophthalmos","Diplopia and its associated anatomical structures","Nystagmus and its associated anatomical structures"]'::jsonb, 'Ptosis, miosis (pinpoint pupil), anhidrosis, and enophthalmos', 'Horner syndrome: BPAE (Blepharoptosis, Pupil miosis, Anhidrosis, Enophthalmos).'),
('69373b7d-cbb4-582f-ac1d-42b91d9f3cd0'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The phrenic nerve (C3-C5) originates from:', '["C5, C6, and C7 cervical nerve roots","T1, T2, and T3 thoracic nerve roots","C1, C2, and C3 cervical nerve roots","C3, C4, and C5 cervical nerve roots","C4, C5, and C6 cervical nerve roots"]'::jsonb, 'C3, C4, and C5 cervical nerve roots', 'The phrenic nerve (C3-C5): motor to the diaphragm.'),
('dad63dae-d4e2-5a85-a1ff-c4c3604c6bf8'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Erb point (upper trunk of brachial plexus) is formed by:', '["C8 and T1 nerve roots","C7 nerve root only","C5 and C6 nerve roots","C5, C6, C7, C8, and T1","T1 and T2 nerve roots"]'::jsonb, 'C5 and C6 nerve roots', 'Erb-Duchenne palsy: waiters tip deformity (C5-C6 injury).'),
('39ed4205-31f8-59c4-94a9-f3e86c9a02e4'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Klumpke paralysis (lower trunk of brachial plexus) is formed by:', '["C5 and C6 nerve roots","T1 and T2 nerve roots","C8 and T1 nerve roots","C5, C6, and C7 nerve roots","C7 nerve root only"]'::jsonb, 'C8 and T1 nerve roots', 'Klumpke paralysis: C8-T1 injury (claw hand deformity).'),
('511a645e-2d80-5e0f-bf30-4da6113ec160'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The femoral nerve (L2-L4) innervates:', '["Gluteus maximus and its associated anatomical structures","Hamstrings and its associated anatomical structures","Tibialis anterior and its associated anatomical structures","Gastrocnemius and its associated anatomical structures","Quadriceps (knee extension), iliopsoas (hip flexion), and sartorius"]'::jsonb, 'Quadriceps (knee extension), iliopsoas (hip flexion), and sartorius', 'Femoral nerve: saphenous nerve (sensory to medial leg).'),
('1292fd2b-02cb-52f0-8434-547d1feb540f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The obturator nerve (L2-L4) innervates:', '["Ankle plantarflexors","Hip extensors","Hip adductors","Knee extensors","Hip abductors"]'::jsonb, 'Hip adductors', 'Obturator nerve: sensory to the medial thigh.'),
('9158290e-930e-5ab1-be75-d3bca2c06054'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The sciatic nerve (L4-S3) innervates:', '["Only the common peroneal nerve and its associated anatomical structures","Only the foot muscles and its associated anatomical structures","Hamstrings (knee flexion), adductor magnus, and the entire leg (via tibial and common peroneal ne","Only the tibial nerve and its associated anatomical structures","Only the hamstrings and its associated anatomical structures"]'::jsonb, 'Hamstrings (knee flexion), adductor magnus, and the entire leg (via tibial and common peroneal ne', 'The sciatic nerve is the largest nerve in the body.'),
('2299ed7c-354a-5cdf-8519-7bdb34df5e1d'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The tibial nerve (L4-S3) innervates:', '["Quadriceps and its associated anatomical structures","Tibialis anterior and its associated anatomical structures","Gastrocnemius (ankle plantarflexion), flexor hallucis longus, flexor digitorum longus","Peroneus longus and brevis and its associated anatomical structures","Extensor hallucis longus and its associated anatomical structures"]'::jsonb, 'Gastrocnemius (ankle plantarflexion), flexor hallucis longus, flexor digitorum longus', 'Tibial nerve: the Achilles reflex (S1).'),
('601888f9-4846-594a-8857-960a153006ee'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The common peroneal nerve (L4-S2) innervates:', '["Flexor digitorum longus and its associated anatomical structures","Tibialis anterior (ankle dorsiflexion), extensor hallucis longus","Intrinsic foot muscles and its associated anatomical structures","Hamstrings and its associated anatomical structures","Gastrocnemius and its associated anatomical structures"]'::jsonb, 'Tibialis anterior (ankle dorsiflexion), extensor hallucis longus', 'Common peroneal nerve: foot drop (deep and superficial peroneal nerves).'),
('e4201c27-bf8e-5ecd-8875-4996b2a93e73'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Foot drop is caused by injury to:', '["The tibial nerve","The common peroneal nerve","The obturator nerve","The sciatic nerve","The femoral nerve"]'::jsonb, 'The common peroneal nerve', 'Foot drop (steppage gait): the common peroneal nerve is most commonly injured.'),
('7d105b32-f1b8-5269-b48f-6b2dcbfb1e2f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The lateral femoral cutaneous nerve (L2-L3) provides sensation to:', '["The posterior thigh","The anterior thigh","The foot","The medial thigh","The lateral thigh"]'::jsonb, 'The lateral thigh', 'Meralgia paresthetica (Bernhardt-Roth syndrome): tingling and numbness of the lateral thigh.'),
('759c706e-1cdd-5420-ba47-87cfb92a599e'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The pudendal nerve (S2-S4) innervates:', '["Hamstrings and its associated anatomical structures","Quadriceps and its associated anatomical structures","Foot muscles and its associated anatomical structures","Perineal muscles (external anal sphincter, external urethral sphincter, pelvic floor","Gluteal muscles and its associated anatomical structures"]'::jsonb, 'Perineal muscles (external anal sphincter, external urethral sphincter, pelvic floor', 'Pudendal nerve block is used in obstetrics (childbirth).'),
('5a20d246-cf79-5223-b8d4-45e915579214'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The superior gluteal nerve (L4-S1) innervates:', '["Hamstrings and its associated anatomical structures","Piriformis and its associated anatomical structures","Gluteus maximus and its associated anatomical structures","Quadriceps and its associated anatomical structures","Gluteus medius, gluteus minimus, and tensor fasciae latae"]'::jsonb, 'Gluteus medius, gluteus minimus, and tensor fasciae latae', 'Superior gluteal nerve: Trendelenburg sign (gluteus medius weakness).'),
('4d85fa57-0d11-5e83-891f-0e2ffdb56744'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The inferior gluteal nerve (L5-S2) innervates:', '["Gluteus medius and minimus","Gluteus maximus","Hamstrings","Quadriceps","Piriformis"]'::jsonb, 'Gluteus maximus', 'Inferior gluteal nerve: gluteus maximus lurch (hip extension weakness).'),
('1b98940d-14b3-5a77-af9c-7bf54f179e03'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Preganglionic sympathetic neurons are located in:', '["The sympathetic chain","The dorsal horn of the spinal cord","The intermediolateral cell column","The ventral horn of the spinal cord","The dorsal root ganglion"]'::jsonb, 'The intermediolateral cell column', 'The IML (lateral horn) contains the preganglionic sympathetic neurons.'),
('98668a92-1a06-5e1c-a9e8-c42dd9a7bb1f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Preganglionic parasympathetic neurons are located in:', '["The ventral horn of the spinal cord and its associated anatomical structures","The T1-L2 levels of the spinal cord and its associated anatomical structures","The dorsal root ganglion and its associated anatomical structures","The dorsal horn of the spinal cord and its associated anatomical structures","The brainstem (CN III, VII, IX, X nuclei) and the S2-S4 levels of the spinal cord (craniosacral o"]'::jsonb, 'The brainstem (CN III, VII, IX, X nuclei) and the S2-S4 levels of the spinal cord (craniosacral o', 'Craniosacral outflow: cranial (midbrain, pons, medulla) and sacral (S2-S4).'),
('fb495340-e571-5b4a-b8aa-212ef85247cd'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'With respect to management, The blood-brain barrier (BBB) is formed by:', '["Microglia and its associated anatomical structures","Tight junctions between capillary endothelial cells, basement membrane, and astrocyte foot processes","Arachnoid granulations and its associated anatomical structures","Choroid plexus and its associated anatomical structures","Ependymal cells and its associated anatomical structures"]'::jsonb, 'Tight junctions between capillary endothelial cells, basement membrane, and astrocyte foot processes', 'BBB: lipophilic and small molecules can cross (O2, CO2, glucose).'),
('a3286753-7164-5acf-aeac-0752e36b1a78'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Circumventricular organs (CVO) are:', '["Areas with the blood-brain barrier and its associated anatomical structures","Areas with the blood-CSF barrier and its associated anatomical structures","Areas with tight junctions and its associated anatomical structures","Areas of the brain WITH NO blood-brain barrier (area postrema, median eminence, pineal gland","Areas with the choroid plexus and its associated anatomical structures"]'::jsonb, 'Areas of the brain WITH NO blood-brain barrier (area postrema, median eminence, pineal gland', 'The area postrema is the chemoreceptor trigger zone (CTZ) for vomiting.'),
('a43c320b-1e0f-5a4b-ae73-eb58220e1a29'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The area postrema (a CVO) is the:', '["Appetite center and its associated anatomical structures","Sleep center and its associated anatomical structures","Chemoreceptor trigger zone (CTZ) for the vomiting reflex","Cardiovascular center and its associated anatomical structures","Respiratory center and its associated anatomical structures"]'::jsonb, 'Chemoreceptor trigger zone (CTZ) for the vomiting reflex', 'The area postrema (vomiting center): emetic drugs (apomorphine) act on the CTZ.'),
('69aab442-7ea7-5de7-8fab-34de97b81ceb'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The hippocampal formation is essential for:', '["Sensory memory and its associated anatomical structures","Procedural memory and its associated anatomical structures","Declarative memory (facts and events) and spatial memory","Emotional memory and its associated anatomical structures","Motor memory and its associated anatomical structures"]'::jsonb, 'Declarative memory (facts and events) and spatial memory', 'Bilateral hippocampal lesion (Alzheimer disease) causes anterograde amnesia.'),
('b16076d2-0d03-51c6-bb19-6a666d65b494'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The basal ganglia are involved in:', '["Vision and its associated anatomical structures","Sensory processing and its associated anatomical structures","Initiation and coordination of voluntary movement, postural control, and motor learning","Autonomic control and its associated anatomical structures","Hearing and its associated anatomical structures"]'::jsonb, 'Initiation and coordination of voluntary movement, postural control, and motor learning', 'Basal ganglia disorders: Parkinson, Huntington, hemiballismus.'),
('51c20d54-dcf5-5c6d-b42f-f9aa19335e86'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The substantia nigra pars compacta (SNc) projects to:', '["The subthalamic nucleus and its associated anatomical structures","The thalamus and its associated anatomical structures","The striatum (caudate and putamen) - the nigrostriatal pathway","The cortex and its associated anatomical structures","The globus pallidus and its associated anatomical structures"]'::jsonb, 'The striatum (caudate and putamen) - the nigrostriatal pathway', 'Degeneration of the SNc causes Parkinson disease.'),
('4ff7bdcf-b2a6-5c25-9e65-f056e69c70d5'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The subthalamic nucleus (STN) is part of:', '["The cerebellum","The thalamus","The brainstem","The basal ganglia","The hypothalamus"]'::jsonb, 'The basal ganglia', 'A lesion of the STN causes hemiballismus.'),
('92516f93-509b-5076-be0c-dd28974826bb'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Hemiballismus (wild, flinging movement of the limb) is caused by:', '["A lesion of the subthalamic nucleus","A lesion of the globus pallidus","A lesion of the substantia nigra","A lesion of the caudate","A lesion of the putamen"]'::jsonb, 'A lesion of the subthalamic nucleus', 'Hemiballismus: sudden onset of involuntary, large-amplitude proximal limb movement.'),
('e75c1fe1-2022-576c-a7ca-139c3fd124ea'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Huntington disease (chorea) is caused by:', '["Degeneration of the motor cortex and its associated anatomical structures","Degeneration of the spinal cord and its associated anatomical structures","Degeneration of GABAergic neurons in the STRIATUM (caudate and putamen), CAG repeat on chromosome 4","Degeneration of the SNc and its associated anatomical structures","Degeneration of the cerebellum and its associated anatomical structures"]'::jsonb, 'Degeneration of GABAergic neurons in the STRIATUM (caudate and putamen), CAG repeat on chromosome 4', 'Huntington disease: autosomal dominant (CAG repeat), chorea, cognitive decline.'),
('89da43f9-f825-5f03-9380-4d5233a25ca0'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Parkinson disease is caused by:', '["Degeneration of the cerebellum","Degeneration of the spinal cord","Degeneration of the dopaminergic neurons in the substantia nigra pars compacta","Degeneration of GABAergic neurons in the striatum","Degeneration of the motor cortex"]'::jsonb, 'Degeneration of the dopaminergic neurons in the substantia nigra pars compacta', 'Parkinson disease: tremor (resting), rigidity (cogwheel), bradykinesia, postural instability.'),
('18eeae82-a9f8-53a1-b58f-02e7b944cbda'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The resting tremor of Parkinson disease is:', '["A dystonic tremor and its associated anatomical structures","An intention tremor and its associated anatomical structures","A task-specific tremor and its associated anatomical structures","A postural tremor and its associated anatomical structures","A pill-rolling tremor (3-5 Hz), WORSE at rest and IMPROVED with movement"]'::jsonb, 'A pill-rolling tremor (3-5 Hz), WORSE at rest and IMPROVED with movement', 'PD tremor: unilateral onset, asymmetric.'),
('4180fb61-ee19-5ac8-8dfd-3e59b0e8619d'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The rigidity of Parkinson disease is characterized by:', '["Dystonia","Spasticity","Lead-pipe rigidity","Cogwheel rigidity","Paratonia"]'::jsonb, 'Cogwheel rigidity', 'PD rigidity: extrapyramidal (both flexors and extensors).'),
('2a2ae72c-5622-59c3-9949-0dc29ca8147b'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Bradykinesia of Parkinson disease is characterized by:', '["Involuntary movement and its associated anatomical structures","Clumsy movement and its associated anatomical structures","Ataxic movement and its associated anatomical structures","Fast movement and its associated anatomical structures","Slowness of initiation and execution of voluntary movement"]'::jsonb, 'Slowness of initiation and execution of voluntary movement', 'Bradykinesia is the most disabling symptom of PD.'),
('cbe336c1-7dc7-5711-b17d-dc06eeb58c00'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The treatment of Parkinson disease is:', '["Levodopa (L-DOPA), carbidopa (decarboxylase inhibitor), and DA agonists","MAO-B inhibitors only and its associated anatomical structures","COMT inhibitors only and its associated anatomical structures","Anticholinergic drugs only and its associated anatomical structures","Amantadine only and its associated anatomical structures"]'::jsonb, 'Levodopa (L-DOPA), carbidopa (decarboxylase inhibitor), and DA agonists', 'The gold standard treatment is levodopa/carbidopa (Sinemet).'),
('4f9d3011-3e9e-544a-8093-e9507ceda96f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Essential tremor (senile tremor) is characterized by:', '["A resting tremor and its associated anatomical structures","A task-specific tremor and its associated anatomical structures","A postural and action tremor (6-12 Hz), bilateral, hereditary, and IMPROVED with alcohol","An intention tremor and its associated anatomical structures","A dystonic tremor and its associated anatomical structures"]'::jsonb, 'A postural and action tremor (6-12 Hz), bilateral, hereditary, and IMPROVED with alcohol', 'Essential tremor: treatment is beta-blockers (propranolol) and primidone.'),
('80de27af-9cbf-5a0f-a3bd-a2d76184c60f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Dystonia is characterized by:', '["Twisting, repetitive movements and abnormal postures","Myoclonus and its associated anatomical structures","Clonus and its associated anatomical structures","Resting tremor and its associated anatomical structures","Intention tremor and its associated anatomical structures"]'::jsonb, 'Twisting, repetitive movements and abnormal postures', 'Dystonia: cervical dystonia (spasmodic torticollis).'),
('58063626-fddc-5c77-8f31-71c5c974d005'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Myoclonus is characterized by:', '["Sustained muscle contraction","Rapid muscle contraction","Rhythmic muscle contraction","Sudden, brief, involuntary muscle jerks","Slow muscle contraction"]'::jsonb, 'Sudden, brief, involuntary muscle jerks', 'Myoclonus: physiologic (sleep myoclonus) or pathologic (epileptic myoclonus).'),
('0f80501e-e0a0-546d-a5cd-6fd16934526d'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Chorea (dance-like movements) is characterized by:', '["Brief, irregular, jerky, flowing movements","Rhythmic, oscillatory movements","Slow, writhing movements","Sustained, twisting movements","Brief, shock-like movements"]'::jsonb, 'Brief, irregular, jerky, flowing movements', 'Chorea: Sydenham chorea (rheumatic fever).'),
('d8f34ff4-f75f-57b1-9da9-f31205718621'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Athetosis is characterized by:', '["Slow, sinuous, writhing movements of the distal limbs","Sustained, twisting movements","Rhythmic, oscillatory movements","Fast, jerky movements","Brief, shock-like movements"]'::jsonb, 'Slow, sinuous, writhing movements of the distal limbs', 'Athetosis: seen in cerebral palsy (basal ganglia lesion).'),
('634ffc9d-7f07-57cf-a217-ef2b4fbae658'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Tics are characteristic of:', '["Dystonia","Huntington disease","Parkinson disease","Tourette syndrome","Essential tremor"]'::jsonb, 'Tourette syndrome', 'Tourette syndrome: premonitory urge, suppressible tics.'),
('afc1b55b-d375-5535-9433-a65deacc0ba6'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'ALS (amyotrophic lateral sclerosis) is:', '["A peripheral nerve disease","A cerebellar disease","A sensory neuron disease","A basal ganglia disease","A motor neuron disease"]'::jsonb, 'A motor neuron disease', 'ALS: UMN and LMN signs, NO sensory loss, NO bowel/bladder dysfunction.'),
('a5d91ee9-4a73-5753-b1f2-5a1a4a1c3d7b'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Primary lateral sclerosis (PLS) is:', '["A mixed UMN and LMN disease","A pure LMN disease","A cerebellar disease","A pure UMN disease","A sensory disease"]'::jsonb, 'A pure UMN disease', 'PLS: slow progression, spastic paraplegia.'),
('0618e03d-8c73-5c79-96c4-be647db7886a'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Progressive muscular atrophy (PMA) is:', '["A sensory disease","A pure LMN disease","A cerebellar disease","A pure UMN disease","A mixed UMN and LMN disease"]'::jsonb, 'A pure LMN disease', 'PMA: the benign form of motor neuron disease.'),
('88d6a085-3593-5060-8496-67f227816be4'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Spinal muscular atrophy (SMA) is:', '["A mixed UMN and LMN disease and its associated anatomical structures","A sensory disease and its associated anatomical structures","A cerebellar disease and its associated anatomical structures","An autosomal recessive (SMN1 gene deletion) LMN disease","A dominant UMN disease and its associated anatomical structures"]'::jsonb, 'An autosomal recessive (SMN1 gene deletion) LMN disease', 'SMA (Werding-Hoffman disease): Type 1 is the infantile form (floppy baby).'),
('0142efa9-6cfb-5487-9b8b-f8088ae45ae7'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Multiple sclerosis (MS) is:', '["A cerebellar disease and its associated anatomical structures","A basal ganglia disease and its associated anatomical structures","A peripheral nerve disease and its associated anatomical structures","A motor neuron disease and its associated anatomical structures","A chronic, inflammatory, demyelinating disease of the CNS (plaques in white matter"]'::jsonb, 'A chronic, inflammatory, demyelinating disease of the CNS (plaques in white matter', 'MS: optic neuritis, INO, Lhermitte sign.'),
('2fe227e8-c6ae-5dcb-ab72-73bb2c694b7c'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Lhermitte sign (electric shock sensation down spine with neck flexion) is classic for:', '["Huntington disease","Essential tremor","ALS","Parkinson disease","Multiple sclerosis"]'::jsonb, 'Multiple sclerosis', 'Lhermitte sign (barber chair sign): flexion of neck elicits electric shock.'),
('3edd9e4a-f3da-5c2b-b29c-d51c6b30bfb6'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Internuclear ophthalmoplegia (INO) is a classic sign of:', '["Parkinson disease","ALS","Huntington disease","Multiple sclerosis","Cerebellar disease"]'::jsonb, 'Multiple sclerosis', 'INO: failure of adduction of the ipsilateral eye and nystagmus of the contralateral eye.'),
('f91e95e0-72b1-5006-bc00-29682409b142'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Optic neuritis is a classic presentation of:', '["Glaucoma","Multiple sclerosis","Retinal detachment","Macular degeneration","Cataract"]'::jsonb, 'Multiple sclerosis', 'Optic neuritis: Uhthoff phenomenon (worsening with heat).'),
('0f07cf2d-7543-5850-a1af-e8763af592bd'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Demyelinating diseases of the PNS include:', '["Guillain-Barre syndrome","Multiple sclerosis","SMA","ALS","Myasthenia gravis"]'::jsonb, 'Guillain-Barre syndrome', 'GBS: ascending paralysis, albuminocytologic dissociation in CSF.'),
('675bfa6c-321e-50c4-923d-b64c07024248'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Axonal neuropathies include:', '["CIDP","Guillain-Barre syndrome","ALS","MS","Charcot-Marie-Tooth disease"]'::jsonb, 'Charcot-Marie-Tooth disease', 'CMT: high-arched feet (pes cavus), distal weakness.'),
('c2131241-b4ac-5252-8f25-ec84485352df'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Myasthenia gravis (MG) is:', '["A metabolic myopathy and its associated anatomical structures","A demyelinating disease of the PNS and its associated anatomical structures","A motor neuron disease and its associated anatomical structures","An autoimmune disease of the neuromuscular junction (acetylcholine receptor antibodies","A muscular dystrophy and its associated anatomical structures"]'::jsonb, 'An autoimmune disease of the neuromuscular junction (acetylcholine receptor antibodies', 'MG: ptosis, diplopia, bulbar symptoms, fatigability.'),
('7b6b312e-d029-51a3-afc8-368782189d12'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Eaton-Lambert syndrome is:', '["An autoimmune disease of the NMJ and its associated anatomical structures","A motor neuron disease and its associated anatomical structures","A metabolic myopathy and its associated anatomical structures","A paraneoplastic syndrome (P/Q-type calcium channel antibodies, proximal weakness that IMPROVES w","A muscular dystrophy and its associated anatomical structures"]'::jsonb, 'A paraneoplastic syndrome (P/Q-type calcium channel antibodies, proximal weakness that IMPROVES w', 'LEMS: small cell lung cancer (SCLC) is the most common associated tumor.'),
('3ec4420e-490a-52e4-985e-50649053ba3d'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Muscular dystrophies include:', '["ALS","Myasthenia gravis","SMA","GBS","Duchenne muscular dystrophy"]'::jsonb, 'Duchenne muscular dystrophy', 'DMD: Gower sign, calf pseudohypertrophy, elevated CK.'),
('d41cec61-7a89-5115-9ec9-80af037959d4'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Proximal myopathy is a feature of:', '["NMJ disease and its associated anatomical structures","Motor neuron disease and its associated anatomical structures","Distal myopathies and its associated anatomical structures","Peripheral neuropathy and its associated anatomical structures","Muscular dystrophies (DMD, LGMD) and inflammatory myopathies"]'::jsonb, 'Muscular dystrophies (DMD, LGMD) and inflammatory myopathies', 'Proximal myopathy: difficulty rising from chair or stairs.'),
('eed9c010-c9fb-5ab1-852b-48ba64f7cf35'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Cerebral edema is a medical emergency that can cause:', '["Hypotension and its associated anatomical structures","Bradycardia and its associated anatomical structures","Decreased ICP and its associated anatomical structures","Increased intracranial pressure (ICP), herniation syndromes, and brain death","Hypothermia and its associated anatomical structures"]'::jsonb, 'Increased intracranial pressure (ICP), herniation syndromes, and brain death', 'Cerebral edema: vasogenic vs cytotoxic. Mannitol and hyperventilation are treatments.'),
('7da8e6c4-8b4c-55e7-ba2e-088c70ab6efe'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Transtentorial herniation (uncal) compresses:', '["The medulla only and its associated anatomical structures","The cerebellum only and its associated anatomical structures","CN III (ipsilateral dilated pupil), cerebral peduncle","CN VI only and its associated anatomical structures","The spinal cord only and its associated anatomical structures"]'::jsonb, 'CN III (ipsilateral dilated pupil), cerebral peduncle', 'Uncal herniation: ipsilateral pupil dilation, contralateral hemiparesis, loss of consciousness.'),
('fd752bdf-1cfa-5e3f-9467-1711687719b6'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The Cushing reflex (Cushing triad) of increased ICP is:', '["Bradycardia, hypotension, and hypothermia","Hypertension, bradycardia, and irregular respiration","Fever, tachycardia, and hypotension","Hypertension, tachycardia, and hyperventilation","Hypotension, tachycardia, and tachypnea"]'::jsonb, 'Hypertension, bradycardia, and irregular respiration', 'Cushing reflex: hypertension (widening pulse pressure) and bradycardia.'),
('5835f1af-a992-5e06-b2b2-42e592f98167'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Subfalcine herniation (cingulate) compresses:', '["CN III and its associated anatomical structures","PCA and its associated anatomical structures","Medulla and its associated anatomical structures","Cerebellar tonsils and its associated anatomical structures","The ACA (anterior cerebral artery), causing contralateral leg weakness"]'::jsonb, 'The ACA (anterior cerebral artery), causing contralateral leg weakness', 'Subfalcine herniation: ACA stroke (leg weakness).'),
('0ce3da7f-71cb-54a6-8636-2910a4b821bd'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Tonsillar herniation (cerebellar) compresses:', '["ACA and its associated anatomical structures","The medulla oblongata (respiratory and cardiac centers), causing respiratory arrest and death","PCA and its associated anatomical structures","Cerebral peduncle and its associated anatomical structures","CN III and its associated anatomical structures"]'::jsonb, 'The medulla oblongata (respiratory and cardiac centers), causing respiratory arrest and death', 'Tonsillar herniation (coning): life-threatening emergency (respiratory arrest).'),
('17bcd222-4e7d-5476-bc09-6953691102b5'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Hydrocephalus can be classified as:', '["Congenital vs acquired","Communicating (impaired absorption) vs non-communicating","High-pressure vs normal-pressure","Acute vs chronic","Symptomatic vs asymptomatic"]'::jsonb, 'Communicating (impaired absorption) vs non-communicating', 'Non-communicating hydrocephalus: obstruction of cerebral aqueduct (aqueductal stenosis).'),
('2c6a5219-b705-5258-a472-4b9c2f09080a'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Dandy-Walker malformation is characterized by:', '["Schizencephaly and its associated anatomical structures","Pachygyria and its associated anatomical structures","Agenesis of the cerebellar vermis, cystic dilation of the 4th ventricle, and hydrocephalus","Holoprosencephaly and its associated anatomical structures","Lissencephaly and its associated anatomical structures"]'::jsonb, 'Agenesis of the cerebellar vermis, cystic dilation of the 4th ventricle, and hydrocephalus', 'Dandy-Walker malformation: posterior fossa cyst, dilated 4th ventricle.'),
('d95b7560-76b2-5d4f-bb2f-feb4da415832'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Arnold-Chiari malformation (Type II) is characterized by:', '["Agenesis of corpus callosum and its associated anatomical structures","Hydromyelia and its associated anatomical structures","Herniation of cerebellar vermis, medulla, and 4th ventricle through foramen magnum (associated wi","Dandy-Walker malformation and its associated anatomical structures","Herniation of cerebellar tonsils only and its associated anatomical structures"]'::jsonb, 'Herniation of cerebellar vermis, medulla, and 4th ventricle through foramen magnum (associated wi', 'Arnold-Chiari Type II: myelomeningocele, hydrocephalus, brainstem compression.'),
('70b45757-48e4-59d6-923a-1c1e1ead41ee'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'A seizure (epileptic seizure) is:', '["A transient, abnormal, synchronous electrical discharge of cerebral neurons (epilepsy is recurren","A sleep disorder and its associated anatomical structures","A psychogenic event and its associated anatomical structures","A transient loss of consciousness and its associated anatomical structures","A transient neurological deficit and its associated anatomical structures"]'::jsonb, 'A transient, abnormal, synchronous electrical discharge of cerebral neurons (epilepsy is recurren', 'Seizure: generalized vs focal (partial) seizures.'),
('02cd52cb-b435-5697-8d82-7b51085177d3'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'A generalized tonic-clonic seizure (grand mal) is characterized by:', '["Myoclonic seizure and its associated anatomical structures","Loss of consciousness, tonic phase (stiffening) and clonic phase","Absence seizure and its associated anatomical structures","Focal seizure and its associated anatomical structures","Atonic seizure and its associated anatomical structures"]'::jsonb, 'Loss of consciousness, tonic phase (stiffening) and clonic phase', 'GTCS: airway management, ABCDE approach in status epilepticus.'),
('39e91304-7b49-5772-a2b3-0ee22f635160'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'An absence seizure (petit mal) is characterized by:', '["Myoclonic jerks and its associated anatomical structures","Tonic-clonic movements and its associated anatomical structures","Drop attacks and its associated anatomical structures","Brief (5-10 seconds) staring spell, loss of awareness, 3-Hz spike-and-wave on EEG (childhood epil","Complex partial seizures and its associated anatomical structures"]'::jsonb, 'Brief (5-10 seconds) staring spell, loss of awareness, 3-Hz spike-and-wave on EEG (childhood epil', 'Absence seizure: hyperventilation can provoke the seizure.'),
('27fa2997-aec2-5754-bab1-42ccaa68ab8c'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Focal (partial) seizure is classified as:', '["Generalized vs focal and its associated anatomical structures","Primary vs secondary and its associated anatomical structures","Simple (preserved consciousness) vs complex","Motor vs sensory and its associated anatomical structures","Tonic vs clonic and its associated anatomical structures"]'::jsonb, 'Simple (preserved consciousness) vs complex', 'Simple partial seizure: focal motor or sensory symptoms (Jacksonian march).'),
('8a7ba08e-355a-5282-a53d-608f53a9567f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Status epilepticus is defined as:', '["Continuous seizure activity for >5 minutes, or two or more seizures without full recovery of cons","A seizure lasting >30 seconds and its associated anatomical structures","Multiple seizures with full recovery and its associated anatomical structures","A single seizure and its associated anatomical structures","A seizure lasting >1 minute and its associated anatomical structures"]'::jsonb, 'Continuous seizure activity for >5 minutes, or two or more seizures without full recovery of cons', 'Status epilepticus: medical emergency (IV benzodiazepines and AEDs).'),
('89bac08b-95bb-547e-8e6c-b1b2b1052ab8'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'First-line treatment of status epilepticus is:', '["Propofol only and its associated anatomical structures","IV lorazepam (or IV diazepam), followed by IV fosphenytoin or IV levetiracetam","Phenobarbital only and its associated anatomical structures","Ketamine only and its associated anatomical structures","Oral AEDs only and its associated anatomical structures"]'::jsonb, 'IV lorazepam (or IV diazepam), followed by IV fosphenytoin or IV levetiracetam', 'Status epilepticus protocol: Lorazepam, Epileptic drug, Valproate or Levetiracetam.'),
('02f57adc-116b-55b7-a210-7c538c9434fc'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The EEG is used for:', '["Diagnosis of dementia and its associated anatomical structures","Diagnosis of epilepsy and classification of seizures","Diagnosis of brain tumor and its associated anatomical structures","Diagnosis of headache and its associated anatomical structures","Diagnosis of stroke and its associated anatomical structures"]'::jsonb, 'Diagnosis of epilepsy and classification of seizures', 'EEG: wakeful state (beta waves), sleep state (theta and delta waves).'),
('96c806a9-b700-559a-b135-c833e6d30fd9'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Headache is classified as:', '["Unilateral and bilateral and its associated anatomical structures","Primary (migraine, tension-type, cluster) and secondary","Mild, moderate, and severe and its associated anatomical structures","Throbbing and pressure-like and its associated anatomical structures","Acute and chronic and its associated anatomical structures"]'::jsonb, 'Primary (migraine, tension-type, cluster) and secondary', 'Primary headache: no underlying organic cause. Secondary: sinusitis, meningitis, SAH.'),
('6f18f6ea-e3bd-5d6e-96d8-8470d32ce792'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Migraine is characterized by:', '["Bilateral, pressure-like headache and its associated anatomical structures","Severe, periorbital headache and its associated anatomical structures","Fever and headache and its associated anatomical structures","Sudden, thunderclap headache and its associated anatomical structures","Unilateral, throbbing headache, nausea, vomiting, photophobia, and phonophobia, with or without aura"]'::jsonb, 'Unilateral, throbbing headache, nausea, vomiting, photophobia, and phonophobia, with or without aura', 'Migraine: treatment is triptans (5-HT1 agonists).'),
('0ee51f95-51dd-576b-b927-6eda5b661b7f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The aura of migraine is usually:', '["Headache before the aura and its associated anatomical structures","Photophobia and phonophobia before the headache and its associated anatomical structures","Vertigo and ataxia before the headache and its associated anatomical structures","Visual symptoms (scintillating scotoma, fortification spectra), sensory or motor symptoms","Nausea and vomiting before the headache and its associated anatomical structures"]'::jsonb, 'Visual symptoms (scintillating scotoma, fortification spectra), sensory or motor symptoms', 'Migraine aura: visual aura is the most common.'),
('7db7f730-5e35-5a93-b722-7b4ac2b1e04e'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Tension-type headache is characterized by:', '["Fever and headache and its associated anatomical structures","Sudden, thunderclap headache and its associated anatomical structures","Severe, periorbital headache and its associated anatomical structures","Bilateral, pressure-like or tightening headache (band-like sensation), mild-to-moderate intensity","Unilateral, throbbing headache and its associated anatomical structures"]'::jsonb, 'Bilateral, pressure-like or tightening headache (band-like sensation), mild-to-moderate intensity', 'TTH: the most common type of primary headache.'),
('46857747-e8ad-506d-b31c-743ede27a3cb'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Cluster headache is characterized by:', '["Throbbing headache and its associated anatomical structures","Mild headache and its associated anatomical structures","Bilateral headache and its associated anatomical structures","Severe, unilateral, periorbital or temporal pain with ipsilateral autonomic features (lacrimation","Pressure-like headache and its associated anatomical structures"]'::jsonb, 'Severe, unilateral, periorbital or temporal pain with ipsilateral autonomic features (lacrimation', 'Cluster headache (suicide headache): excruciating pain, circadian periodicity.'),
('eaa4348b-a479-54eb-bb8d-508588d55d6f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Trigeminal neuralgia (tic douloureux) is characterized by:', '["Mild pain and its associated anatomical structures","Throbbing pain and its associated anatomical structures","Sudden, severe, electric shock-like, unilateral pain in V2 or V3 distribution (triggered by touch","Continuous, burning pain and its associated anatomical structures","Bilateral pain and its associated anatomical structures"]'::jsonb, 'Sudden, severe, electric shock-like, unilateral pain in V2 or V3 distribution (triggered by touch', 'Trigeminal neuralgia: carbamazepine is first-line treatment.'),
('0b59c750-58ab-563e-b1d8-81d524a4d3ab'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Subarachnoid hemorrhage (SAH) is characterized by:', '["Sudden, severe, thunderclap headache (worst headache of life), meningismus, and blood in CSF","Bilateral headache and its associated anatomical structures","Gradual onset headache and its associated anatomical structures","Pressure-like headache and its associated anatomical structures","Mild headache and its associated anatomical structures"]'::jsonb, 'Sudden, severe, thunderclap headache (worst headache of life), meningismus, and blood in CSF', 'SAH: CT scan is the first test (hyperdense blood in basal cisterns).'),
('c8f88171-ced3-5d2e-a80b-36eda67ff024'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The most common cause of non-traumatic SAH is:', '["Coagulopathy","Ruptured saccular aneurysm","AVM rupture","CNS vasculitis","Trauma"]'::jsonb, 'Ruptured saccular aneurysm', 'Berry aneurysm: anterior communicating artery is the most common site.'),
('f3ff3595-bab9-548c-84bf-0c1a063519c9'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Stroke is classified as:', '["Ischemic (thrombotic, embolic, lacunar) and hemorrhagic","Carotid and vertebrobasilar and its associated anatomical structures","Anterior and posterior and its associated anatomical structures","Complete and partial and its associated anatomical structures","Cortical and subcortical and its associated anatomical structures"]'::jsonb, 'Ischemic (thrombotic, embolic, lacunar) and hemorrhagic', 'Ischemic stroke is the most common (85%).'),
('ecd3f08c-2548-5452-8b36-b745dd013c10'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Hemorrhagic stroke (ICH) is characterized by:', '["Focal neurological deficit, headache, vomiting, hypertension, and decreased consciousness (CT sho","TIA and its associated anatomical structures","Migraine and its associated anatomical structures","Syncope and its associated anatomical structures","Mild headache and its associated anatomical structures"]'::jsonb, 'Focal neurological deficit, headache, vomiting, hypertension, and decreased consciousness (CT sho', 'ICH: basal ganglia (putamen) is the most common site (hypertensive hemorrhage).'),
('f6fa50f6-0872-5256-83c7-fe52feb2a41a'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'TIAs (transient ischemic attacks) are:', '["Syncope and its associated anatomical structures","Stroke with full recovery and its associated anatomical structures","Brief (<24 hours) episodes of focal neurological deficit","Seizure and its associated anatomical structures","Migraine with aura and its associated anatomical structures"]'::jsonb, 'Brief (<24 hours) episodes of focal neurological deficit', 'TIA: ABCD2 score is used to stratify stroke risk.'),
('a0a87360-3cd1-57f0-96c4-6b547df9d3e5'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'A stroke in the ACA territory causes:', '["Aphasia","Ataxia","Contralateral motor and sensory loss of the FACE and ARM","Contralateral homonymous hemianopsia","Contralateral motor and sensory loss of the LEG (lower limb) and urinary incontinence"]'::jsonb, 'Contralateral motor and sensory loss of the LEG (lower limb) and urinary incontinence', 'ACA stroke: leg weakness > arm weakness.'),
('3e882e04-ca3a-5d74-a478-b49cdc12ce2a'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'A stroke in the MCA territory causes:', '["Vertigo","Contralateral motor and sensory loss of the LEG","Ataxia","Diplopia","Contralateral motor and sensory loss of FACE and ARM (upper limb), aphasia"]'::jsonb, 'Contralateral motor and sensory loss of FACE and ARM (upper limb), aphasia', 'MCA stroke (most common): face and arm weakness > leg weakness.'),
('6d2cc544-ae60-52aa-bb20-b87f4c9bbc2f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'A stroke in the PCA territory causes:', '["Aphasia","Contralateral motor and sensory loss of the LEG","Contralateral homonymous hemianopsia","Contralateral motor and sensory loss of the FACE and ARM","Ataxia"]'::jsonb, 'Contralateral homonymous hemianopsia', 'PCA stroke: visual loss (occipital lobe infarction).'),
('141d4538-7648-54a7-a84f-e47eaff183a4'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'A stroke in the basilar artery territory (posterior circulation) causes:', '["Hemianopsia","Hemiparesis","Seizures","Aphasia","Brainstem signs"]'::jsonb, 'Brainstem signs', 'Top of the basilar syndrome: midbrain, thalamus, and occipital symptoms.'),
('111641bc-f7a6-5e6a-8d24-736921f01a87'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Wallenberg syndrome (lateral medullary syndrome) is caused by:', '["Occlusion of the MCA and its associated anatomical structures","Occlusion of the PICA (posterior inferior cerebellar artery) or the vertebral artery","Occlusion of the PCA and its associated anatomical structures","Occlusion of the AICA and its associated anatomical structures","Occlusion of the SCA and its associated anatomical structures"]'::jsonb, 'Occlusion of the PICA (posterior inferior cerebellar artery) or the vertebral artery', 'Wallenberg syndrome: lateral medullary infarction.'),
('c3471b86-4d9b-5c88-b133-e34e95d0c110'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Classic signs of Wallenberg syndrome include:', '["Contralateral facial pain/temperature loss and its associated anatomical structures","Ipsilateral hemiparesis and its associated anatomical structures","Contralateral Horner and its associated anatomical structures","Ipsilateral (Horner, facial pain/temperature loss, ataxia, dysphagia, hoarseness","Ipsilateral body pain/temperature loss and its associated anatomical structures"]'::jsonb, 'Ipsilateral (Horner, facial pain/temperature loss, ataxia, dysphagia, hoarseness', 'Crossed sensory loss (ipsilateral face + contralateral body) is the hallmark.'),
('acd9f489-9a11-5032-830d-3ce3bde0873f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Weber syndrome (midbrain syndrome) is caused by:', '["Occlusion of the PICA and its associated anatomical structures","Occlusion of the PCA (paramedian branches), causing CN III palsy + contralateral hemiparesis","Occlusion of the SCA and its associated anatomical structures","Occlusion of the MCA and its associated anatomical structures","Occlusion of the AICA and its associated anatomical structures"]'::jsonb, 'Occlusion of the PCA (paramedian branches), causing CN III palsy + contralateral hemiparesis', 'Weber syndrome (ventral midbrain): ipsilateral CN III palsy + contralateral hemiparesis.'),
('992a6ad9-0087-5c18-aa36-3708432ff598'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Millard-Gubler syndrome (pontine syndrome) is caused by:', '["Occlusion of the basilar artery (paramedian branches), causing CN VI and CN VII palsy + contralat","Occlusion of the MCA and its associated anatomical structures","Occlusion of the AICA and its associated anatomical structures","Occlusion of the PICA and its associated anatomical structures","Occlusion of the SCA and its associated anatomical structures"]'::jsonb, 'Occlusion of the basilar artery (paramedian branches), causing CN VI and CN VII palsy + contralat', 'Millard-Gubler syndrome (ventral pons): ipsilateral CN VI and VII palsy + contralateral hemiparesis.'),
('c4807f15-c835-5ccf-80f2-9b9e4fc717cb'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'A stroke in the lenticulostriate arteries (lacunar stroke) causes:', '["Brainstem stroke and its associated anatomical structures","Pure motor stroke (internal capsule), pure sensory stroke (thalamus), or ataxic-hemiparesis","Cortical stroke and its associated anatomical structures","Hemianopsia and its associated anatomical structures","Cerebellar stroke and its associated anatomical structures"]'::jsonb, 'Pure motor stroke (internal capsule), pure sensory stroke (thalamus), or ataxic-hemiparesis', 'Lacunar stroke (small vessel disease): hypertension and diabetes are risk factors.'),
('8f4c86dc-8fd3-5ba3-b749-4918a4a856a8'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Intracerebral hemorrhage (ICH) is most commonly caused by:', '["Aneurysm","Chronic hypertension","Trauma","Cerebral amyloid angiopathy","AVM"]'::jsonb, 'Chronic hypertension', 'Hypertensive ICH: basal ganglia (putamen), thalamus, pons, and cerebellum.'),
('8b4cebd4-e71a-521f-b51e-cf1085ce2903'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Cerebral amyloid angiopathy (CAA) causes ICH in:', '["Middle-aged adults","Neonates","Children","Young adults","The elderly"]'::jsonb, 'The elderly', 'CAA (congophilic angiopathy): APOE epsilon-4 allele is the risk factor.'),
('11feeeba-8c5f-5c65-a2a3-d675dcd87322'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'An arteriovenous malformation (AVM) is:', '["A lymphatic malformation and its associated anatomical structures","A congenital malformation of cerebral vessels (high-flow shunt between artery and vein","A venous malformation and its associated anatomical structures","A low-flow malformation and its associated anatomical structures","A capillary malformation and its associated anatomical structures"]'::jsonb, 'A congenital malformation of cerebral vessels (high-flow shunt between artery and vein', 'AVM treatment: surgery, embolization, radiosurgery.'),
('5471b048-961c-546e-8b4f-af27d918b6a6'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'A cavernous malformation (cavernoma) is:', '["A dural AV fistula","A high-flow AVM","A capillary telangiectasia","A venous angioma","A low-flow vascular malformation"]'::jsonb, 'A low-flow vascular malformation', 'Cavernoma: Zabramski classification (Type I-IV).'),
('849d8b63-1af9-5a59-a5fb-bcb6767cd27d'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Dementia (major neurocognitive disorder) is characterized by:', '["Delirium and its associated anatomical structures","Decline in cognitive function (memory, language, executive function) that interferes with daily life","Aphasia and its associated anatomical structures","Amnestic syndrome and its associated anatomical structures","Apraxia and its associated anatomical structures"]'::jsonb, 'Decline in cognitive function (memory, language, executive function) that interferes with daily life', 'Alzheimer disease is the most common cause of dementia.'),
('d7824674-5fd7-59d7-ab0f-1a8b8527b42f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Alzheimer disease is characterized by:', '["Extracellular amyloid plaques (beta-amyloid) and intracellular neurofibrillary tangles","Lewy bodies and its associated anatomical structures","Pick bodies and its associated anatomical structures","Huntingtin inclusions and its associated anatomical structures","TDP-43 inclusions and its associated anatomical structures"]'::jsonb, 'Extracellular amyloid plaques (beta-amyloid) and intracellular neurofibrillary tangles', 'AD: APOE epsilon-4 allele is the genetic risk factor.'),
('0ffe2ef5-3086-5b94-9ed6-aaa12bdf5357'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The first and most prominent symptom of Alzheimer disease is:', '["Language problems","Executive dysfunction","Visuospatial problems","Behavioral changes","Short-term memory loss"]'::jsonb, 'Short-term memory loss', 'AD: hippocampal atrophy on MRI, amnesia is the cardinal symptom.'),
('14e066d5-3bd2-5a95-8764-b4629f65387b'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Vascular dementia (multi-infarct dementia) is characterized by:', '["Hallucinations and its associated anatomical structures","Stepwise decline in cognitive function, history of stroke, and focal neurological signs","Parkinsonism and its associated anatomical structures","Memory loss is the first symptom and its associated anatomical structures","Gradual decline and its associated anatomical structures"]'::jsonb, 'Stepwise decline in cognitive function, history of stroke, and focal neurological signs', 'Vascular dementia: Hachinski ischemic score, treatment is control of vascular risk factors.'),
('1e67c87d-3fdc-5e8f-adbd-c7bed44fd436'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Lewy body dementia (DLB) is characterized by:', '["Cognitive decline + parkinsonism + visual hallucinations + fluctuating cognition + REM sleep beha","Behavioral changes and its associated anatomical structures","Stepwise decline and its associated anatomical structures","Early and severe amnesia and its associated anatomical structures","Language problems and its associated anatomical structures"]'::jsonb, 'Cognitive decline + parkinsonism + visual hallucinations + fluctuating cognition + REM sleep beha', 'DLB: sensitivity to neuroleptics (severe reaction).'),
('284a20c9-554a-52b3-aed9-39f0dda88b69'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Frontotemporal dementia (FTD, Pick disease) is characterized by:', '["Early memory loss and its associated anatomical structures","Visual hallucinations and its associated anatomical structures","Parkinsonism and its associated anatomical structures","Behavioral changes (disinhibition, apathy), language problems","Ataxia and its associated anatomical structures"]'::jsonb, 'Behavioral changes (disinhibition, apathy), language problems', 'FTD: Pick bodies (tau protein) or TDP-43 inclusions.'),
('dd5760b6-a68a-51fa-91ae-cbaffc806739'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Delirium (acute confusional state) is characterized by:', '["Acute onset, fluctuating course, inattention, and disorganized thinking","Insidious onset and progressive course and its associated anatomical structures","Psychosis and its associated anatomical structures","Depression and its associated anatomical structures","Mania and its associated anatomical structures"]'::jsonb, 'Acute onset, fluctuating course, inattention, and disorganized thinking', 'Delirium (CAM criteria): underlying cause (infection, metabolic, drugs).'),
('6fbbb122-45f4-5394-b205-d8ddbcb58965'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The Glasgow Coma Scale (GCS) assesses:', '["Pupillary response and its associated anatomical structures","Respiratory pattern and its associated anatomical structures","Heart rate and its associated anatomical structures","Blood pressure and its associated anatomical structures","Eye opening (E), verbal response (V), and motor response (M) - E4, V5, M6"]'::jsonb, 'Eye opening (E), verbal response (V), and motor response (M) - E4, V5, M6', 'GCS: E4, V5, M6 = 15 (fully conscious); E1, V1, M1 = 3 (deep coma).'),
('de9b6141-6a08-503e-86b9-b2c27a113285'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'A GCS score of 3 indicates:', '["Brain death","Mild brain injury","Full consciousness","Moderate brain injury","Deep coma"]'::jsonb, 'Deep coma', 'GCS 3 is the lowest possible score (worst prognosis).'),
('d16fe33e-e1ef-5264-827a-aa21abf91461'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'A GCS score of 8 or less indicates:', '["Mild brain injury","Severe brain injury","Full consciousness","Brain death","Moderate brain injury"]'::jsonb, 'Severe brain injury', 'GCS <= 8: severe injury, consider intubation.'),
('a19d9e71-e92e-5cbf-9d97-27d2363745f9'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The most common primary brain tumor in adults is:', '["Medulloblastoma","Meningioma","Glioblastoma multiforme","Pituitary adenoma","Schwannoma"]'::jsonb, 'Glioblastoma multiforme', 'GBM: the most aggressive primary brain tumor.'),
('6dccab66-cd55-597f-a7a9-827d0889d13a'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The most common primary brain tumor in children is:', '["Meningioma","Craniopharyngioma","Medulloblastoma","Glioblastoma multiforme","Pituitary adenoma"]'::jsonb, 'Medulloblastoma', 'Medulloblastoma: the most common malignant brain tumor in children.'),
('6fc469d2-6c5d-5efe-9626-6e3c43cc63df'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The most common extra-axial brain tumor is:', '["Craniopharyngioma","Schwannoma","Glioblastoma","Pituitary adenoma","Meningioma"]'::jsonb, 'Meningioma', 'Meningioma: extra-axial, dural-based, enhances uniformly.'),
('67c18d0c-cbd5-5081-9dfe-8dec3ef7f944'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The most common pituitary tumor is:', '["TSH-secreting adenoma","Prolactinoma","Non-functioning adenoma","ACTH-secreting adenoma","GH-secreting adenoma"]'::jsonb, 'Prolactinoma', 'Prolactinoma: causes galactorrhea, amenorrhea, infertility.'),
('c25fa3fd-4b6a-53a1-97a8-a1ca30ee211b'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Vestibular schwannoma (acoustic neuroma) arises from:', '["CN VII","CN IX","CN V","CN VIII","CN VI"]'::jsonb, 'CN VIII', 'Vestibular schwannoma: hearing loss, tinnitus, vertigo.'),
('3ec5faa4-a784-5289-8825-d0cfe8e9bc80'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Craniopharyngioma arises from:', '["Hypothalamus","Pineal gland","Choroid plexus","Pituitary gland","Rathke pouch remnant"]'::jsonb, 'Rathke pouch remnant', 'Craniopharyngioma: most common suprasellar tumor in children.'),
('245efc16-899e-58d0-b4d2-a9a7436f965c'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Pineal region tumors include:', '["Craniopharyngioma and its associated structures","Glioblastoma and its associated structures","Pituitary adenoma and its associated structures","Meningioma and its associated structures","Germinoma, pineocytoma, pineoblastoma"]'::jsonb, 'Germinoma, pineocytoma, pineoblastoma', 'Pineal germinoma: sensitive to radiation therapy.'),
('d6c2cfd6-de8d-54a3-a40c-aa08a308e81f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Brain metastases most commonly originate from:', '["Ovarian cancer and its associated anatomical structures","Prostate cancer and its associated anatomical structures","Pancreatic cancer and its associated anatomical structures","Lung cancer, breast cancer, melanoma, renal cell carcinoma, colon cancer","Liver cancer and its associated anatomical structures"]'::jsonb, 'Lung cancer, breast cancer, melanoma, renal cell carcinoma, colon cancer', 'Brain metastases: lung cancer is the most common primary source.'),
('bb7e56d3-2d9a-5d75-b4f8-fd6ea89d22bc'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The most common spinal tumor is:', '["Astrocytoma","Metastatic tumor","Schwannoma","Ependymoma","Meningioma"]'::jsonb, 'Metastatic tumor', 'Spinal metastases are more common than primary spinal tumors.'),
('73d39a04-4692-5849-a1e2-4d94b5924272'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The most common intramedullary spinal tumor is:', '["Hemangioblastoma","Schwannoma","Ependymoma","Meningioma","Astrocytoma"]'::jsonb, 'Ependymoma', 'Ependymoma: most common intramedullary tumor in adults (especially filum terminale).'),
('7aab7700-4f4f-5c92-80d4-5f78e9dbd033'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The most common intradural extramedullary spinal tumor is:', '["Metastasis","Ependymoma","Hemangioblastoma","Meningioma and schwannoma","Astrocytoma"]'::jsonb, 'Meningioma and schwannoma', 'Meningioma and schwannoma account for most intradural extramedullary tumors.'),
('9b48d3c8-d416-5074-ad6a-4ac01c7f2728'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Syringomyelia is:', '["A congenital malformation and its associated anatomical structures","A spinal tumor and its associated anatomical structures","A spinal injury and its associated anatomical structures","A spinal infection and its associated anatomical structures","A fluid-filled cavity (syrinx) within the spinal cord"]'::jsonb, 'A fluid-filled cavity (syrinx) within the spinal cord', 'Syringomyelia: cape-like loss of pain and temperature, Charcot joints.'),
('1dae3962-cbec-50be-a2a1-68763ecc66a6'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Choroid plexus papilloma is:', '["A vascular malformation","A congenital cyst","A pituitary tumor","A benign tumor of the choroid plexus","A malignant tumor"]'::jsonb, 'A benign tumor of the choroid plexus', 'Choroid plexus papilloma: overproduction of CSF, hydrocephalus.'),
('dcb5408f-4477-5cb2-9b7a-14a65088adae'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The most common cause of spinal cord compression is:', '["Disc herniation and its associated anatomical structures","Primary spinal tumor and its associated anatomical structures","Spinal epidural abscess and its associated anatomical structures","Metastatic epidural spinal cord compression","Spinal hematoma and its associated anatomical structures"]'::jsonb, 'Metastatic epidural spinal cord compression', 'MESCC: emergency, treat with steroids and radiation/surgery.'),
('d7f0713e-dc8e-565e-a03d-60405e01a5c9'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Epidural spinal cord compression presents with:', '["Neck pain and its associated anatomical structures","Shoulder pain and its associated anatomical structures","Back pain (first symptom), motor weakness, sensory loss, and autonomic dysfunction","Headache and its associated anatomical structures","Arm pain and its associated anatomical structures"]'::jsonb, 'Back pain (first symptom), motor weakness, sensory loss, and autonomic dysfunction', 'Back pain is the earliest symptom of spinal cord compression.'),
('bc255338-30c9-53eb-bc7c-ae364ec6f08d'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The most common cause of non-traumatic spinal cord injury is:', '["Spinal epidural abscess","Spinal cord compression from metastasis","Spinal hematoma","Transverse myelitis","Spinal cord infarction"]'::jsonb, 'Spinal cord compression from metastasis', 'Metastatic compression is more common than primary spinal tumors.'),
('0c89ad58-7df7-5241-a50a-6a3f62f1094f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Transverse myelitis is:', '["An inflammatory demyelinating condition of the spinal cord","A compressive condition and its associated anatomical structures","A degenerative condition and its associated anatomical structures","A vascular condition and its associated anatomical structures","A traumatic condition and its associated anatomical structures"]'::jsonb, 'An inflammatory demyelinating condition of the spinal cord', 'Transverse myelitis: associated with MS, NMDA, infections, or idiopathic.'),
('c4c55ddc-4859-51c2-9044-f7fa21f8c41d'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Spinal cord infarction (anterior spinal artery syndrome) causes:', '["Loss of all modalities and its associated anatomical structures","Loss of motor function only and its associated anatomical structures","Loss of proprioception only and its associated anatomical structures","Loss of pain and temperature only and its associated anatomical structures","Loss of motor function and pain/temperature below the lesion, with preserved proprioception and v"]'::jsonb, 'Loss of motor function and pain/temperature below the lesion, with preserved proprioception and v', 'Anterior spinal artery syndrome: dorsal columns spared.'),
('f5c63c49-f7f7-57be-b17b-0e5b2d4ec705'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Spinal epidural abscess presents with:', '["Abdominal pain and nausea","Headache and neck stiffness","Fever, back pain, and neurological deficit","Chest pain and dyspnea","Joint pain and swelling"]'::jsonb, 'Fever, back pain, and neurological deficit', 'Spinal epidural abscess: neurosurgical emergency.'),
('b9ab51b7-0d82-5ecd-ad0f-23604c5685d3'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Spinal subdural hematoma is:', '["A neoplastic condition","A rare condition","A common spinal emergency","A degenerative condition","A vascular malformation"]'::jsonb, 'A rare condition', 'Spinal subdural hematoma: may occur after lumbar puncture or anticoagulation.'),
('519c2bbd-2d0a-57db-8334-eee22a1d7806'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Cavernous sinus thrombosis presents with:', '["Back pain and leg weakness and its associated anatomical structures","Chest pain and dyspnea and its associated anatomical structures","Neck pain and arm weakness and its associated anatomical structures","Abdominal pain and nausea and its associated anatomical structures","Fever, headache, periorbital edema, proptosis, and cranial nerve palsies"]'::jsonb, 'Fever, headache, periorbital edema, proptosis, and cranial nerve palsies', 'Cavernous sinus thrombosis: infection spreads from the face (danger triangle).'),
('d3181fa8-9d10-5779-b6e3-6ab96ab72826'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The circle of Willis provides collateral circulation between:', '["The ACA and MCA","The PCA and SCA","The anterior and posterior circulations","The right and left ICAs","The vertebral and basilar arteries"]'::jsonb, 'The anterior and posterior circulations', 'Circle of Willis: protects against ischemia if one artery is occluded.'),
('6bd9f75b-a28f-543b-bca3-d2b9a5373475'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Cerebral autoregulation maintains constant cerebral blood flow between:', '["MAP 60-100 mmHg","MAP 40-80 mmHg","MAP 70-120 mmHg","MAP 50-150 mmHg","MAP 30-70 mmHg"]'::jsonb, 'MAP 50-150 mmHg', 'Cerebral autoregulation: between MAP 50 and 150 mmHg, CBF is constant at ~50 mL/100g/min.'),
('d9cac99d-a80d-51fb-b028-495c8ee176ac'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The Monro-Kellie doctrine states that:', '["The blood volume is constant and its associated anatomical structures","The CSF volume is constant and its associated anatomical structures","The sum of brain, blood, and CSF volumes in the cranium is constant (any increase in one causes a","The ICP is always normal and its associated anatomical structures","The brain volume is fixed and its associated anatomical structures"]'::jsonb, 'The sum of brain, blood, and CSF volumes in the cranium is constant (any increase in one causes a', 'Monro-Kellie: compensation for increased ICP is through displacement of CSF and blood.'),
('4335633c-b484-5221-861f-49a791a581ba'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The mammalian dive reflex (oxygen-conserving reflex) involves:', '["Mydriasis and its associated anatomical structures","Tachycardia and vasodilation and its associated anatomical structures","Bradycardia, peripheral vasoconstriction, and blood shunting to vital organs (mediated by CN V an","Hyperventilation and its associated anatomical structures","Increased metabolic rate and its associated anatomical structures"]'::jsonb, 'Bradycardia, peripheral vasoconstriction, and blood shunting to vital organs (mediated by CN V an', 'The dive reflex: triggered by facial immersion in cold water (mediated by trigeminal and vagus nerves).'),
('97cb0897-69d5-5ea5-ac98-30178e93d647'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The trigeminocardiac reflex (during surgery) causes:', '["Hyperventilation and its associated anatomical structures","Cardiac arrest and its associated anatomical structures","Sudden bradycardia and hypotension when the trigeminal nerve is stimulated","Mydriasis and its associated anatomical structures","Tachycardia and hypertension and its associated anatomical structures"]'::jsonb, 'Sudden bradycardia and hypotension when the trigeminal nerve is stimulated', 'Trigeminocardiac reflex: most common during skull base and craniofacial surgery.'),
('d194f63c-384c-5430-ab41-4bfa67de89dc'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The oculocardiac reflex (during eye surgery) causes:', '["Bradycardia when pressure is applied to the globe or traction on extraocular muscles","Mydriasis and its associated anatomical structures","Increased ICP and its associated anatomical structures","Hypertension and its associated anatomical structures","Tachycardia and its associated anatomical structures"]'::jsonb, 'Bradycardia when pressure is applied to the globe or traction on extraocular muscles', 'Oculocardiac reflex: mediated by trigeminal (afferent) and vagus (efferent) nerves.'),
('7e4e4165-22ec-5dcd-beac-6b40a767f97a'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The blood supply of the internal capsule is from:', '["Vertebral artery","Lenticulostriate arteries","PCA","ACA","Basilar artery"]'::jsonb, 'Lenticulostriate arteries', 'Lenticulostriate arteries are end arteries (prone to lacunar stroke from hypertension).'),
('abd38e1a-85cd-5831-a79d-1d8c26229741'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The blood supply of the basal ganglia is from:', '["PCA only and its associated anatomical structures","Lenticulostriate arteries (MCA) and recurrent artery of Heubner","Vertebral artery only and its associated anatomical structures","Basilar artery only and its associated anatomical structures","ACA only and its associated anatomical structures"]'::jsonb, 'Lenticulostriate arteries (MCA) and recurrent artery of Heubner', 'The recurrent artery of Heubner supplies the anterior limb of the internal capsule and parts of the basal ganglia.'),
('b058b0e5-474c-5e20-9b6f-71bafb31d547'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The blood supply of the thalamus is from:', '["Vertebral artery and its associated anatomical structures","Basilar artery and its associated anatomical structures","PCA (thalamoperforating and thalamogeniculate arteries) and PComA","MCA and its associated anatomical structures","ACA and its associated anatomical structures"]'::jsonb, 'PCA (thalamoperforating and thalamogeniculate arteries) and PComA', 'Thalamic stroke: PCA occlusion (thalamic syndrome - Dejerine-Roussy).'),
('ca9c6a42-6b3c-57d0-a842-85c6f38ad24f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'Dejerine-Roussy syndrome (thalamic pain syndrome) is:', '["Motor weakness and its associated anatomical structures","Aphasia and its associated anatomical structures","Visual loss and its associated anatomical structures","Central post-stroke pain (burning, tingling, severe pain on the contralateral side after a thalam","Ataxia and its associated anatomical structures"]'::jsonb, 'Central post-stroke pain (burning, tingling, severe pain on the contralateral side after a thalam', 'Dejerine-Roussy syndrome: neuropathic pain after thalamic infarct.'),
('6254ebce-fb1a-59f0-85df-583548395808'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The blood-brain barrier is absent in:', '["The cerebral cortex only and its associated anatomical structures","The basal ganglia only and its associated anatomical structures","The thalamus only and its associated anatomical structures","The area postrema, median eminence, pineal gland, and neurohypophysis","The entire brain and its associated anatomical structures"]'::jsonb, 'The area postrema, median eminence, pineal gland, and neurohypophysis', 'The circumventricular organs lack BBB to allow sensing of blood-borne substances.'),
('1eaad88d-9734-5bb3-815a-dbaa48ebab7d'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The CSF is absorbed into the venous system via:', '["Choroid plexus into the ventricles and its associated anatomical structures","Ependymal cells into the subarachnoid space and its associated anatomical structures","Perivascular spaces and its associated anatomical structures","Lymphatic channels in the spinal canal and its associated anatomical structures","Arachnoid granulations (Pacchionian granulations) into the superior sagittal sinus"]'::jsonb, 'Arachnoid granulations (Pacchionian granulations) into the superior sagittal sinus', 'CSF absorption: arachnoid granulations act as one-way valves.'),
('9611ba2a-6b7c-5e4a-8a8f-0f29d63321a1'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The third ventricle is connected to the fourth ventricle via:', '["The interventricular foramen","The cerebral aqueduct","The foramen of Monro","The central canal","The foramina of Luschka and Magendie"]'::jsonb, 'The cerebral aqueduct', 'The cerebral aqueduct is the narrowest part of the ventricular system.'),
('57ba4369-da56-5a42-b40b-f965649f4e87'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The fourth ventricle is connected to the subarachnoid space via:', '["The foramina of Luschka (lateral) and Magendie","The cerebral aqueduct","The interventricular foramen","The foramen of Monro","The central canal"]'::jsonb, 'The foramina of Luschka (lateral) and Magendie', 'Obstruction of fourth ventricle foramina causes hydrocephalus.'),
('1f34f725-d6f3-5e25-bdfd-62a1afc0130e'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The lateral ventricles are connected to the third ventricle via:', '["The interventricular foramina","The foramina of Luschka","The central canal","The foramen of Magendie","The cerebral aqueduct"]'::jsonb, 'The interventricular foramina', 'The foramen of Monro connects each lateral ventricle to the third ventricle.'),
('cc302c82-48ce-5c45-b732-894b27146e51'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The pineal gland (epiphysis) is located:', '["In the sella turcica","In the midline, posterior to the third ventricle","In the posterior fossa","In the anterior cranial fossa","In the middle cranial fossa"]'::jsonb, 'In the midline, posterior to the third ventricle', 'The pineal gland is a midline structure that secretes melatonin.'),
('f423e5df-7d8d-5063-b2c9-d90bf9ccd9cf'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The pituitary stalk (infundibulum) connects:', '["The hypothalamus to the pituitary gland","The pineal gland to the hypothalamus","The hippocampus to the mammillary bodies","The amygdala to the hypothalamus","The thalamus to the pituitary"]'::jsonb, 'The hypothalamus to the pituitary gland', 'The pituitary stalk carries hypothalamic hormones to the posterior pituitary and portal blood to the anterior pituitary.'),
('3e717805-92fd-50e9-90a0-f6c29577397f'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'For a patient presenting with symptoms, The optic chiasm is located:', '["In the anterior cranial fossa","In the middle cranial fossa","Above the pituitary gland","In the posterior cranial fossa","In the cavernous sinus"]'::jsonb, 'Above the pituitary gland', 'A pituitary tumor compressing the optic chiasm causes bitemporal hemianopsia.'),
('93932ff5-c950-55cb-97bc-2381c3dd7526'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The olfactory bulb and tract are located:', '["In the sella turcica","In the posterior cranial fossa","In the cavernous sinus","In the anterior cranial fossa","In the middle cranial fossa"]'::jsonb, 'In the anterior cranial fossa', 'The olfactory nerve (CN I) passes through the cribriform plate to the olfactory bulb.'),
('a51c20c3-771c-5606-8faa-1fba1e0bde95'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The trigeminal ganglion (Gasserian ganglion) is located:', '["In the foramen ovale","In the Meckel cave","In the cavernous sinus","In the foramen rotundum","In the posterior cranial fossa"]'::jsonb, 'In the Meckel cave', 'The trigeminal ganglion contains the cell bodies of the sensory neurons of CN V.'),
('c21c5257-39df-5b4b-a0b2-8c4ff9224fd7'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The geniculate ganglion (of CN VII) is located:', '["In the pons","In the medulla","In the foramen stylomastoid","In the internal acoustic meatus","In the facial canal of the temporal bone"]'::jsonb, 'In the facial canal of the temporal bone', 'The geniculate ganglion contains the cell bodies for taste from the anterior 2/3 of the tongue.'),
('3eb43bcb-2de7-51c3-afb1-da2b100d8c83'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The spiral ganglion (of CN VIII) is located:', '["In the pons","In the cerebellopontine angle","In the modiolus of the cochlea","In the medulla","In the internal acoustic meatus"]'::jsonb, 'In the modiolus of the cochlea', 'The spiral ganglion (cochlear ganglion) contains the first-order auditory neurons.'),
('04bd75f0-b8e7-589c-afd4-2bac39d8ba7d'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The vestibular ganglion (Scarpa ganglion) is located:', '["In the cerebellopontine angle","In the pons","In the medulla","In the internal acoustic meatus","In the modiolus of the cochlea"]'::jsonb, 'In the internal acoustic meatus', 'The vestibular ganglion contains the first-order vestibular neurons (balance).'),
('b2f1bf0e-6f5f-5a77-8201-4b01eedf586c'::uuid, 'Anatomy (Paper 2)', 'Neuroanatomy', 'The blood supply to the internal capsule is primarily from:', '["Anterior choroidal artery","Lenticulostriate arteries","Anterior cerebral artery","Basilar artery","Posterior cerebral artery"]'::jsonb, 'Lenticulostriate arteries', 'Lenticulostriate arteries (from MCA) supply internal capsule, basal ganglia, corona radiata. Hypertension → microaneurysms → Charcot-Bouchard aneurysms → ICH.'),
